INSERT INTO characters (char, data) VALUES ('駕', '{"9000": "", "Chữ Trung Quốc": "駕", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 馬 | Số nét | 15 | nét | 加 | gia | biểu âm | thêm vào | 馬 | mã | biểu nghĩa | ngựa | 駕 = 加 (Gia, biểu âm) + 馬 (Mã, biểu nghĩa: ngựa); chữ hình thanh. Phần 馬 chỉ liên quan đến ngựa; phần 加 cho âm jià/giá.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Bạch thư | Đại triện | Tiểu triện | Chữ hình thanh: 馬 (mã) biểu nghĩa ''ngựa'', 加 (gia) biểu âm. Nghĩa gốc là điều khiển xe ngựa; sau mở rộng sang lái xe. Bạch thư, đại triện và tiểu triện ghi lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mã (293) Gia (73)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Gia (số 228 - thêm vào) ở trên chữ Mã (số 187 - con ngựa) . Đặt thêm (Gia) yên cương lên lưng ngựa (Mã) để điều khiển, cưỡi gọi là giá (giá lâm, hộ giá). Giải thích sự chuyển ý: Chữ Gia (thêm vào) chỉ âm, chữ Mã (ngựa) chỉ ý. Điều khiển ngựa kéo xe (Mã) gọi là giá (Giá). *(Biến âm Hán Việt: Gia -> Giá)*", "Nghĩa Tiếng Việt_Xie": "lái xe", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>加馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "加", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "驾", "Unihan_Traditional (Chữ Phồn thể)": "駕", "Pinyin_Xie": "jià", "Âm Hán Việt_Xie": "giá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc điều khiển xe cộ hoặc danh từ chỉ xe của vua. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騙', '{"9000": "", "Chữ Trung Quốc": "騙", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 馬 | Số nét | 19 | nét | 馬 | mã | biểu nghĩa | ngựa | 扁 | thiên | biểu âm | âm thiên/biên | 騙 = 馬 (Mã, biểu nghĩa: ngựa) + 扁 (Thiên, biểu âm); chữ hình thanh. Nghĩa gốc: leo lên ngựa bằng cách vung chân qua — nghĩa \"lừa dối\" phát triển từ đó.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary: 騙 là chữ hình thanh gồm 馬 (ngựa — biểu nghĩa) và 扁 (biểu âm). Nghĩa gốc: leo lên ngựa bằng cách vung một chân qua lưng ngựa (mount by swinging a leg across). Nghĩa phái sinh: lừa đảo, gian trá — hình dung hành động lách qua bằng thủ thuật. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mã (293) Biển (337)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mã (số 187 - con ngựa) và chữ Biển (số 203 - tấm biển) . Kẻ cưỡi ngựa (Mã) mang theo tấm biển (Biển) giả danh lừa bịp để đi lừa gạt người khác. Giải thích sự chuyển ý: Chữ Biển (tấm biển/dẹp) chỉ âm, chữ Mã (ngựa) chỉ ý. Kẻ xấu lừa gạt người khác rồi nhảy lên lưng ngựa (Mã) chạy trốn gọi là lừa gạt (Phiến). *(Biến âm Hán Việt: Biển -> Phiến)*", "Nghĩa Tiếng Việt_Xie": "nói dối", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬扁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "骗", "Unihan_Traditional (Chữ Phồn thể)": "騙", "Pinyin_Xie": "piàn", "Âm Hán Việt_Xie": "thiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động lừa lọc người khác hoặc nhảy lên lưng ngựa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('針', '{"9000": "", "Chữ Trung Quốc": "針", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 10 | nét | 釒 | biểu nghĩa | kim loại | 十 | thập | biểu âm | 針 = 釒 (kim, biểu nghĩa: kim loại) + 十 (Thập, biểu âm); chữ hình thanh. Thành phần 釒 cho biết đây là vật bằng kim loại, 十 cung cấp âm đọc gần với zhēn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Wiktionary ghi 針 là chữ hình thanh: 釒 (kim, biểu nghĩa: kim loại) + 十 (thập, biểu âm). Chữ chỉ cây kim, cái ghim, hoặc kim châm cứu. Có hình đại triện từ Wikimedia. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (32) Thập (2)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Kim (số 167 - kim loại) và chữ Thập (số 24 - số 10) . Một vật dụng bằng kim loại (Kim) nhỏ bé mỏng manh như một phần mười (Thập) sợi tóc dùng để khâu vá là cây kim. Giải thích sự chuyển ý: Chữ Thập (số 10) chỉ âm, chữ Kim (kim loại) chỉ ý. Đồ vật bằng kim loại (Kim) rất mảnh dùng để may vá, châm cứu (Châm). *(Biến âm Hán Việt: Thập -> Châm)*", "Nghĩa Tiếng Việt_Xie": "cây kim", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金十", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "十", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "针", "Unihan_Traditional (Chữ Phồn thể)": "針", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "châm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cây kim khâu hoặc làm động từ chỉ việc châm cứu, tiêm thuốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('銅', '{"9000": "", "Chữ Trung Quốc": "銅", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 14 | nét | 金 | kim | biểu nghĩa | kim loại | 同 | đồng | biểu âm | cùng nhau (cho âm tóng) | 銅 = 金 (Kim, biểu nghĩa: kim loại) + 同 (Đồng, biểu âm). Chữ hình thanh: bộ Kim cho nghĩa (kim loại màu đỏ), 同 cho âm tóng/đồng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 銅 là chữ hình thanh gồm 金 (kim loại, biểu nghĩa) và 同 (biểu âm). Nghĩa gốc là kim loại đồng (copper) — kim loại màu đỏ cam được sử dụng rộng rãi từ thời đại đồ đồng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (32) Đồng (93)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Kim (số 167 - kim loại) và chữ Đồng (số 184 - cùng nhau) . Các loại kim loại (Kim) có màu đỏ giống nhau (Đồng) gọi chung là kim loại đồng. Giải thích sự chuyển ý: Chữ Đồng (cùng nhau) chỉ âm, chữ Kim (kim loại) chỉ ý. Tên một loại kim loại (Kim) có màu vàng đỏ (Đồng).", "Nghĩa Tiếng Việt_Xie": "đồng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "铜", "Unihan_Traditional (Chữ Phồn thể)": "銅", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "dong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm định ngữ bổ nghĩa cho danh từ khác để chỉ chất liệu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鎔', '{"9000": "", "Chữ Trung Quốc": "鎔", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 18 | nét | 金 | kim | biểu nghĩa | kim loại | 容 | dung | biểu âm | 鎔 = 金 (Kim, biểu nghĩa: kim loại) + 容 (Dung, biểu âm); chữ hình thanh. Bộ 金 chỉ liên quan đến kim loại, 容 cho âm đọc gần với róng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Wiktionary ghi {{Han compound|水|alt1=金|容|ls=psc|c1=s|c2=p}}: dùng 金 (kim loại) làm bộ nghĩa và 容 làm biểu âm. Chữ chỉ hành động nung chảy, đúc khuôn kim loại. Có tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (32) Dung (322)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Kim (số 167 - kim loại) và chữ Dung (số 132 - bao dung) . Kim loại (Kim) được nấu chảy hòa quyện, bao dung (Dung) với nhau trong lò để đúc thành hình dạng mới gọi là đúc (dung). Giải thích sự chuyển ý: Chữ Dung (bao dung) chỉ âm, chữ Kim (kim loại) chỉ ý. Quá trình làm cho kim loại (Kim) nóng chảy thành nước (Dung).", "Nghĩa Tiếng Việt_Xie": "rhodium", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金容", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "容", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "镕", "Unihan_Traditional (Chữ Phồn thể)": "鎔", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "dung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc nung chảy kim loại hoặc làm danh từ chỉ cái khuôn đúc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羣', '{"9000": "", "Chữ Trung Quốc": "羣", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Dương (40) Quân (28)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Quân (số 30 - quân tử / vua) ở trên chữ Dương (số 123 - con cừu) . Một người quân tử (Quân) chăn dắt cả một đàn cừu (Dương) gọi là bầy đàn, quần thể. Giải thích sự chuyển ý: Chữ Quân (vua/quân tử) chỉ âm, chữ Dương (con cừu) chỉ ý. Tập tính của loài cừu (Dương) là luôn sống tập trung lại với nhau, mở rộng ra gọi là bầy đàn (Quần). *(Biến âm Hán Việt: Quân -> Quần)*", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>君羊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "君", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "群", "Unihan_Traditional (Chữ Phồn thể)": "羣", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硯', '{"9000": "", "Chữ Trung Quốc": "硯", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thạch (302) Kiến (56)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thạch (số 112 - hòn đá) và chữ Kiến (số 147 - nhìn thấy) . Nhìn (Kiến) thấy hòn đá (Thạch) được khoét lõm mài dũa cẩn thận để làm chỗ mài mực gọi là nghiên mực. Giải thích sự chuyển ý: Chữ Kiến (nhìn thấy) chỉ âm, chữ Thạch (đá) chỉ ý. Dụng cụ bằng đá (Thạch) chuyên dùng để mài mực viết chữ (Nghiên). *(Biến âm Hán Việt: Kiến -> Nghiên)*", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "見", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砚", "Unihan_Traditional (Chữ Phồn thể)": "硯", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鵬', '{"9000": "", "Chữ Trung Quốc": "鵬", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 鳥 | Số nét | 19 | nét | 朋 | bằng | biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鵬 = 朋 (Bằng, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim); chữ hình thanh. Bộ 鳥 cho biết đây là tên loài chim, phần 朋 gợi âm đọc péng/bằng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 鵬 (péng) là chữ hình thanh: 鳥 (chim) làm nghĩa phù, 朋 làm âm phù. Đây là tên con chim đại bàng thần thoại Bằng (鵬) trong Trang Tử — loài chim khổng lồ có thể bay chín vạn dặm. Cấu trúc rõ ràng theo Wiktionary: {{Han compound|朋|鳥|ls=psc|c1=p|c2=s|t2=bird}}. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Điểu (290) Bằng (96)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bằng (số 74 - bạn bè) và chữ Điểu (số 196 - con chim) . Loài chim (Điểu) khổng lồ bay lượn trên bầu trời được gọi là người bạn (Bằng) của mây gió (Chim bằng). Giải thích sự chuyển ý: Chữ Bằng (bạn bè) chỉ âm, chữ Điểu (con chim) chỉ ý. Tên một loài chim (Điểu) lớn phi thường trong truyền thuyết (Bằng).", "Nghĩa Tiếng Việt_Xie": "chim đại bàng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰朋鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鹏", "Unihan_Traditional (Chữ Phồn thể)": "鵬", "Pinyin_Xie": "péng", "Âm Hán Việt_Xie": "bằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng đầu câu làm chủ ngữ hoặc làm tân ngữ trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶯', '{"9000": "", "Chữ Trung Quốc": "鶯", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Điểu (290) Huỳnh", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Huỳnh (sáng lập lòe) ở trên chữ Điểu (số 196 - con chim) . Loài chim (Điểu) có màu sắc rực rỡ sáng chói lập lòe (Huỳnh) gọi là chim oanh vàng. Giải thích sự chuyển ý: Chữ Huỳnh (ánh sáng lập lòe) chỉ âm, chữ Điểu (con chim) chỉ ý. Tên một loài chim (Điểu) có bộ lông màu vàng lục đẹp, hót hay (Oanh). *(Biến âm Hán Việt: Huỳnh -> Oanh)*", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "莺", "Unihan_Traditional (Chữ Phồn thể)": "鶯", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('當', '{"9000": "", "Chữ Trung Quốc": "當", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Điền (247) Thượng (338)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thượng (ưa chuộng, coi trọng) ở trên chữ Điền (mảnh ruộng) . Người đàn ông luôn coi trọng (Thượng) mảnh ruộng (Điền) của mình thì mới có thể đảm đương gia đình, làm việc chính đáng. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thượng (coi trọng) chỉ âm, chữ Điền (ruộng) chỉ ý. Chịu trách nhiệm, gánh vác, đảm đương công việc đồng áng (Đương). *(Biến âm Hán Việt: Thượng -> Đương)*", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>田", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賞', '{"9000": "", "Chữ Trung Quốc": "賞", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 15 | nét | 商 | thương | biểu âm | 貝 | bối | biểu nghĩa | vỏ sò, tiền | 賞 = 商 (Thương, biểu âm: cho âm shǎng/thưởng) + 貝 (Bối, biểu nghĩa: tiền/tài vật). Chữ hình thanh. Kim văn đã ghi nhận dạng chữ này.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Bạch thư | Đại triện | Theo Wiktionary, 賞 là chữ hình thanh: 商 biểu âm (shǎng), 貝 biểu nghĩa (tiền tài). Nghĩa gốc: ban thưởng bằng tiền/tài vật. Nghĩa mở rộng: khen ngợi, thưởng thức (賞析, 欣賞). Kim văn, bạch thư và đại triện đều có ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bối (241) Thượng (338)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thượng (ưa chuộng, coi trọng) ở trên chữ Bối (tiền bạc / của cải) . Khi được bề trên coi trọng (Thượng), người ta sẽ được ban cho tiền bạc, của cải (Bối) gọi là phần thưởng. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thượng (coi trọng) chỉ âm, chữ Bối (tiền bạc) chỉ ý. Dùng tiền bạc của cải (Bối) để khích lệ người có công (Thưởng). *(Biến âm Hán Việt: Thượng -> Thưởng)*", "Nghĩa Tiếng Việt_Xie": "phần thưởng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "赏", "Unihan_Traditional (Chữ Phồn thể)": "賞", "Pinyin_Xie": "shǎng", "Âm Hán Việt_Xie": "thưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ mang tân ngữ chỉ người hoặc vật được thưởng, hoặc làm danh từ chỉ phần thưởng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('兩', '{"9000": "", "Chữ Trung Quốc": "兩", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (1) Quynh (318)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Một cái cân (cái đòn gánh), bên dưới có treo hai khối trọng lượng người cân lại cho bằng nhau ở hai bên, gọi là hai (lưỡng). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Hình ảnh cái đòn gánh có hai vật treo hai bên bằng nhau, biểu thị số hai, một cặp đôi (Lưỡng).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "两", "Unihan_Traditional (Chữ Phồn thể)": "兩", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滿', '{"9000": "", "Chữ Trung Quốc": "滿", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (306) Mạn (253)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủy (nước) đứng cạnh chữ Mạn (bình chứa / trải ra) . Nước (Thủy) đong vào đồ chứa (Mạn) rót đến mức tràn cả ra ngoài là đầy đặn, viên mãn (mãn). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Mạn (dài/to) chỉ âm, chữ Thủy (nước) chỉ ý. Chất lỏng đổ đầy đến mức tràn ra ngoài gọi là đầy đủ (Mãn).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "满", "Unihan_Traditional (Chữ Phồn thể)": "滿", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糸', '{"9000": "", "Chữ Trung Quốc": "糸", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (268)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình dáng của một lọn tơ tằm được cuộn lại nhiều vòng và kéo dài thả buông xuống dưới thành sợi chỉ tơ mỏng manh (mịch). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Khắc họa hình ảnh kén tằm nhả tơ bị cuộn thành từng lọn nhỏ vắt lại (Mịch).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>幺小", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "小", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "幺", "Unihan_Simplified (Chữ Giản thể)": "糸", "Unihan_Traditional (Chữ Phồn thể)": "糸", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紅', '{"9000": "", "Chữ Trung Quốc": "紅", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 9 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, lụa | 工 | công | biểu âm | (biểu âm, đọc gần hóng) | 紅 = 糸 (Mịch, biểu nghĩa: sợi tơ lụa) + 工 (Công, biểu âm). Chữ hình thanh: bộ Mịch cho nghĩa màu sắc tơ lụa, phần 工 cho âm. Đây là phồn thể của 红.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary: 紅 là chữ hình thanh, gồm 糸 (biểu nghĩa: tơ lụa) và 工 (biểu âm). Màu đỏ hồng (hóng) — màu của lụa nhuộm tươi. Gốc nghĩa là màu đỏ nhạt, về sau mở rộng thành đỏ nói chung, và cả hồng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (268) Công (167)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mịch (sợi tơ) đứng cạnh chữ Công (người thợ) . Những người thợ (Công) khéo léo nhuộm sợi tơ (Mịch) thành màu đỏ sặc sỡ để may áo cho lễ hội (hồng). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Công (người thợ) chỉ âm, chữ Mịch (sợi tơ) chỉ ý. Tơ lụa được thợ nhuộm thành màu đỏ (Hồng).", "Nghĩa Tiếng Việt_Xie": "màu đỏ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹工", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "工", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "红", "Unihan_Traditional (Chữ Phồn thể)": "紅", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Động từ | 动词 | Thường làm tính từ đứng trước danh từ để chỉ màu sắc hoặc làm vị ngữ biểu thị sự nổi tiếng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豸', '{"9000": "", "Chữ Trung Quốc": "豸", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình dáng của một con vật hoang dã há miệng chồm lên, hoặc một con sâu có cái đầu to, cái thân dài và lưng vằn vện bò trên mặt đất. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Vẽ lại hình dáng của các loài động vật hoang dã, không có chân, hoặc thú dữ (Trãi).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>爫犭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "爫", "Unihan_Simplified (Chữ Giản thể)": "豸", "Unihan_Traditional (Chữ Phồn thể)": "豸", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貓', '{"9000": "", "Chữ Trung Quốc": "貓", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 豸 | Số nét | 15 | nét | 豸 | trại | biểu nghĩa | thú không chân sau, loài thú | 苗 | miêu | biểu âm | mầm cây (cho âm miāo) | 貓 = 豸 (Trại, biểu nghĩa: loài thú) + 苗 (Miêu, biểu âm); chữ hình thanh. Âm 苗 (miáo) gần với māo — có thể phản ánh nguồn gốc tượng thanh tiếng kêu \"meo\". Wiktionary ghi chú thành phần âm có thể chỉ bản chất tượng thanh của từ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 貓 là chữ hình thanh: 豸 (loài thú) biểu nghĩa, 苗 biểu âm gần māo. Wiktionary ghi chú thành phần âm 苗 có thể chỉ bản chất tượng thanh — tiếng kêu \"meo\" của con mèo. Ma Xulun đề xuất 豸 là chữ gốc của 貓. Dạng giản thể là 猫 (bộ 犭). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trãi (514) Miêu (278)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Trãi (loài thú) đứng cạnh chữ Miêu (cây mạ non) . Con vật thuộc bộ lông thú (Trãi) hay chui rúc vào ruộng mạ non (Miêu) để rình bắt chuột chính là con mèo. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Miêu (mạ non) chỉ âm, chữ Trãi (động vật dã thú) chỉ ý. Loài thú nhỏ bắt chuột (Con mèo).", "Nghĩa Tiếng Việt_Xie": "con mèo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸苗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "苗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "猫", "Unihan_Traditional (Chữ Phồn thể)": "貓", "Pinyin_Xie": "māo", "Âm Hán Việt_Xie": "mèo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con mèo, thường đứng độc lập hoặc làm định ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('階', '{"9000": "", "Chữ Trung Quốc": "階", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 阜 | Số nét | 11 | nét | 阝 | phụ | biểu nghĩa | đất cao, gò đống (biến thể của 阜) | 皆 | giai | biểu âm | tất cả, đều | 階 = 阝(阜, Phụ, biểu nghĩa: đất cao, bậc) + 皆 (Giai, biểu âm); chữ hình thanh — bộ 阜 chỉ nơi có độ cao, bậc thang, 皆 cho âm jiē.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 階 là chữ hình thanh: 阜/阝 (đất cao, bậc) biểu nghĩa, 皆 biểu âm. Nguyên nghĩa là bậc thang, thềm nhà; mở rộng sang cấp bậc, giai đoạn xã hội. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phụ (579) Giai (578)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Giai (số 578 - đều, cùng) ở bên phải bộ Phụ (số 579 - dãy núi). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Giai (đều cùng) chỉ âm, bộ Phụ (núi) chỉ ý. Các bậc thềm cao đều như nhau thì được gọi là bậc thềm (Giai).", "Nghĩa Tiếng Việt_Xie": "cấp bậc; bậc thềm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝皆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "jiē", "Âm Hán Việt_Xie": "giai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ bậc tam cấp hoặc các giai đoạn, thứ bậc trong xã hội. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彑', '{"9000": "", "Chữ Trung Quốc": "彑", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình đầu con lợn. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Mô phỏng trực tiếp hình ảnh cái đầu lợn thò ra (Kệ).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "彑", "Unihan_Traditional (Chữ Phồn thể)": "彑", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彔', '{"9000": "", "Chữ Trung Quốc": "彔", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kệ (581) Thủy (040)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Kệ (số 581 - đầu lợn) ở trên chữ Thủy (số 040 - nước). Giải thích sự chuyển ý: Đây là chữ Hội ý. Hình ảnh con lợn đang cúi đầu xuống vũng nước uống, rõ ràng chúng đang khát nước, biểu thị ý \"rõ ràng\" (Lục).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>彑氺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彑", "Unihan_Simplified (Chữ Giản thể)": "录", "Unihan_Traditional (Chữ Phồn thể)": "彔", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綠', '{"9000": "", "Chữ Trung Quốc": "綠", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 14 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, vải | 彔 | lục | biểu âm | 綠 = 糸 (Mịch, biểu nghĩa: sợi tơ/vải) + 彔 (Lục, biểu âm); chữ hình thanh (psc). Bộ 糸 chỉ vật liệu dệt, 彔 cho âm. Màu xanh lá được liên tưởng từ màu xanh của tơ lụa nhuộm từ cây cỏ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 綠 (lǜ): chữ hình thanh, gồm 糸 (sợi tơ, biểu nghĩa) và 彔 (Lục, biểu âm). Màu xanh lá cây — màu của tơ lụa nhuộm xanh từ thực vật. Tiểu triện ghi nhận dạng chữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (180) Lục (582)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mịch (số 180 - sợi tơ) ở bên trái chữ Lục (số 582 - rõ ràng). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Lục (rõ ràng) chỉ âm, bộ Mịch (sợi tơ/màu nhuộm) chỉ ý. Chỉ màu xanh biếc, xanh lá cây (Lục).", "Nghĩa Tiếng Việt_Xie": "màu xanh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹彔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "绿", "Unihan_Traditional (Chữ Phồn thể)": "綠", "Pinyin_Xie": "lǜ", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ đứng trước danh từ để chỉ màu sắc xanh lá cây. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枼', '{"9000": "", "Chữ Trung Quốc": "枼", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thế (584) Mộc (021)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thế (số 584 - 30 năm) ở trên chữ Mộc (số 021 - cây gỗ). Giải thích sự chuyển ý: Đây là chữ Hội ý. Cây đã sống được 30 năm thì thân cây to lớn, có thể đem xẻ ra thành các tấm gỗ mỏng làm đồ dùng (Diệp).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>世木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "世", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葉', '{"9000": "", "Chữ Trung Quốc": "葉", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 艸 | Số nét | 12 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 枼 | biểu âm | lá cây — hình ảnh gốc của từ này | 葉 = 艸 (Tháu, biểu nghĩa: thực vật) + 枼 (biểu âm, hình ảnh gốc của lá cây). Chữ hình thanh: 枼 vốn là tranh tượng hình cho lá cây; bộ 艸 được thêm vào sau để phân biệt với các chữ khác.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 枼 (cũng đọc yè) là hình ảnh tượng hình gốc cho từ ''lá cây''. Bộ 艸 (thực vật) được thêm vào sau để tạo ra 葉, phân biệt với các nghĩa khác của 枼. Chữ xuất hiện trong kim văn và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (146) Diệp (585)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 146 - cỏ/cây) ở trên chữ Diệp (số 585 - tấm gỗ mỏng). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Diệp (tấm gỗ mỏng) chỉ âm, bộ Thảo (cỏ cây) chỉ ý. Thứ mỏng dẹt mọc trên cây chính là lá cây (Diệp).", "Nghĩa Tiếng Việt_Xie": "lá", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹枼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "枼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "yè", "Âm Hán Việt_Xie": "diệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ lá cây hoặc làm lượng từ cho những vật mỏng dẹt như lá, thuyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('風', '{"9000": "", "Chữ Trung Quốc": "風", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 風 | Số nét | 9 | nét | 風 | phong | tượng hình | gió — chữ tượng hình mượn từ phượng hoàng | 風 là chữ tượng hình, ban đầu là hình con phượng hoàng (鳳) mượn âm để viết chữ \"gió\". Kim văn cho thấy phần phải gồm 凡 (biểu âm phong) trên và ba sợi lông đuôi phượng hoàng bên dưới. Về sau hình dạng đơn giản hoá, bộ 虫 trong thư pháp Chu và Tần là do đơn giản hoá thêm từ hình lông đuôi. Shuowen hiểu nhầm khi gán cho 虫.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Bạch thư | Đại triện | Tiểu triện | Wiktionary: 風 ban đầu là chữ hội ý mượn hình con phượng hoàng (鳳) để ghi âm \"phong\" (gió). Kim văn có 凡 (biểu âm) phía trên và ba sợi lông đuôi phượng hoàng phía dưới. Các dạng sau dựa vào phần phải của kim văn, bỏ bớt hai trong ba sợi lông. Bộ 虫 trong thư pháp Chu và Tần là do đơn giản hoá tiếp từ hình lông đuôi — Shuowen Jiezi giải thích sai khi liên kết với côn trùng. (Theo Li, 2012) | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phàm (017) Trùng (308)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Trùng (số 308 - côn trùng) ở trong chữ Phàm (số 017 - cánh buồm). Giải thích sự chuyển ý: Đây là chữ Hội ý. Đám côn trùng bay theo gió trên mặt sông biển, gặp cánh buồm thì đậu lại. Mượn hình ảnh đó để chỉ gió (Phong).", "Nghĩa Tiếng Việt_Xie": "gió; tục, thói quen; bệnh phong", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴几䖝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䖝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "几", "Unihan_Simplified (Chữ Giản thể)": "风", "Unihan_Traditional (Chữ Phồn thể)": "風", "Pinyin_Xie": "fēng", "Âm Hán Việt_Xie": "phong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ gió hoặc động từ với nghĩa là phơi gió. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('毬', '{"9000": "", "Chữ Trung Quốc": "毬", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mao (260) Cầu (597)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mao (số 260 - lông/da) ở bên trái chữ Cầu (số 597 - tìm kiếm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cầu chỉ âm, bộ Mao (da/lông) chỉ ý. Quả bóng thời xưa làm bằng da, bằng lông để đá hoặc đánh (Cầu).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰毛求", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "求", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "毛", "Unihan_Simplified (Chữ Giản thể)": "毬", "Unihan_Traditional (Chữ Phồn thể)": "毬", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('丶', '{"9000": "", "Chữ Trung Quốc": "丶", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình một nét chấm nhỏ. Giải thích sự chuyển ý: Đây là chữ Tượng hình / Chỉ sự. Tượng hình một dấu chấm.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: me", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "丶", "Unihan_Traditional (Chữ Phồn thể)": "丶", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('執', '{"9000": "", "Chữ Trung Quốc": "執", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hạnh (606) Hoàn (608)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hạnh (số 606 - may mắn) ở bên trái chữ Hoàn (số 608 - thẳng thắn). Giải thích sự chuyển ý: Đây là chữ Hội ý. Kẻ có tính tình thẳng thắn (Hoàn) sẽ có được nhiều sự tốt lành do trời ban (Hạnh). Chấp mang ý nghĩa cầm giữ, cai quản vững vàng.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰幸丸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "幸", "Unihan_Simplified (Chữ Giản thể)": "执", "Unihan_Traditional (Chữ Phồn thể)": "執", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寫', '{"9000": "", "Chữ Trung Quốc": "寫", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Miên (042) Tích (611)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Miên (số 042 - mái nhà) ở trên chữ Tích (số 611 - chiếc giày). Giải thích sự chuyển ý: Đây là chữ Hội ý. Khi vào trong nhà (Miên) thì cởi bỏ đôi giày (Tích) xếp ngay ngắn. Tả mang nghĩa bố trí, sắp đặt, bày ra.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>宀舄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "写", "Unihan_Traditional (Chữ Phồn thể)": "寫", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('丿', '{"9000": "", "Chữ Trung Quốc": "丿", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình một nét phẩy. Giải thích sự chuyển ý: Đây là chữ Chỉ sự. Tượng hình một nét phẩy (Phiệt).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: me", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "丿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "丿", "Unihan_Traditional (Chữ Phồn thể)": "丿", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夾', '{"9000": "", "Chữ Trung Quốc": "夾", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (009) Đại (017)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hai chữ Nhân (số 009 - người) đứng ở hai bên sườn chữ Đại (số 017 - người to lớn). Giải thích sự chuyển ý: Đây là chữ Hội ý. Hình ảnh hai đứa nhỏ đứng nép ở hai bên người đàn ông. Giáp mang nghĩa là hai bên, kẹp giữa.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴大从", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "从", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "夹", "Unihan_Traditional (Chữ Phồn thể)": "夾", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('單', '{"9000": "", "Chữ Trung Quốc": "單", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (036) Điền (057) Thập (007)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hai chữ Khẩu (số 036 - miệng) ở trên chữ Điền (số 057 - ruộng) và chữ Thập (số 007 - mười/hoàn thiện). Giải thích sự chuyển ý: Đây là chữ Hội ý. Tờ giấy ghi chép lời cam kết (Khẩu) của 2 người về mảnh ruộng (Điền) mua bán rõ ràng (Thập). Đơn là tờ giấy thỏa thuận, cũng mang nghĩa đơn độc.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>吅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "单", "Unihan_Traditional (Chữ Phồn thể)": "單", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卩', '{"9000": "", "Chữ Trung Quốc": "卩", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Trực tiếp khắc họa chi tiết hình dáng cái thẻ của quan cầm vào khi chầu vua thời xưa. Giải thích sự chuyển ý: Mở rộng từ hình ảnh cái thẻ tre (cốt khí), Tiết cũng có nghĩa là tiết tháo, chí khí của người làm quan.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴丨㇆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丨", "Unihan_Simplified (Chữ Giản thể)": "卩", "Unihan_Traditional (Chữ Phồn thể)": "卩", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盌', '{"9000": "", "Chữ Trung Quốc": "盌", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 皿 | Số nét | 10 | nét | 盌 | oản | tượng hình | dị thể cổ của 碗 (bát, chén) | 盌 là dị thể cổ của 碗 (oản — cái bát). Wiktionary ghi {{zh-see|碗}}. Bộ 皿 (mãnh — đồ vật/bình chứa) liên quan. Kim văn và tiểu triện có hình.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Wiktionary ghi 盌 là dị thể của 碗 (wǎn — cái bát). Kim văn và tiểu triện có hình. Bộ 皿 (mãnh) gốc liên quan đến đồ đựng. Chữ 碗 hiện đại dùng bộ 石 (thạch — đá/sứ), trong khi 盌 dùng bộ 皿 (đồ đựng). Đây là sự chuyển biến từ biểu thị ''đồ đựng'' sang ''đồ sứ/đất nung''. Nguồn hanziyuan có hình Kim văn và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Uyển (530) Mãnh (134)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Uyển (số 530 - uốn cong) ở trên chữ Mãnh (số 134 - chậu/đồ đựng). Giải thích sự chuyển ý: Chữ Uyển (uốn cong) chỉ âm, chữ Mãnh (đồ đựng) chỉ ý. Chỉ cái chén, cái bát có dáng uốn cong mềm mại (Oản). (Biến âm Hán Việt: Uyển -> Oản)", "Nghĩa Tiếng Việt_Xie": "cái bát nhỏ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>夗皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "wǎn", "Âm Hán Việt_Xie": "oản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Dùng làm danh từ chỉ cái bát đựng đồ ăn hoặc làm lượng từ cho đơn vị bát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟲', '{"9000": "", "Chữ Trung Quốc": "蟲", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 虫 | Số nét | 18 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng | 虫 | trùng | biểu nghĩa | sâu, côn trùng | 虫 | trùng | biểu nghĩa | sâu, côn trùng | 蟲 = 虫 × 3; chữ hội ý — ba con sâu (虫) chồng lên nhau biểu thị \"nhiều sâu, côn trùng nói chung\". Đây là dạng chữ truyền thống, giản thể là 虫.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 蟲 là chữ hội ý: ba chữ 虫 (trùng, nghĩa: rắn/sâu) chồng lại. Hình thức tam điệp gợi ý số nhiều — tất cả các loài côn trùng, sâu bọ. Lưu ý: 虫 cũng là chữ truyền thống độc lập. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trùng (535)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Ba chữ Trùng (số 535 - côn trùng) viết chồng lên nhau. Giải thích sự chuyển ý: Việc lặp lại ba lần chữ Trùng biểu thị số lượng rất nhiều, ý chỉ sự tụ tập của vô số loài côn trùng, sâu bọ.", "Nghĩa Tiếng Việt_Xie": "côn trùng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "虫", "Unihan_Traditional (Chữ Phồn thể)": "蟲", "Pinyin_Xie": "chóng", "Âm Hán Việt_Xie": "trùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường đứng độc lập làm danh từ chỉ các loài côn trùng hoặc sâu bọ nói chung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('學', '{"9000": "", "Chữ Trung Quốc": "學", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (20) Tử (38) Hào (544)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Đứa trẻ (Tử - số 38) đang bắt chước (Hào - số 544) làm theo lời thầy dạy. Hai bàn tay gỡ bỏ sự u mê (Mịch - số 20 - che đậy) phủ trùm trên đầu đứa trẻ. Giải thích sự chuyển ý: Chữ Hào (bắt chước) chỉ âm, ý nghĩa là gỡ bỏ u tối. Học là chịu nghe lời thầy dạy để được khai sáng. (Biến âm Hán Việt: Hào -> Học)", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>𦥯子", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦥯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "子", "Unihan_Simplified (Chữ Giản thể)": "学", "Unihan_Traditional (Chữ Phồn thể)": "學", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厶', '{"9000": "", "Chữ Trung Quốc": "厶", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình một cánh tay đang gập lại ôm đồ vật vào lòng. Giải thích sự chuyển ý: Cánh tay hay có xu hướng vơ mọi thứ vào mình làm của riêng. Tư mang ý nghĩa là sự riêng tư, chuyện cá nhân, tư lợi.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴㇛丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丶", "Unihan_Simplified (Chữ Giản thể)": "厶", "Unihan_Traditional (Chữ Phồn thể)": "厶", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('書', '{"9000": "", "Chữ Trung Quốc": "書", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Viết (131) Duật (548)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Duật (số 548 - cây bút) nằm ở trên chữ Viết (số 131 - lời nói). Hình ảnh bàn tay đang cầm bút (Duật) ghi lại những lời nói (Viết) trên giấy. Giải thích sự chuyển ý: Lời nói gió bay, nhưng khi được dùng bút chép lại thì thành văn bản vĩnh cửu. Thư là viết, là ghi chép lại thành sách vở, thư từ.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>聿日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "日", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "聿", "Unihan_Simplified (Chữ Giản thể)": "书", "Unihan_Traditional (Chữ Phồn thể)": "書", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圖', '{"9000": "", "Chữ Trung Quốc": "圖", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vi (58)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bên ngoài là bộ Vi (số 58 - bao quanh), bên trong là chữ Bỉ (gồm 囗, 十, 回). Giải thích sự chuyển ý: Hình ảnh một khu vực lãnh thổ, mảnh đất rộng lớn (Vi) đã được phân chia quy hoạch thành các khu vực nhỏ khác nhau bên trong. Đồ chính là bản vẽ sơ đồ, bản đồ, hình vẽ phác họa.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗啚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "啚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "图", "Unihan_Traditional (Chữ Phồn thể)": "圖", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('㫃', '{"9000": "", "Chữ Trung Quốc": "㫃", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (12) Phương (560)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhân (số 12 - người) đứng kết hợp với chữ Phương (số 560 - hình vuông). Hình ảnh người đang cầm một lá cờ hình vuông. Giải thích sự chuyển ý: Tượng hình lá cờ đuôi nheo đang bay phấp phới trong gió (Yển).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰方人", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "人", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "方", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('斿', '{"9000": "", "Chữ Trung Quốc": "斿", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Yển (561) Tử (58)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Yển (số 561 - cờ bay) ở trên chữ Tử (số 58 - con cái). Lá cờ của Thiên tử (Tử) đi tuần thú chu du thiên hạ. Giải thích sự chuyển ý: Du là lá cờ hoặc các dải tua cờ dùng để trang trí.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "斿", "Unihan_Traditional (Chữ Phồn thể)": "斿", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('亼', '{"9000": "", "Chữ Trung Quốc": "亼", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (12) Nhất (1)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhân (số 12 - người) đứng ở trên chữ Nhất (số 1 - một). Nhiều người cùng kéo đến đứng tại một (Nhất) nơi. Giải thích sự chuyển ý: Nhiều người gom về một chỗ. Tập là sự tập trung, tụ họp lại.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>人一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "一", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "人", "Unihan_Simplified (Chữ Giản thể)": "亼", "Unihan_Traditional (Chữ Phồn thể)": "亼", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筆', '{"9000": "", "Chữ Trung Quốc": "筆", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 竹 | Số nét | 12 | nét | 竹 | trúc | biểu nghĩa | tre/trúc | 聿 | biểu âm | bút lông — nghĩa gốc của chữ viết | 筆 = 竹 (Trúc, biểu nghĩa: tre/trúc) + 聿 (biểu âm, âm gốc *bǐt); chữ hình thanh. 聿 ban đầu chính là chữ chỉ bút lông; 竹 được thêm vào sau để chỉ cán bút làm bằng tre.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary: 聿 (bút) ban đầu là chữ gốc chỉ cây bút lông; bộ 竹 (trúc) được thêm vào sau khi 聿 đã chuyển nghĩa, nhằm nhấn mạnh vật liệu tre của cán bút. Đây là hình thanh: 竹 biểu nghĩa, 聿 biểu âm *bǐt. Chữ xuất hiện sớm trong giáp cốt và kim văn với hình ảnh bàn tay cầm bút. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (211) Duật (548)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 211 - tre trúc) ở trên chữ Duật (số 548 - cây bút). Cán của cây bút (Duật) thường được chế tác bằng tre, trúc. Giải thích sự chuyển ý: Chữ Duật (bút) chỉ âm, bộ Trúc (tre) chỉ ý. Bút là cây bút dùng để viết chữ (Bút/Viết). (Biến âm Hán Việt: Duật -> Bút)", "Nghĩa Tiếng Việt_Xie": "cái bút", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>⺮聿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "聿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笔", "Unihan_Traditional (Chữ Phồn thể)": "筆", "Pinyin_Xie": "bǐ", "Âm Hán Việt_Xie": "bút", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm danh từ chỉ công cụ viết hoặc làm lượng từ cho các khoản tiền, nét vẽ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戔', '{"9000": "", "Chữ Trung Quốc": "戔", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thập (007) Qua (537)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Có chữ Thập (số 007 - số nhiều) ở trên chữ Qua (số 537 - vũ khí). Chữ Qua đâm chồng chéo lên nhau biểu thị có nhiều sự giết hại, nhiều sự đánh nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Biểu thị vũ khí đánh nhau gây thương tích. Tàn là tàn sát, đau đớn, thương đau.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "戋", "Unihan_Traditional (Chữ Phồn thể)": "戔", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簾', '{"9000": "", "Chữ Trung Quốc": "簾", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 竹 | Số nét | 19 | nét | 竹 | trúc | biểu nghĩa | tre, vật liệu tre | 廉 | liêm | biểu âm | liêm khiết, rẻ — cho âm đọc | 簾 là chữ hình thanh: 竹 (Trúc, biểu nghĩa — vật liệu tre) + 廉 (Liêm, biểu âm). Wiktionary xác nhận: {{Han compound|竹|廉|ls=psc|c1=s|c2=p}}. Nghĩa: rèm che cửa làm từ tre hoặc vải.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 簾 là chữ hình thanh gồm 竹 (tre, biểu nghĩa) và 廉 (biểu âm, âm lián). Nghĩa gốc: tấm màn, rèm che cửa làm từ tre đan. Rèm tre là vật dụng thông dụng trong nhà ở truyền thống Đông Á. Âm lián xuất phát từ thành phần 廉 (liêm). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (211) Liêm (628)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 211 - tre trúc) ở trên chữ Liêm (số 628 - thanh liêm/góc nhà). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Liêm (góc nhà) chỉ âm, bộ Trúc (tre trúc) chỉ ý. Bức rèm mành treo ở nhà làm bằng tre trúc gọi là cái Liêm (rèm).", "Nghĩa Tiếng Việt_Xie": "cái mành mành", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>⺮廉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "rèm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vật dụng dùng để che cửa sổ hoặc cửa ra vào. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飛', '{"9000": "", "Chữ Trung Quốc": "飛", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 飛 | Số nét | 9 | nét | 飛 | phi | tượng hình | chim đang bay lên | 飛 là chữ tượng hình: mô tả con chim bay lên. Wiktionary xác nhận liushu p (tượng hình). Dạng giáp cốt văn và bạch thư rõ ràng vẽ hình chim bay. Dạng hiện đại giống 升 có tua rua, là sự cách điệu hóa theo thời gian.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Bạch thư | Tiểu triện | Theo Wiktionary: 飛 là chữ tượng hình vẽ con chim đang bay lên. Giáp cốt văn và bạch thư còn giữ hình ảnh rõ ràng. Dạng hiện đại đã cách điệu, trông giống 升 (thăng) có tua rua. Nghĩa gốc: bay; mở rộng: nhanh chóng, bay vụt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thăng (227)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Có chữ Thăng (số 227 - bay lên) kết hợp cùng hình hai đôi cánh chim. Giải thích sự chuyển ý: Đây là chữ Hội ý (hoặc Tượng hình). Chim tung đôi cánh vỗ mạnh để cất cánh bay cao. Phi là bay lên, con chim bay cao.", "Nghĩa Tiếng Việt_Xie": "bay", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴升𠃧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠃧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "升", "Unihan_Simplified (Chữ Giản thể)": "飞", "Unihan_Traditional (Chữ Phồn thể)": "飛", "Pinyin_Xie": "fēi", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Phó từ | 副词 | Làm động từ chính trong câu để chỉ hành động bay hoặc di chuyển trên không. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彳', '{"9000": "", "Chữ Trung Quốc": "彳", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (009)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhân đứng (số 009 - người) được thêm một nét phẩy ở trên, chỉ ý người đang vác vật gì nặng nên bước đi ngắn và chậm. Giải thích sự chuyển ý: Đây là chữ Hội ý. Hình ảnh bắp vế và bàn chân. Xích là bước chân trái, bước ngắn và chậm chạp.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>丨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "彳", "Unihan_Traditional (Chữ Phồn thể)": "彳", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遠', '{"9000": "", "Chữ Trung Quốc": "遠", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 13 | nét | 辵 | sước | biểu nghĩa | đi, bước | 袁 | viên | biểu âm | họ Viên | 遠 = 辵 (Sước/Sách, biểu nghĩa: đi đường, bước chân) + 袁 (Viên, biểu âm). Đây là chữ hình thanh: bộ 辵 cho biết nghĩa liên quan đến sự đi lại/khoảng cách, 袁 cho âm gần với 遠.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Theo Wiktionary, 遠 là chữ hình thanh: 辵 (đi, bước) biểu nghĩa + 袁 biểu âm. Hình kim văn và tiểu triện đã được ghi nhận. Nghĩa gốc là khoảng cách xa xôi khi đi bộ — từ 辵 (chân bước) + 袁 (âm). Hình thức chữ phồn thể dùng trong văn bản truyền thống. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (644) Viên (642)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 644 - đi chậm) đi cùng chữ Viên (số 642 - áo dài). Người mặc áo dài (Viên) đi dạo (Xước) thong dong tận nơi phương xa. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Viên (áo dài) chỉ âm, bộ Xước (bước đi) chỉ ý. Viễn là xa xôi, dài, lâu dài. *(Biến âm Hán Việt: Viên -> Viễn)*", "Nghĩa Tiếng Việt_Xie": "xa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶袁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "袁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "远", "Unihan_Traditional (Chữ Phồn thể)": "遠", "Pinyin_Xie": "yuǎn", "Âm Hán Việt_Xie": "viễn, viến, viển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Phó từ | 副词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc làm động từ với nghĩa là tránh xa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夬', '{"9000": "", "Chữ Trung Quốc": "夬", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Đại (017) Quyết (110)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Nét gấp (chữ Quyết) ở trên chữ Đại (số 017 - to lớn/người). Hình cánh tay gập lại vỗ lên ngực tỏ ý quyết tâm. Giải thích sự chuyển ý: Đây là chữ Hội ý. Ra quyết định dứt khoát. Quái (hay Quyết) là phân chia, quyết định dứt khoát.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>人", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "夬", "Unihan_Traditional (Chữ Phồn thể)": "夬", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叚', '{"9000": "", "Chữ Trung Quốc": "叚", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kệ (581) Thù (209)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Phần bên trái có 2 bàn tay (biến thể) đang cầm một vật đưa cho bàn tay bên phải (Thù). Giải thích sự chuyển ý: Đây là chữ Hội ý. Cầm vật đưa cho người khác mượn hoặc cho thuê. Giả là vay mượn, giả dối (thường dùng làm bộ phận tạo chữ cho 假).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𡰥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝦', '{"9000": "", "Chữ Trung Quốc": "蝦", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 虫 | Số nét | 15 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng (bộ thủ động vật nhỏ) | 叚 | giả | biểu âm | (cho âm xiā) | 蝦 = 虫 (Trùng, biểu nghĩa: côn trùng/động vật nhỏ) + 叚 (Giả, biểu âm: cho âm xiā). Chữ hình thanh — 虫 xác định nghĩa là sinh vật nhỏ sống dưới nước, 叚 cho âm đọc. 蝦 là chữ truyền thống, giản thể là 虾.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 蝦 là chữ hình thanh: 虫 (trùng — côn trùng/động vật nhỏ) biểu nghĩa, 叚 (giả) biểu âm. Nghĩa là tôm (shrimp, prawn). Giản thể là 虾. Chữ truyền thống dùng ở Đài Loan và Hong Kong. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trùng (308) Giả (662)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trùng (số 308 - côn trùng/loài giáp xác) ở bên trái chữ Giả (số 662 - mượn). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Giả (mượn) chỉ âm, bộ Trùng (loài nhỏ) chỉ ý. Hà là con tôm, con hà mô (con ếch nhái). *(Biến âm Hán Việt: Giả -> Hà)*", "Nghĩa Tiếng Việt_Xie": "con tôm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "虾", "Unihan_Traditional (Chữ Phồn thể)": "蝦", "Pinyin_Xie": "xiā", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm thành phần trong từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('皀', '{"9000": "", "Chữ Trung Quốc": "皀", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bạch (055) Chủy (046)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bạch (số 055 - trắng) ở trên chữ Chủy (số 046 - cái thìa/muỗng). Hạt gạo trắng (Bạch) nấu thành cơm rồi dùng thìa (Chủy) múc ăn ngon lành. Giải thích sự chuyển ý: Đây là chữ Hội ý. Tập biểu thị mùi thơm của ngũ cốc khi chín.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>白匕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "白", "Unihan_Simplified (Chữ Giản thể)": "皀", "Unihan_Traditional (Chữ Phồn thể)": "皀", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卽', '{"9000": "", "Chữ Trung Quốc": "卽", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tập (664) Tiết (142)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tập (số 664 - mùi thơm ngũ cốc) ở bên trái chữ Tiết (số 142 - đốt tre/tiết tháo). Người có đức độ sống tiết tháo (Tiết) thì tiếng thơm (Tập) lan tỏa ngay lập tức. Giải thích sự chuyển ý: Đây là chữ Hội ý. Một người tiến lại gần nồi cơm thơm (Tập) để ăn. Tức là tiến lại gần, lập tức, ngay tức khắc.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰皀卩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "卩", "Unihan_Simplified (Chữ Giản thể)": "卽", "Unihan_Traditional (Chữ Phồn thể)": "卽", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('節', '{"9000": "", "Chữ Trung Quốc": "節", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 竹 | Số nét | 13 | nét | ⺮ | trúc | biểu nghĩa | tre, trúc | 即 | tức | biểu âm | 節 = ⺮ (Trúc, biểu nghĩa: tre/trúc) + 即 (Tức, biểu âm); chữ hình thanh. Hình ảnh đốt tre — mỗi đoạn ngăn cách bởi một đốt. Từ đó mở rộng sang nghĩa đoạn, khoảng, tiết (tiết trời, lễ tiết, khí tiết).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Chữ hình thanh: ⺮ (tre) là thành phần biểu nghĩa — 節 biểu thị đốt tre, đoạn ngắn giữa hai mấu của thân tre. 即 là thành phần biểu âm. Từ nghĩa đốt tre mở rộng sang: đoạn thời gian (tiết), lễ hội (tết/tiết), khí tiết/phẩm hạnh, chương mục văn bản. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (211) Tức (665)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 211 - tre trúc) ở trên chữ Tức (số 665 - lập tức/tức khắc). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tức chỉ âm, bộ Trúc (cây tre) chỉ ý. Tiết là cái đốt tre làm cho cây tre cứng cáp. Cũng dùng để chỉ chí khí cứng cỏi (tiết tháo). *(Biến âm Hán Việt: Tức -> Tiết)*", "Nghĩa Tiếng Việt_Xie": "đốt, đoạn; tiết trời; một khoảng thời gian; ngày tết, lễ; lễ tháo, tiết tháo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>⺮即", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "即", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "节", "Unihan_Traditional (Chữ Phồn thể)": "節", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "tiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ ngày lễ hoặc làm lượng từ để đếm các đoạn, các tiết học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('異', '{"9000": "", "Chữ Trung Quốc": "異", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Điền (057) Cộng (587)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Điền (số 057 - ruộng) ở trên chữ Cộng (số 587 - cùng chung). Đem tất cả ruộng đất (Điền) của mọi người hợp chung lại (Cộng) là một điều hết sức kỳ lạ. Giải thích sự chuyển ý: Đây là chữ Hội ý. Sự phân chia ruộng đất không theo lẽ thường. Dị mang nghĩa là khác biệt, kỳ lạ, dị thường.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>田共", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "共", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "异", "Unihan_Traditional (Chữ Phồn thể)": "異", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘼', '{"9000": "", "Chữ Trung Quốc": "嘼", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (012) Điền (057)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Có hai chữ Khẩu ở trên, sau đó đến chữ Điền, chữ Nhất và một chữ Khẩu ở dưới. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Khắc họa hình ảnh các loài vật nuôi bị nhốt ở trong nhà hoặc ngoài ruộng (Điền). Súc là súc vật, thú nuôi.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>吅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('獸', '{"9000": "", "Chữ Trung Quốc": "獸", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Súc (673) Khuyển (033)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Súc (số 673 - con vật) ở bên trái chữ Khuyển (số 033 - con chó). Con chó (Khuyển) đi săn đuổi con mồi (Súc). Giải thích sự chuyển ý: Đây là chữ Hội ý. Biểu thị các loài vật hoang dã. Thú là các con vật sống hoang dã, dã thú.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰嘼犬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "嘼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犬", "Unihan_Simplified (Chữ Giản thể)": "兽", "Unihan_Traditional (Chữ Phồn thể)": "獸", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匄', '{"9000": "", "Chữ Trung Quốc": "匄", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bao (020) Vong (381)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Vong (số 381 - mất mát/trốn tránh) ở dưới chữ Bao (số 020 - bao bọc). Người đang ẩn nấp (Vong), miệng cầu xin trời phật che chở (Bao). Giải thích sự chuyển ý: Đây là chữ Hội ý. Kẻ cùng đường phải đi xin ăn, cầu xin người khác. Cái là cầu xin, cầu mong, người ăn mày.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴勹亡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "勹", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飲', '{"9000": "", "Chữ Trung Quốc": "飲", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 食 | Số nét | 12 | nét | 酉 | dậu | biểu nghĩa | bình rượu | 人 | nhân | biểu nghĩa | người | 口 | khẩu | biểu nghĩa | miệng | 飲 ban đầu là chữ hội ý trong giáp cốt văn: 酉 (bình rượu) + 人 (người) + 口 (miệng) — hình ảnh người cúi xuống bình uống rượu, có các giọt nước. Trong đồng thư, miệng tách ra và biến dạng thành 今, thân người thành 欠. Dạng lệ thư thay 酓 bằng 食, đây là hình thức hiện hành.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Đại triện | Trong giáp cốt văn, 飲 là chữ hội ý: người (人) cúi xuống bình rượu (酉) há miệng (口) uống, có các giọt biểu thị nước/nước bọt. Sau đó trong đồng thư, miệng tách khỏi thân người, biến thành 今; thân người thành 欠 (ngáp). Cả hai thành phần này cũng đồng thời làm biểu âm. Dạng lệ thư đổi 酓 thành 食 (ăn), tạo ra chữ 飲 hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thực (683) Khiếm (097)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thực (số 683 - ăn) ở bên trái chữ Khiếm (số 097 - há miệng/thiếu). Cái không thể thiếu (Khiếm) được khi ăn (Thực) đó là uống nước. Giải thích sự chuyển ý: Đây là chữ Hội ý. Dùng miệng để tiêu thụ đồ ăn thức uống lỏng. Ẩm là uống.", "Nghĩa Tiếng Việt_Xie": "uống", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "飠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "欠", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "yǐn", "Âm Hán Việt_Xie": "ẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động uống hoặc làm danh từ chỉ đồ uống trong các từ ghép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飢', '{"9000": "", "Chữ Trung Quốc": "飢", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 食 | Số nét | 10 | nét | 食 | thực | biểu nghĩa | thức ăn | 几 | cơ | biểu âm | 飢 = 食 (Thực, biểu nghĩa: thức ăn) + 几 (Cơ, biểu âm); chữ hình thanh. Bộ 食 xác nhận nghĩa liên quan đến ăn uống — thiếu ăn, đói; 几 cho âm đọc gần jī.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 飢 (jī) là chữ hình thanh: bộ 食 (thức ăn) cho nghĩa — thiếu thức ăn, đói; 几 (cơ) cho âm. Wiktionary xác nhận cấu trúc Han compound ls=psc. Có tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thực (683) Kỷ (113)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thực (số 683 - thức ăn) ở bên trái chữ Kỷ (số 113 - bản thân/cái bàn). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Kỷ chỉ âm, bộ Thực (thức ăn) chỉ ý. Cơ là tình trạng đói kém, mất mùa, thiếu thức ăn.", "Nghĩa Tiếng Việt_Xie": "đói bụng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "飠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "几", "Unihan_Simplified (Chữ Giản thể)": "饥", "Unihan_Traditional (Chữ Phồn thể)": "飢", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "cơ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ miêu tả trạng thái đói hoặc danh từ chỉ nạn đói trong văn viết. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('時', '{"9000": "", "Chữ Trung Quốc": "時", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhật (039) Tự (312)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhật (số 039 - mặt trời/ngày) ở bên trái chữ Tự (số 312 - chùa). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tự chỉ âm, bộ Nhật (mặt trời) chỉ ý. Thời là thời gian, thời điểm, thời cơ.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日寺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飯', '{"9000": "", "Chữ Trung Quốc": "飯", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 食 | Số nét | 12 | nét | 食 | thực | biểu nghĩa | ăn, thức ăn | 反 | phản | biểu âm | âm phù | 飯 là chữ hình thanh (psc): 食 (thực — ăn/thức ăn, biểu nghĩa) + 反 (phản, biểu âm). Thức ăn (食) phản lại/quay lại thành cơm chín — hình ảnh nấu nướng và thức ăn cơ bản.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Bạch thư | Tiểu triện | Wiktionary: 飯 = 食 (thức ăn, biểu nghĩa) + 反 (biểu âm), chữ hình thanh. 食 là ý phù chỉ ăn uống, 反 cho âm fàn/phạn. Kim văn, bạch thư và tiểu triện đều có dạng chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thực (683) Phản (245)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thực (số 683 - thức ăn) ở bên trái chữ Phản (số 245 - ngược lại). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Phản chỉ âm, bộ Thực (thức ăn) chỉ ý. Phạn là cơm (thức ăn chính). *(Biến âm Hán Việt: Phản -> Phạn)*", "Nghĩa Tiếng Việt_Xie": "Cơm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠反", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "反", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "饭", "Unihan_Traditional (Chữ Phồn thể)": "飯", "Pinyin_Xie": "fàn", "Âm Hán Việt_Xie": "phạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường đứng sau động từ ăn hoặc kết hợp tạo từ chỉ các bữa ăn trong ngày. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屵', '{"9000": "", "Chữ Trung Quốc": "屵", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sơn (026) Hán (128)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Sơn (số 026 - núi) ở trên chữ Hán (số 128 - sườn núi). Giải thích sự chuyển ý: Đây là chữ Hội ý. Hình ảnh sườn núi cao và dốc. Ngạc là dáng núi cao dốc, bờ vách đứng.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>山厂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喬', '{"9000": "", "Chữ Trung Quốc": "喬", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Yểu (375) Cao (313)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Yểu (số 375 - chết trẻ) ở trên chữ Cao (số 313 - cao, viết giảm nét). Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Yểu chỉ âm, chữ Cao chỉ ý. Kiều biểu thị dáng mọc lên cao mà cong (như cành cây).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>夭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "乔", "Unihan_Traditional (Chữ Phồn thể)": "喬", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('橋', '{"9000": "", "Chữ Trung Quốc": "橋", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (021) Kiều (691)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 021 - cây gỗ) ở bên trái chữ Kiều (số 691 - cao mà cong). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Kiều (cong/cao) chỉ âm, bộ Mộc (gỗ) chỉ ý. Kiều là cái cầu bắc qua sông (thường làm bằng gỗ, hình cong).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木喬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桥", "Unihan_Traditional (Chữ Phồn thể)": "橋", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('㕣', '{"9000": "", "Chữ Trung Quốc": "㕣", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bát (012) Khẩu (012)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bát (số 012 - chia ra) ở trên chữ Khẩu (số 012 - miệng/cửa hang). Hình giống nước được phân chia ra từ cái cửa hang. Giải thích sự chuyển ý: Đây là chữ Hội ý. Duyên là dòng nước chảy giữa khe núi, hoặc thuận theo dòng nước.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>八口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "口", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "八", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('廴', '{"9000": "", "Chữ Trung Quốc": "廴", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là một bộ thủ, nét kéo dài. Giải thích sự chuyển ý: Đây là chữ Tượng hình/Chỉ sự. Dẫn có nghĩa là bước đi dài, đi đường dài, bước đi đĩnh đạc.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: cbl/o", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "㇋㇏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "㇋", "Unihan_Simplified (Chữ Giản thể)": "廴", "Unihan_Traditional (Chữ Phồn thể)": "廴", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('壴', '{"9000": "", "Chữ Trung Quốc": "壴", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sĩ (034) Đậu (417)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Sĩ (số 034) nằm trên chữ Đậu (số 417). Hoặc cũng có thể nhớ là có chữ Cát (吉) ở trên. Hình cái trống tròn ở giữa, trên có đồ trang trí, dưới có giá kê. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Chú là cái trống.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>十豆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "十", "Unihan_Simplified (Chữ Giản thể)": "壴", "Unihan_Traditional (Chữ Phồn thể)": "壴", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('尌', '{"9000": "", "Chữ Trung Quốc": "尌", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chú (699) Thốn (051)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Chú (số 699 - cái trống) ở bên trái chữ Thốn (số 051 - tấc/đơn vị đo/tay). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Chú chỉ âm, bộ Thốn (bàn tay) chỉ ý. Thụ là dùng tay cầm nắm để dựng lên, thụ cũng có nghĩa là đứng thẳng, dựng đứng.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰壴寸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "寸", "Unihan_Simplified (Chữ Giản thể)": "尌", "Unihan_Traditional (Chữ Phồn thể)": "尌", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('樹', '{"9000": "", "Chữ Trung Quốc": "樹", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (021) Thụ (700)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 021 - cây) ở bên trái chữ Thụ (số 700 - đứng thẳng). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thụ (đứng thẳng) chỉ âm, bộ Mộc (cây cối) chỉ ý. Thụ là cây, hoặc hành động trồng cây, gây dựng (thụ lập).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木尌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "树", "Unihan_Traditional (Chữ Phồn thể)": "樹", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畫', '{"9000": "", "Chữ Trung Quốc": "畫", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Duật (203) Điền (057) Nhất (001)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Duật (số 203 - cây bút) ở trên chữ Điền (số 057 - ruộng) và chữ Nhất (số 001 - một vạch). Lấy bút (Duật) vẽ phong cảnh đồng ruộng (Điền) rồi lồng vào khung tranh (Nhất). Giải thích sự chuyển ý: Đây là chữ Hội ý. Họa là vẽ tranh, bức tranh. Chữ còn có âm Hoạch (kế hoạch, vạch ra).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>聿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "画", "Unihan_Traditional (Chữ Phồn thể)": "畫", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臥', '{"9000": "", "Chữ Trung Quốc": "臥", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 臣 | Số nét | 8 | nét | 臣 | thần | biểu nghĩa | mắt nhìn xuống (hình con mắt lệch) | 人 | nhân | biểu nghĩa | người | 臥 = 臣 (Thần, biểu nghĩa: mắt nhìn xuống) + 人 (Nhân, biểu nghĩa: người); chữ hội ý — người cúi người, mắt nhìn xuống đất, gợi tư thế nằm xuống.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Bạch thư | Tiểu triện | Theo Wiktionary, 臥 là chữ hội ý (hội ý): 臣 mô phỏng con mắt nhìn xuống, 人 là người. Hợp lại chỉ người nằm rạp, mắt nhắm hoặc nhìn xuống đất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thần (705) Bốc (087)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thần (số 705 - bề tôi) ở bên trái chữ Bốc (số 087 - bói toán). Kẻ bề tôi (Thần) giỏi bói toán (Bốc) thường nằm nhàn hạ. Giải thích sự chuyển ý: Đây là chữ Hội ý. Ngọa biểu thị tư thế nằm nghỉ, nằm xuống.", "Nghĩa Tiếng Việt_Xie": "nằm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰臣人", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "人", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "臣", "Unihan_Simplified (Chữ Giản thể)": "卧", "Unihan_Traditional (Chữ Phồn thể)": "臥", "Pinyin_Xie": "wò", "Âm Hán Việt_Xie": "ngọa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ tư thế nằm hoặc làm tính từ trong các từ ghép như ngọa thất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卬', '{"9000": "", "Chữ Trung Quốc": "卬", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chủy (046) Tiết (142)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Có chữ Tiết (số 142 - đốt tre/tiết tháo) ở bên phải, phần bên trái là chữ Chủy (biến thể giống nét của 卯/Công). Theo quan niệm Nho giáo, cuộc sống đạo hạnh tiết tháo là mục đích của người quân tử. Giải thích sự chuyển ý: Đây là chữ Hội ý. Ngang là từ dùng để xưng hô (ta, tôi) mang ý nghĩa khích lệ sự cao ngạo, hiên ngang.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰卩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "卬", "Unihan_Traditional (Chữ Phồn thể)": "卬", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遊', '{"9000": "", "Chữ Trung Quốc": "遊", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 12 | nét | 辵 | xước | biểu nghĩa | đi, di chuyển (bộ辶) | 斿 | du | biểu âm | lá cờ bay phất phới — cho âm đọc | 遊 là chữ hình thanh: 辵/辶 (Xước, biểu nghĩa — di chuyển, đi lại) + 斿 (Du, biểu âm). Wiktionary xác nhận: {{Han compound|辵|斿|c1=s|c2=p|t1=walk|ls=psc}}. Chữ truyền thống của 游, chỉ sự du ngoạn, đi dạo.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | 遊 là chữ hình thanh gồm 辵 (đi, di chuyển — biểu nghĩa) và 斿 (biểu âm, âm yóu). 斿 vốn mô tả lá cờ bay phất phới, khi kết hợp với bộ 辵 tạo ra ý nghĩa di chuyển tự do như cờ bay. Chữ truyền thống, dạng giản thể là 游 (thường dùng cho bơi lội). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (182) Du (217)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 182 - bước đi/dừng lại) ôm lấy chữ Du (số 217 - cờ đuôi nheo/con thoi). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Du chỉ âm, bộ Xước (đi) chỉ ý. Du là đi chơi, ngắm cảnh lúc đi lúc nghỉ (du ngoạn).", "Nghĩa Tiếng Việt_Xie": "đi chơi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶斿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "yóu", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước danh từ chỉ địa điểm hoặc kết hợp với động từ khác để chỉ hoạt động vui chơi, di chuyển. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虍', '{"9000": "", "Chữ Trung Quốc": "虍", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là hình cái vằn vện ở lông con hổ. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Hô (hay Hổ) là bộ thủ dùng để chỉ con hổ, con cọp.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴七", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "虍", "Unihan_Traditional (Chữ Phồn thể)": "虍", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('𧇎', '{"9000": "", "Chữ Trung Quốc": "𧇎", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hô (713) Đậu (714)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hô (số 713 - con hổ) ở trên chữ Đậu (số 714 - đồ cúng tế). Ý chỉ rằng cái chén đựng lễ vật (Đậu) được đặt trước tượng hình con hổ (Hô). Giải thích sự chuyển ý: Đây là chữ Hội ý. Hi là tên một loại đồ dùng làm bằng đất nung dùng để cúng tế.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虎合", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虎", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戲', '{"9000": "", "Chữ Trung Quốc": "戲", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hi (715) Qua (537)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hi (số 715 - đồ cúng/chỉ âm) ở bên trái chữ Qua (số 537 - vũ khí/giáo mác). Cầm vũ khí (Qua) diễn trò đánh nhau trước đồ cúng (Hi). Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Hi chỉ âm, chữ Qua chỉ ý. Hí là vui chơi, diễn trò, kịch (du hí, diễn hí).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰䖒戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䖒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "戈", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滾', '{"9000": "", "Chữ Trung Quốc": "滾", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (041) Cổn (723)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 041 - nước) ở bên trái chữ Cổn (số 723 - áo lễ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cổn chỉ âm, bộ Thủy chỉ ý. Cổn là dòng nước chảy cuồn cuộn, lăn, lộn (như nước cuộn).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵袞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "袞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滚", "Unihan_Traditional (Chữ Phồn thể)": "滾", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐵', '{"9000": "", "Chữ Trung Quốc": "鐵", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 21 | nét | 金 | kim | biểu nghĩa | kim loại | 鐵 là chữ hình thanh (psc): 金 (kim, biểu nghĩa: kim loại) + 𢧤 (biểu âm, không còn dùng độc lập). Bộ 金 chỉ rõ đây là kim loại; 𢧤 cung cấp âm đọc. Theo Thuyết Văn Giải Tự, dạng gốc là 𨮯 với 大 ở trên, bộ phận biểu âm ban đầu không phải 𢧜. Tiểu triện và lục thư thông còn lưu.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | 鐵 (hình thanh): 金 (kim loại, biểu nghĩa) + 𢧤 (biểu âm). Theo Thuyết Văn Giải Tự, dạng gốc là 𨮯 với bộ 大 ở trên, bộ phận biểu âm gốc không phải 𢧜. Sau quá trình diễn biến, hình thể thay đổi. Tiểu triện và lục thư thông còn lưu dạng gốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (223) Tái (247) Trình (725)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 223 - kim loại) ở bên trái chữ Tái (số 247 - tai họa, viết giảm nét) và chữ Trình (số 725 - đệ trình). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thiết (𢧜 - bộ phận bên phải) chỉ âm, bộ Kim chỉ ý. Thiết là kim loại sắt, cứng như sắt.", "Nghĩa Tiếng Việt_Xie": "sắt, Fe", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "铁", "Unihan_Traditional (Chữ Phồn thể)": "鐵", "Pinyin_Xie": "tiě", "Âm Hán Việt_Xie": "thiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Làm danh từ chỉ chất sắt hoặc làm tính từ bổ nghĩa để chỉ sự cứng rắn, kiên quyết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('還', '{"9000": "", "Chữ Trung Quốc": "還", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 16 | nét | 辵 | sước | biểu nghĩa | đi, bước (bộ 辶) | 睘 | quán | biểu âm | nhìn vòng quanh (phonetic) | 還 là chữ hình thanh: 辵 (Sước, bộ 辶 — biểu nghĩa: đi, bước chân) + 睘 (Quán, biểu âm). Wiktionary xác nhận: 辵 (walk) + 睘 (phonetic) = to go back, to return. Chữ hình thanh về hành động đi về, trở lại.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 還 (huán) nghĩa là trở lại, hoàn trả. Đọc hái/hái nghĩa là vẫn còn, còn nữa. Wiktionary: 辵 (đi bộ, biểu nghĩa) + 睘 (biểu âm) = đi trở về. Dạng giản thể 还 đơn giản hóa đáng kể. Phồn thể 還 bảo tồn cấu trúc hình thanh đầy đủ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (182) Hồi (136)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Giống chữ Viễn (遠 - xa), khi chúng ta thay phần Thổ bằng chữ Hồi (số 136 - quay về). Viễn là đi xa, còn Hoàn là từ nơi xa quay trở về. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hoàn (睘) chỉ âm, bộ Xước (đi) chỉ ý. Hoàn là quay trở về, trở lại, hoàn lại.", "Nghĩa Tiếng Việt_Xie": "Cũng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶睘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "还", "Unihan_Traditional (Chữ Phồn thể)": "還", "Pinyin_Xie": "hái", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Chữ này làm động từ chỉ sự quay lại, trả lại hoặc làm phó từ chỉ trạng thái tiếp diễn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('環', '{"9000": "", "Chữ Trung Quốc": "環", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngọc (728) Hoàn (睘)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngọc (số 728 - đá quý) ở bên trái chữ Hoàn (睘 - viết giảm nét/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hoàn (睘) chỉ âm, bộ Ngọc chỉ ý. Hoàn là cái vòng bằng ngọc, cái vòng (tuần hoàn, hoàn cảnh).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王睘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "环", "Unihan_Traditional (Chữ Phồn thể)": "環", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('癶', '{"9000": "", "Chữ Trung Quốc": "癶", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình hai bàn chân vắt chéo, chân trái vắt qua phải, chân phải vắt qua trái khiến bước đi không thuận. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Bát là hai bàn chân bẹt ra đối nghịch nhau, gạt ra.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴刁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "癶", "Unihan_Traditional (Chữ Phồn thể)": "癶", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('頁', '{"9000": "", "Chữ Trung Quốc": "頁", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 頁 | Số nét | 9 | nét | 首 | thủ | biểu nghĩa | đầu người | 卩 | tiết | biểu nghĩa | tư thế quỳ | 頁 = 首 (Thủ, đầu người) + 卩 (Tiết, tư thế quỳ); chữ tượng hình/hội ý (ls=p). Toàn bộ chữ vẽ đầu người trên thân đang quỳ — nhấn mạnh phần đầu. Về sau dùng làm bộ thủ trong các chữ liên quan đến đầu.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Bạch thư | Đại triện | Tiểu triện | 頁 và 首 (thủ — đầu) ban đầu là cùng một chữ tượng hình, cùng nghĩa ''đầu người''. Điểm khác biệt là 頁 vẽ cả thân người (đang quỳ) bên dưới đầu, trong khi 首 chỉ vẽ phần đầu. Về sau 頁 được dùng thay cho 葉 (lá, trang giấy) — là nghĩa chính ngày nay. Nghĩa gốc ''đầu'' được bảo lưu trong bộ thủ 頁 ở các chữ như 頭 (đầu), 頸 (cổ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (001) Tự (047) Bát (012)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhất (số 001), chữ Tự (số 047 - mũi/tự mình) và chữ Bát (số 012 - hai chân). Hình người lộ rõ cái đầu, cái mắt và đôi chân, trong đó con mắt/mũi được lấy để thể hiện cái đầu. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Hiệt là cái đầu. Thường làm bộ thủ cho các chữ liên quan đến đầu cổ.", "Nghĩa Tiếng Việt_Xie": "tờ giấy, trang giấy", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>丆貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "页", "Unihan_Traditional (Chữ Phồn thể)": "頁", "Pinyin_Xie": "yè", "Âm Hán Việt_Xie": "hiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường làm lượng từ đứng sau số từ để đếm số trang sách hoặc tài liệu. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('頭', '{"9000": "", "Chữ Trung Quốc": "頭", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 頁 | Số nét | 16 | nét | 豆 | đậu | biểu âm | (biểu âm) | 頁 | hiệt | biểu nghĩa | đầu người | 頭 = 豆 (Đậu, biểu âm) + 頁 (Hiệt, biểu nghĩa: đầu người); chữ hình thanh. Đây là dạng truyền thống, giản thể là 头.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Chữ hình thanh: 頁 (hiệt) biểu nghĩa chỉ đầu người; 豆 (đậu) cho âm đọc. Dạng chữ truyền thống 頭 có trong tiểu triện. Nghĩa gốc và phổ biến nhất: đầu người, đầu vật; mở rộng sang nghĩa đầu tiên, người đứng đầu. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Đậu (714) Hiệt (733)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Đậu (số 714 - cái bát/chỉ âm) ở bên trái bộ Hiệt (số 733 - cái đầu). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đậu chỉ âm, bộ Hiệt chỉ ý. Đầu là cái đầu, phần phía trên, đỉnh ngọn.", "Nghĩa Tiếng Việt_Xie": "cái đầu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豆頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "頁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豆", "Unihan_Simplified (Chữ Giản thể)": "头", "Unihan_Traditional (Chữ Phồn thể)": "頭", "Pinyin_Xie": "tóu", "Âm Hán Việt_Xie": "đầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Trợ từ | 助词 | Làm danh từ chỉ bộ phận cơ thể, lượng từ cho gia súc hoặc hậu tố danh từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('燈', '{"9000": "", "Chữ Trung Quốc": "燈", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hỏa (178) Đăng (735)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hỏa (số 178 - lửa) ở bên trái chữ Đăng (số 735 - bước lên). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đăng (lên) chỉ âm, bộ Hỏa (lửa) chỉ ý. Đăng là ngọn đèn, bó đuốc.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火登", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "登", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "灯", "Unihan_Traditional (Chữ Phồn thể)": "燈", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絨', '{"9000": "", "Chữ Trung Quốc": "絨", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 12 | nét | 絨 | nhung | tượng hình | vải nhung, lông mịn; bộ 糸 | 絨 thuộc bộ 糸 (mịch, sợi/tơ). Wiktionary chỉ ghi nhận chữ truyền thống mà không có phân tích thành phần chi tiết. Bộ 糸 biểu nghĩa (vải/sợi). Giản thể là 绒.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Wiktionary ghi nhận cấu trúc nhưng không cung cấp phân tích nguồn gốc. Bộ 糸 (sợi/tơ) biểu nghĩa, gợi ý chất liệu vải mịn. Nghĩa gốc: vải nhung, vải có lông mịn mặt; cũng chỉ lông tơ mềm. Chữ truyền thống, giản thể là 绒. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (372) Nhung (738)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 372 - sợi tơ) ở bên trái chữ Nhung (số 738 - chiến tranh). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nhung (chiến tranh) chỉ âm, bộ Mịch (sợi tơ) chỉ ý. Nhung là thứ vải dệt bằng lông vũ, vừa dày vừa ấm.", "Nghĩa Tiếng Việt_Xie": "nhung, bằng lông thú", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹戎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "绒", "Unihan_Traditional (Chữ Phồn thể)": "絨", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "nhung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ chất liệu vải nhung hoặc sợi lông tơ mịn của động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黽', '{"9000": "", "Chữ Trung Quốc": "黽", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình con ếch đang ngồi với cái bụng to và các chân bám dưới đất. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Mãnh là con ếch, con nhái, con ngóe.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𦥑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "黾", "Unihan_Traditional (Chữ Phồn thể)": "黽", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繩', '{"9000": "", "Chữ Trung Quốc": "繩", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 19 | nét | 糸 | mịch | biểu nghĩa | tơ, sợi | 黽 | mãnh | biểu âm | con cóc — cho âm | 繩 = 糸 (Mịch, biểu nghĩa: tơ/sợi) + 黽 (Mãnh, biểu âm); chữ hình thanh. Phần 糸 gợi vật liệu dạng sợi, phần 黽 cho âm shéng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary: 繩 là chữ hình thanh, gồm 糸 (biểu nghĩa: tơ/sợi) và 黽 (biểu âm). Tiểu triện xác nhận cấu trúc này. Nghĩa gốc là dây thừng, dây buộc; mở rộng sang nghĩa đo lường, kiềm chế. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (372) Mãnh (740)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 372 - sợi dây) ở bên trái chữ Mãnh (số 740 - con ếch). Dùng sợi dây (Mịch) để buộc con ếch (Mãnh) lại. Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Thằng/Mãnh chỉ âm, bộ Mịch chỉ ý. Thằng là sợi dây, dây thừng.", "Nghĩa Tiếng Việt_Xie": "dây thừng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹黽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "绳", "Unihan_Traditional (Chữ Phồn thể)": "繩", "Pinyin_Xie": "shéng", "Âm Hán Việt_Xie": "thằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ dây thừng hoặc làm động từ trong các từ ghép chỉ sự ước thúc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厷', '{"9000": "", "Chữ Trung Quốc": "厷", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hựu (208) Tư (071)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hựu (số 208 - bàn tay) ở trên chữ Tư (số 071 - riêng). Hình cái bắp tay ở trên cánh tay gập lại. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Quăng là cánh tay, bắp tay vươn ra.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𠂇厶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠂇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厶", "Unihan_Simplified (Chữ Giản thể)": "厷", "Unihan_Traditional (Chữ Phồn thể)": "厷", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷄', '{"9000": "", "Chữ Trung Quốc": "鷄", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hề (746) Điểu (172)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hề (số 746 - nô tì/chỉ âm) ở bên trái chữ Điểu (số 172 - con chim). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hề chỉ âm, bộ Điểu chỉ ý. Kê là con gà. (Ghi chú: Có thể viết bằng chữ Truy thay cho chữ Điểu -> 雞).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰奚鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鷄", "Unihan_Traditional (Chữ Phồn thể)": "鷄", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('爿', '{"9000": "", "Chữ Trung Quốc": "爿", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là một nửa chữ Mộc (cây gỗ) ở bên trái. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Khi chia chữ Mộc ra làm đôi theo chiều dọc thì nửa bên trái gọi là Tường (mảnh ván trái), nửa bên phải gọi là Phiến.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴片", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "丬", "Unihan_Traditional (Chữ Phồn thể)": "爿", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寽', '{"9000": "", "Chữ Trung Quốc": "寽", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trảo (241) Thốn (051)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Trảo (số 241 - bàn tay úp) ở trên chữ Thốn (số 051 - bàn tay, tấc). Giải thích sự chuyển ý: Đây là chữ Hội ý. Dùng 5 ngón tay (Trảo) để nắm chặt một vật (Thốn). Luật là nắm giữ, vuốt ve.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>爫寸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "爫", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('將', '{"9000": "", "Chữ Trung Quốc": "將", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tường (748) Nhục (285) Thốn (051)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tường (số 748 - ván gỗ) ở bên trái chữ Nhục (số 285 - thịt) và chữ Thốn (số 051 - tay cầm). Tay cầm (Thốn) miếng thịt (Nhục) đặt trên tấm ván gỗ (Tường) để chuẩn bị làm lễ tế thần. Giải thích sự chuyển ý: Đây là chữ Hội ý. Tương nghĩa là chuẩn bị, sắp tới (tương lai). Chữ có một âm đọc là Tướng mang nghĩa người cầm đầu, tướng quân.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰爿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "将", "Unihan_Traditional (Chữ Phồn thể)": "將", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臱', '{"9000": "", "Chữ Trung Quốc": "臱", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tự (756) Huyệt (125) Phương (128)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tự (số 756 - bản thân mình) ở trên chữ Huyệt (số 125 - cái hang) và chữ Phương (số 128 - vuông vắn). Đào một cái huyệt vuông vắn chôn cất chính mình (Tự) xong xuôi thì không còn thấy bóng dáng nữa. Giải thích sự chuyển ý: Đây là chữ Hội ý. Biên là không còn nhìn thấy nữa, vắng bóng.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>自", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邊', '{"9000": "", "Chữ Trung Quốc": "邊", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 18 | nét | 辶 | biểu nghĩa | đi bộ, chuyển động | 臱 | biểu âm | 邊 = 辶 (bộ辵 viết tắt, biểu nghĩa: đi, chuyển động) + 臱 (biểu âm). Chữ hình thanh: bộ辵 (辶) gợi ý ranh giới di chuyển, biên giới; 臱 cho âm. Bộ辵 được thêm vào trong giai đoạn kim văn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Bạch thư | Theo Wiktionary: 邊 vốn là chữ 臱, sau được thêm bộ辵 (辶) trong giai đoạn kim văn. Chữ hình thanh: 辵 (chuyển động, đi — biểu nghĩa) + 臱 (biểu âm). Xuất hiện từ giáp cốt văn và bạch thư. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (182) Biên (757)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 182 - bước đi) và chữ Biên (số 757 - vắng bóng/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Biên (臱) chỉ âm, bộ Xước chỉ ý. Biên là đường viền, bờ sông, nơi giáp ranh (biên giới, biên cương).", "Nghĩa Tiếng Việt_Xie": "bên, phía; bờ, rịa, ven, mép, vệ, viền, cạnh; biên giới; giới hạn, chừng mực; ở gần, bên cạnh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶臱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "边", "Unihan_Traditional (Chữ Phồn thể)": "邊", "Pinyin_Xie": "biān", "Âm Hán Việt_Xie": "biên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ chỉ phương vị | 方位词 | Thường làm danh từ chỉ biên giới, giới hạn hoặc làm từ chỉ phương vị để xác định vị trí bên cạnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ chỉ phương vị | 方位词 | Chỉ vị trí và đứng SAU danh từ — 桌子上, 家里 — chứ không đứng trước như ''trên bàn'', ''trong nhà''. Thường đi cùng 在.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槳', '{"9000": "", "Chữ Trung Quốc": "槳", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tướng (750) Mộc (075)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tướng/Tương (số 750 - chỉ âm) ở trên bộ Mộc (số 075 - cây gỗ). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tương chỉ âm, bộ Mộc chỉ ý. Tương là cái mái chèo làm bằng gỗ.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>將木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "將", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桨", "Unihan_Traditional (Chữ Phồn thể)": "槳", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('後', '{"9000": "", "Chữ Trung Quốc": "後", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 彳 | Số nét | 9 | nét | 彳 | xích | biểu nghĩa | bước đi, hành động | 幺 | yêu | biểu nghĩa | sợi dây nhỏ/ràng buộc | 夂 | tri | biểu nghĩa | bàn chân đi chậm | 後 là hội ý: trong giáp cốt văn gồm 幺 (sợi dây) + 夊 (bàn chân) — bàn chân bị dây trói, đi chậm/bị tụt lại phía sau. Sau thêm 彳 (bước đi) để nhấn mạnh hành động. Chữ hội ý điển hình.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Theo Wiktionary, trong giáp cốt văn 後 là hội ý: 幺 (sợi dây) + 夊 (bàn chân) — hình ảnh bàn chân bị dây trói, tụt lại phía sau. Bộ 彳 được thêm vào sau để làm rõ nghĩa ''chuyển động''. Dạng giản thể 后 là một chữ khác (có nghĩa ''hoàng hậu''). Hán-Việt: ''hậu''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xích (198) Yêu (014) Truy (183)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xích (số 198 - bước ngắn), chữ Yêu (số 014 - nhỏ bé) và bộ Truy (số 183 - đi sau). Bởi nhỏ bé (Yêu) nên bước đi ngắn, chậm chạp (Xích + Truy) nên phải đến sau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Hậu là đến sau, phía sau (hậu quả, hậu phương).", "Nghĩa Tiếng Việt_Xie": "mặt sau", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "hòu", "Âm Hán Việt_Xie": "hậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ chỉ phương vị | 方位词 | Danh từ | 名词 | Tính từ | 形容词 | Thường làm từ chỉ phương vị đứng sau danh từ hoặc làm tính từ bổ nghĩa cho danh từ. | Từ chỉ phương vị | 方位词 | Chỉ vị trí và đứng SAU danh từ — 桌子上, 家里 — chứ không đứng trước như ''trên bàn'', ''trong nhà''. Thường đi cùng 在. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臨', '{"9000": "", "Chữ Trung Quốc": "臨", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 臣 | Số nét | 17 | nét | 臣 | thần | biểu nghĩa | con mắt (theo Wiktionary: mắt nhìn xuống) | 人 | nhân | biểu nghĩa | người | 品 | phẩm | biểu âm | vật phẩm, đồ vật | 臨 = 臣 (Thần, biểu nghĩa: mắt nhìn xuống) + 人 (Nhân, biểu nghĩa: người) + 品 (Phẩm, thứ ba); chữ hội ý (có cách hiểu phụ là hình thanh). Wiktionary: người (人) nhìn xuống vật phẩm (品) bằng con mắt (臣) — hình ảnh bề trên đến thị sát/giám sát.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Chữ hội ý: 臣 (mắt hướng xuống) + 人 (người) + 品 (vật phẩm) — người đứng trên nhìn xuống vật. Wiktionary xác nhận ls=ic nhưng cũng ghi cách phân tích thay thế là psc (臥+品). 臨 mang nghĩa tiếp cận, đến gần, bề trên giám sát, hoặc sao chép (臨帖 — tập viết theo mẫu). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thần (705) Nhân (009) Phẩm (335)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thần (số 705 - bề tôi), chữ Nhân (số 009 - người) và chữ Phẩm (số 335 - đồ vật/chỉ âm). Hình một người từ trên cao cúi xuống, con mắt mở to xem xét các vật phẩm. Giải thích sự chuyển ý: Đây là chữ Hội ý. Lâm là ở trên cao nhìn xuống dưới, hoặc đi đến đâu đó (quang lâm).", "Nghĩa Tiếng Việt_Xie": "chuyên nghiệp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰臣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "临", "Unihan_Traditional (Chữ Phồn thể)": "臨", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Giới từ | 介词 | Thường làm động từ chỉ sự đến gần hoặc phó từ chỉ hành động sắp xảy ra. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('監', '{"9000": "", "Chữ Trung Quốc": "監", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 皿 | Số nét | 14 | nét | 臥 | biểu nghĩa | người nhìn xuống (mắt nhấn mạnh) | 皿 | mãnh | biểu nghĩa | đồ đựng, bình chứa | 監 là chữ hội ý (ls=ic): hình người cúi xuống nhìn vào đồ đựng (bình/chậu). Dạng ban đầu: người với mắt nhấn mạnh đang nhìn vào bình nước — như nhìn gương. Về sau bình nước biến thành 血, rồi thêm nét di chuyển xuống dưới 人. Nguyên hình của 鑑 (gương).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Theo Wiktionary (Ji Xusheng, 2004), 監 gồm 臥 (người cúi với mắt nhấn mạnh, biểu nghĩa) + 皿 (bình chứa nước, biểu nghĩa): người nhìn xuống bình nước = nhìn gương. Đây là dạng gốc của 鑑 (gương soi). Phần bình nước sau bị biến thành 血, rồi nét thêm di chuyển xuống dưới phần người. Nghĩa phái sinh: giám sát, giám ngục. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thần (705) Nhân (009) Mãnh (366)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thần (bề tôi), chữ Nhân (người), chữ Nhất và chữ Mãnh (chậu nước). Người đứng cúi đầu mở to mắt nhìn vào chậu nước để soi xét. Giải thích sự chuyển ý: Đây là chữ Hội ý. Giám là soi xét, giám sát, trông coi (giám đốc).", "Nghĩa Tiếng Việt_Xie": "giám sát", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "监", "Unihan_Traditional (Chữ Phồn thể)": "監", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "giam, giám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động trông coi hoặc danh từ chỉ nhà giam. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籃', '{"9000": "", "Chữ Trung Quốc": "籃", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (424) Giám (767)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 424 - tre trúc) ở trên chữ Giám (số 767 - chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Giám chỉ âm, bộ Trúc chỉ ý. Lam là cái giỏ, cái rổ đan bằng tre trúc (làn).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>⺮監", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "監", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篮", "Unihan_Traditional (Chữ Phồn thể)": "籃", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('買', '{"9000": "", "Chữ Trung Quốc": "買", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 12 | nét | 网 | võng | biểu nghĩa | lưới | 貝 | bối | biểu nghĩa | tiền, vỏ sò | 買 = 网 (Võng: lưới) + 貝 (Bối: tiền/vỏ sò); chữ hội ý. Dùng lưới (网) để vớt tiền (貝) về — hình ảnh mua hàng thu về của cải. Wiktionary cũng ghi nhận giả thuyết hình thanh: 羅 + 貝 theo Baxter & Sagart.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Đại triện | Theo Wiktionary, 買 nguyên là chữ hội ý: 网 (lưới) + 貝 (vỏ sò/tiền). Dùng lưới vớt tiền về — nghĩa là mua. Dạng cổ nhất là 𧵽. Baxter & Sagart đề xuất hình thanh 羅+貝 nhưng đây là giả thuyết, không phải quan điểm chính thống. Chữ truyền thống, có hình kim văn và đại triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Võng (122) Bối (225)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Võng (số 122 - cái lưới) ở trên chữ Bối (số 225 - tiền). Mang lưới đi gom thu vơ vét tiền bạc. Giải thích sự chuyển ý: Đây là chữ Hội ý. Mãi là mua lấy đồ vật (mãi mãi = mua bán).", "Nghĩa Tiếng Việt_Xie": "mua, sắm, tậu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>罒貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "买", "Unihan_Traditional (Chữ Phồn thể)": "買", "Pinyin_Xie": "mǎi", "Âm Hán Việt_Xie": "mãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ vật được mua để cấu tạo cụm động tân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瓈', '{"9000": "", "Chữ Trung Quốc": "瓈", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngọc (728) Lê (779)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngọc (số 728 - đá quý) ở bên trái chữ Lê (số 779 - chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Lê chỉ âm, bộ Ngọc chỉ ý. Lê là chất thủy tinh, pha lê.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王黎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('牽', '{"9000": "", "Chữ Trung Quốc": "牽", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Huyền (786) Mịch (021) Ngưu (274)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Huyền (số 786 - màu đen) ở trên bộ Mịch (số 021 - khăn trùm) và bộ Ngưu (số 274 - con bò). Cầm lấy cái dây màu đen (Huyền) buộc mũi con bò (Ngưu) để dắt ra khỏi chuồng (Mịch). Giải thích sự chuyển ý: Đây là chữ Hội ý. Khiên là dắt, lôi kéo, làm liên lụy đến người khác.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>玄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "牵", "Unihan_Traditional (Chữ Phồn thể)": "牽", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('爲', '{"9000": "", "Chữ Trung Quốc": "爲", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trảo (241) Tượng (000)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Trảo (số 241 - bàn tay úp) ở trên hình con voi (Tượng - viết biến thể). Hình bàn tay (Trảo) đang chỉ dẫn con voi dùng vòi nâng vật nặng. Giải thích sự chuyển ý: Đây là chữ Hội ý. Vi có nghĩa là làm, tạo ra (hành vi). Đọc là Vị thì có nghĩa là vì, bởi vì, giúp cho.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>爫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冏', '{"9000": "", "Chữ Trung Quốc": "冏", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (021) Bát (012) Khẩu (012)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 021 - biên giới/khung) bao bên ngoài chữ Bát (số 012 - chia ra) và bộ Khẩu (số 012 - miệng). (Mô phỏng hình khung cửa sổ sáng sủa). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Quýnh là sáng tỏ, rõ rệt.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冂㕣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㕣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冂", "Unihan_Simplified (Chữ Giản thể)": "冏", "Unihan_Traditional (Chữ Phồn thể)": "冏", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巂', '{"9000": "", "Chữ Trung Quốc": "巂", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sơn (096) Truy (580) Quýnh (791)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Sơn (số 096 - núi) ở trên bộ Truy (số 580 - con chim) và chữ Quýnh (số 791 - sáng tỏ). Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Huề là tên một loại chim (chim cuốc, chim tử quy).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "巂", "Unihan_Traditional (Chữ Phồn thể)": "巂", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('攜', '{"9000": "", "Chữ Trung Quốc": "攜", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (207) Huề (792)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 207 - tay) ở bên trái chữ Huề (số 792 - chim cuốc/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Huề chỉ âm, bộ Thủ chỉ ý. Huề là nắm tay, dắt đi, mang theo bên mình (đề huề).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌巂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('長', '{"9000": "", "Chữ Trung Quốc": "長", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 長 | Số nét | 8 | nét | 長 | trường | tượng hình | người già tóc dài — hình ảnh trường thọ | 長 là chữ tượng hình — hình vẽ người già với mái tóc dài. Wiktionary ghi {{liushu|p}}: người già tóc dài. Dạng cổ còn lưu trong chữ 镸. So sánh với bộ trên của 老 và 考.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Tiểu triện | Theo Wiktionary, 長 là chữ tượng hình: hình vẽ người già với mái tóc dài. Giáp cốt văn, kim văn và tiểu triện đều lưu dạng này. Nghĩa gốc là dài, về sau mở rộng thành lớn tuổi, lớn hơn, đứng đầu. So sánh bộ trên của 老 và 考 — đều có hình người già. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (001) Thần (796)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhất (số 001 - một) gạch ngang qua thân chữ Thần (số 796 - thời gian/sấm chớp). Tượng trưng cho dòng thời gian bất tận vô thủy vô chung. Giải thích sự chuyển ý: Đây là chữ Hội ý. Trường có nghĩa là dài lâu. Đọc âm Trưởng có nghĩa là lớn lên, người đứng đầu.", "Nghĩa Tiếng Việt_Xie": "to, lớn; đứng đầu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "长", "Unihan_Traditional (Chữ Phồn thể)": "長", "Pinyin_Xie": "zhǎng", "Âm Hán Việt_Xie": "trường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ đứng trước danh từ để chỉ đặc tính dài hoặc làm danh từ chỉ sở trường. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餘', '{"9000": "", "Chữ Trung Quốc": "餘", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 食 | Số nét | 15 | nét | 食 | thực | biểu nghĩa | thức ăn | 余 | dư | biểu âm | tôi (đại từ cổ) | 餘 = 食 (Thực, biểu nghĩa: thức ăn) + 余 (Dư, biểu âm). Chữ hình thanh: bộ 食 gợi thức ăn còn thừa; 余 cho âm dư.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary: 餘 là chữ hình thanh gồm 食 (biểu nghĩa: thức ăn) và 余 (biểu âm). Nguyên nghĩa gắn với thức ăn còn dư lại sau bữa ăn, mở rộng sang ý ''còn thừa'', ''dôi ra''. Dạng giản thể 余 được dùng thay thế trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thực (683) Dư (802)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thực (số 683 - đồ ăn) ở bên trái chữ Dư (số 802 - tôi/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Dư chỉ âm, bộ Thực chỉ ý. Dư là có thừa lương thực, có dư (dư thừa).", "Nghĩa Tiếng Việt_Xie": "dư thừa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠余", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "余", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "馀", "Unihan_Traditional (Chữ Phồn thể)": "餘", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "dư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Số từ | 数词 | Chữ này thường đứng sau số từ để chỉ số lượng lẻ hoặc làm tính từ biểu thị sự dư thừa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喿', '{"9000": "", "Chữ Trung Quốc": "喿", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phẩm (335) Mộc (075)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Phẩm (số 335 - ba miệng) ở trên bộ Mộc (số 075 - cây cối). Hình ảnh bầy chim mở miệng kêu trên cây. Giải thích sự chuyển ý: Đây là chữ Hội ý. Táo là ồn ào, tiếng chim kêu.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>品木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "品", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "喿", "Unihan_Traditional (Chữ Phồn thể)": "喿", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陽', '{"9000": "", "Chữ Trung Quốc": "陽", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 阜 | Số nét | 11 | nét | 阜 | biểu nghĩa | gò đất, đồi | 昜 | biểu âm | ánh nắng | 陽 là chữ hình thanh: 阜 (biểu nghĩa: gò đất, đồi) + 昜 (biểu âm: ánh nắng). Theo Wiktionary, 昜 là dạng gốc của chữ này — sau đó 阜 được thêm vào. Chỉ phía đối diện với mặt trời (sườn đồi hướng nam, phía dương).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 陽 (Hán-Việt: dương) là chữ hình thanh theo Wiktionary: 阜 (gò đất) + 昜 (Dương, biểu âm: ánh nắng). Ban đầu chỉ viết là 昜 — phía mặt trời chiếu vào. 阜 được thêm vào sau để cụ thể hóa sườn đồi hướng nam, phía dương. Khái niệm âm-dương (陰陽) là nền tảng của triết học Trung Hoa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phụ (180) Đán (103) Vật (144)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Phụ (số 180 - núi đồi) ở bên trái chữ Đán (số 103 - buổi sáng) và chữ Vật (số 144 - đồ vật/viết biến thể). Mặt trời (Đán) lên cao đang chiếu sáng khắp núi đồi (Phụ) và vạn vật (Vật). Giải thích sự chuyển ý: Đây là chữ Hội ý. Dương là mặt trời, khí dương (thái dương).", "Nghĩa Tiếng Việt_Xie": "dương", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝昜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "阳", "Unihan_Traditional (Chữ Phồn thể)": "陽", "Pinyin_Xie": "yáng", "Âm Hán Việt_Xie": "dương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ mặt trời hoặc làm tính từ chỉ thuộc tính hướng sáng, thuộc dương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('場', '{"9000": "", "Chữ Trung Quốc": "場", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thổ (032) Dương (806)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thổ (số 032 - đất) ở bên trái phần bên phải của chữ Dương (Dương 昜 - mặt trời chiếu sáng/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Dương (昜) chỉ âm, bộ Thổ chỉ ý. Trường là chỗ đất rộng và bằng phẳng (quảng trường, hội trường).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土昜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "场", "Unihan_Traditional (Chữ Phồn thể)": "場", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('負', '{"9000": "", "Chữ Trung Quốc": "負", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 9 | nét | ⺈ | nhân | biểu nghĩa | người (biến thể ⺈) | 貝 | bối | biểu nghĩa | vỏ sò, tiền | 負 = ⺈ (Nhân, người) + 貝 (Bối, vỏ sò/tiền); chữ hội ý. Người mang vỏ sò — hình ảnh gánh nặng, mang vác, nợ nần.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | 負 là chữ hội ý: ⺈ (người) + 貝 (vỏ sò, tiền). Hình ảnh người mang vỏ sò trên lưng — gánh nặng, từ đó nghĩa gánh chịu, thua lỗ, số âm. Wiktionary xác nhận cấu trúc hội ý rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (009) Bối (225)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhân (số 009 - người/biến thể) ở trên chữ Bối (số 225 - tiền của). Người có tiền thì thường được kẻ khác cậy nhờ. Giải thích sự chuyển ý: Đây là chữ Hội ý. Phụ là nhờ vào, dựa vào, mang vác trên lưng.", "Nghĩa Tiếng Việt_Xie": "Tiêu cực", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>⺈貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺈", "Unihan_Simplified (Chữ Giản thể)": "负", "Unihan_Traditional (Chữ Phồn thể)": "負", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Danh từ | 名词 | Thường làm động từ mang nghĩa gánh vác, phụ lòng hoặc làm tính từ chỉ số âm trong toán học. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倉', '{"9000": "", "Chữ Trung Quốc": "倉", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tập (058) Quân (141)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tập (số 058 - tụ tập) ở trên chữ Quân (số 141 - vua/viết biến đi). Vua (Quân) thu thuế lúa của dân rồi tập hợp (Tập) cất vào trong kho. Giải thích sự chuyển ý: Đây là chữ Hội ý. Thương là nhà kho, chỗ để lưu trữ thóc lúa, hàng hóa.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>亽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "仓", "Unihan_Traditional (Chữ Phồn thể)": "倉", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槍', '{"9000": "", "Chữ Trung Quốc": "槍", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Thương (811)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây gỗ) ở bên trái chữ Thương (số 811 - cái kho/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thương chỉ âm, bộ Mộc chỉ ý. Thương là cây thương làm bằng gỗ (một loại binh khí). Ngày nay dùng để chỉ súng bắn (thương tặc).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木倉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "倉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枪", "Unihan_Traditional (Chữ Phồn thể)": "槍", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('課', '{"9000": "", "Chữ Trung Quốc": "課", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 15 | nét | 言 | ngôn | biểu nghĩa | lời nói, đánh giá | 果 | quả | biểu âm | cho âm kè/khoá | 課 là chữ hình thanh: 言 (Ngôn, biểu nghĩa — lời nói, đánh giá) + 果 (Quả, biểu âm). Wiktionary ghi: {{Han compound|言|果|ls=psc|c1=s|c2=p|t1=to say}} – to assess; to examine. Nghĩa gốc: đánh giá, kiểm tra; sau mở rộng sang bài học, môn học, thuế.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Wiktionary ghi 課 là chữ hình thanh: 言 (lời nói, đánh giá — biểu nghĩa) + 果 (biểu âm, âm kè/quả). Nghĩa gốc: đánh giá, xem xét (to assess, to examine). Mở rộng: bài học, giờ học (一課 — một bài học); thuế, định mức (課稅 — đánh thuế). Phồn thể 課; giản thể 课. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (814) Quả (100)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 814 - lời nói) ở bên trái chữ Quả (số 100 - kết quả/chỉ âm). Dùng lời nói để sát hạch người thi, đưa ra kết quả đánh giá. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quả chỉ âm, bộ Ngôn chỉ ý. Khóa là bài học, môn học, sát hạch (khóa trình).", "Nghĩa Tiếng Việt_Xie": "bài học", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "课", "Unihan_Traditional (Chữ Phồn thể)": "課", "Pinyin_Xie": "kè", "Âm Hán Việt_Xie": "khoá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ bài học hoặc lượng từ cho các bài học trong giáo trình. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('國', '{"9000": "", "Chữ Trung Quốc": "國", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vi (030) Vực (484)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Vi (số 030 - bao quanh) bao bọc bên ngoài chữ Vực (số 484 - cõi đất). Biên giới bao quanh lãnh thổ khu vực. Giải thích sự chuyển ý: Đây là chữ Hội ý. Quốc là đất nước, quốc gia.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗或", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "或", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "国", "Unihan_Traditional (Chữ Phồn thể)": "國", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冓', '{"9000": "", "Chữ Trung Quốc": "冓", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tỉnh (516) Tái (817)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tỉnh (số 516 - cái giếng/chỗ sâu) ở trên chữ Tái (số 817 - hai). Nơi sâu kín (Tỉnh) chỉ có hai vợ chồng (Tái) gặp nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Cấu là nơi kín đáo, phòng riêng của vợ chồng, cũng có ý chỉ sự gặp gỡ (giao cấu).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>井再", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "再", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "井", "Unihan_Simplified (Chữ Giản thể)": "冓", "Unihan_Traditional (Chữ Phồn thể)": "冓", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('講', '{"9000": "", "Chữ Trung Quốc": "講", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 17 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn ngữ | 冓 | cấu | biểu âm | (biểu âm) | 講 = 言 (Ngôn, biểu nghĩa: lời nói) + 冓 (Cấu, biểu âm); chữ hình thanh. Bộ 言 cho biết liên quan đến ngôn ngữ, phát biểu; 冓 cung cấp âm đọc jiǎng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Theo Wiktionary, 講 là chữ hình thanh: bộ 言 (ngôn — lời nói) biểu nghĩa, 冓 (cấu) biểu âm. Nghĩa là giảng giải, thảo luận, nói chuyện. Dùng phổ biến trong 講話 (nói chuyện), 講解 (giải thích), 講座 (bài giảng), 講義 (bài học). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (814) Cấu (818)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 814 - lời nói) ở bên trái chữ Cấu (số 818 - sâu kín/chỉ âm). Dùng lời nói để giải thích các nghĩa lý sâu xa. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cấu chỉ âm, bộ Ngôn chỉ ý. Giảng là dùng lời nói để giải thích cho người khác hiểu (giảng bài).", "Nghĩa Tiếng Việt_Xie": "giảng giải", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言冓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "讲", "Unihan_Traditional (Chữ Phồn thể)": "講", "Pinyin_Xie": "jiǎng", "Âm Hán Việt_Xie": "giảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ nội dung được diễn giải. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聽', '{"9000": "", "Chữ Trung Quốc": "聽", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 耳 | Số nét | 22 | nét | 耳 | nhĩ | biểu nghĩa | tai | 口 | khẩu | biểu nghĩa | miệng (nhiều người nói) | 聽 gốc là hội ý 𦔻: 耳 (Nhĩ, tai) + 口 (Khẩu, miệng) — lắng nghe. Về sau được viết lại dạng hình thanh: 𡈼 (biểu âm) + 耳 (biểu nghĩa) + 㥁 (biểu nghĩa). Chữ giản thể 听 hoàn toàn không liên quan — vốn nghĩa là mỉm cười. Hai loại hội ý và hình thanh đều tồn tại trong lịch sử.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Tiểu triện | 聽 gốc là hội ý 𦔻 (耳+口 — tai và miệng = nghe). Theo Wiktionary, sau đó được cải viết theo dạng hình thanh với 𡈼 biểu âm, 耳 và 㥁 biểu nghĩa. Chữ giản thể 听 vốn là chữ khác (nghĩa mỉm cười), không liên quan nguồn gốc. Giáp cốt văn và kim văn xác nhận dạng hội ý ban đầu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhĩ (213) Đức (821)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhĩ (số 213 - tai) ở bên trái chữ Đức (số 821 - đạo đức/viết biến thể). Tai nghe những lời giảng dạy đạo đức để có được cuộc sống tốt lành. Giải thích sự chuyển ý: Đây là chữ Hội ý. Thính là dùng tâm trí để lắng nghe, nghe theo (thính giác).", "Nghĩa Tiếng Việt_Xie": "nghe", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𢛳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "tīng", "Âm Hán Việt_Xie": "thinh, thính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động tiếp nhận âm thanh bằng tai hoặc tuân theo ý kiến của người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賣', '{"9000": "", "Chữ Trung Quốc": "賣", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 15 | nét | 出 | xuất | biểu nghĩa | đi ra, đưa ra ngoài | 買 | mãi | biểu âm | mua | 賣 là chữ hội ý kiêm hình thanh (ls=ic, ls2=psc): 出 (xuất — đưa ra ngoài) kết hợp với 買 (mãi — mua) để tạo nghĩa ngược lại \"bán\". 出 cũng đóng vai trò biểu âm exoactive theo Sagart (1999). Phần 出 sau này bị rút gọn thành 士 không liên quan về mặt từ nguyên.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | Theo Wiktionary, 賣 vốn là 𧷓, gồm 出 (xuất — đưa ra) + 買 (mãi — mua) theo lối hội ý: \"đưa ra ngoài những gì đã mua\" = bán. Yếu tố 出 cũng mang tính biểu âm exoactive (Sagart, 1999). Về sau 出 bị đơn giản hóa thành 士 không có liên hệ từ nguyên. Dạng phồn thể 賣 giữ nguyên cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sĩ (033) Mãi (769)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Sĩ (số 033 - kẻ sĩ) ở trên chữ Mãi (số 769 - mua). Mãi là mua của cải, Sĩ là thứ không thể mua bằng tiền (chí khí của kẻ sĩ là cái không thể đem bán). Giải thích sự chuyển ý: Đây là chữ Hội ý. Mại là bán (thương mại).", "Nghĩa Tiếng Việt_Xie": "bán", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "卖", "Unihan_Traditional (Chữ Phồn thể)": "賣", "Pinyin_Xie": "mài", "Âm Hán Việt_Xie": "mại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ đứng trước danh từ chỉ hàng hóa để biểu thị hành động bán hoặc trao đổi lấy tiền. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讀', '{"9000": "", "Chữ Trung Quốc": "讀", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 22 | nét | 言 | ngôn | biểu nghĩa | lời nói | 𧶠 | biểu âm | 讀 = 言 (Ngôn, biểu nghĩa: lời nói) + 𧶠 (biểu âm); chữ hình thanh. Phần 言 gợi nghĩa đọc—vận dụng lời nói; 𧶠 cho âm đọc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | Theo Wiktionary, 讀 là chữ hình thanh: 言 (ngôn, biểu nghĩa: lời nói) kết hợp với 𧶠 (biểu âm). Chữ này ghi lại hành động đọc—dùng tiếng nói để diễn giải văn bản viết. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (814) Mại (823)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 814 - lời nói) ở bên trái chữ Mại (số 823 - bán/chỉ âm). Để bán được hàng, kẻ bán phải dùng lời nói to tên các món hàng để người khác nghe rõ. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Mại chỉ âm, bộ Ngôn chỉ ý. Độc là đọc to rõ tiếng, từng câu từng chữ (đọc sách, độc giả).", "Nghĩa Tiếng Việt_Xie": "dấu phảy câu, dấu ngắt câu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言賣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "读", "Unihan_Traditional (Chữ Phồn thể)": "讀", "Pinyin_Xie": "dú", "Âm Hán Việt_Xie": "độc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này chủ yếu làm động từ chỉ hành động đọc, hoặc làm danh từ chỉ sự ngắt câu trong văn cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('義', '{"9000": "", "Chữ Trung Quốc": "義", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 羊 | Số nét | 13 | nét | 我 | ngã | biểu âm | tôi, cái cày/vũ khí | 羊 | dương | biểu nghĩa | dê — tốt đẹp, tốt lành | 義 = 我 (Ngã, biểu âm) + 羊 (Dương, biểu nghĩa: điều tốt đẹp, cát tường); chữ hình thanh. Bộ 羊 ở đây không có nghĩa ''con dê'' mà biểu thị ''tốt lành, đẹp đẽ'' (như trong 祥, 善, 幸).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | 義 là chữ hình thanh: 羊 biểu nghĩa ''tốt lành, đẹp đẽ'' (không phải ''con dê''), 我 biểu âm. Wiktionary ghi rõ: ''羊 here signifies \"good; beautiful; auspicious\" and not \"sheep\"''. Nghĩa gốc là ''điều đúng đắn, chính nghĩa, ý nghĩa''. Xuất hiện từ giáp cốt văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Dương (248) Ngã (324)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Dương (số 248 - con dê/chỉ âm) ở trên chữ Ngã (số 324 - ta). Chữ Dương còn có âm là Tường (điều tốt lành). Gặp điều phải đạo, tốt lành (Dương) thì ta (Ngã) nên làm. Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Dương chỉ âm, chữ Ngã chỉ ý. Nghĩa là hành động đúng với lẽ phải, đạo lý (trượng nghĩa, tình nghĩa).", "Nghĩa Tiếng Việt_Xie": "nghĩa khí", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>羊我", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "我", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "义", "Unihan_Traditional (Chữ Phồn thể)": "義", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "nghĩa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ đạo lý làm người hoặc làm tính từ bổ nghĩa cho hành động chính nghĩa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氣', '{"9000": "", "Chữ Trung Quốc": "氣", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khí (828) Mễ (453)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khí (số 828 - hơi nước) bao bên ngoài bộ Mễ (số 453 - gạo). Nấu cơm (Mễ) hơi nóng bốc lên ngùn ngụt (Khí). Giải thích sự chuyển ý: Đây là chữ Hội ý. Khí là thể khí, hiện tượng tự nhiên (như nóng, lạnh, ẩm) hoặc trạng thái tinh thần (khí sắc, dũng khí).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "米", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "气", "Unihan_Traditional (Chữ Phồn thể)": "氣", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坴', '{"9000": "", "Chữ Trung Quốc": "坴", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thổ (032) Bát (012)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bát (số 012 - tám/chia ra) ở giữa hai chữ Thổ (số 032 - đất). Hình các gò đất lớn liên tiếp nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Lục là gò đất lớn, đống đất lớn.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "坴", "Unihan_Traditional (Chữ Phồn thể)": "坴", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埶', '{"9000": "", "Chữ Trung Quốc": "埶", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lục (830) Hoàn (037)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lục (số 830 - đống đất) ở bên trái chữ Hoàn (số 037 - viên đạn). Lấy nắm đất (Lục) vo thành những viên đạn tròn (Hoàn), chúng có sức sinh động mạnh mẽ. Giải thích sự chuyển ý: Đây là chữ Hội ý. Thế là cái sức mạnh, thế lực.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰坴丸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "坴", "Unihan_Simplified (Chữ Giản thể)": "埶", "Unihan_Traditional (Chữ Phồn thể)": "埶", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('熱', '{"9000": "", "Chữ Trung Quốc": "熱", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thế (831) Hỏa (088)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thế (số 831 - sức mạnh) ở trên bộ Hỏa (số 088 - lửa/4 chấm hỏa). Sức mạnh của lửa là tạo ra sức nóng. Giải thích sự chuyển ý: Đây là chữ Hội ý. Nhiệt là nóng, ấm (khí nhiệt). Cũng có ý chỉ tinh thần hăng hái, mạnh mẽ (nhiệt tình).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>埶灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "埶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "灬", "Unihan_Simplified (Chữ Giản thể)": "热", "Unihan_Traditional (Chữ Phồn thể)": "熱", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雲', '{"9000": "", "Chữ Trung Quốc": "雲", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 雨 | Số nét | 12 | nét | 雨 | vũ | biểu nghĩa | mưa | 云 | vân | biểu âm | mây (dạng gốc, cũng cho âm) | 雲 = 雨 (Vũ, biểu nghĩa: mưa) + 云 (Vân, biểu âm và biểu nghĩa gốc); Wiktionary xếp chữ này vừa là hội ý vừa là hình thanh (ls=ic + ls2=psc). Ban đầu 云 tự nó đã có nghĩa là mây; sau thêm bộ 雨 để phân biệt. Đây là trường hợp chữ ban đầu viết là 云, rồi mở rộng thành 雲.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | 雲 ban đầu được viết là 云 — tự nó đã mô tả hình ảnh đám mây xoắn. Về sau, bộ 雨 (vũ — mưa) được thêm vào để làm rõ nghĩa, phân biệt với 云 (nói/rằng). Wiktionary xác nhận: 雨 là biểu nghĩa, 云 vừa là biểu âm vừa là hình thức gốc. Đây là ví dụ điển hình của chữ Hán phát triển qua nhiều giai đoạn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vũ (574) Vân (833)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Vũ (số 574 - mưa) ở trên chữ Vân (số 833 - chỉ âm). Đám mây thường xuất hiện khi có mưa. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Vân chỉ âm, bộ Vũ chỉ ý. Vân là đám mây trên trời (phong vân).", "Nghĩa Tiếng Việt_Xie": "Đám mây", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>雨云", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "云", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "yún", "Âm Hán Việt_Xie": "vân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước động từ để làm chủ ngữ hoặc đứng sau danh từ khác làm định ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('電', '{"9000": "", "Chữ Trung Quốc": "電", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 雨 | Số nét | 13 | nét | 雨 | vũ | biểu nghĩa | mưa | 申 | thân | biểu âm | can địa chi thứ 9 | 電 = 雨 (Vũ, biểu nghĩa: mưa) + 申 (Thân, biểu âm). Đây là chữ hình thanh, đồng thời cũng được phân tích là hội ý: 雨 (mưa) + 申 (ánh chớp dài ngoằn ngoèo). Nghĩa gốc là tia chớp trong cơn mưa.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Lụa Mã Vương Đôi | Theo Wiktionary, 電 là chữ hình thanh: 雨 (mưa) biểu nghĩa + 申 biểu âm. Đồng thời cũng có yếu tố hội ý: 申 vẽ hình tia chớp ngoằn ngoèo trong mưa. Hình kim văn, lụa Mã Vương Đôi đã được ghi nhận. Nghĩa gốc là sấm sét/chớp, phái sinh thành điện (electricity) trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vũ (574) Điền (024)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Vũ (số 574 - mưa) ở trên chữ Điền (viết biến đi thành chữ Thân 申 - có đuôi cong dài). Tia chớp (đuôi cong) xuất hiện khi trời mưa. Giải thích sự chuyển ý: Đây là chữ Hội ý (hoặc Tượng hình). Điện là sấm chớp, điện.", "Nghĩa Tiếng Việt_Xie": "điện; chớp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>雨电", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "电", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "电", "Unihan_Traditional (Chữ Phồn thể)": "電", "Pinyin_Xie": "diàn", "Âm Hán Việt_Xie": "điện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng trước các danh từ khác để tạo thành từ ghép liên quan đến điện lực hoặc thiết bị điện. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閃', '{"9000": "", "Chữ Trung Quốc": "閃", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 門 | Số nét | 10 | nét | 門 | môn | biểu nghĩa | cổng, cửa | 人 | nhân | biểu nghĩa | người | 閃 = 門 (Môn — cổng) + 人 (Nhân — người); chữ hội ý — một người chạy vụt qua cổng, tạo cảm giác chớp mắt thoáng qua. Từ hình ảnh này suy ra nghĩa: né tránh, chớp sáng, lóe lên nhanh.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 閃 là chữ hội ý: 門 (môn — cổng) + 人 (nhân — người), nghĩa là một người chạy vụt qua cổng. Từ hình ảnh thoáng qua đó suy ra: tránh né, chớp sáng, lóe lên, nhanh như chớp. Dùng trong 閃電 (sét chớp), 閃避 (né tránh), 閃光 (ánh chớp), 閃亮 (lấp lánh). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Môn (472) Nhân (009)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhân (số 009 - người) ở trong bộ Môn (số 472 - cánh cửa). Người đang nghiêng đầu qua cánh cổng nhìn trộm. Giải thích sự chuyển ý: Đây là chữ Hội ý. Thiểm là ló đầu ra nhìn trộm. Cũng có ý là chớp nháy, sáng thoáng qua (thiểm điện).", "Nghĩa Tiếng Việt_Xie": "né, nấp, tránh, lánh; chớp, loé, lấp loáng; đau sái", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門人", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "人", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "闪", "Unihan_Traditional (Chữ Phồn thể)": "閃", "Pinyin_Xie": "shǎn", "Âm Hán Việt_Xie": "thiểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ hành động né tránh nhanh hoặc ánh sáng lóe lên đột ngột. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聲', '{"9000": "", "Chữ Trung Quốc": "聲", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 耳 | Số nét | 17 | nét | 殸 | khánh | biểu âm | nhạc khí bằng đá (âm phù) | 耳 | nhĩ | biểu nghĩa | tai | 聲 là chữ hình thanh (psc): 殸 (khánh — nhạc khí đá, biểu âm) + 耳 (nhĩ — tai, biểu nghĩa). Tai nghe âm thanh phát ra từ nhạc khí đá — cấu tạo trực quan về âm thanh và cơ quan cảm nhận.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Tiểu triện | Wiktionary: 聲 = 殸 (biểu âm) + 耳 (tai, biểu nghĩa), chữ hình thanh. Giáp cốt văn đã có dạng chữ này, chứng tỏ tuổi đời rất cổ. 殸 là hình ảnh nhạc khí bằng đá khánh (磬), âm thanh phát ra khi gõ. 耳 chỉ người nghe. Hai phần kết hợp tạo nghĩa tiếng, âm thanh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khánh (838) Thù (839) Nhĩ (213)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Khánh (số 838 - đá nhạc) và chữ Thù (số 839 - binh khí gõ) ở trên bộ Nhĩ (số 213 - tai). Tai (Nhĩ) nghe rõ âm thanh phát ra khi lấy tay cầm cái thù gõ vào cái khánh. Giải thích sự chuyển ý: Đây là chữ Hội ý. Thanh là âm thanh, tiếng động (thanh âm, thanh danh).", "Nghĩa Tiếng Việt_Xie": "tiếng, âm thanh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>殸耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "声", "Unihan_Traditional (Chữ Phồn thể)": "聲", "Pinyin_Xie": "shēng", "Âm Hán Việt_Xie": "thanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ âm thanh hoặc làm lượng từ cho tiếng động và lời nói. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夆', '{"9000": "", "Chữ Trung Quốc": "夆", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Truy (183) Phong (585)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Truy (số 183 - đi sau) ở trên chữ Phong (số 585 - dồi dào/cỏ cây). Mọi vật sinh trưởng được đều nhờ vào chở che của đất nên ta phải một lòng tôn kính. Giải thích sự chuyển ý: Đây là chữ Hội ý. Phong là sự tôn kính, là lễ tế.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>夂丰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "夂", "Unihan_Simplified (Chữ Giản thể)": "夆", "Unihan_Traditional (Chữ Phồn thể)": "夆", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犮', '{"9000": "", "Chữ Trung Quốc": "犮", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phiệt (004) Khuyển (251)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Nét Phẩy (số 004) ở dưới bộ Khuyển (số 251 - con chó). Ngụ ý là con chó mọc thêm một chân nữa, đang ba chân bốn cẳng chạy tới tấp. Giải thích sự chuyển ý: Đây là chữ Tượng hình (hoặc Hội ý). Bạt là hình dáng con chó chạy mau, chạy gấp.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>又", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "犮", "Unihan_Traditional (Chữ Phồn thể)": "犮", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髮', '{"9000": "", "Chữ Trung Quốc": "髮", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 髟 | Số nét | 15 | nét | 髟 | biểu nghĩa | tóc dài | 犮 | biểu âm | 髮 = 髟 (biểu nghĩa: tóc dài) + 犮 (biểu âm). Chữ hình thanh. Dạng gốc là 𩠙 (首+犬); 犬 là viết tắt của 犮. Bộ 首 sau được thay bằng 髟.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary: 髮 là chữ hình thanh gồm 髟 (tóc dài — biểu nghĩa) và 犮 (biểu âm). Dạng gốc 𩠙 gồm 首 (đầu) và 犬 (chó); 犬 là dạng viết tắt của 犮 theo học giả Takada Tadachika. Xuất hiện từ kim văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tiêu (861) Bạt (862)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tiêu/Bưu (số 861 - tóc dài) ở trên chữ Bạt (số 862 - chạy mau/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Bạt chỉ âm, bộ Tiêu chỉ ý. Phát là tóc ở trên đầu (răng tóc).", "Nghĩa Tiếng Việt_Xie": "tóc; một phần nghìn của một tấc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>髟犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "fà", "Âm Hán Việt_Xie": "phát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ chỉ tóc hoặc đơn vị đo lường rất nhỏ trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('㐬', '{"9000": "", "Chữ Trung Quốc": "㐬", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là hình vẽ dải cờ đuôi nheo (phất phơ trong gió). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Lưu là dải cờ.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('園', '{"9000": "", "Chữ Trung Quốc": "園", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vi (030) Viên (294)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Vi (số 030 - bao quanh) bao bọc bên ngoài chữ Viên (số 294 - cái áo thụng/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Viên chỉ âm, bộ Vi chỉ ý. Viên là cái vườn có tường bao quanh (hoa viên, công viên).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗袁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "袁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "园", "Unihan_Traditional (Chữ Phồn thể)": "園", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黃', '{"9000": "", "Chữ Trung Quốc": "黃", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 黃 | Số nét | 12 | nét | 炗 | quang | biểu âm | ánh sáng | 田 | điền | biểu nghĩa | ruộng đồng | 黃 là chữ hình thanh (psc): 炗 (Quang, biểu âm: ánh sáng) + 田 (Điền, biểu nghĩa: đồng ruộng). Tuy nhiên, theo Chi (2010) đây nguyên là chữ tượng hình mô tả người tàn tật bụng phình to — màu vàng chỉ là nghĩa vay mượn từ âm. Là dạng phồn thể của 黄.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | 黃 (hoàng) nguyên là chữ tượng hình theo nghiên cứu của Chi (2010): mô tả người tàn tật với ngực/bụng phô ra. Nghĩa ''màu vàng'' là nghĩa vay mượn phiên âm từ thời giáp cốt văn. He (1998) đề xuất giả thuyết khác. Wiktionary ghi: ''originally a pictograph... phonetically borrowed for yellow since the oracle bone script.'' Chữ có đầy đủ dạng giáp cốt, kim văn, triện văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Quang (682) Điền (024)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Điền (số 024 - đồng ruộng) nằm ở giữa chữ Quang (số 682 - ánh sáng/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Quang chỉ âm, chữ Điền chỉ ý. Hoàng là màu của đất, đất thuộc hành Thổ có màu vàng. Hoàng là màu vàng (hoàng thổ).", "Nghĩa Tiếng Việt_Xie": "vàng, màu vàng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>廿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "黄", "Unihan_Traditional (Chữ Phồn thể)": "黃", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng, huỳnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ màu sắc hoặc danh từ chỉ họ người và các sự vật có màu vàng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匊', '{"9000": "", "Chữ Trung Quốc": "匊", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bao (020) Mễ (453)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Bao (số 020 - bao bọc) ở ngoài ôm lấy bộ Mễ (số 453 - hạt gạo). Hình cánh tay ôm các hạt gạo vơ vào trong. Giải thích sự chuyển ý: Đây là chữ Hội ý. Cúc là nắm đồ vật ở trong tay.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰勹米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "米", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "勹", "Unihan_Simplified (Chữ Giản thể)": "匊", "Unihan_Traditional (Chữ Phồn thể)": "匊", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彥', '{"9000": "", "Chữ Trung Quốc": "彥", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Văn (065) Lập (112) Hán (027) Sam (860)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lập (số 112/có thể viết là chữ Văn 065) ở trên chữ Hán (số 027 - sườn núi) và bộ Sam (số 860 - râu tóc). Giải thích sự chuyển ý: Đây là chữ Hội ý. Ngạn là người hiền sĩ, người tài đức xuất chúng.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "彦", "Unihan_Traditional (Chữ Phồn thể)": "彥", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顏', '{"9000": "", "Chữ Trung Quốc": "顏", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 頁 | Số nét | 18 | nét | 彥 | ngạn | biểu âm | âm phù | 頁 | hiệt | biểu nghĩa | đầu, mặt | 顏 là chữ hình thanh (psc): 彥 (ngạn, biểu âm) + 頁 (hiệt — đầu/mặt, biểu nghĩa). Kim văn: 产 (biểu âm) + 面 (mặt, biểu nghĩa). Nghĩa gốc: khuôn mặt, vẻ ngoài — từ bộ 頁 là đầu/mặt người.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Lục thư thông | Wiktionary: 顏 = 彥 (biểu âm) + 頁 (đầu/mặt, biểu nghĩa), chữ hình thanh. Kim văn phân tích khác: 产 (âm) + 面 (mặt). Nghĩa gốc: khuôn mặt, diện mạo — sau mở rộng sang ''màu sắc, thể diện''. Kim văn, tiểu triện và lục thư thông đều có dạng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngạn (880) Hiệt (181)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Ngạn (số 880 - người tài đức/chỉ âm) ở bên trái bộ Hiệt (số 181 - đầu/mặt). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ngạn chỉ âm, bộ Hiệt (huyệt) chỉ ý. Nhan là sắc mặt, vẻ mặt, dáng mặt (nhan sắc, hồng nhan).", "Nghĩa Tiếng Việt_Xie": "Yến", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彥頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "颜", "Unihan_Traditional (Chữ Phồn thể)": "顏", "Pinyin_Xie": "yán", "Âm Hán Việt_Xie": "nhan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ khuôn mặt, dung mạo hoặc màu sắc trong văn viết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眔', '{"9000": "", "Chữ Trung Quốc": "眔", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mục (121) Thủy (082)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mục (số 121 - con mắt) ở trên bộ Thủy (số 082 - nước/viết dạng 氺 xuôi xuống). Giải thích sự chuyển ý: Đây là chữ Hội ý. Đạp là những giọt nước mắt chảy ra từ con mắt đang nhớ thương.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>罒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('懷', '{"9000": "", "Chữ Trung Quốc": "懷", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (061) Hoài (885)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tâm (số 061 - tim) ở bên trái chữ Hoài (số 885 - giấu kín/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hoài chỉ âm, bộ Tâm chỉ ý. Hoài là sự nhớ nhung, những điều giữ ở trong lòng (hoài bão, hoài niệm).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄褱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "褱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怀", "Unihan_Traditional (Chữ Phồn thể)": "懷", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('㐄', '{"9000": "", "Chữ Trung Quốc": "㐄", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Truy (183)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Khóa (㐄) là chữ Truy (số 183 - đi sau) viết lật ngược đứng lên. Chữ Truy là đi sau, viết lật ngược lại mang nghĩa đi trước, vượt qua. Giải thích sự chuyển ý: Đây là chữ Chỉ sự. Khóa là đi trước, vượt qua.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>十", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "㐄", "Unihan_Traditional (Chữ Phồn thể)": "㐄", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夅', '{"9000": "", "Chữ Trung Quốc": "夅", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Truy (183) Khóa (896)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Truy (số 183 - bàn chân đi sau) ở trên chữ Khóa (số 896 - bàn chân đi trước). Bàn chân đi trước ở phía dưới, đi sau ở phía trên, nghĩa là người này đang đi từ trên cao xuống dưới thấp. Giải thích sự chuyển ý: Đây là chữ Hội ý. Hàng là đi từ trên cao xuống dưới thấp. Nó cũng có nghĩa là đầu hàng, phục tùng.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>夂㐄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "夂", "Unihan_Simplified (Chữ Giản thể)": "夅", "Unihan_Traditional (Chữ Phồn thể)": "夅", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漸', '{"9000": "", "Chữ Trung Quốc": "漸", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Trảm (572)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước) ở bên trái chữ Trảm (số 572 - chém/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Trảm chỉ âm, bộ Thủy chỉ ý. Tiệm là nước chảy từ từ, dần dần (tiệm tiến, dần tiệm).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵斬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渐", "Unihan_Traditional (Chữ Phồn thể)": "漸", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('亞', '{"9000": "", "Chữ Trung Quốc": "亞", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là hình vẽ mô phỏng cái tổ chim. Tổ chim có thể phủ trùm, che kín cho con chim tránh khỏi mưa rét. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Á có nghĩa là phủ trùm, che chở. Nó cũng mang nghĩa là thứ hai (á quân), hoặc châu Á.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴二", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "亚", "Unihan_Traditional (Chữ Phồn thể)": "亞", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('牀', '{"9000": "", "Chữ Trung Quốc": "牀", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tường (510) Mộc (075)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tường (số 510 - tấm gỗ) ở bên trái chữ Mộc (số 075 - cây cối). Xẻ cây gỗ thành tấm, đóng thành cái giường để nằm. Giải thích sự chuyển ý: Đây là chữ Hội ý. Sàng là cái giường.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰爿木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "木", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "爿", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縣', '{"9000": "", "Chữ Trung Quốc": "縣", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 16 | nét | 目 | mục | hội ý | mắt, đầu người | 木 | mộc | hội ý | cây | 糸 | mịch | hội ý | sợi dây | 縣 là chữ hội ý: Mục (目, mắt — đại diện cho đầu người) + Mộc (木, cây) + Mịch (糸, sợi dây). Ý nghĩa gốc: treo đầu người lên cây bằng sợi dây — cực hình thời cổ, sau chuyển nghĩa sang 懸 (treo) và đơn vị hành chính cấp huyện. Trong bản Tần, 目+木 bị biến dạng thành 県 (đầu ngược 𥄉), và 糸 thành 系.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Đại triện | Tiểu triện | 縣 ban đầu là chữ hội ý: 目 (mắt, đại diện cho đầu người) + 木 (cây) + 糸 (sợi dây) — vẽ cảnh treo đầu người lên cây, nghĩa gốc là 懸 (treo lên). Về sau dùng để chỉ đơn vị hành chính — huyện. Trong bản Tần, hình 目+木 bị biến dạng sang 県 (đầu lộn ngược), 糸 đổi thành 系. Wiktionary ghi nhận đầy đủ quá trình biến đổi chữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Huyền (903) Hệ (904)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Huyền (số 903 - đầu treo ngược/chỉ âm) ở bên trái chữ Hệ (số 904 - buộc). Giải thích sự chuyển ý: Đây là chữ Hình thanh và Hội ý. Huyện/Huyền nghĩa gốc là treo, buộc. Sau được mượn làm danh từ chỉ khu vực hành chính (huyện, châu huyện).", "Nghĩa Tiếng Việt_Xie": "Quận", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰系", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "县", "Unihan_Traditional (Chữ Phồn thể)": "縣", "Pinyin_Xie": "xiàn", "Âm Hán Việt_Xie": "huyện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ đơn vị hành chính hoặc làm động từ với nghĩa treo lên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('懸', '{"9000": "", "Chữ Trung Quốc": "懸", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Huyện (905) Tâm (061)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Huyện (số 905 - treo/chỉ âm) ở trên bộ Tâm (số 061 - tim). Trong lòng lo nghĩ không yên, tâm trí như bị treo lơ lửng giữa khoảng không. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Huyện chỉ âm, bộ Tâm chỉ ý. Huyền là treo lơ lửng (huyền bí, treo giải).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>縣心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "縣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "悬", "Unihan_Traditional (Chữ Phồn thể)": "懸", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帳', '{"9000": "", "Chữ Trung Quốc": "帳", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cân (113) Trường (797)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Cân (số 113 - cái khăn/tấm vải) ở bên trái chữ Trường (số 797 - dài/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Trường chỉ âm, bộ Cân chỉ ý. Trướng là cái màn, cái rèm bạt.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾長", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "長", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "帐", "Unihan_Traditional (Chữ Phồn thể)": "帳", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冘', '{"9000": "", "Chữ Trung Quốc": "冘", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (021) Nhân (019)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 021 - che trùm) đè lên bộ Nhân (số 019 - người/chân đi). Người muốn đi nhưng bị sự u mê phủ trùm lên đầu nên chần chừ, do dự, không tiến lên được. Giải thích sự chuyển ý: Đây là chữ Hội ý. Dâm là chần chừ, do dự không quyết.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴巾乚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "冘", "Unihan_Traditional (Chữ Phồn thể)": "冘", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('與', '{"9000": "", "Chữ Trung Quốc": "與", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 臼 | Số nét | 13 | nét | 舁 | dư | biểu âm | (biểu âm yú/yǔ) | 牙 | nha | biểu âm | (biểu âm yá/yǔ) | 與 là chữ hình thanh đặc biệt: cả hai thành phần 舁 và 牙 đều là biểu âm theo Wiktionary. Dạng gốc gần nhất là 𦥸. Nghĩa gốc là đưa/cho; sau mở rộng thành giới từ và liên từ ''và, cùng với''. Có hình ảnh từ kim văn, bạch thư và tiểu triện.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Bạch thư | Tiểu triện | 與 là chữ hình thanh theo Wiktionary: {{Han compound|ls=psc|舁|牙|c1=p|c2=p}} — cả hai thành phần đều là biểu âm. Dạng gốc gần nhất là 𦥸. Nghĩa gốc là ban cho, trao tặng. Sau phát triển thành giới từ ''với, cùng'' và liên từ ''và''. Có hình ảnh từ kim văn (kim văn chim), bạch thư và tiểu triện — lịch sử lâu đời. Dạng giản thể là 与. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình ảnh hai cánh tay ở trên và hai cánh tay ở dưới đều cùng cầm cái ngà voi trao cho nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Dữ là cấp cho, trao đổi. Cũng dùng làm liên từ: và, cùng với (tham dự, dữ dội).", "Nghĩa Tiếng Việt_Xie": "cho; đi lại chơi bời, thân thiện; khen ngợi, tán thưởng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "与", "Unihan_Traditional (Chữ Phồn thể)": "與", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "dư, dự, dữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Liên từ | 连词 | Giới từ | 介词 | Động từ | 动词 | Chữ này thường làm liên từ nối các danh từ hoặc giới từ biểu thị sự đồng hành, liên kết. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巿', '{"9000": "", "Chữ Trung Quốc": "巿", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (001) Cân (113)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhất (số 001 - một nét ngang) đi qua bộ Cân (số 113 - cái khăn/vải). Hình cái trục cuốn vải tạo thành cuộn. Giải thích sự chuyển ý: Đây là chữ Hội ý. Táp (Phất) là cuốn vòng quanh, cái dải băng, tạp dề che trước ngực.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>十巾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "十", "Unihan_Simplified (Chữ Giản thể)": "巿", "Unihan_Traditional (Chữ Phồn thể)": "巿", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紙', '{"9000": "", "Chữ Trung Quốc": "紙", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 10 | nét | 糸 | mịch | biểu nghĩa | tơ lụa, sợi | 氏 | thị | biểu âm | 紙 = 糸 (Mịch, biểu nghĩa: tơ lụa, sợi) + 氏 (Thị, biểu âm); chữ hình thanh. Bộ 糸 phản ánh nguồn gốc làm giấy từ sợi tơ hoặc vải; 氏 cho âm đọc gần zhǐ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 紙 (zhǐ) là chữ hình thanh: bộ 糸 (tơ lụa, sợi) cho nghĩa — giấy ban đầu làm từ sợi tơ tằm hoặc vải; 氏 (thị) cho âm. Wiktionary xác nhận cấu trúc Han compound ls=psc với c1=s (silk), c2=p. Giấy do Thái Luân cải tiến vào khoảng năm 105 SCN từ vỏ cây và tơ cũ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (237) Thị (679)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 237 - sợi tơ) ở bên trái chữ Thị (số 679 - họ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thị chỉ âm, bộ Mịch chỉ ý. Chỉ vốn là loại vải dùng để viết chữ. Sau này được dùng để gọi giấy viết.", "Nghĩa Tiếng Việt_Xie": "giấy viết", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹氏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "zhǐ", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm danh từ chỉ chất liệu viết hoặc làm lượng từ cho các văn bản, giấy tờ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籤', '{"9000": "", "Chữ Trung Quốc": "籤", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 竹 | Số nét | 23 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 韱 | biểu âm | 籤 = 竹 (Trúc, biểu nghĩa: tre) + 韱 (biểu âm); chữ hình thanh. Phần 竹 gợi vật liệu tre — thẻ tre dùng bói toán; 韱 cho âm qiān.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 籤 là chữ hình thanh: 竹 (trúc, biểu nghĩa: tre) kết hợp với 韱 (biểu âm). Chữ chỉ thẻ tre có khắc chữ dùng bói toán, rút thăm; mở rộng ra nghĩa nhãn, thẻ, que. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (118) Tiêm (926)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 118 - tre trúc) ở trên chữ Tiêm (số 926 - nhỏ bé/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tiêm chỉ âm, bộ Trúc chỉ ý. Thiêm là những cái thẻ tre (rút thiêm, tăm xỉa răng).", "Nghĩa Tiếng Việt_Xie": "dấu hiệu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>⺮韱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "thiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại thẻ tre, nhãn giấy hoặc tăm xỉa răng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疋', '{"9000": "", "Chữ Trung Quốc": "疋", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là hình vẽ mô phỏng cái cẳng chân. Thuyết Văn Giải Tự nói rằng: ''Sơ, túc dã'', nghĩa là Sơ chính là cái chân vậy. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Sơ là cẳng chân (như chữ Túc). Ngoài ra còn đọc là Thất (lượng từ chỉ tấm vải).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>㇖龰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "㇖", "Unihan_Simplified (Chữ Giản thể)": "疋", "Unihan_Traditional (Chữ Phồn thể)": "疋", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('專', '{"9000": "", "Chữ Trung Quốc": "專", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chuyên (叀) Thốn (041)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Chuyên (叀 - hình con suốt sợi chỉ) ở trên bộ Thốn (số 041 - cái tay). Khi đánh sợi dệt vải phải tập trung chú ý vào việc dùng tay quay suốt. Giải thích sự chuyển ý: Đây là chữ Hội ý. Chuyên là tập trung tâm trí, chú ý vào một việc (chuyên tâm, chuyên môn).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>寸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "专", "Unihan_Traditional (Chữ Phồn thể)": "專", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轉', '{"9000": "", "Chữ Trung Quốc": "轉", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 車 | Số nét | 18 | nét | 車 | xa | biểu nghĩa | xe, bánh xe | 專 | chuyên | biểu âm | biểu âm | 轉 = 車 (Xa, biểu nghĩa: xe/bánh xe) + 專 (Chuyên, biểu âm); chữ hình thanh. Bộ 車 xác định nghĩa liên quan đến bánh xe quay; phần 專 cung cấp âm đọc zhuǎn/zhuàn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 轉 là chữ hình thanh: 車 (xe, bánh xe) là phần biểu nghĩa, 專 là phần biểu âm. Nghĩa gốc là bánh xe quay; mở rộng sang xoay, chuyển hướng, chuyển giao. Dạng tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xa (159) Chuyên (930)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xa (số 159 - chiếc xe) ở bên trái chữ Chuyên (số 930 - quay suốt/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Chuyên chỉ âm, bộ Xa chỉ ý. Chuyển là chuyển động, biến đổi, thay đổi (chuyển hướng, luân chuyển).", "Nghĩa Tiếng Việt_Xie": "Xoay", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車專", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "專", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "转", "Unihan_Traditional (Chữ Phồn thể)": "轉", "Pinyin_Xie": "zhuǎn", "Âm Hán Việt_Xie": "chuyển, chuyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị sự thay đổi hướng đi, vị trí hoặc trạng thái. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巤', '{"9000": "", "Chữ Trung Quốc": "巤", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xuyên (047) Thử (210)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xuyên (số 047 - sông/được viết biến đổi từ bộ Sam 彡) ở trên và chữ Thử (số 210 - con chuột/viết biến đổi) ở dưới. Liệp là cái lông ở đầu con chuột. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Liệp là lông rậm (ở cằm, mũi).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>巛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "巤", "Unihan_Traditional (Chữ Phồn thể)": "巤", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('獵', '{"9000": "", "Chữ Trung Quốc": "獵", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khuyển (094) Liệp (933)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khuyển (số 094 - con chó/ 犭) ở bên trái chữ Liệp (số 933 - rậm lông/chỉ âm). Dùng chó đi săn thú. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Liệp (巤) chỉ âm, bộ Khuyển chỉ ý. Liệp là dùng chó đi săn, đi săn bắn (săn liệp).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭巤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猎", "Unihan_Traditional (Chữ Phồn thể)": "獵", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騎', '{"9000": "", "Chữ Trung Quốc": "騎", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 馬 | Số nét | 18 | nét | 馬 | mã | biểu nghĩa | ngựa | 奇 | cơ | biểu âm | kỳ lạ, số lẻ | 騎 = 馬 (Mã, biểu nghĩa: ngựa) + 奇 (Cơ, biểu âm). Chữ hình thanh: bộ 馬 chỉ hoạt động cưỡi ngựa, 奇 cho âm đọc. Nghĩa là cưỡi (ngựa, xe đạp), kỵ binh.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Theo Wiktionary, 騎 là chữ hình thanh (psc): bộ 馬 biểu nghĩa ''ngựa'', thành phần 奇 biểu âm. Nghĩa cơ bản là cưỡi ngựa, mở rộng sang cưỡi bất kỳ phương tiện (xe đạp, xe máy). Từ tổ hợp 騎士 (kỵ sĩ) và 騎兵 (kỵ binh) quan trọng trong lịch sử quân sự. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mã (187) Kỳ (447)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mã (số 187 - con ngựa) ở bên trái chữ Kỳ (số 447 - lạ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Kỳ chỉ âm, bộ Mã chỉ ý. Kỵ là cưỡi ngựa, người cưỡi ngựa (kỵ sĩ).", "Nghĩa Tiếng Việt_Xie": "lái", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬奇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "骑", "Unihan_Traditional (Chữ Phồn thể)": "騎", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ đứng trước danh từ chỉ phương tiện hoặc con vật để biểu thị hành động cưỡi hoặc đi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('凵', '{"9000": "", "Chữ Trung Quốc": "凵", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là hình vật gì để đựng đồ nên nó trũng xuống. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Khảm là cái đựng đồ vật, cái hố. Cũng có ý chỉ là há miệng ra.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴冂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "凵", "Unihan_Traditional (Chữ Phồn thể)": "凵", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擊', '{"9000": "", "Chữ Trung Quốc": "擊", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khảm (940) Xa (159) Thù (079) Thủ (064)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Khảm (940), Xa (159), Thù (079) và Thủ (064). Đào cái hố thật sâu (Khảm) để xe (Xa) rơi dọc xuống, rồi tay (Thủ) cầm chắc vũ khí (Thù) xông ra đánh. Giải thích sự chuyển ý: Đây là chữ Hội ý. Kích là công kích, đánh bằng vũ khí.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>𣪠手", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣪠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "手", "Unihan_Simplified (Chữ Giản thể)": "击", "Unihan_Traditional (Chữ Phồn thể)": "擊", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄰', '{"9000": "", "Chữ Trung Quốc": "鄰", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 邑 | Số nét | 14 | nét | 粦 | lân | biểu âm | âm lân (cho âm lín) | 阝 | biểu nghĩa | ấp, làng xóm (biến thể của 邑) | 鄰 là chữ hình thanh (ls=psc): 阝(邑 — ấp, làng xóm) là phần biểu nghĩa; 粦 là phần biểu âm cho âm lín. Cấu trúc rõ ràng: chữ liên quan địa danh, chỉ làng xóm kế cận.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 鄰 gồm 粦 (biểu âm, cho âm lín) + 邑/阝 (ấp — làng xóm, biểu nghĩa) theo cấu trúc hình thanh. Nghĩa gốc: hàng xóm láng giềng, vùng đất kề cận. Dạng giản thể 邻 thu gọn phần âm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lân (943) Ấp (163)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lân (số 943 - ma trơi/chỉ âm) ở bên trái bộ Ấp (số 163 - thôn ấp/viết là 阝). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Lân (粦) chỉ âm, bộ Ấp (邑) chỉ ý. Lân là láng giềng, các nhà ở gần nhau (lân cận).", "Nghĩa Tiếng Việt_Xie": "gần, kề; láng giềng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰粦阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邻", "Unihan_Traditional (Chữ Phồn thể)": "鄰", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Thường làm danh từ chỉ người hàng xóm hoặc làm tính từ chỉ sự gần kề về địa lý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('張', '{"9000": "", "Chữ Trung Quốc": "張", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cung (057) Trường (797)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Cung (số 057 - cây cung) ở bên trái chữ Trường (số 797 - dài/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Trường chỉ âm, bộ Cung chỉ ý. Trương là giương cung, căng dây cung, mở rộng (khai trương, phô trương).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰弓長", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "長", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弓", "Unihan_Simplified (Chữ Giản thể)": "张", "Unihan_Traditional (Chữ Phồn thể)": "張", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('𣦼', '{"9000": "", "Chữ Trung Quốc": "𣦼", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Đãi (947) Hựu (018)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Đãi (số 947 - xương tàn) ở trên bộ Hựu (số 018 - bàn tay). Bàn tay (Hựu) bóc lột hết da thịt còn trơ lại bộ xương tàn (Đãi). Giải thích sự chuyển ý: Đây là chữ Hội ý. Tàn có nghĩa là ác, xấu, làm tổn hại (tàn bạo, tàn hại).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歺又", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "又", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歺", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('華', '{"9000": "", "Chữ Trung Quốc": "華", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 艸 | Số nét | 10 | nét | 華 | hoa | tượng hình | hoa nở, rực rỡ, Trung Hoa | 華 là chữ tượng hình gốc (pictograph). Kim văn cho thấy hình hoa nở trên cành (phần trên) và thân cây/rễ (phần dưới — bộ 于). Về sau tiểu triện thêm bộ 艸 (cỏ/cây). Đây là dạng gốc của 花 (hoa). Cũng có thể phân tích hình thanh với 于 là âm phù.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | Wiktionary: 華 gốc là tượng hình (pictograph) của hoa cây nở rộ — dạng gốc của 花 (hoa). Kim văn thấy rõ hoa nở trên cành. Tiểu triện thêm bộ 艸. Cũng phân tích là hình thanh với 于 là âm phù. 華 và 𠌶 ban đầu là cùng một chữ, bị tách ra nhầm trong Thuyết Văn. Từ nghĩa ''hoa'' phái sinh sang ''rực rỡ, Trung Hoa, người Hoa''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là hình vẽ mô phỏng những cánh hoa (có cành và lá). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Hoa là cánh hoa, cũng có nghĩa là đẹp, tốt, vinh hiển, sang trọng (hoa lệ, phồn hoa, Trung Hoa).", "Nghĩa Tiếng Việt_Xie": "đẹp; quầng trăng, quầng mặt trời; người Trung Quốc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "华", "Unihan_Traditional (Chữ Phồn thể)": "華", "Pinyin_Xie": "huá", "Âm Hán Việt_Xie": "hoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ chỉ sự đẹp đẽ, lộng lẫy hoặc làm danh từ chỉ nước Trung Quốc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畢', '{"9000": "", "Chữ Trung Quốc": "畢", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hoa (950) Điền (024)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là chữ Hoa (số 950 - bông hoa), trong đó bộ Thảo đầu (艹) được thay bằng bộ Điền (số 024 - ruộng). Để lấy nghĩa là bông hoa đã kết thành quả (trên điền). Giải thích sự chuyển ý: Đây là chữ Hội ý. Việc đơm hoa kết trái đã hoàn thành. Tất là hoàn thành, làm xong (tất nghiệp, hoàn tất).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>田", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "毕", "Unihan_Traditional (Chữ Phồn thể)": "畢", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('媽', '{"9000": "", "Chữ Trung Quốc": "媽", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nữ (038) Mã (187)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nữ (số 038 - phụ nữ) ở bên trái chữ Mã (số 187 - con ngựa/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Mã chỉ âm, bộ Nữ chỉ ý. Ma là mẹ, tiếng con gọi mẹ.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "馬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妈", "Unihan_Traditional (Chữ Phồn thể)": "媽", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('丩', '{"9000": "", "Chữ Trung Quốc": "丩", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là hình vẽ mô phỏng hai sợi dây buộc, quấn chặt vào nhau. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Cưu là quấn lại với nhau, dây dưa (cưu mang, dây cưu).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴丨㇙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丨", "Unihan_Simplified (Chữ Giản thể)": "丩", "Unihan_Traditional (Chữ Phồn thể)": "丩", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('兌', '{"9000": "", "Chữ Trung Quốc": "兌", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bát (012) Huynh (286)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Bát (số 012 - số tám/chia ra) ở trên chữ Huynh (số 286 - người anh/mở miệng). Hai nét của chữ bát như hai nét nếp nhăn đuôi mắt (hoặc trên miệng) thể hiện người đang vui vẻ. Giải thích sự chuyển ý: Đây là chữ Hội ý. Đoài là vui vẻ, thông suốt. Ngoài ra còn có nghĩa là đổi chác (đoái hoái, hối đoái).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>㕣儿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㕣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "儿", "Unihan_Simplified (Chữ Giản thể)": "兑", "Unihan_Traditional (Chữ Phồn thể)": "兌", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('說', '{"9000": "", "Chữ Trung Quốc": "說", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 14 | nét | 言 | ngôn | biểu nghĩa | lời nói | 兌 | đoái | biểu âm | vui vẻ, đổi chác | 說 = 言 (Ngôn, biểu nghĩa: lời nói) + 兌 (Đoái, biểu âm); chữ hình thanh. Bộ 言 chỉ hành động ngôn ngữ; 兌 cho âm đọc shuō. 說 là phồn thể, giản thể là 说.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Wiktionary xác nhận: hình thanh gồm 言 (lời nói, biểu nghĩa) và 兌 (biểu âm). Tiểu triện đã ghi nhận cấu trúc này. 說 là chữ cổ cho ''nói'' (speak, say, talk); cũng có nghĩa quở trách (scold, upbraid). Trong triết học: 說 còn chỉ một lý thuyết, một học thuyết (doctrine, theory). Đây là phồn thể của 说 hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Đoài (961)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói) ở bên trái chữ Đoài (số 961 - vui vẻ, thông suốt/chỉ âm). Dùng lời nói để giải thích cho người nghe thông suốt, vui vẻ. Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Đoài chỉ âm, bộ Ngôn chỉ ý. Thuyết là nói, giải thích (thuyết minh, diễn thuyết).", "Nghĩa Tiếng Việt_Xie": "nói", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言兌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "说", "Unihan_Traditional (Chữ Phồn thể)": "說", "Pinyin_Xie": "shuō", "Âm Hán Việt_Xie": "thuyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước tân ngữ để biểu đạt hành vi nói hoặc làm danh từ chỉ lý thuyết. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('個', '{"9000": "", "Chữ Trung Quốc": "個", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (008) Cố (557)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhân đứng (số 008 - người) ở bên trái chữ Cố (số 557 - bền vững/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cố chỉ âm, bộ Nhân chỉ ý. Cá là lượng từ chỉ sự đơn lẻ: cái, chiếc (cá nhân).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻固", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "固", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "个", "Unihan_Traditional (Chữ Phồn thể)": "個", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('師', '{"9000": "", "Chữ Trung Quốc": "師", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Đôi (𠂤) Táp (帀)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Đôi (𠂤 - đồi đất/biến thể bộ Phụ 阝) ở bên trái chữ Táp (帀 - đi một vòng/bao quanh). Quân đội thường đóng trại bao quanh (Táp) trên đồi (Đôi). Giải thích sự chuyển ý: Đây là chữ Hội ý. Sư là một đơn vị binh lính (gồm 2500 quân), xuất quân (sư đoàn). Sư cũng là người thầy, người truyền đạo (tôn sư).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𠂤帀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "𠂤", "Unihan_Simplified (Chữ Giản thể)": "师", "Unihan_Traditional (Chữ Phồn thể)": "師", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('諸', '{"9000": "", "Chữ Trung Quốc": "諸", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 15 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn ngữ | 者 | giả | biểu âm | 諸 = 言 (Ngôn, biểu nghĩa: lời nói) + 者 (Giả, biểu âm). Chữ hình thanh: bộ 言 chỉ liên quan đến ngôn ngữ/biểu đạt, 者 cho âm đọc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Lưu thư thông (Minh) | Chữ hình thanh: 言 (lời nói) biểu nghĩa, 者 biểu âm. 諸 là hư từ quan trọng trong văn ngôn, mang nhiều nghĩa: \"tất cả các\", \"nhiều\", hoặc là hợp âm của 之於/之乎 (chi ư/chi hồ). Xuất hiện từ kim văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Giả (958)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói) ở bên trái chữ Giả (số 958 - người ấy/chỉ âm). Lời nói chỉ chung nhiều người. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Giả chỉ âm, bộ Ngôn chỉ ý. Chư là từ chỉ số nhiều: các, mọi (chư vị, chư tôn).", "Nghĩa Tiếng Việt_Xie": "(là hợp thanh của 2 chữ \"chi ư\")", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "诸", "Unihan_Traditional (Chữ Phồn thể)": "諸", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "chư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Đại từ | 代词 | Trợ từ | 助词 | Chữ này làm tính từ hạn định đứng trước danh từ để chỉ số nhiều hoặc làm trợ từ ngữ khí trong văn ngôn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('著', '{"9000": "", "Chữ Trung Quốc": "著", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | thảo | biểu nghĩa | cỏ — phần biểu nghĩa cổ | 者 | giả | biểu âm | gợi âm ''zhù'' | 著 = 艹 (Thảo, cỏ) + 者 (Giả, biểu âm). Chữ hình thanh: nghĩa gốc liên quan đến ''sáng tỏ, rõ rệt'' rồi mở rộng sang ''nổi danh, viết sách (trước tác)'', và ''mặc, đeo'' (trùng âm ''zhuó''). Trong giản thể, 著/着 phân vai: 著 dùng cho ''nổi tiếng, trước tác'', 着 dùng cho trợ từ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 著 là chữ hình thanh: 艸 (艹) biểu nghĩa, 者 biểu âm. Nghĩa gốc ''sáng tỏ, hiển hiện''; mở rộng thành ''nổi danh'' (著名), ''viết sách'' (著作), và đa nghĩa do âm khác nhau (zhù, zhuó, zhāo, zhe). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (028) Giả (958)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 028 - cỏ cây) ở trên chữ Giả (số 958 - người ấy/chỉ âm). Cây cỏ sinh ra hoa trổ bông rõ ràng. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Giả chỉ âm, bộ Thảo chỉ ý. Trứ là sáng tỏ, rõ ràng (trứ danh, danh trứ). Đọc là Trước biểu thị hành động đang diễn ra.", "Nghĩa Tiếng Việt_Xie": "nêu lên, nổi lên, rõ rệt, nổi danh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "着", "Unihan_Traditional (Chữ Phồn thể)": "著", "Pinyin_Xie": "zhe", "Âm Hán Việt_Xie": "trứ, trước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ với nghĩa viết sách, sáng tác hoặc làm tính từ chỉ sự nổi bật, rõ rệt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('們', '{"9000": "", "Chữ Trung Quốc": "們", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (008) Môn (169)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhân đứng (số 008 - người) ở bên trái chữ Môn (số 169 - cái cửa/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Môn chỉ âm, bộ Nhân chỉ ý. Môn là từ hậu tố chỉ số nhiều (nhiều người): bọn họ, chúng (bọn ta: ngã môn, bọn họ: tha môn).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻門", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "門", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "们", "Unihan_Traditional (Chữ Phồn thể)": "們", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('請', '{"9000": "", "Chữ Trung Quốc": "請", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 15 | nét | 言 | ngôn | biểu nghĩa | lời nói | 青 | thanh | biểu âm | xanh | 請 = 言 (Ngôn, biểu nghĩa: lời nói) + 青 (Thanh, biểu âm); chữ hình thanh. 言 chỉ hành động lời nói; 青 (qīng) cho âm gần qǐng. Nghĩa gốc là thưa trình, xin phép — dùng lời nói để đề nghị.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Bạch thư | Tiểu triện | Theo Wiktionary, 請 là chữ hình thanh: 言 (biểu nghĩa: nói) + 青 (biểu âm). Bạch thư (sách lụa Mã Vương Đôi) và Tiểu triện đều ghi nhận cấu trúc này. Nghĩa gốc: thưa trình, xin phép; từ đó mở rộng sang mời (mời khách), nhờ vả, kính thưa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Thanh (580)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói) ở bên trái chữ Thanh (số 580 - màu xanh/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thanh chỉ âm, bộ Ngôn chỉ ý. Thỉnh là lời cầu xin, khẩn cầu. Cũng mang nghĩa mời, hỏi thăm (thỉnh cầu, thỉnh an).", "Nghĩa Tiếng Việt_Xie": "mời mọc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言青", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "青", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "请", "Unihan_Traditional (Chữ Phồn thể)": "請", "Pinyin_Xie": "qǐng", "Âm Hán Việt_Xie": "thỉnh, tình, tính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Trợ từ | 助词 | Thường làm động từ đứng đầu câu để biểu thị sự kính trọng, cầu khiến lịch sự. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('這', '{"9000": "", "Chữ Trung Quốc": "這", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 10 | nét | 辶 | biểu nghĩa | đi, chuyển động | 言 | ngôn | biểu âm | 這 = 辶 (biểu nghĩa: đi/chuyển động) + 言 (Ngôn, biểu âm); chữ hình thanh. Tuy nhiên theo Wiktionary, chữ này ban đầu là động từ nghĩa \"gặp gỡ\" (âm yàn), sau bị nhầm với 遮 trong chữ viết trung đại mà chuyển thành từ chỉ thị ''này/đây''.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 這 (giá/zhè): chữ hình thanh — 辶 (biểu nghĩa — đi) + 言 (biểu âm). Theo Wiktionary, chữ này ban đầu là động từ \"gặp gỡ\" (âm hiện đại là yàn), sau bị nhầm lẫn trong chữ viết thời trung đại với 遮 (chỉ thị ''này/đây''). Qua quá trình đó, 這 tiếp quản vai trò của từ chỉ thị gần và âm đọc thay đổi thành zhè. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Ngôn (149)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi) bao quanh chữ Ngôn (số 149 - lời nói/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Giá là đại từ chỉ định khoảng cách gần: này, cái này, việc này (giá cá - cái này).", "Nghĩa Tiếng Việt_Xie": "này, cái này; bây giờ, lúc nay", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "言", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "这", "Unihan_Traditional (Chữ Phồn thể)": "這", "Pinyin_Xie": "zhè", "Âm Hán Việt_Xie": "giá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Tính từ | 形容词 | Chữ này làm đại từ chỉ thị đứng trước danh từ hoặc lượng từ để chỉ đối tượng ở gần. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗎', '{"9000": "", "Chữ Trung Quốc": "嗎", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030) Mã (187)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 030 - cái miệng) ở bên trái chữ Mã (số 187 - con ngựa/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Mã chỉ âm, bộ Khẩu chỉ ý. Ma là trợ từ nghi vấn dùng ở cuối câu hỏi (phải không, đúng không).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "馬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吗", "Unihan_Traditional (Chữ Phồn thể)": "嗎", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冎', '{"9000": "", "Chữ Trung Quốc": "冎", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là hình vẽ mô phỏng bộ xương khô (những mảnh xương sọ ghép lại). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Quải là bộ xương khô (chữ Cốt 骨 được tạo từ chữ Quải và bộ Nhục).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>冂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咼', '{"9000": "", "Chữ Trung Quốc": "咼", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Quải (988) Khẩu (030)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 030 - miệng) nằm ở trong chữ Quải (số 988 - xương/chỉ âm). Cái miệng méo đi vì hốt hoảng. Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Qua là cái miệng méo xệch đi.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴冎口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呙", "Unihan_Traditional (Chữ Phồn thể)": "咼", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('過', '{"9000": "", "Chữ Trung Quốc": "過", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 11 | nét | 辵 | sước | biểu nghĩa | đi, bước chân | 咼 | oà | biểu âm | miệng lệch | 過 = 辵/辶 (Sước, biểu nghĩa: đi bước, di chuyển) + 咼 (Oà, biểu âm); chữ hình thanh. Bộ 辶 gợi hành động đi qua; 咼 cung cấp âm. Kim văn, bạch thư và tiểu triện đều ghi nhận.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Bạch thư | Tiểu triện | 過 là chữ hình thanh: 辵/辶 (biểu nghĩa, đi bước) + 咼 (biểu âm). Wiktionary xác nhận cấu trúc này. Nghĩa gốc: đi qua, vượt qua. Mở rộng sang: quá mức, sai lầm, đã từng. Kim văn (bronze) và bạch thư (silk) có hình thức sớm nhất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Qua (989)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi) bao quanh chữ Qua (số 989 - miệng méo/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Qua chỉ âm, bộ Xước chỉ ý. Quá là đi qua, vượt lên trên (quá cảnh, quá độ). Quá cũng có nghĩa là lỗi lầm (tội quá).", "Nghĩa Tiếng Việt_Xie": "qua, vượt; hơn, quá; đã từng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶咼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "过", "Unihan_Traditional (Chữ Phồn thể)": "過", "Pinyin_Xie": "guò", "Âm Hán Việt_Xie": "qua, quá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Trợ từ | 助词 | Danh từ | 名词 | Chữ này làm động từ chỉ sự di chuyển vượt qua, làm trợ từ biểu thị hành động đã từng xảy ra, hoặc làm danh từ chỉ lỗi lầm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí). | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('歲', '{"9000": "", "Chữ Trung Quốc": "歲", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bộ (077) Tuất (991)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tuất (số 991 - chi Tuất) nằm lồng ở giữa chữ Bộ (số 077 - bước đi/được tách làm hai nửa trên dưới). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tuất chỉ âm, chữ Bộ chỉ ý. Tuế là một năm, một tuổi (tuế nguyệt, vạn tuế).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>止", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('話', '{"9000": "", "Chữ Trung Quốc": "話", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 13 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn ngữ | 𠯑 | biểu âm | thành phần biểu âm (không liên quan đến 舌 lưỡi) | 話 là chữ hình thanh: 言 (ngôn — lời nói) biểu nghĩa, 𠯑 biểu âm. Wiktionary lưu ý phần bên phải không liên quan đến 舌 (lưỡi) dù trông giống; đây là điểm thường bị nhầm.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 話 = 言 (ngôn — lời nói, biểu nghĩa) + 𠯑 (biểu âm). Wiktionary nhấn mạnh: phần bên phải không phải 舌 (lưỡi) mà là 𠯑 — một thành phần biểu âm riêng. Chữ hình thanh điển hình của nhóm chữ ngôn-bộ chỉ hành vi ngôn ngữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Thiệt (135)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói) ở bên trái bộ Thiệt (số 135 - cái lưỡi). Cái lưỡi phát ra lời nói. Giải thích sự chuyển ý: Đây là chữ Hội ý (hoặc Hình thanh). Thoại là lời nói, nói chuyện (đối thoại, điện thoại).", "Nghĩa Tiếng Việt_Xie": "nói", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言舌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "话", "Unihan_Traditional (Chữ Phồn thể)": "話", "Pinyin_Xie": "huà", "Âm Hán Việt_Xie": "thoại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ làm tân ngữ cho động từ hoặc tự đóng vai trò động từ trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掛', '{"9000": "", "Chữ Trung Quốc": "掛", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Quái (995)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌) ở bên trái chữ Quái (số 995 - quẻ bói/chỉ âm). Dùng tay để treo lên. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quái chỉ âm, bộ Thủ chỉ ý. Quải là dùng tay treo lên, đeo cái gì bên mình.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌卦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "挂", "Unihan_Traditional (Chữ Phồn thể)": "掛", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麼', '{"9000": "", "Chữ Trung Quốc": "麼", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 麻 | Số nét | 14 | nét | 麻 | ma | biểu âm | cây gai, cho âm | 幺 | yêu | biểu nghĩa | nhỏ bé, tiny | 麼 = 麻 (Ma, biểu âm) + 幺 (Yêu, biểu nghĩa: nhỏ bé); chữ hình thanh. Phần 麻 cho âm gần với \"me/ma\", phần 幺 gợi nghĩa nhỏ nhặt.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Wiktionary: 麼 là chữ hình thanh (形聲), gồm 麻 (biểu âm) và 幺 (biểu nghĩa: nhỏ bé). Nghĩa gốc là \"nhỏ bé, ti tiện\". Về sau dùng làm trợ từ nghi vấn cuối câu (什麼, 怎麼) — đây là dùng theo âm, không theo nghĩa gốc. Chữ giản thể 么 là dạng viết tắt chỉ giữ phần 幺. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ma (200) Yêu (052)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ma (số 200 - cây gai/chỉ âm) đè lên bộ Yêu (số 052 - nhỏ bé/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ma chỉ âm, bộ Yêu chỉ ý. Ma vốn có nghĩa là nhỏ bé. Trong văn bạch thoại được dùng làm trợ từ (cái gì: thập ma - cái sao: chẩm ma).", "Nghĩa Tiếng Việt_Xie": "bé nhỏ; vậy (trợ ngữ)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴麻幺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麻", "Unihan_Simplified (Chữ Giản thể)": "么", "Unihan_Traditional (Chữ Phồn thể)": "麼", "Pinyin_Xie": "me", "Âm Hán Việt_Xie": "ma", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ từ | 助词 | Đại từ | 代词 | Thường đứng cuối câu hỏi làm trợ từ nghi vấn hoặc kết hợp tạo thành đại từ nghi vấn. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí). | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麗', '{"9000": "", "Chữ Trung Quốc": "麗", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 鹿 | Số nét | 19 | nét | 麗 | lệ | tượng hình | con hươu với cặp gạc đẹp | 麗 là chữ tượng hình: hình ảnh con hươu với cặp gạc cân đối, đẹp đẽ. Wiktionary xác nhận đây là {{liushu|p}} — chữ thuần tượng hình, không phải ghép thành phần. Cặp gạc hươu toả ra hai bên là biểu tượng của vẻ đẹp đối xứng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | 麗 là chữ tượng hình mô phỏng con hươu với cặp gạc xoè đôi. Wiktionary ghi: {{liushu|p}} — a deer with antlers. Hình dáng cân đối của gạc hươu trở thành biểu tượng cho vẻ đẹp, hoa lệ. Chữ giáp cốt và kim văn đều thể hiện rõ hình con hươu nhìn chính diện với gạc xoè hai bên. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lệ (丽) Lộc (1000)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lệ (丽 - chỉ âm/sừng hươu) ở trên chữ Lộc (số 1000 - con hươu/chỉ ý). Lệ là hình hai cái cặp sừng hươu rất đẹp. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Lệ là đẹp, tốt đẹp (hoa lệ, mỹ lệ, tráng lệ).", "Nghĩa Tiếng Việt_Xie": "(xem: cao ly 高麗,高丽)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>丽鹿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "丽", "Unihan_Traditional (Chữ Phồn thể)": "麗", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để miêu tả vẻ đẹp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飄', '{"9000": "", "Chữ Trung Quốc": "飄", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phiếu (1003) Phong (206)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Phiếu (số 1003 - tờ vé/chỉ âm) ở bên trái chữ Phong (số 206 - gió). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Phiếu chỉ âm, chữ Phong chỉ ý. Phiêu là gió thổi nhẹ nhàng, bay phấp phới, lơ lửng (phiêu bạt, phiêu lãng).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰票風", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "風", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揚', '{"9000": "", "Chữ Trung Quốc": "揚", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Dương (390)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - bàn tay) ở bên trái chữ Dương (số 390 - mặt trời/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Dương chỉ âm, bộ Thủ chỉ ý. Dương là dùng tay giơ lên, tung lên cao (tán dương, tuyên dương).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌昜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "扬", "Unihan_Traditional (Chữ Phồn thể)": "揚", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('順', '{"9000": "", "Chữ Trung Quốc": "順", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 頁 | Số nét | 12 | nét | 川 | xuyên | biểu âm | sông (cho âm) | 頁 | hiệt | biểu nghĩa | đầu người | 順 = 川 (Xuyên, biểu âm) + 頁 (Hiệt, biểu nghĩa: đầu người); chữ hình thanh theo phân tích hiện đại. Tuy nhiên Thuyết Văn Giải Tự diễn giải là hội ý: đầu người thuận theo dòng sông — đi thuận chiều nước.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Bạch thư | Đại triện | Tiểu triện | Lệ thư | 順 có hai cách phân tích: (1) hình thanh — 川 biểu âm, 頁 biểu nghĩa; (2) hội ý theo Thuyết Văn — 川 (sông) + 頁 (đầu) = đầu thuận theo dòng sông, tức đi thuận chiều, tuân theo. Wiktionary trích dẫn cả hai, ưu tiên psc. Dạng phồn thể dùng tại Đài Loan và Hong Kong. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xuyên (1007) Hiệt (181)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Xuyên (số 1007 - dòng sông) ở bên trái bộ Hiệt (số 181 - cái đầu). Mái tóc từ trên đầu chảy suôn thẳng xuống như dòng nước sông. Giải thích sự chuyển ý: Đây là chữ Hội ý. Thuận là tuân theo quy luật tự nhiên, nghe theo (thuận lợi, hòa thuận).", "Nghĩa Tiếng Việt_Xie": "Thuấn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰川頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "頁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "川", "Unihan_Simplified (Chữ Giản thể)": "顺", "Unihan_Traditional (Chữ Phồn thể)": "順", "Pinyin_Xie": "shùn", "Âm Hán Việt_Xie": "thuận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Giới từ | 介词 | Thường làm tính từ đứng trước danh từ hoặc làm động từ chỉ sự tuân theo, đi dọc theo hướng nào đó. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒦', '{"9000": "", "Chữ Trung Quốc": "蒦", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (028) Chích (850)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 028 - cỏ cây) ở trên chữ Chích (số 850 - bắt con chim/chỉ âm). Hình bàn tay thò vào trong bụi cỏ bắt lấy con chim đang trốn. Giải thích sự chuyển ý: Đây là chữ Hội ý. Hoạch là nắm lấy, dùng tay bắt lấy (thu hoạch).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹隻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒦", "Unihan_Traditional (Chữ Phồn thể)": "蒦", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('護', '{"9000": "", "Chữ Trung Quốc": "護", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 20 | nét | 言 | ngôn | biểu nghĩa | lời nói, báo cáo để bảo vệ | 蒦 | hoạch | biểu âm | 護 là chữ hình thanh: bộ 言 (ngôn, biểu nghĩa: lời nói, dùng lời để bảo vệ) kết hợp với 蒦 (hoạch, biểu âm). Ý nghĩa: dùng lời nói để che chở, bảo vệ. Tiểu triện còn lưu. Dạng giản thể là 护.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 護 (hộ/hù) là chữ hình thanh, gồm 言 (lời nói) biểu nghĩa và 蒦 biểu âm. Nghĩa gốc là dùng lời nói để che chở, bảo vệ; sau mở rộng sang mọi hành động bảo vệ. Tiểu triện còn lưu dạng chữ. Dạng giản thể 护 giảm số nét đáng kể. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Hoạch (1009)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói) ở bên trái chữ Hoạch (số 1009 - bắt lấy/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hoạch chỉ âm, bộ Ngôn chỉ ý. Hộ là dùng lời nói để giúp đỡ, che chở, bảo vệ (bảo hộ, cứu hộ).", "Nghĩa Tiếng Việt_Xie": "che chở, bảo vệ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言蒦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "护", "Unihan_Traditional (Chữ Phồn thể)": "護", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "hộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ đối tượng được bảo vệ hoặc kết hợp thành từ ghép như bảo hộ, hộ tống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('認', '{"9000": "", "Chữ Trung Quốc": "認", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 14 | nét | 言 | ngôn | biểu nghĩa | lời nói | 忍 | nhẫn | biểu âm | 認 = 言 (Ngôn, biểu nghĩa: lời nói) + 忍 (Nhẫn, biểu âm); chữ hình thanh. Bộ 言 cho biết đây là hành vi nhận thức qua lời nói hay xác nhận bằng ngôn ngữ; 忍 cho âm.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 認 (chữ phồn thể — giữ nguyên trong bản này) có nghĩa nhận ra, nhận biết, thừa nhận. Wiktionary phân tích hình thanh: 言 (lời nói, biểu nghĩa) + 忍 (biểu âm). Nghĩa gốc gắn với việc \"nói nhận\" — xác nhận bằng lời, từ đó mở rộng thành nhận biết, nhận ra. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Nhẫn (1012)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói) ở bên trái chữ Nhẫn (số 1012 - chịu đựng/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nhẫn chỉ âm, bộ Ngôn chỉ ý. Nhận là dùng lời nói để bày tỏ sự bằng lòng, đồng ý (thừa nhận, nhận thức).", "Nghĩa Tiếng Việt_Xie": "nhận ra, nhận biết; chấp thuận, nhận, bằng lòng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言忍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "忍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "认", "Unihan_Traditional (Chữ Phồn thể)": "認", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ hoặc động từ khác để biểu thị sự nhận biết hoặc đồng ý. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潔', '{"9000": "", "Chữ Trung Quốc": "潔", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Khiết (絜)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước/ 氵) ở bên trái chữ Khiết (絜 - thước dây/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Khiết (絜) chỉ âm, bộ Thủy chỉ ý. Khiết là nước trong sạch. Cũng là từ chỉ sự tu dưỡng thân tâm trong sạch (thanh khiết).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵絜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "絜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洁", "Unihan_Traditional (Chữ Phồn thể)": "潔", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噹', '{"9000": "", "Chữ Trung Quốc": "噹", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030) Đương (520)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 030 - miệng/âm thanh) ở bên trái chữ Đương (số 520 - gánh vác/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đương chỉ âm, bộ Khẩu chỉ ý. Đang là tiếng kêu keng keng do đồ vật kim loại rơi va chạm phát ra.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口當", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "當", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "当", "Unihan_Traditional (Chữ Phồn thể)": "噹", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('進', '{"9000": "", "Chữ Trung Quốc": "進", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 11 | nét | 辵 | biểu nghĩa | bước đi | 隹 | biểu nghĩa | chim đuôi ngắn | 進 = 辵/辶 (biểu nghĩa: bước đi) + 隹 (biểu nghĩa: chim đuôi ngắn); chữ hội ý. Wiktionary ghi ls=ic: chim chỉ bước tiến về phía trước, không lùi lại — vì vậy ý nghĩa là tiến lên, bước vào. Cũng được phân tích là hình thanh (辵+閵).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | 進 là chữ hội ý: 辵 (bước đi) + 隹 (chim đuôi ngắn). Wiktionary giải thích: ''a bird can only walk forward, not backward, hence implying forward''. Cũng có phân tích hình thanh: 辵 + 閵 (ls=psc). Shuowen Jiezi theo cách hình thanh. Nghĩa gốc: tiến lên, bước vào. Dạng giáp cốt, kim văn, đại triện, tiểu triện đều ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Truy (202)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi) bao quanh bộ Truy (số 202 - chim đuôi ngắn/chỉ âm). Loài chim khi vỗ cánh chỉ bay tới phía trước chứ không lùi. Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Truy chỉ âm, bộ Xước chỉ ý. Tiến là đi lên phía trước, thăng tiến (tiến lên, tiến sĩ).", "Nghĩa Tiếng Việt_Xie": "đi vào", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "进", "Unihan_Traditional (Chữ Phồn thể)": "進", "Pinyin_Xie": "jìn", "Âm Hán Việt_Xie": "tiến, tấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trung tâm trong câu hoặc kết hợp với các động từ khác để chỉ xu hướng chuyển động hướng vào trong hoặc đi lên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('體', '{"9000": "", "Chữ Trung Quốc": "體", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 骨 | Số nét | 22 | nét | 骨 | cốt | biểu nghĩa | xương | 豊 | biểu âm | 體 = 骨 (Cốt, biểu nghĩa: xương) + 豊 (biểu âm, âm tǐ≈lǐ); chữ hình thanh. Bộ cốt 骨 gợi ý thân thể gắn liền với bộ xương. 體 là dạng phồn thể; giản thể là 体.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Chữ hình thanh: 骨 (cốt, biểu nghĩa: xương) + 豊 (biểu âm, âm tǐ). Wiktionary xác nhận cấu trúc psc. 體 chỉ thân thể, hình thể, thể chất. Kim văn và tiểu triện đã được ghi nhận. Giản thể 体 (người + bản — thân người là gốc rễ) là cách viết khác về mặt cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cốt (1026) Lễ (1027)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Cốt (số 1026 - xương) ở bên trái chữ Lễ (số 1027 - đồ thờ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Lễ chỉ âm, chữ Cốt chỉ ý. Thể là thân thể, thân mình (cơ thể, thể xác).", "Nghĩa Tiếng Việt_Xie": "thân, mình; hình thể; dạng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨豊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "体", "Unihan_Traditional (Chữ Phồn thể)": "體", "Pinyin_Xie": "tǐ", "Âm Hán Việt_Xie": "thể", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ thân thể, hình thức hoặc làm động từ với nghĩa trải nghiệm, thấu hiểu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('堯', '{"9000": "", "Chữ Trung Quốc": "堯", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thổ (032) Ngột (1029)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Ba bộ Thổ (số 032 - đất) ở trên chữ Ngột (số 1029 - cao bằng phẳng). Đống đất rất cao to mà bằng phẳng trên đỉnh. Giải thích sự chuyển ý: Đây là chữ Hội ý. Nghiêu là cao (cao vút). Cũng là tên gọi của vua Nghiêu (Đường Nghiêu).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>垚兀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "垚", "Unihan_Simplified (Chữ Giản thể)": "尧", "Unihan_Traditional (Chữ Phồn thể)": "堯", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('澆', '{"9000": "", "Chữ Trung Quốc": "澆", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Nghiêu (1030)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước/ 氵) ở bên trái chữ Nghiêu (số 1030 - cao/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nghiêu chỉ âm, bộ Thủy chỉ ý. Kiêu là tưới nước (kiêu thủy).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵堯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浇", "Unihan_Traditional (Chữ Phồn thể)": "澆", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('會', '{"9000": "", "Chữ Trung Quốc": "會", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tập (295) Tằng (934)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tập (số 295 - tụ họp/ 亼) ở trên chữ Tằng (số 934 - từng trải/viết giảm nét thành 曰 ở dưới). Giải thích sự chuyển ý: Đây là chữ Hội ý. Hội là tụ tập lại, hội họp, cuộc gặp mặt (đại hội, hội nghị).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "会", "Unihan_Traditional (Chữ Phồn thể)": "會", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('樂', '{"9000": "", "Chữ Trung Quốc": "樂", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Yêu (052) Bạch (106) Mộc (075)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Bạch (số 106 - bộc bạch tâm sự) ở giữa hai chữ Yêu (số 052 - nhỏ bé/chính là chữ Ti 絲 viết giảm nét chỉ dây đàn), bên dưới là bộ Mộc (số 075 - thân đàn bằng gỗ). Giải thích sự chuyển ý: Đây là chữ Hội ý. Nhạc là nhạc cụ, âm nhạc (âm nhạc, nhạc sĩ). Chữ có âm là Lạc mang nghĩa là vui vẻ (khoái lạc).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "乐", "Unihan_Traditional (Chữ Phồn thể)": "樂", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寶', '{"9000": "", "Chữ Trung Quốc": "寶", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Miên (040) Ngọc (096) Phữu (283) Bối (243)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Miên (số 040 - mái nhà) che chở cho các chữ: Ngọc (số 096), Phữu (số 283 - đồ sành sứ) và Bối (số 243 - tiền bạc). Ngầm ý trong nhà có rất nhiều đồ quý giá. Giải thích sự chuyển ý: Đây là chữ Hội ý. Bảo là đồ vật quý giá, báu vật (bảo bối, gia bảo).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>宀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('強', '{"9000": "", "Chữ Trung Quốc": "強", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cung (057) Khẩu (030) Trùng (142)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Cung (số 057 - cây cung) ở bên trái chữ Khẩu (số 030) và bộ Trùng (số 142 - côn trùng). Cách viết khác thường thấy: 强 (chữ Khẩu đổi thành Tư 厶). Giải thích sự chuyển ý: Đây là chữ Hội ý. Cường là cứng, mạnh mẽ (cường tráng, kiên cường).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰弓𧈧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𧈧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弓", "Unihan_Simplified (Chữ Giản thể)": "强", "Unihan_Traditional (Chữ Phồn thể)": "強", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('運', '{"9000": "", "Chữ Trung Quốc": "運", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 12 | nét | 辵 | sước | biểu nghĩa | chuyển động, di chuyển | 軍 | quân | biểu âm | biểu âm | 運 = 辵 (Sước, biểu nghĩa: chuyển động) + 軍 (Quân, biểu âm); chữ hình thanh. Bộ 辵 xác định nghĩa liên quan đến di chuyển/vận chuyển; phần 軍 cung cấp âm đọc yùn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | Theo Wiktionary, 運 là chữ hình thanh: 辵 (chuyển động) là phần biểu nghĩa, 軍 là phần biểu âm. Nghĩa gốc là di chuyển, vận chuyển; mở rộng sang vận may, số phận. Dạng đại triện và tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Quân (840)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi) bao quanh chữ Quân (số 840 - quân đội/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quân chỉ âm, bộ Xước chỉ ý. Vận là chuyển động, di chuyển (vận chuyển, vận động). Cũng mang ý nghĩa là số mệnh (vận mệnh).", "Nghĩa Tiếng Việt_Xie": "sự may mắn, vận may; sự chuyên trở", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶軍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "軍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "运", "Unihan_Traditional (Chữ Phồn thể)": "運", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "vận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước tân ngữ chỉ hàng hóa hoặc làm danh từ kết hợp với các từ chỉ may mắn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('丂', '{"9000": "", "Chữ Trung Quốc": "丂", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (001)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là hình làn hơi bốc lên (từ dưới) nhưng bị vật gì đó chắn ngang nên phải lượn cong. Nét chắn ngang là nét Nhất (一). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Khảo là khí bị nghẹn lại không thông, vướng mắc.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>一㇉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "一", "Unihan_Simplified (Chữ Giản thể)": "丂", "Unihan_Traditional (Chữ Phồn thể)": "丂", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('號', '{"9000": "", "Chữ Trung Quốc": "號", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 虍 | Số nét | 13 | nét | 号 | hào | biểu âm | gào thét (âm phù) | 虎 | hổ | biểu nghĩa | hổ | Gốc: 號 là tượng hình hổ gầm (hổ với vạch thở ra). Sau đó trở thành hội ý (ic) hoặc hình thanh: 号 (gào, biểu âm) + 虎 (hổ, biểu nghĩa). Nghĩa gốc: gầm rú, la hét — sau mở rộng sang ''hiệu lệnh, danh hiệu, số hiệu''.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Wiktionary: 號 gốc là tượng hình hổ với vạch thể hiện hơi thở gầm rú. Sau phát triển thành hội ý: 号 (miệng gào) + 虎 (hổ). Nghĩa ''gầm, la hét'' là gốc; từ đó phái sinh sang ''tín hiệu, hiệu lệnh, danh hiệu, số''. Trong dạng hiện tại: hội ý và hình thanh kết hợp. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030) Khảo (1042) Hổ (1043)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 030 - miệng) và chữ Khảo (số 1042 - bị nghẹn/chỉ âm) nằm bên cạnh chữ Hổ (số 1043 - con hổ/chỉ ý). Con hổ há miệng gào rống lấy oai. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Hào là tiếng gầm rống của mãnh thú (gao thét). Chữ có âm là Hiệu chỉ danh xưng, tên gọi (danh hiệu, quốc hiệu).", "Nghĩa Tiếng Việt_Xie": "KHÔNG.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰号虎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "号", "Unihan_Simplified (Chữ Giản thể)": "号", "Unihan_Traditional (Chữ Phồn thể)": "號", "Pinyin_Xie": "hào", "Âm Hán Việt_Xie": "hiệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ số hiệu, tên gọi hoặc làm động từ với nghĩa gào khóc, hô to. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('䜌', '{"9000": "", "Chữ Trung Quốc": "䜌", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Ngôn (149)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói) nằm kẹp ở giữa hai bộ Mịch (số 120 - sợi tơ/ 糹). Lời nói rối loạn như cuộn tơ bị vò. Giải thích sự chuyển ý: Đây là chữ Hội ý. Luyến là rối loạn, không dứt ra được.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴絲言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "絲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彎', '{"9000": "", "Chữ Trung Quốc": "彎", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Luyến (1045) Cung (057)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Luyến (số 1045 - rối loạn/chỉ âm) ở trên bộ Cung (số 057 - cây cung/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Luyến chỉ âm, bộ Cung chỉ ý. Loan là cong queo, không thẳng (uốn cong, khúc loan).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>䜌弓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䜌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弓", "Unihan_Simplified (Chữ Giản thể)": "弯", "Unihan_Traditional (Chữ Phồn thể)": "彎", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('𡨄', '{"9000": "", "Chữ Trung Quốc": "𡨄", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Miên (040)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Miên (số 040 - mái nhà) che trên các nét ngang dọc như chữ 茻 (cỏ) và Bát 八. Hình ảnh cánh nhà sàn có những lỗ thủng thưa, dột nát. Giải thích sự chuyển ý: Đây là chữ Hội ý. Tái là mái nhà dột nát, thưa thớt.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>宀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賽', '{"9000": "", "Chữ Trung Quốc": "賽", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tái (1048) Bối (243)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tái (số 1048 - nhà dột/chỉ âm) ở trên bộ Bối (số 243 - tiền bạc/chỉ ý). Sống trong hoàn cảnh nhà thưa vách nát thì càng phải ra sức nỗ lực thi đua kiếm tiền. Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Tái là thi đua, thi đấu (thi đấu, giải tái).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>宀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "赛", "Unihan_Traditional (Chữ Phồn thể)": "賽", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('錦', '{"9000": "", "Chữ Trung Quốc": "錦", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 16 | nét | 金 | kim | biểu âm | 帛 | biểu nghĩa | lụa, vải | 錦 = 金 (Kim, biểu âm) + 帛 (biểu nghĩa: lụa, vải quý). Chữ hình thanh: 帛 (lụa) cho nghĩa loại vải; 金 cho âm jǐn (Hán-Việt: gấm). Gấm là loại lụa dệt hoa văn phức tạp, có giá trị như vàng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 錦 (gấm) là chữ hình thanh theo Wiktionary: {{Han compound|金|帛|c1=p|c2=s|ls=psc}}. Bộ 帛 (lụa) cho nghĩa loại vải dệt hoa; 金 cho âm jǐn. Middle Chinese và Old Chinese đều ghi nhận. Gấm là loại lụa dệt hoa văn phức tạp, từng được coi quý như vàng — vải 帛 của 金 (vàng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (069) Bạch (842)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 069 - kim loại/chỉ âm) ở bên trái chữ Bạch (số 842 - tấm lụa trắng/chỉ ý - viết là 帛). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Kim chỉ âm, chữ Bạch (帛) chỉ ý. Cẩm là thứ vải lụa gấm dệt hoa văn đẹp và quý (gấm vóc, cẩm tú).", "Nghĩa Tiếng Việt_Xie": "gấm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金帛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "锦", "Unihan_Traditional (Chữ Phồn thể)": "錦", "Pinyin_Xie": "jǐn", "Âm Hán Việt_Xie": "cẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ vải dệt hoa rực rỡ hoặc làm tính từ mô tả sự đẹp đẽ, lộng lẫy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('標', '{"9000": "", "Chữ Trung Quốc": "標", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Phiếu (1003)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây cối) ở bên trái chữ Phiếu (số 1003 - tờ phiếu/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Phiếu chỉ âm, bộ Mộc chỉ ý. Tiêu là ngọn cây (cành cao nhất). Cũng mang ý nghĩa là dấu hiệu, mục tiêu để nhắm tới.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木票", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "标", "Unihan_Traditional (Chữ Phồn thể)": "標", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('僉', '{"9000": "", "Chữ Trung Quốc": "僉", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tập (295) Huyên (139) Từ (235)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tập (số 295 - hội họp/ 亼) ở trên, ở giữa là chữ Huyên (số 139 - nhiều miệng kêu/ 吅), dưới cùng là chữ Từ (số 235 - hai người đi theo/ 从). Hình ảnh tất cả mọi người tụ tập lại cùng đồng thanh nói như nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Thiêm có nghĩa là đều, cùng, tất cả.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>亼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "佥", "Unihan_Traditional (Chữ Phồn thể)": "僉", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臉', '{"9000": "", "Chữ Trung Quốc": "臉", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 肉 | Số nét | 17 | nét | ⺼ | nhục | biểu nghĩa | thịt, bộ phận cơ thể | 僉 | thiêm | biểu âm | tất cả, đồng lòng | 臉 = ⺼ (Nhục/月, biểu nghĩa: bộ phận cơ thể) + 僉 (Thiêm, biểu âm); chữ hình thanh. Phần ⺼ chỉ đây là bộ phận cơ thể (mặt, má), phần 僉 cho biết âm đọc liǎn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 臉 là chữ hình thanh: ⺼/肉 (biểu nghĩa, bộ phận cơ thể) kết hợp với 僉 (biểu âm). Nghĩa là khuôn mặt, má, diện mạo; cũng mang nghĩa danh dự, thể diện. Đây là dạng phồn thể — 脸 là dạng giản thể. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhục (250) Thiêm (1055)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhục (số 250 - cơ thể/viết dạng 月) ở bên trái chữ Thiêm (số 1055 - tất cả/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thiêm chỉ âm, bộ Nhục chỉ ý. Kiểm là cái má ở trên mặt con người. Nó cũng có nghĩa là vẻ mặt, sắc mặt.", "Nghĩa Tiếng Việt_Xie": "khuôn mặt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月僉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "僉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脸", "Unihan_Traditional (Chữ Phồn thể)": "臉", "Pinyin_Xie": "liǎn", "Âm Hán Việt_Xie": "kiem", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ bộ phận khuôn mặt của con người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('樣', '{"9000": "", "Chữ Trung Quốc": "樣", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Dạng (1057)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây cối/vật liệu) ở bên trái chữ Dạng (số 1057 - con sông/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Dạng chỉ âm, bộ Mộc chỉ ý. Dạng là vật liệu dùng làm mẫu. Cũng có nghĩa là hình dáng, kiểu mẫu, cách thức (hình dạng, đa dạng).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木羕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "样", "Unihan_Traditional (Chữ Phồn thể)": "樣", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓋', '{"9000": "", "Chữ Trung Quốc": "蓋", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 艸 | Số nét | 13 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật | 盍 | hạp | biểu âm | tại sao không; che đậy | 蓋 = 艸 (Thảo, biểu nghĩa: cỏ/lá) + 盍 (Hạp, biểu âm); chữ hình thanh. Nghĩa gốc là mái lợp tranh. 盍 vốn là chữ gốc chỉ \"che đậy\" nhưng bị vay mượn sang nghĩa \"tại sao không\", nên 蓋 đảm nhận nghĩa che phủ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Bạch thư | Đại triện | Tiểu triện | 蓋 là chữ hình thanh: 艸 (cỏ) cho nghĩa, 盍 cho âm. Nghĩa gốc là mái tranh (thatch). 盍 vốn chỉ \"che đậy\" nhưng bị mượn nghĩa sang \"tại sao không\", nên 蓋 đảm nhận nghĩa che phủ và mở rộng sang nắp đậy, che giấu, hơn cả. Có dạng bạch thư, đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (028) Hạp (1063)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 028 - cỏ) che ở trên chữ Hạp (số 1063 - hợp lại/đậy lại/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hạp chỉ âm, bộ Thảo chỉ ý. Cái là vật dùng để che đậy (như túp lều cỏ lợp trên bát đĩa), cái nắp, cái vung. Cũng có nghĩa là che đậy, vượt trội hơn (tài trí cái thế).", "Nghĩa Tiếng Việt_Xie": "che phủ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹盍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "盖", "Unihan_Traditional (Chữ Phồn thể)": "蓋", "Pinyin_Xie": "gài", "Âm Hán Việt_Xie": "cai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Liên từ | 连词 | Chữ này làm động từ đứng trước danh từ để chỉ hành động che phủ hoặc làm danh từ chỉ cái nắp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('許', '{"9000": "", "Chữ Trung Quốc": "許", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 11 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn ngữ | 午 | ngọ | biểu âm | giờ Ngọ (11h-13h), hướng Nam | 許 = 言 (Ngôn, biểu nghĩa: lời nói) + 午 (Ngọ, biểu âm); chữ hình thanh — bộ 言 chỉ lời nói, lời hứa, 午 cho âm xǔ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 許 là chữ hình thanh: 言 (lời nói) biểu nghĩa, 午 biểu âm. Nguyên nghĩa là nói lên lời cho phép, đồng ý — hứa hẹn, chấp thuận bằng lời. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Ngọ (144)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói) ở bên trái chữ Ngọ (số 144 - can Ngọ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ngọ chỉ âm, bộ Ngôn chỉ ý. Hứa là dùng lời nói để bằng lòng, nghe theo, cho phép (cho phép, hứa hẹn).", "Nghĩa Tiếng Việt_Xie": "như thế (tiếng dùng làm trợ ngữ)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言午", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "午", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "许", "Unihan_Traditional (Chữ Phồn thể)": "許", "Pinyin_Xie": "xǔ", "Âm Hán Việt_Xie": "hử, hổ, hứa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Thường làm động từ biểu thị sự đồng ý, cho phép hoặc làm phó từ chỉ sự ước lượng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('對', '{"9000": "", "Chữ Trung Quốc": "對", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trạc (丵) Thốn (041)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Trạc (丵 - cây cỏ mọc xum xuê/giống chữ Nghiệp 業 mất chữ Mộc 木) ở bên trái bộ Thốn (số 041 - cái tay). Giải thích sự chuyển ý: Đây là chữ Hội ý. Đối là hướng về phía nhau, cư xử qua lại. Cũng có nghĩa là ứng đáp, đối đáp đúng đắn (đối mặt, đối lập).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰寸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "对", "Unihan_Traditional (Chữ Phồn thể)": "對", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啇', '{"9000": "", "Chữ Trung Quốc": "啇", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lập (112) Cổ (107)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lập (số 112 - đứng) ở trên chữ Cổ (số 107 - xưa, cổ). Phần chân chữ Lập cắm sâu xuống, ôm trọn lấy chữ Cổ. Giải thích sự chuyển ý: Đây là chữ Hội ý. Ngụ ý rằng cái gì muốn đứng vững (Lập) thì phải bám chặt, gắn liền với nguồn cội, truyền thống cổ xưa (Cổ). Đích là cái gốc rễ, cội nguồn.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>𪞐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讓', '{"9000": "", "Chữ Trung Quốc": "讓", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 24 | nét | 言 | ngôn | biểu nghĩa | lời nói | 襄 | tương | biểu âm | giúp đỡ, phụ trợ | 讓 = 言 (Ngôn, biểu nghĩa: lời nói) + 襄 (Tương, biểu âm). Đây là chữ hình thanh: bộ 言 cho biết nghĩa liên quan đến ngôn ngữ/thái độ, 襄 cho âm. Nghĩa gốc là phê bình, quở trách; phái sinh thành ''nhường, nhượng bộ''.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Theo Wiktionary, 讓 là chữ hình thanh: 言 (lời nói) biểu nghĩa + 襄 biểu âm. Nghĩa gốc là dùng lời phê bình, quở trách. Phái sinh thêm nghĩa ''nhường, nhượng bộ'' — lùi bước, nhường chỗ. Tiểu triện và lục thư thông đã được ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Tương (1077)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói) ở bên trái chữ Tương (số 1077 - nhường/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tương chỉ âm, bộ Ngôn chỉ ý. Nhượng là dùng lời nói để nhường nhịn, từ chối nhường cho người khác (nhượng bộ, khiêm nhượng).", "Nghĩa Tiếng Việt_Xie": "thua kém; nhường; mời", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言襄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "襄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "让", "Unihan_Traditional (Chữ Phồn thể)": "讓", "Pinyin_Xie": "ràng", "Âm Hán Việt_Xie": "nhường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Giới từ | 介词 | Chữ này làm động từ đứng trước tân ngữ để biểu thị sự nhường nhịn hoặc làm giới từ trong câu bị động. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('農', '{"9000": "", "Chữ Trung Quốc": "農", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辰 | Số nét | 13 | nét | 曲 | khúc | biểu nghĩa | đôi tay (trong dạng gốc) | 辰 | thìn | biểu nghĩa | ruộng đồng, công cụ làm ruộng | 農 = 曲 + 辰; chữ hội ý. Wiktionary giải thích: phần trên không phải 曲 thực sự mà là hai bàn tay xưa; 辰 biểu thị ruộng đồng. Hình ảnh người nông dân đôi tay mang sản vật từ đồng ruộng ra chợ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Chữ hội ý. Trong dạng hiện tại gồm 曲+辰 (ruộng). Nhưng Wiktionary xác nhận: phần trên ban đầu là hai bàn tay — nông dân mang sản vật từ đồng (辰). Giáp cốt văn, kim văn đều có. Dạng phồn thể, giản thể là 农. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khúc (496) Thìn (859)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Khúc (số 496 - bài hát) ở trên bộ Thìn (số 859 - tháng 3). Vào tháng Thìn bắt đầu có mưa, nhà nông lo cày cấy, vừa làm vừa hát các bài ca đối đáp với nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Nông là làm ruộng, hoặc người làm nghề nông (nông nghiệp, nhà nông).", "Nghĩa Tiếng Việt_Xie": "người làm ruộng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>曲辰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辰", "Unihan_Simplified (Chữ Giản thể)": "农", "Unihan_Traditional (Chữ Phồn thể)": "農", "Pinyin_Xie": "nóng", "Âm Hán Việt_Xie": "nông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ ngành nông nghiệp hoặc làm tính từ liên quan đến nhà nông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餵', '{"9000": "", "Chữ Trung Quốc": "餵", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 食 | Số nét | 17 | nét | 食 | thực | biểu nghĩa | ăn, thức ăn | 畏 | uý | biểu âm | sợ hãi | 餵 = 食 (Thực, biểu nghĩa: thức ăn) + 畏 (Uý, biểu âm). Chữ hình thanh: 食 chỉ hành động liên quan đến ăn uống, 畏 cho âm đọc. Nghĩa là cho ăn (người hay động vật), nuôi dưỡng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 餵 là chữ hình thanh (psc): bộ 食 biểu nghĩa ''thức ăn'', thành phần 畏 biểu âm. Nghĩa là cho ăn (thú vật, người), nuôi dưỡng. Trong tiếng Việt không có từ Hán-Việt tương ứng thông dụng từ chữ này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thực (066) Úy (1085)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thực (số 066 - thức ăn/viết dạng 飠) ở bên trái chữ Úy (số 1085 - sợ hãi/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Úy chỉ âm, bộ Thực chỉ ý. Ủy là đút cho ăn, nuôi dưỡng súc vật chăn nuôi.", "Nghĩa Tiếng Việt_Xie": "Xin chào", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠畏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "vị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ mang tân ngữ chỉ người hoặc động vật được cho ăn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('條', '{"9000": "", "Chữ Trung Quốc": "條", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Du (1087)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Du (số 1087 - nhanh chóng/chỉ âm) lồng ghép vào bên trong bộ Mộc (số 075 - cây cối). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Du chỉ âm, bộ Mộc chỉ ý. Điều là những cành nhỏ trên cây. Sau mang ý nghĩa là các điều khoản, thứ tự mạch lạc (điều khoản, điều kiện).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰条", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "条", "Unihan_Traditional (Chữ Phồn thể)": "條", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趕', '{"9000": "", "Chữ Trung Quốc": "趕", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 走 | Số nét | 14 | nét | 走 | tẩu | biểu nghĩa | chạy, đi nhanh | 旱 | hạn | biểu âm | (biểu âm) | 趕 = 走 (Tẩu, biểu nghĩa: chạy, đi nhanh) + 旱 (Hạn, biểu âm); chữ hình thanh. Bộ 走 cho biết liên quan đến chạy, đuổi theo; 旱 (hạn) cung cấp âm đọc gǎn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 趕 là chữ hình thanh: bộ 走 (tẩu — chạy) biểu nghĩa, 旱 (hạn) biểu âm. Nghĩa gốc là đuổi theo, bắt kịp; mở rộng thành xua đuổi, vội vàng, lái (súc vật). Dùng trong 趕快 (mau lên), 追趕 (đuổi theo), 趕到 (kịp đến). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tẩu (204) Hạn (1089)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tẩu (số 204 - chạy, đi) ở bên trái chữ Hạn (số 1089 - khô hạn/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hạn chỉ âm, bộ Tẩu chỉ ý. Cản là đuổi theo, lùa súc vật đi.", "Nghĩa Tiếng Việt_Xie": "đuổi theo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走旱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "赶", "Unihan_Traditional (Chữ Phồn thể)": "趕", "Pinyin_Xie": "gǎn", "Âm Hán Việt_Xie": "cán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Giới từ | 介词 | Làm động từ biểu thị hành động đuổi theo hoặc làm giới từ chỉ thời gian cận kề. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賴', '{"9000": "", "Chữ Trung Quốc": "賴", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 16 | nét | 剌 | lạt | biểu âm | cho âm lài/lại | 貝 | buổi | biểu nghĩa | tiền, vật có giá trị | 賴 là chữ hình thanh: 剌 (Lạt, biểu âm) + 貝 (Bối, biểu nghĩa — tiền, vật có giá trị). Wiktionary ghi: {{Han compound|剌|貝|c1=p|c2=s|t2=cowry|ls=psc}} – to profit. Nghĩa gốc: thu lợi, nhờ cậy; sau mở rộng sang \"ỷ lại, không chịu nhận\".", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Wiktionary ghi 賴 là chữ hình thanh: 剌 (biểu âm) + 貝 (vỏ sò — tiền cổ, biểu nghĩa). Nghĩa gốc: thu lợi (to profit), nhờ cậy vào thứ gì đó. Mở rộng: ỷ lại (依賴 — phụ thuộc), chối bỏ trách nhiệm (賴賬 — chối nợ). Phồn thể 賴; giản thể 赖. Cũng dùng làm họ người (姓賴). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lạt (剌) Bối (243)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lạt (剌 - chặt đứt/chỉ âm - ghép bởi Thúc 束 bó buộc và Đao 刀) nằm ở bên trái bộ Bối (số 243 - tiền bạc/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Lạt chỉ âm, bộ Bối chỉ ý. Khi gặp hoàn cảnh bó buộc khó khăn thì đành phải cậy nhờ người khác. Lại là nhờ cậy, nương tựa, ỷ lại (ỷ lại, vô lại).", "Nghĩa Tiếng Việt_Xie": "nhờ cậy; ích lợi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰束負", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "負", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "束", "Unihan_Simplified (Chữ Giản thể)": "赖", "Unihan_Traditional (Chữ Phồn thể)": "賴", "Pinyin_Xie": "lài", "Âm Hán Việt_Xie": "lại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ biểu thị hành động dựa dẫm hoặc đổ oan cho người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('懶', '{"9000": "", "Chữ Trung Quốc": "懶", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (061) Lại (1093)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tâm (số 061 - trái tim/viết dạng 忄) ở bên trái chữ Lại (số 1093 - ỷ lại/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Lại chỉ âm, bộ Tâm chỉ ý. Lãn là tâm trí lười biếng, biếng nhác (lãn công, lười lãn).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄賴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馱', '{"9000": "", "Chữ Trung Quốc": "馱", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mã (056) Đại (029)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mã (số 056 - con ngựa) ở bên trái chữ Đại (số 029 - to lớn/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đại chỉ âm, bộ Mã chỉ ý. Đà là dùng ngựa chở đồ vật, thồ hàng cồng kềnh (thồ, đà).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬大", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "大", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沒', '{"9000": "", "Chữ Trung Quốc": "沒", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Bao (055) Hựu (047)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước/ 氵) ở bên trái chữ Bao (số 055 - bao bọc) và chữ Hựu (số 047 - cánh tay). Người bị đuối nước, bị nước trùm phủ lên, cánh tay vùng vẫy cũng bị che mất. Giải thích sự chuyển ý: Đây là chữ Hội ý. Một là chìm đắm dưới nước, mất tích (mai một). Cũng mang nghĩa là không có.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "没", "Unihan_Traditional (Chữ Phồn thể)": "沒", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麥', '{"9000": "", "Chữ Trung Quốc": "麥", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 麥 | Số nét | 11 | nét | 來 | lai | biểu âm | âm gốc | 夊 | biểu nghĩa | dấu chân hướng xuống, đi chậm | 麥 = 來 (Lai, biểu âm) + 夊 (dấu chân hướng xuống, biểu nghĩa). Chữ hình thanh: 來 cho âm, 夊 gợi ý bước chân — lúa mì được mang đến từ xa theo từng bước chân.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt | Kim văn | Đại triện | Tiểu triện | Ban đầu chữ 來 vốn có nghĩa là lúa mì (hình ảnh bông lúa), nhưng bị mượn âm để viết nghĩa \"đến\". Người ta tạo 麥 bằng cách thêm 夊 (dấu chân) vào dưới 來 để giữ lại nghĩa lúa mì. Theo Wiktionary: 來 biểu âm, 夊 biểu nghĩa (bước đi — lúa mì được mang đến). Nhiều học giả đồng thuận về việc 麥 là chữ phân hóa từ 來. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lai (281) Tuy (593)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lai (số 281 - lúa mì/tới) ở trên chữ Tuy (số 593 - bước chậm/ 夊). Hình ảnh cây lúa mạch có rễ mọc rủ xuống. Giải thích sự chuyển ý: Đây là chữ Tượng hình (hoặc Hội ý). Mạch là lúa mạch, lúa mì.", "Nghĩa Tiếng Việt_Xie": "lúa tẻ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>來夂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "來", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "夂", "Unihan_Simplified (Chữ Giản thể)": "麦", "Unihan_Traditional (Chữ Phồn thể)": "麥", "Pinyin_Xie": "mài", "Âm Hán Việt_Xie": "mạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm định ngữ trong các cụm từ chỉ các loại ngũ cốc, bột mì. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擔', '{"9000": "", "Chữ Trung Quốc": "擔", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Chiêm (1116)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌) ở bên trái chữ Chiêm (số 1116 - chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Chiêm chỉ âm, bộ Thủ chỉ ý. Đảm là dùng tay để gánh vác, khiêng vác. Cũng mang ý nghĩa là đảm nhận, chịu trách nhiệm (đảm nhiệm, bảo đảm).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌詹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "詹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "担", "Unihan_Traditional (Chữ Phồn thể)": "擔", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甚', '{"9000": "", "Chữ Trung Quốc": "甚", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 甘 | Số nét | 9 | nét | 甘 | cam | biểu nghĩa | ngọt — vị ngon | 匕 | chuỷ | biểu nghĩa | cái thìa — múc thức ăn ngon | 甚 là chữ hội ý (ic): 甘 (vị ngọt) + 匕 (cái thìa) — múc thứ rất ngon, cực kỳ thích thú. Nghĩa gốc ''rất, cực kỳ'' — biểu thị mức độ cao.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | Theo Wiktionary, 甚 là chữ hội ý gồm 甘 (vị ngọt) + 匕 (cái thìa) — múc cho mình thứ ngon ngọt nhất, từ đó phái sinh nghĩa ''rất, cực kỳ, quá mức''. Trong tiếng Trung hiện đại, 甚 chủ yếu xuất hiện trong các từ ghép như 甚至 (thậm chí), 甚至于, ít khi đứng độc lập. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cam (1121) Thất (159)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Cam (số 1121 - vị ngọt/chỉ ý) ở trên chữ Thất (số 159 - chữ 匹 - tấm vải/chỉ âm). Ăn đồ ngọt đến mức quá nhiều. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thất chỉ âm, chữ Cam chỉ ý. Thậm là rất, lắm, hết mực, vượt quá giới hạn (thậm chí, thái thậm).", "Nghĩa Tiếng Việt_Xie": "rất", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>甘匹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "甘", "Unihan_Simplified (Chữ Giản thể)": "甚", "Unihan_Traditional (Chữ Phồn thể)": "甚", "Pinyin_Xie": "shén", "Âm Hán Việt_Xie": "thậm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Đại từ | 代词 | Thường làm phó từ đứng trước tính từ hoặc động từ tâm lý để biểu thị mức độ cao. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豬', '{"9000": "", "Chữ Trung Quốc": "豬", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 豕 | Số nét | 15 | nét | 豕 | thỉ | biểu nghĩa | lợn | 者 | giả | biểu âm | 豬 = 豕 (Thỉ, biểu nghĩa: lợn) + 者 (Giả, biểu âm); chữ hình thanh. Bộ 豕 xác nhận nghĩa là lợn; 者 cho âm đọc gần zhū.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Bạch thư | Tiểu triện | 豬 (zhū) là chữ hình thanh: bộ 豕 (lợn) cho nghĩa — con lợn; 者 (giả) cho âm. Wiktionary xác nhận cấu trúc Han compound ls=psc. Có dạng bạch thư (帛書) và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thỉ (373) Giả (662)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thỉ (số 373 - con lợn) ở bên trái chữ Giả (số 662 - đại từ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Giả chỉ âm, bộ Thỉ chỉ ý. Trư là con heo, lợn rùng, lợn nhà (trư bát giới).", "Nghĩa Tiếng Việt_Xie": "con lợn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豕者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豕", "Unihan_Simplified (Chữ Giản thể)": "猪", "Unihan_Traditional (Chữ Phồn thể)": "豬", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "trư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với các từ khác để chỉ các bộ phận hay món ăn từ lợn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('領', '{"9000": "", "Chữ Trung Quốc": "領", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 頁 | Số nét | 14 | nét | 令 | lệnh | biểu âm | lệnh, mệnh lệnh | 頁 | hiệt | biểu nghĩa | đầu, trang | 領 = 令 (Lệnh, biểu âm) + 頁 (Hiệt, biểu nghĩa: đầu/cổ); chữ hình thanh. Phần 頁 chỉ liên quan đến vùng đầu/cổ, phần 令 cho biết âm đọc lǐng — gần với Hán-Việt lãnh.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Theo Wiktionary, 領 là chữ hình thanh: 令 (biểu âm) kết hợp với 頁 (biểu nghĩa, đầu/cổ). Nghĩa gốc là cổ áo, vùng cổ; từ đó phát sinh nghĩa dẫn dắt, lãnh đạo (người đứng đầu), lĩnh vực. Có hình đại triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lệnh (1128) Hiệt (119)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lệnh (số 1128 - mệnh lệnh/chỉ âm) ở bên trái bộ Hiệt (số 119 - cái đầu/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Lệnh chỉ âm, bộ Hiệt chỉ ý. Lĩnh (Lãnh) là người đứng đầu, nắm giữ quyền chỉ huy (lãnh đạo, thủ lĩnh). Cũng có nghĩa là nhận lấy (lĩnh thưởng, lĩnh hội).", "Nghĩa Tiếng Việt_Xie": "cổ áo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰令頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "领", "Unihan_Traditional (Chữ Phồn thể)": "領", "Pinyin_Xie": "lǐng", "Âm Hán Việt_Xie": "lãnh, lĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ mang tân ngữ như lĩnh tiền, lãnh đạo hoặc làm danh từ chỉ cổ áo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('給', '{"9000": "", "Chữ Trung Quốc": "給", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 12 | nét | 糸 | mịch | biểu nghĩa | sợi tơ | 合 | cáp | biểu âm | 給 = 糸 (Mịch, biểu nghĩa: sợi tơ/lụa quý) + 合 (Cáp, biểu âm); chữ hình thanh. Phần 糸 gợi của cải quý báu; 合 cho âm gěi/jǐ. Nghĩa gốc: giàu có, phong phú; mở rộng ra nghĩa cho.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Shuowen Jiezi (dẫn trong Wiktionary), 給 là chữ hình thanh: 糸 (mịch, biểu nghĩa: sợi tơ) kết hợp với 合 (cáp, biểu âm). Nghĩa gốc là \"giàu có, phong phú\" — gợi lụa tơ dồi dào; ngày nay chủ yếu nghĩa \"cho\". | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Hợp (145)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糹) ở bên trái chữ Hợp (số 145 - hợp lại/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Hợp chỉ âm, bộ Mịch chỉ ý. Cấp là đưa cho, ban cho, cung cấp vật dụng đầy đủ (cung cấp, cấp dưỡng).", "Nghĩa Tiếng Việt_Xie": "đưa cho", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹合", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "给", "Unihan_Traditional (Chữ Phồn thể)": "給", "Pinyin_Xie": "gěi", "Âm Hán Việt_Xie": "cấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Giới từ | 介词 | Trợ từ | 助词 | Thường làm động từ mang tân ngữ chỉ người nhận hoặc làm giới từ biểu thị đối tượng tiếp nhận. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吅', '{"9000": "", "Chữ Trung Quốc": "吅", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm hai chữ Khẩu (số 030 - cái miệng) đặt cạnh song song nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Huyên là nhiều lời, ồn ào (nói huyên thuyên). Thường đóng vai trò làm thành phần cấu tạo chữ khác.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "吅", "Unihan_Traditional (Chữ Phồn thể)": "吅", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('歡', '{"9000": "", "Chữ Trung Quốc": "歡", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Quán (1133) Khiếm (410)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Quán (số 1133 - chim nhỏ kêu/chỉ âm) ở bên trái bộ Khiếm (số 410 - há miệng/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quán chỉ âm, bộ Khiếm chỉ ý. Hoan là há miệng cười to, vui mừng vui vẻ (hoan hỉ, hoan nghênh).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰雚欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "欠", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('現', '{"9000": "", "Chữ Trung Quốc": "現", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngọc (096) Kiến (169)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngọc (số 096 - ngọc/viết dạng 王) ở bên trái chữ Kiến (số 169 - nhìn thấy/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Kiến chỉ âm, bộ Ngọc chỉ ý. Viên ngọc phát ra ánh sáng nhìn thấy rất rõ ràng. Hiện là rõ ràng, có thật trước mắt, xuất hiện. Cũng có nghĩa là bây giờ, ngày nay (hiện tại, hiện nay).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "見", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "现", "Unihan_Traditional (Chữ Phồn thể)": "現", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('點', '{"9000": "", "Chữ Trung Quốc": "點", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 黑 | Số nét | 17 | nét | 黑 | hắc | biểu nghĩa | đen, tối | 占 | chiêm | biểu âm | chiếm, bói | 點 = 黑 (Hắc, biểu nghĩa: đen/tối) + 占 (Chiêm, biểu âm); chữ hình thanh. Bộ 黑 xác định nghĩa liên quan đến màu tối, vết nhỏ; 占 cung cấp âm đọc diǎn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 點 là chữ hình thanh: 黑 (hắc) biểu nghĩa — màu đen, vết đen; 占 (chiêm) biểu âm. Nghĩa gốc là chấm nhỏ màu tối. Từ đó mở rộng: điểm, vị trí, chút ít, chạm nhẹ vào. Giản thể là 点. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hắc (270) Chiêm (1116)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hắc (số 270 - màu đen) ở bên trái chữ Chiêm (số 1116 - nói nhiều/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Chiêm chỉ âm, bộ Hắc chỉ ý. Điểm là một chấm đen nhỏ, vết nhơ nhỏ (dấu điểm, ưu điểm). Cũng có nghĩa là một chút, một tí.", "Nghĩa Tiếng Việt_Xie": "điểm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黑占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黑", "Unihan_Simplified (Chữ Giản thể)": "点", "Unihan_Traditional (Chữ Phồn thể)": "點", "Pinyin_Xie": "diǎn", "Âm Hán Việt_Xie": "điểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ giờ giấc, động từ chỉ hành động gật đầu hoặc lượng từ cho một chút. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('誰', '{"9000": "", "Chữ Trung Quốc": "誰", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 15 | nét | 言 | ngôn | biểu nghĩa | nói, lời nói | 隹 | chuy | biểu âm | 誰 = 言 (Ngôn, biểu nghĩa: nói) + 隹 (Chuy, biểu âm); chữ hình thanh. Bộ 言 gắn với hành vi ngôn ngữ/hỏi, 隹 cho âm đọc shuí.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 誰 là chữ hình thanh: 言 (nói) làm thành phần biểu nghĩa, 隹 làm thành phần biểu âm. Nghĩa: đại từ hỏi — ai, người nào. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Truy (202)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/chỉ ý) ở bên trái chữ Truy (số 202 - chim đuôi ngắn/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Truy chỉ âm, bộ Ngôn chỉ ý. Thùy là đại từ dùng để hỏi: ai, người nào (thùy tri - ai biết).", "Nghĩa Tiếng Việt_Xie": "ai (câu hỏi)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "谁", "Unihan_Traditional (Chữ Phồn thể)": "誰", "Pinyin_Xie": "shuí", "Âm Hán Việt_Xie": "thùy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Chữ này làm đại từ nghi vấn đứng ở vị trí chủ ngữ hoặc tân ngữ để hỏi về người. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('編', '{"9000": "", "Chữ Trung Quốc": "編", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 15 | nét | 糸 | mịch | biểu nghĩa | sợi chỉ, tơ | 扁 | thiên | biểu âm | 編 = 糸 (Mịch, biểu nghĩa: sợi chỉ) + 扁 (Thiên, biểu âm); chữ hình thanh. Bộ Mịch gợi hành động đan/dệt bằng sợi chỉ, phần 扁 cho âm đọc biān. Gốc nghĩa là kết nối các sợi thành sách bằng cách đóng gáy.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Tiểu triện | Chữ hình thanh: 糸 (sợi chỉ, biểu nghĩa) + 扁 (biểu âm). Nghĩa gốc là ''kết sách bằng sợi chỉ'' — thời cổ đại người Hán dùng dây buộc các thanh tre/gỗ lại thành sách (竹簡). Từ đó 編 mở rộng thành ''dệt, soạn thảo, biên soạn, biên chế''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Biển (188)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糹/chỉ ý) ở bên trái chữ Biển (số 188 - dẹp, mỏng/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Biển chỉ âm, bộ Mịch chỉ ý. Biên là dùng sợi dây xâu các thẻ tre tạo thành sách, đan bện (biên kết). Từ đó mang nghĩa là biên soạn, ghi chép lại.", "Nghĩa Tiếng Việt_Xie": "biên soạn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹扁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "编", "Unihan_Traditional (Chữ Phồn thể)": "編", "Pinyin_Xie": "biān", "Âm Hán Việt_Xie": "biên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước tân ngữ để chỉ hoạt động biên soạn sách vở hoặc đan lát đồ vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禸', '{"9000": "", "Chữ Trung Quốc": "禸", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Quynh (020) Tư (165)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Quynh (số 020 - vùng xa xôi) bao quanh bộ Tư (số 165 - riêng tư). Hình ảnh dấu vết chân thú in trên mặt đất. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Nhựu là vết chân của dã thú in trên đất (bộ Nhựu).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>厶冂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厶", "Unihan_Simplified (Chữ Giản thể)": "禸", "Unihan_Traditional (Chữ Phồn thể)": "禸", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('離', '{"9000": "", "Chữ Trung Quốc": "離", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 隹 | Số nét | 18 | nét | 离 | ly | biểu âm | 隹 | biểu nghĩa | chim | 離 = 离 (Ly, biểu âm) + 隹 (biểu nghĩa: chim). Chữ hình thanh. Nghĩa gốc là con chim hoàng anh đen (black-naped oriole); sau đó mượn âm để chỉ nghĩa rời xa.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Wiktionary: 離 gốc là 离 + 隹 (chim), nghĩa đầu là chim hoàng anh đen (Oriolus chinensis). Sau đó mượn âm (phono-semantic borrowing) để chỉ nghĩa rời đi, xa cách — nghĩa này chiếm ưu thế trong tiếng Hán hiện đại. Còn lưu trong từ 離黃 (tên cũ loài chim). Có dạng tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Truy (202) Hung (1152) Nhựu (1153)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Truy (số 202 - con chim), chữ Hung (số 1152 - hung dữ) và chữ Nhựu (số 1153 - vết chân thú). Con thú gặp con chim ác liền bỏ chạy để lại vết chân. Giải thích sự chuyển ý: Đây là chữ Hội ý (hoặc Hình thanh). Ly là chia lìa, rời xa, chia cách (ly biệt, chia ly).", "Nghĩa Tiếng Việt_Xie": "tránh xa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰离隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "离", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "lệ, ly, li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Giới từ | 介词 | Thường làm động từ chỉ sự chia tách hoặc làm giới từ biểu thị khoảng cách không gian, thời gian. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籬', '{"9000": "", "Chữ Trung Quốc": "籬", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 竹 | Số nét | 24 | nét | 竹 | trúc | biểu nghĩa | bamboo | 離 | li | biểu âm | 籬 = 竹 (Trúc, biểu nghĩa: tre) + 離 (Li, biểu âm); chữ hình thanh. Hàng rào làm bằng tre — bộ 竹 biểu nghĩa (chất liệu tre), 離 cho âm lí.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 籬 là chữ hình thanh: 竹 (trúc, biểu nghĩa) + 離 (li, biểu âm). Wiktionary xác nhận cấu trúc rõ ràng. Nghĩa: hàng rào bằng tre hoặc cành cây; cũng dùng trong 笊籬 (cái vợt, rây). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (108) Ly (1154)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 108 - tre trúc) ở trên chữ Ly (số 1154 - rời xa/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ly chỉ âm, bộ Trúc chỉ ý. Ly là hàng rào bờ dậu được làm từ tre trúc (phàn ly).", "Nghĩa Tiếng Việt_Xie": "hàng rào", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>⺮離", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "離", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篱", "Unihan_Traditional (Chữ Phồn thể)": "籬", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ hàng rào bảo vệ quanh nhà hoặc vườn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋤', '{"9000": "", "Chữ Trung Quốc": "鋤", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 15 | nét | 金 | kim | biểu nghĩa | kim loại | 助 | trợ | biểu âm | 鋤 = 金 (Kim, biểu nghĩa: kim loại) + 助 (Trợ, biểu âm: cho âm chú/trừ). Chữ hình thanh.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 鋤 là chữ hình thanh: 金 (kim loại) biểu nghĩa, 助 biểu âm. Nghĩa gốc: cuốc (công cụ nông nghiệp bằng kim loại). Mở rộng: nhổ bỏ, tiêu diệt (鋤草, 鋤強扶弱). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (069) Trợ (1156)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 069 - kim loại) ở bên trái chữ Trợ (số 1156 - giúp sức/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Trợ chỉ âm, bộ Kim chỉ ý. Sừ là cái cuốc, cái bừa làm bằng sắt để giúp nhà nông làm ruộng.", "Nghĩa Tiếng Việt_Xie": "cuốc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金助", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "助", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "锄", "Unihan_Traditional (Chữ Phồn thể)": "鋤", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "trừ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cái cuốc hoặc làm động từ chỉ hành động cuốc đất, làm cỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('歸', '{"9000": "", "Chữ Trung Quốc": "歸", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phụ (164) Chỉ (158) Trửu (393)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm bộ Phụ (số 164 - núi đất/viết dạng 𠂤) ở trên chữ Chỉ (số 158 - bàn chân), bên cạnh là chữ Trửu (số 393 - cái chổi). Người con gái lấy chồng mang theo cái chổi gánh vác việc nhà. Giải thích sự chuyển ý: Đây là chữ Hội ý. Quy nghĩa gốc là người con gái đi lấy chồng. Sau mang ý nghĩa là trở về (quy lai, quy hồi).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰帚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "归", "Unihan_Traditional (Chữ Phồn thể)": "歸", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雛', '{"9000": "", "Chữ Trung Quốc": "雛", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sô (874) Truy (202)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Sô (số 874 - cỏ rơm/chỉ âm) ở bên trái chữ Truy (số 202 - chim non/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Sô chỉ âm, bộ Truy chỉ ý. Sồ là con chim non, con gà con (anh thư chim sồ).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰芻隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "芻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "雏", "Unihan_Traditional (Chữ Phồn thể)": "雛", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴨', '{"9000": "", "Chữ Trung Quốc": "鴨", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 鳥 | Số nét | 16 | nét | 甲 | giáp | biểu âm | vỏ giáp, thứ nhất | 鳥 | điểu | biểu nghĩa | chim | 鴨 = 甲 (Giáp, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim). Chữ hình thanh. Con chim (鳥) có âm từ 甲 → con vịt, loài chim nước quen thuộc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Theo Wiktionary, 鴨 là chữ hình thanh gồm 甲 (phonetic) và 鳥 (semantic: chim). Glyph tiểu triện và Lục thư thông đã xác nhận. Dạng giản thể là 鸭. Vịt là loài chim nước được thuần hoá từ rất sớm trong lịch sử Trung Hoa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Giáp (1165) Điểu (1019)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Giáp (số 1165 - cái áo giáp/chỉ âm) ở bên trái bộ Điểu (số 1019 - con chim/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Giáp chỉ âm, bộ Điểu chỉ ý. Áp là từ dùng để gọi con vịt, con ngan.", "Nghĩa Tiếng Việt_Xie": "con vịt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰甲鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鸭", "Unihan_Traditional (Chữ Phồn thể)": "鴨", "Pinyin_Xie": "yā", "Âm Hán Việt_Xie": "áp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ con vịt, thường đứng độc lập hoặc làm định ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婁', '{"9000": "", "Chữ Trung Quốc": "婁", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vô (820) Trung (127) Nữ (038)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Vô (số 820 - không có/viết dạng 毋), chữ Trung (số 127 - ở giữa) và chữ Nữ (số 038 - nữ giới). Sinh con gái thì khi xưa quan niệm là không có người nối dõi. Giải thích sự chuyển ý: Đây là chữ Hội ý. Lâu là không có gì hết, trống không.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "娄", "Unihan_Traditional (Chữ Phồn thể)": "婁", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('數', '{"9000": "", "Chữ Trung Quốc": "數", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lâu (1167) Phộc (044)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lâu (số 1167 - trống không/chỉ âm) ở bên trái bộ Phộc (số 044 - đánh khẽ/viết dạng 攵). Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Số là số lượng (con số, dân số). Nó cũng được dùng làm động từ mang nghĩa là tính toán, đếm (số học, đếm số).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰婁⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "婁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺙", "Unihan_Simplified (Chữ Giản thể)": "数", "Unihan_Traditional (Chữ Phồn thể)": "數", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巠', '{"9000": "", "Chữ Trung Quốc": "巠", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (001) Xuyên (092) Công (048)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Nét Nhất (一), chữ Xuyên (số 092 - sông/巛) và chữ Công (số 048 - công việc). Có sách ghi chữ Công vốn là chữ Sinh (生) chỉ âm. Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Kinh là những mạch nước giống như con sông chảy ngầm dưới mặt đất.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>工", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "巠", "Unihan_Traditional (Chữ Phồn thể)": "巠", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('頸', '{"9000": "", "Chữ Trung Quốc": "頸", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 頁 | Số nét | 16 | nét | 巠 | kinh | biểu âm | thẳng, kinh mạch | 頁 | hiệt | biểu nghĩa | đầu, trang | 頸 = 巠 (Kinh, biểu âm) + 頁 (Hiệt, biểu nghĩa: đầu); chữ hình thanh. Bộ 頁 chỉ vùng đầu cổ; 巠 cho âm đọc jǐng. Nghĩa: cổ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Chữ hình thanh: 巠 (kinh) biểu âm; 頁 (hiệt, đầu) biểu nghĩa. Tiểu triện ghi nhận. Nghĩa: cổ (neck). Từ phổ biến: 颈椎 (đốt sống cổ), 长颈鹿 (hươu cao cổ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kinh (1171) Hiệt (119)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Kinh (số 1171 - mạch nước ngầm/chỉ âm) ở bên trái bộ Hiệt (số 119 - cái đầu/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Kinh chỉ âm, bộ Hiệt chỉ ý. Cảnh là phần cổ của con người hoặc con vật (như cổ họng, gáy).", "Nghĩa Tiếng Việt_Xie": "cổ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巠頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "颈", "Unihan_Traditional (Chữ Phồn thể)": "頸", "Pinyin_Xie": "jǐng", "Âm Hán Việt_Xie": "cảnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ bộ phận như cổ tử cung, cổ chai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('丵', '{"9000": "", "Chữ Trung Quốc": "丵", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình ảnh những ngọn cỏ mọc tua tủa tạo thành bụi rậm đan xen nhau. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Trác là bụi cỏ mọc rậm rạp. (Chữ này là thành phần trên của chữ Nghiệp 業).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>业𢆉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𢆉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "业", "Unihan_Simplified (Chữ Giản thể)": "丵", "Unihan_Traditional (Chữ Phồn thể)": "丵", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('燭', '{"9000": "", "Chữ Trung Quốc": "燭", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hỏa (086) Thục (1178)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hỏa (số 086 - ngọn lửa/chỉ ý) ở bên trái chữ Thục (số 1178 - con sâu/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thục chỉ âm, bộ Hỏa chỉ ý. Chúc là cây đuốc, cây nến (hoa chúc, sáp chúc).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火蜀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蜀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烛", "Unihan_Traditional (Chữ Phồn thể)": "燭", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隊', '{"9000": "", "Chữ Trung Quốc": "隊", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 阜 | Số nét | 11 | nét | 阜 | phụ | biểu nghĩa | gò đất, địa hình cao | 㒸 | biểu âm | âm gần duì | 隊 = 阜 (Phụ, biểu nghĩa: gò đất — viết là 阝 bên trái) + 㒸 (biểu âm); chữ hình thanh. Bộ 阜 gợi địa thế, hàng ngũ di chuyển trên địa hình. Nghĩa gốc liên quan đến người xếp hàng trên địa thế dốc, sau mở rộng thành đội ngũ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | Chữ 隊 là chữ hình thanh: 阜 (phụ, gò đất — viết là 阝 bên trái) là phần biểu nghĩa, 㒸 là phần biểu âm. Wiktionary xác nhận: {{Han compound|阜|㒸|c1=s|c2=p|ls=psc}}. Giáp cốt văn và kim văn cho thấy hình người xếp hàng trên địa thế dốc. Nghĩa gốc: di chuyển thành hàng ngũ; sau phát triển thành đội quân, nhóm người có tổ chức. Chữ truyền thống, giản thể là 队. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phụ (164) Toại (1187)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Phụ (số 164 - núi đất/ 阝) ở bên trái chữ Toại (số 1187 - toại nguyện/viết giảm nét/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Toại chỉ âm, bộ Phụ chỉ ý. Đội là một nhóm người tập hợp có tổ chức (quân đội, đồng đội).", "Nghĩa Tiếng Việt_Xie": "đội quân; dàn thành hàng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝㒸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㒸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "队", "Unihan_Traditional (Chữ Phồn thể)": "隊", "Pinyin_Xie": "duì", "Âm Hán Việt_Xie": "đội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ hàng ngũ hoặc làm lượng từ cho các nhóm, đội. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('發', '{"9000": "", "Chữ Trung Quốc": "發", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bát (105) Cung (057) Thù (079)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bát (số 105 - gạt ra/ 癶/chỉ âm) ở trên chữ Cung (số 057 - cây cung) và chữ Thù (số 079 - binh khí). Giải thích sự chuyển ý: Đây là chữ Hội ý (hoặc Hình thanh). Bắn cung vũ khí ra. Phát là khai mở, mở đầu, bắn ra, phát ra (phát triển, phát hành, xuất phát).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>癶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "发", "Unihan_Traditional (Chữ Phồn thể)": "發", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('則', '{"9000": "", "Chữ Trung Quốc": "則", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bối (154) Đao (016)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bối (số 154 - tiền bạc) ở bên trái bộ Đao (số 016 - con dao/ 刂). Nhà vua ra quy định, ai có công thì thưởng tiền Bối, ai có tội thì dùng Đao chặt đầu. Giải thích sự chuyển ý: Đây là chữ Hội ý. Tắc là phép tắc, khuôn phép, quy định (quy tắc, nguyên tắc). Cũng dùng làm liên từ: thì, bèn.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貝刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "则", "Unihan_Traditional (Chữ Phồn thể)": "則", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漁', '{"9000": "", "Chữ Trung Quốc": "漁", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Ngư (1102)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước/ 氵) ở bên trái chữ Ngư (số 1102 - con cá/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ngư chỉ âm, bộ Thủy chỉ ý. Ngư là việc bắt cá dưới nước, nghề đánh cá (ngư nghiệp, ngư dân).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵魚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "魚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渔", "Unihan_Traditional (Chữ Phồn thể)": "漁", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('須', '{"9000": "", "Chữ Trung Quốc": "須", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 頁 | Số nét | 12 | nét | 彡 | biểu nghĩa | lông, tóc | 頁 | biểu nghĩa | đầu người | 須 = 彡 (biểu nghĩa: lông/tóc) + 頁 (biểu nghĩa: đầu người); chữ tượng hình/hội ý cổ. Wiktionary ghi ls=p (pictographic compound): hình một cái đầu người có lông râu hai bên — nguyên nghĩa là bộ râu. Sau mượn âm để chỉ ''cần phải''.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | 須 vốn là hình vẽ: 彡 (lông/tóc) bên cạnh 頁 (đầu người) — mô tả bộ râu mọc hai bên mặt. Wiktionary xác nhận: ls=p, ''a head with hair on its side — beard; whiskers — original character of 鬚''. Sau đó nghĩa ''râu'' được tách sang 鬚, còn 須 mang nghĩa mượn ''cần phải, tất yếu''. Dạng giáp cốt, kim văn, bạch thư, đại triện, tiểu triện đều ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sam (059) Hiệt (119)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Sam (số 059 - lông dài) ở bên trái chữ Hiệt (số 119 - cái đầu). Giải thích sự chuyển ý: Đây là chữ Hội ý (hoặc Hình thanh). Tu vốn là râu mọc dưới cằm. Sau được mượn dùng với nghĩa là cần phải, nên làm (tu yếu, tất tu). Cũng có nghĩa là chốc lát.", "Nghĩa Tiếng Việt_Xie": "Phải", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彡頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "頁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彡", "Unihan_Simplified (Chữ Giản thể)": "须", "Unihan_Traditional (Chữ Phồn thể)": "須", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "tua", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Trợ động từ | 能愿动词 | Danh từ | 名词 | Dùng làm phó từ hoặc động từ năng nguyện đứng trước động từ để biểu thị sự bắt buộc, cần thiết. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Trợ động từ | 能愿动词 | Đứng trước động từ chính để nêu khả năng, ý muốn hoặc sự cho phép: 会, 能, 可以, 想, 要. Phủ định đặt 不 trước chính nó — 不能去. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬚', '{"9000": "", "Chữ Trung Quốc": "鬚", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 髟 | Số nét | 22 | nét | 髟 | phiêu | biểu nghĩa | tóc, lông dài | 須 | tua | biểu âm | râu, cần (biểu âm và biểu nghĩa) | 鬚 = 髟 (Phiêu, biểu nghĩa: tóc/lông dài) + 須 (Tua, vừa biểu âm vừa biểu nghĩa: râu); chữ hội ý kiêm hình thanh. Hai bộ đều liên quan đến lông/râu.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Chữ hội ý kiêm hình thanh. Theo Wiktionary: 髟 (tóc dài) biểu nghĩa, 須 vừa cho âm vừa mang nghĩa râu. Nguyên bản chỉ viết 須, sau thêm 髟 để phân biệt. 鬚 chỉ riêng râu mặt (râu cằm, râu mép), phân biệt với 鬍 (râu nói chung). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tiêu (190) Tu (1192)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tiêu (số 190 - tóc rủ/Bưu/ 髟/chỉ ý) ở trên chữ Tu (số 1192 - cần phải/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tu chỉ âm, bộ Tiêu chỉ ý. Tu là râu mọc ở cằm, ria mép (râu ria).", "Nghĩa Tiếng Việt_Xie": "râu cằm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>髟須", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "須", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "tu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ râu của người, động vật hoặc các bộ phận giống râu của thực vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('網', '{"9000": "", "Chữ Trung Quốc": "網", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 14 | nét | 糸 | biểu nghĩa | dây thừng, sợi | 罔 | vóng | biểu âm | lưới, không có | 網 = 糸 (biểu nghĩa: dây sợi/thừng) + 罔 (Vóng, biểu âm); chữ hình thanh. Bộ 糸 cho biết chữ liên quan đến sợi/lưới, 罔 cho biết âm đọc wǎng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 網 là chữ hình thanh (psc): 糸 biểu nghĩa ''dây sợi/thừng'', 罔 biểu âm. Nghĩa là lưới, mạng lưới. Chữ giản thể tương đương là 网 (vốn là chữ tượng hình lưới cá cổ). Thấy trong tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Võng (1202)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糹/chỉ ý) ở bên trái chữ Võng (số 1202 - cái lưới/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Võng chỉ âm, bộ Mịch chỉ ý. Võng là cái lưới bện bằng tơ sợi. Hiện nay chữ này đã có thể thay thế hoàn toàn chữ 网 hoặc 罔.", "Nghĩa Tiếng Việt_Xie": "mạng lưới", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹罔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "网", "Unihan_Traditional (Chữ Phồn thể)": "網", "Pinyin_Xie": "wǎng", "Âm Hán Việt_Xie": "võng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ các loại lưới hoặc làm động từ với nghĩa giăng lưới, bắt bằng lưới. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('線', '{"9000": "", "Chữ Trung Quốc": "線", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 15 | nét | 糹 | mịch | biểu nghĩa | sợi tơ | 泉 | tuyền | biểu âm | suối | 線 = 糹 (Mịch, biểu nghĩa: sợi tơ) + 泉 (Tuyền, biểu âm). Chữ hình thanh: 糹 cho biết liên quan đến sợi chỉ/tơ, 泉 cho âm đọc gần với xiàn/tuyến.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 線 là chữ hình thanh: 糹 (sợi tơ) biểu nghĩa, 泉 biểu âm. Nghĩa gốc là sợi chỉ mỏng, sau mở rộng thành đường thẳng, tia sáng, đường dây. Wiktionary xác nhận cấu trúc 糸 + 泉 (ls=psc). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Tuyền (728)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糹/chỉ ý) ở bên trái chữ Tuyền (số 728 - dòng suối/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tuyền chỉ âm, bộ Mịch chỉ ý. Tuyến là sợi dây, sợi chỉ (hồng tuyến). Cũng chỉ đường đi, vạch kẻ (đường tuyến, tiền tuyến).", "Nghĩa Tiếng Việt_Xie": "đường, tia", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹泉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "泉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "xiàn", "Âm Hán Việt_Xie": "tuyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại dây, sợi hoặc đường kẻ trong hình học và đời sống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('親', '{"9000": "", "Chữ Trung Quốc": "親", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 見 | Số nét | 16 | nét | 辛 | tân | biểu âm | vất vả, cay đắng | 見 | kiến | biểu nghĩa | nhìn thấy | 親 = 辛 (Tân, biểu âm) + 見 (Kiến, biểu nghĩa: nhìn thấy); chữ hình thanh (psc). Kim văn dùng cách này; tiểu triện thay 辛 bằng 𣓀 (thanh cành cây). Bên trái vốn là hình một cái đục và cành cây (cành phỉ làm roi), được cách điệu thành 亲.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | 親 (qīn): chữ hình thanh. Kim văn gồm 辛 (biểu âm: cái đục) và 見 (biểu nghĩa: nhìn thấy). Tiểu triện dùng 𣓀 + 見; phần trái vốn là hình cái đục với cành cây ở dưới biểu thị \"cành phỉ dùng làm roi\" — gợi sự trông nom, chăm sóc thân thiết. Sau được cách điệu thành 亲 bên trái. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tân (160) Kiến (169)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Tân (số 160 - vị cay/biến thể thành Lập 立 và Mộc 木/chỉ âm) ở bên trái chữ Kiến (số 169 - nhìn thấy/chỉ ý). Người mà ta luôn gặp mặt và nhìn thấy. Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Thân là cha mẹ, người thân yêu của chúng ta (thân sinh, phụ thân). Từ đó mang nghĩa là gần gũi, thân thiết.", "Nghĩa Tiếng Việt_Xie": "cha mẹ; ruột thịt; thân cận, gần gũi; cô dâu; thơm, hôn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亲見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "見", "Unihan_Simplified (Chữ Giản thể)": "亲", "Unihan_Traditional (Chữ Phồn thể)": "親", "Pinyin_Xie": "qīn", "Âm Hán Việt_Xie": "thân, thấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ chỉ sự gần gũi hoặc danh từ chỉ người ruột thịt trong gia đình. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縫', '{"9000": "", "Chữ Trung Quốc": "縫", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 16 | nét | 糹 | biểu nghĩa | sợi tơ, chỉ may | 逢 | phùng | biểu âm | gặp gỡ | 縫 = 糹 (biểu nghĩa: sợi tơ/chỉ may) + 逢 (Phùng, biểu âm); chữ hình thanh (psc). Bộ 糸/糹 chỉ chỉ sợi, 逢 cho âm. Hai nghĩa: may vá (féng) và kẽ hở/đường nối (fèng).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 縫 (féng/fèng): chữ hình thanh, gồm 糹 (chỉ sợi, biểu nghĩa) và 逢 (Phùng, biểu âm). Nghĩa 1 (féng): may, khâu vá — dùng chỉ xuyên qua. Nghĩa 2 (fèng): đường nối, kẽ hở, vết nứt — chỗ gặp nhau của hai mảnh. Tiểu triện ghi nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Phùng (1206)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糹/chỉ ý) ở bên trái chữ Phùng (số 1206 - gặp gỡ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Phùng chỉ âm, bộ Mịch chỉ ý. Phùng là may vá quần áo, dùng tơ chỉ nối ghép (khâu phùng). Cũng mang nghĩa khe hở (kẽ phùng).", "Nghĩa Tiếng Việt_Xie": "may áo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹逢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "逢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "缝", "Unihan_Traditional (Chữ Phồn thể)": "縫", "Pinyin_Xie": "fèng", "Âm Hán Việt_Xie": "phùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ hành động khâu vá hoặc làm danh từ chỉ đường khe hở. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗇', '{"9000": "", "Chữ Trung Quốc": "嗇", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lai (281) Hồi (031)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Phía trên là chữ Lai (số 281 - lúa mì/phân tích ra 2 chữ Nhân 人 và Thổ 土). Phía dưới là chữ Hồi (số 031 - trở về). Hai người đào đất mang về đắp tường để tiết kiệm. Giải thích sự chuyển ý: Đây là chữ Hội ý. Sắc là thu góp đồ vật mang về cất giấu, tiết kiệm. Cũng mang nghĩa xấu là hà tiện, keo kiệt (keo sắc).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>坐回", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "回", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "坐", "Unihan_Simplified (Chữ Giản thể)": "啬", "Unihan_Traditional (Chữ Phồn thể)": "嗇", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('牆', '{"9000": "", "Chữ Trung Quốc": "牆", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tường (090) Sắc (1213)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tường (số 090 - cái giường / tấm ván / 爿 /kiêm chỉ âm) ở bên trái chữ Sắc (số 1213 - tiết kiệm). Tường vách có thể đắp bằng đất hoặc ốp tấm ván cho chắc. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tường chỉ âm, chữ Sắc chỉ ý. Tường là bức vách, bức tường xây bằng gạch đá hoặc ván (thành tường).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰爿嗇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "嗇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "爿", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齊', '{"9000": "", "Chữ Trung Quốc": "齊", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 齊 | Số nét | 14 | nét | 齊 | tày | tượng hình | nhiều vật sắp xếp đều nhau | 齊 là chữ tượng hình: hình ảnh nhiều bông lúa hay gai nhọn mọc đều nhau. Giáp cốt văn mô tả nhiều vật sắp thành hàng ngang đều đặn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tượng hình tự: giáp cốt văn miêu tả nhiều trái cây hoặc gai mọc đều trên cành cây. Nghĩa gốc là ''đều nhau, ngay ngắn''. Liên quan đến 薺 (cỏ tật lê). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Người xưa quan sát thấy trong các loại cây sinh trưởng, không gì bằng nhau và đều tăm tắp như cây lúa, nên tạo hình vẽ bông lúa. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Tề nghĩa là đều nhau, bằng nhau, ngang hàng, gọn gàng (chỉnh tề, tề gia).", "Nghĩa Tiếng Việt_Xie": "đều, không so le; nước Tề, đất Tề", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "齐", "Unihan_Traditional (Chữ Phồn thể)": "齊", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "tề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự bằng phẳng hoặc làm phó từ chỉ hành động diễn ra cùng lúc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齋', '{"9000": "", "Chữ Trung Quốc": "齋", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 齊 | Số nét | 17 | nét | 齊 | tề | biểu âm | đều, chỉnh tề — cho âm | 示 | thị | biểu nghĩa | thần linh, thờ phụng — chỉ nghĩa lễ giới | 齋 = 齊 (Tề, biểu âm) + 示 (Thị, biểu nghĩa: thần/thờ phụng). Chữ hình thanh: 齊 cho âm gần, 示 cho nghĩa ''lễ giới trước thần''.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Wiktionary xác nhận 齋 là chữ hình thanh (psc): 齊 (tề) cho âm, 示 (thị — thần linh, thờ phụng) cho nghĩa. Nghĩa gốc: kiêng cữ, ăn chay trước khi làm lễ tế thần. Mở rộng: phòng học/thư phòng (nơi thanh tịnh), ăn chay Phật giáo. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tề (1215) Thị (113)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thị (số 113 - khấn vái/thần đất/viết dạng 示 giống chữ Tiểu) chui vào trong khoảng trống ở dưới chữ Tề (số 1215 - chỉnh tề). Nhà cửa đồ vật có nhỏ bé cũng phải chỉnh tề. Giải thích sự chuyển ý: Đây là chữ Hội ý. Trai là nhà ở tĩnh mịch, sạch sẽ (thư trai). Cũng có nghĩa là giữ trong sạch, ngăn tham dục, ăn chay (trai giới).", "Nghĩa Tiếng Việt_Xie": "nhanh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴齊小", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "小", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齊", "Unihan_Simplified (Chữ Giản thể)": "斋", "Unihan_Traditional (Chữ Phồn thể)": "齋", "Pinyin_Xie": "zhāi", "Âm Hán Việt_Xie": "trai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ phòng học hoặc động từ chỉ việc ăn chay. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('塵', '{"9000": "", "Chữ Trung Quốc": "塵", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lộc (317) Thổ (032)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Lộc (số 317 - con hươu nai) ở trên bộ Thổ (số 032 - đất). Đàn nai chạy tán loạn dẫm đạp làm cát đất bụi mù bay lên. Giải thích sự chuyển ý: Đây là chữ Hội ý. Trần là bụi bặm, bụi trần (phong trần, hồng trần).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>鹿土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "土", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "尘", "Unihan_Traditional (Chữ Phồn thể)": "塵", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隨', '{"9000": "", "Chữ Trung Quốc": "隨", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 阜 | Số nét | 14 | nét | 辵 | xước | biểu nghĩa | đi bộ, chuyển động | 𡐦 | biểu âm | 隨 là chữ hình thanh: bộ 辵 (xước, biểu nghĩa: đi theo, chuyển động) kết hợp với 𡐦 (biểu âm). Ý nghĩa gốc là đi theo sau. Dạng phồn thể, dạng giản thể là 随.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 隨 (tuỳ/suí) là chữ hình thanh, gồm 辵 (đi) biểu nghĩa và 𡐦 biểu âm. Nghĩa gốc: đi theo. Wiktionary ghi nhiều nghĩa: theo sau, nghe theo, tùy thuận, đi cùng, lập tức (phương ngữ Mân Nam). Cũng dùng chỉ quẻ 17 trong Kinh Dịch (\"tùy\"). Dạng phồn thể; giản thể là 随. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phụ (164) Xước (162) Tả (222) Nhục (130)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bên trái là bộ Phụ (số 164 - 阝), bên phải là chữ Tả (số 222 - tay trái) và Nhục (số 130 - thịt), được bao bởi bộ Xước (số 162 - bước đi). Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Tùy là thuận theo, theo nhau, nghe theo (tùy tùng, tùy ý).", "Nghĩa Tiếng Việt_Xie": "tuỳ theo; đời nhà Tuỳ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝遀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "随", "Unihan_Traditional (Chữ Phồn thể)": "隨", "Pinyin_Xie": "suí", "Âm Hán Việt_Xie": "tuỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Giới từ | 介词 | Thường làm động từ chỉ sự đi theo hoặc làm giới từ với nghĩa tùy theo, đi kèm tân ngữ phía sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼕', '{"9000": "", "Chữ Trung Quốc": "鼕", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cổ (429) Đông (288)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Cổ (số 429 - cái trống/chỉ ý) ở trên chữ Đông (số 288 - mùa đông/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đông chỉ âm, bộ Cổ chỉ ý. Đông là âm thanh tùng tùng của tiếng trống phát ra.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>鼓冬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼓", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咅', '{"9000": "", "Chữ Trung Quốc": "咅", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lập (112) Khẩu (030)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lập (số 112 - đứng) ở trên chữ Khẩu (số 030 - cái miệng). Cha mẹ dùng miệng la mắng để con trẻ có thể tự đứng trên đôi chân của mình. Giải thích sự chuyển ý: Đây là chữ Hội ý. Phôi là tiếng la mắng, cãi nhau, khạc nhổ đi. Cũng được dùng làm thán từ bày tỏ thái độ (úi chà).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>立口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "口", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "立", "Unihan_Simplified (Chữ Giản thể)": "咅", "Unihan_Traditional (Chữ Phồn thể)": "咅", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('樓', '{"9000": "", "Chữ Trung Quốc": "樓", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Lâu (1167)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây cối/chỉ ý) ở bên trái chữ Lâu (số 1167 - trống không/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Lâu chỉ âm, bộ Mộc chỉ ý. Lâu là căn nhà làm bằng gỗ, nhà lầu, tầng lầu (cao lâu, lầu son).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木婁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "婁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "楼", "Unihan_Traditional (Chữ Phồn thể)": "樓", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齒', '{"9000": "", "Chữ Trung Quốc": "齒", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 齒 | Số nét | 15 | nét | 齒 | xỉ | tượng hình | hàm răng, miệng đầy răng | 齒 là chữ tượng hình (pictograph) gốc: miệng đầy răng. Wiktionary xác nhận: ban đầu là tượng hình (liushu=p), sau thêm 止 (âm đọc chǐ) trở thành hình thanh. Chữ có lịch sử từ giáp cốt văn và kim văn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Đại triện | Theo Wiktionary, 齒 ban đầu là chữ tượng hình: hình miệng với các răng. Về sau thêm 止 biểu âm (đọc chǐ), thành hình thanh. Nghĩa gốc: răng. Mở rộng: tuổi tác (vì người cổ đại đánh giá tuổi qua tình trạng răng). Chữ có mặt từ giáp cốt văn với hình ảnh rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chỉ (158) Khảm (023) Nhân (019)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Chỉ (số 158 - bàn chân/chỉ âm) ở trên bộ Khảm (số 023 - há miệng hở ra 凵) và chứa 4 chữ Nhân 人. Hình ảnh cái miệng đang hở ra lộ hai hàm răng lởm chởm. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Xỉ là cái răng (răng xỉ, xỉ nhục).", "Nghĩa Tiếng Việt_Xie": "răng; tuổi tác", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>止𠚕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠚕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "止", "Unihan_Simplified (Chữ Giản thể)": "齿", "Unihan_Traditional (Chữ Phồn thể)": "齒", "Pinyin_Xie": "chǐ", "Âm Hán Việt_Xie": "xỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ răng hoặc tuổi tác, làm động từ với nghĩa nhắc đến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('從', '{"9000": "", "Chữ Trung Quốc": "從", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xích (060) Tòng (011) Chỉ (158)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xích (số 060 - bước ngắn/ 彳), chữ Tòng (số 011 - 2 người đi theo nhau/ 从) và chữ Chỉ (số 158 - bàn chân). Giải thích sự chuyển ý: Đây là chữ Hội ý. Tòng là đi theo, làm theo, thuận theo (tòng phục, tòng quân). Cũng dùng làm giới từ: từ (từ đó).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('語', '{"9000": "", "Chữ Trung Quốc": "語", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 14 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn từ | 吾 | ngô | biểu âm | tôi/ta — cổ ngữ | 語 = 言 (Ngôn, biểu nghĩa: lời nói) + 吾 (Ngô, biểu âm *ŋaʔ/*ŋa); chữ hình thanh. Bộ 言 cho nghĩa ngôn ngữ/lời nói, bộ 吾 cho âm gần yǔ/yù.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary: {{Han compound|言|吾|ls=psc|c1=s|c2=p|tr=*ŋaʔ; *ŋah|tr2=*ŋa}}. Thuộc họ từ *ŋa- xoay quanh ý \"đối diện/hồi đáp\": 語 là ngôn ngữ, lời đáp. 言 biểu nghĩa (lời nói), 吾 biểu âm. Phồn thể 語 tương ứng giản thể 语. Có dạng tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Ngô (573)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/chỉ ý) ở bên trái chữ Ngô (số 573 - tôi/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ngô chỉ âm, bộ Ngôn chỉ ý. Ngữ là nói chuyện, bàn luận, lời nói (ngôn ngữ, ngoại ngữ).", "Nghĩa Tiếng Việt_Xie": "ngôn ngữ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言吾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "语", "Unihan_Traditional (Chữ Phồn thể)": "語", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "ngữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ ngôn ngữ, lời nói hoặc làm động từ với nghĩa là nói chuyện, đàm thoại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繫', '{"9000": "", "Chữ Trung Quốc": "繫", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 19 | nét | 毄 | biểu âm | 糸 | mịch | biểu nghĩa | sợi chỉ, dây | 繫 = 糸 (Mịch, biểu nghĩa: sợi chỉ/dây) + 毄 (biểu âm); chữ hình thanh. Bộ 糸 chỉ vật liên quan đến sợi dây, buộc kết. 毄 cung cấp âm. Chữ truyền thống, dạng giản thể là 系.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 繫 là chữ hình thanh: 糸 (sợi chỉ, dây) biểu nghĩa, 毄 biểu âm. Nghĩa gốc: buộc, cột, cài cúc áo. Nghĩa mở rộng: hệ thống, liên kết. Hai âm đọc: jì (buộc, cài) và xì (hệ, liên quan). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xa (159) Khảm (023) Thù (079) Mịch (120)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Xa (số 159 - xe), bộ Khảm (số 023 - hố sâu 凵), chữ Thù (số 079 - binh khí) và chữ Mịch (số 120 - sợi tơ 糸). Xe của kẻ thù bị đánh rơi xuống hố, kẻ thù bị trói bằng dây. Giải thích sự chuyển ý: Đây là chữ Hội ý. Hệ là buộc, trói lại, thắt lại.", "Nghĩa Tiếng Việt_Xie": "buộc, bó, nối", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>𣪠糸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣪠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糸", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "hệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ hành động buộc, trói hoặc làm danh từ trong các từ ghép chỉ sự liên hệ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餌', '{"9000": "", "Chữ Trung Quốc": "餌", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 食 | Số nét | 14 | nét | 食 | thực | biểu nghĩa | ăn, thức ăn | 耳 | nhĩ | biểu âm | tai | 餌 = 食 (Thực, biểu nghĩa: ăn) + 耳 (Nhĩ, biểu âm); chữ hình thanh. Bộ 食 chỉ liên quan đến thức ăn; phần 耳 cho âm đọc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 餌 là chữ hình thanh: 食 (biểu nghĩa, ăn) + 耳 (biểu âm). Nghĩa là ''mồi câu, mồi nhử; bánh gạo''. Tiểu triện đã được ghi nhận. Hán-Việt phục nguyên theo Trung cổ âm nyiX là ''nhị''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thực (184) Nhĩ (128)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thực (số 184 - thức ăn/chỉ ý) ở bên trái chữ Nhĩ (số 128 - cái tai/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nhĩ chỉ âm, bộ Thực chỉ ý. Nhị vốn là cái bánh làm từ bột gạo, đồ ăn thừa. Từ đó chuyển ý thành mồi nhử mồi câu (mồi nhị).", "Nghĩa Tiếng Việt_Xie": "mồi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "飠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "饵", "Unihan_Traditional (Chữ Phồn thể)": "餌", "Pinyin_Xie": "ěr", "Âm Hán Việt_Xie": "nhị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ làm tân ngữ cho động từ đánh bắt hoặc làm động từ với nghĩa dụ dỗ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釣', '{"9000": "", "Chữ Trung Quốc": "釣", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 11 | nét | 金 | kim | biểu nghĩa | kim loại | 勺 | thược | biểu âm | 釣 = 金 (Kim, biểu nghĩa: kim loại) + 勺 (Thược, biểu âm: cho âm diào/điếu). Chữ hình thanh.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary, 釣 là chữ hình thanh: 金 (kim loại) biểu nghĩa, 勺 biểu âm. Nghĩa gốc: lưỡi câu (kim loại hình cong như 勺); mở rộng sang câu cá, dụ dỗ. Bạch thư, đại triện và tiểu triện ghi nhận dạng chữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (069) Thược (849)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 069 - kim loại) ở bên trái chữ Thược (số 849 - cái thìa/chỉ âm). Cái lưỡi câu làm bằng kim loại cong như cái thìa. Giải thích sự chuyển ý: Đây là chữ Hội ý. Điếu là dùng mồi để câu cá (câu điếu).", "Nghĩa Tiếng Việt_Xie": "câu cá", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金勺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "钓", "Unihan_Traditional (Chữ Phồn thể)": "釣", "Pinyin_Xie": "diào", "Âm Hán Việt_Xie": "điếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước tân ngữ chỉ hoạt động câu cá hoặc dụ dỗ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絲', '{"9000": "", "Chữ Trung Quốc": "絲", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 12 | nét | 糸 | mịch | biểu nghĩa | cuộn tơ | 糸 | mịch | biểu nghĩa | cuộn tơ | 絲 = 糸 + 糸; chữ hội ý. Hai cuộn tơ (糸) kết hợp tượng trưng cho lụa — vải được se từ nhiều sợi tơ nhỏ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Chữ hội ý: hai bộ 糸 ghép tượng trưng hai cuộn tơ xoắn thành sợi lụa. Giáp cốt văn và kim văn đã có dạng này. Dạng phồn thể, giản thể là 丝. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm hai bộ Mịch (số 120 - sợi tơ/ 糸) đặt song song. Ý nói rằng nhiều sợi tơ kết hợp vặn xoắn tạo thành. Giải thích sự chuyển ý: Đây là chữ Hội ý. Ti là sợi tơ tằm, tơ lụa (tơ ti).", "Nghĩa Tiếng Việt_Xie": "lụa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹糸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "糸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "丝", "Unihan_Traditional (Chữ Phồn thể)": "絲", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "tơ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ sợi tơ hoặc lượng từ chỉ đơn vị đo lường cực nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舉', '{"9000": "", "Chữ Trung Quốc": "舉", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 臼 | Số nét | 16 | nét | 與 | dữ | biểu âm | cho âm (dạng ban đầu là 擧) | 手 | thủ | biểu nghĩa | tay | 舉 = 與 (Dữ, biểu âm) + 手 (Thủ, biểu nghĩa: tay); chữ hình thanh. Theo Wiktionary, dạng ban đầu là 擧. Thành phần 手 sau đó biến thành 𰀁. Nghĩa gốc: hai tay nâng vật lên.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | 舉 theo Wiktionary là chữ hình thanh: 與 biểu âm, 手 biểu nghĩa. Dạng ban đầu 擧 (với bộ 手 rõ ràng). Bộ 手 bên dưới gợi hình ảnh dùng tay nâng lên. Liên quan đến 奉 (phụng — dâng lên). Nghĩa gốc là giơ tay, nâng lên; mở rộng sang: đề cử, cử hành, liệt kê. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Dữ (1081) Thủ (064)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Dữ (số 1081 - cho, cùng với/viết giảm nét/chỉ âm) ở trên bộ Thủ (số 064 - cái tay/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Dữ chỉ âm, bộ Thủ chỉ ý. Cử là dùng tay nâng lên, giơ lên (nhất cử nhất động). Nó cũng có nghĩa là đề xuất, chọn ra (bầu cử, cử nhân).", "Nghĩa Tiếng Việt_Xie": "ngẩng (đầu), nâng lên, nhấc lên; cử động", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>與", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "jǔ", "Âm Hán Việt_Xie": "cử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động nâng nhấc vật gì đó hoặc làm danh từ chỉ hành vi, cử chỉ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('頂', '{"9000": "", "Chữ Trung Quốc": "頂", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 頁 | Số nét | 11 | nét | 丁 | đinh | biểu âm | 頁 | hiệt | biểu nghĩa | đầu người | 頂 = 丁 (Đinh, biểu âm) + 頁 (Hiệt, biểu nghĩa: đầu người); chữ hình thanh. Bộ 頁 xác nhận nghĩa liên quan đến đầu người, đỉnh đầu; 丁 cho âm đọc gần dǐng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | 頂 (dǐng) là chữ hình thanh: bộ 頁 (đầu người) cho nghĩa — đỉnh đầu, chỗ cao nhất; 丁 (đinh) cho âm. Wiktionary xác nhận cấu trúc Han compound ls=psc với c1=p (phonetic: 丁), c2=s (semantic: head). Có đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Đinh (007) Hiệt (119)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Đinh (số 007 - can Đinh/chỉ âm) ở bên trái bộ Hiệt (số 119 - cái đầu/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đinh chỉ âm, bộ Hiệt chỉ ý. Đỉnh là đỉnh đầu người. Mở rộng ra là chỗ cao nhất, ngọn, chóp của sự vật (đỉnh núi, đỉnh phong).", "Nghĩa Tiếng Việt_Xie": "Đứng đầu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰丁頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "顶", "Unihan_Traditional (Chữ Phồn thể)": "頂", "Pinyin_Xie": "dǐng", "Âm Hán Việt_Xie": "đính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Lượng từ | 量词 | Thường làm danh từ chỉ phần cao nhất, động từ chỉ hành động chống đỡ, hoặc lượng từ cho mũ nón. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淺', '{"9000": "", "Chữ Trung Quốc": "淺", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Tiên (1251)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước/ 氵/chỉ ý) ở bên trái chữ Tiên/Tàn (số 1251 - tàn phá/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tàn chỉ âm, bộ Thủy chỉ ý. Thiển là cạn, nước cạn không sâu (nông cạn). Cũng có nghĩa là ngắn hẹp (tài hèn học thiển).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵戔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浅", "Unihan_Traditional (Chữ Phồn thể)": "淺", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('壽', '{"9000": "", "Chữ Trung Quốc": "壽", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sĩ (033) Nhất (001) Công (048) Khẩu (030) Thốn (041)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Sĩ (士), Nhất (一), Công (工), Nhất (一), Khẩu (口) và Thốn (寸). Chỉ có kẻ sĩ trí tuệ hiểu quy luật trời đất, làm việc cống hiến cho xã hội, tu tốt cái miệng (khẩu) có chừng mực (thốn). Giải thích sự chuyển ý: Đây là chữ Hội ý. Họa từ miệng sinh ra, bệnh từ miệng đưa vào. Bí quyết trường thọ là cái miệng có chừng mực. Thọ là sống lâu (trường thọ).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>吋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "寿", "Unihan_Traditional (Chữ Phồn thể)": "壽", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擣', '{"9000": "", "Chữ Trung Quốc": "擣", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Thọ (1256)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Thọ (số 1256 - sống lâu/chỉ âm). Muốn sống lâu thì tay phải làm việc. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Đảo là dùng chày giã thóc, đâm, đập, nện (đảo y). (Thường viết chữ giản thể là 捣).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌壽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "擣", "Unihan_Traditional (Chữ Phồn thể)": "擣", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('廣', '{"9000": "", "Chữ Trung Quốc": "廣", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nghiễm (053) Hoàng (844)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nghiễm (số 053 - mái hiên/ 广 /chỉ ý) che lấy chữ Hoàng (số 844 - màu vàng/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hoàng chỉ âm, bộ Nghiễm chỉ ý. Quảng là tòa nhà rộng lớn. Cũng có nghĩa là rộng rãi, mênh mông, xa (quảng đại, quảng cáo).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广黄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('曠', '{"9000": "", "Chữ Trung Quốc": "曠", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhật (072) Quảng (1258)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhật (số 072 - mặt trời/chỉ ý) ở bên trái chữ Quảng (số 1258 - rộng lớn/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quảng chỉ âm, bộ Nhật chỉ ý. Khoáng là sáng sủa rõ ràng (do mặt trời chiếu tỏ). Cũng mang ý nghĩa là sự rộng lớn, trống trải, xa vắng.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日廣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "旷", "Unihan_Traditional (Chữ Phồn thể)": "曠", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('結', '{"9000": "", "Chữ Trung Quốc": "結", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 12 | nét | 糸 | mịch | biểu nghĩa | sợi, dây | 吉 | cát | biểu âm | 結 = 糸 (Mịch, biểu nghĩa: sợi dây/lụa) + 吉 (Cát, biểu âm); chữ hình thanh — bộ Mịch chỉ hành động dùng dây/sợi để buộc, 吉 cho âm đọc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Chữ hình thanh: bộ 糸 (mịch, sợi/lụa) chỉ hành động thắt, buộc bằng dây, 吉 (cát) cho âm. Tiểu triện và Lục thư thông còn lưu. 結 mang nghĩa thắt nút, kết lại, liên kết — từ nghĩa gốc thắt sợi dây mở rộng sang kết hôn (結婚), kết quả (結果), kết thúc (結束). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Cát (692)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糹/chỉ ý) ở bên trái chữ Cát (số 692 - tốt lành/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cát chỉ âm, bộ Mịch chỉ ý. Kết là dùng dây buộc trói lại với nhau, gắn bó với nhau (kết hợp, kết tóc, kết thúc).", "Nghĩa Tiếng Việt_Xie": "thắt nút; kết, bó; liên kết; kết hợp; ra quả, kết quả", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "结", "Unihan_Traditional (Chữ Phồn thể)": "結", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "kế, kết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động liên kết, đơm hoa kết trái hoặc làm danh từ chỉ nút thắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('築', '{"9000": "", "Chữ Trung Quốc": "築", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 竹 | Số nét | 16 | nét | 筑 | trúc | biểu âm | nhạc cụ cổ (biểu âm) | 木 | mộc | biểu nghĩa | gỗ | 築 là chữ hình thanh (psc): 筑 (Trúc, biểu âm) + 木 (Mộc, biểu nghĩa: gỗ). Chữ chỉ hành động xây dựng bằng gỗ và đất. Đây là dạng phồn thể; giản thể hiện đại là 筑.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 築 ghép 筑 (biểu âm) + 木 (gỗ, biểu nghĩa). Kim văn, tiểu triện và lục thư thông đều ghi nhận. Nghĩa gốc là đóng/dựng bằng gỗ, mở rộng sang xây dựng nói chung. Truyền thống: 築 là phồn thể, 筑 là tên nhạc cụ và giản thể của 築. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (108) Công (048) Phàm (206) Mộc (075)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm bộ Trúc (số 108 - tre trúc/ 竹), bộ Mộc (số 075 - cây gỗ/ 木), chữ Công (số 048 - thợ/ 工) và chữ Phàm (số 206 - bao quát/ 凡). Giải thích sự chuyển ý: Đây là chữ Hội ý. Trúc là tất cả những việc làm liên quan đến dùng tre, gỗ để xây cất (kiến trúc, xây dựng).", "Nghĩa Tiếng Việt_Xie": "xây dựng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>⺮𣑦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣑦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "zhú", "Âm Hán Việt_Xie": "trốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ đứng trước danh từ chỉ công trình để biểu thị việc xây dựng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('劍', '{"9000": "", "Chữ Trung Quốc": "劍", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thiêm (601) Đao (016)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thiêm (số 601 - tập hợp/chỉ âm) ở bên trái bộ Đao (số 016 - con dao/ 刂 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thiêm chỉ âm, bộ Đao chỉ ý. Kiếm là thanh kiếm, thanh gươm vũ khí (bảo kiếm).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰僉刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "僉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "剑", "Unihan_Traditional (Chữ Phồn thể)": "劍", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駁', '{"9000": "", "Chữ Trung Quốc": "駁", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mã (187) Giao (241)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mã (số 187 - con ngựa/chỉ ý) ở bên trái chữ Giao (số 241 - giao cắt/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Giao chỉ âm, bộ Mã chỉ ý. Bác vốn là loài thú hung dữ giống con ngựa bạch. Từ đó chuyển ý chỉ sự loang lổ, hỗn tạp. Cũng có nghĩa là bắt bẻ lại, chống lại (bác bỏ, phản bác).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬爻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "驳", "Unihan_Traditional (Chữ Phồn thể)": "駁", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賢', '{"9000": "", "Chữ Trung Quốc": "賢", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 15 | nét | 臤 | biểu âm | 貝 | bối | biểu nghĩa | tiền bạc, của cải | 賢 là chữ hình thanh (psc): 臤 (biểu âm) + 貝 (Bối, biểu nghĩa: tiền bạc, quý giá). Bộ 貝 gợi hình ảnh người xứng đáng như tiền quý — có giá trị; 臤 cung cấp âm đọc. Tiểu triện còn lưu.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 賢 (hình thanh): 臤 (biểu âm) + 貝 (tiền bạc, biểu nghĩa). Nghĩa gốc là xứng đáng, quý giá như tiền bạc. Phát triển thành nghĩa đức hạnh, tài giỏi, hiền tài. Tiểu triện còn lưu dạng gốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thần (137) Hựu (029) Bối (154)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Thần (số 137 - bề tôi), chữ Hựu (số 029 - bàn tay) và chữ Bối (số 154 - tiền bạc). Vị quan (Thần) có đức tài giúp dân yên ổn làm ăn (Hựu) có của để dành (Bối). Giải thích sự chuyển ý: Đây là chữ Hội ý. Hiền là người có đức hạnh, tài năng tốt lành (hiền tài, hiền đức, hiền nhân).", "Nghĩa Tiếng Việt_Xie": "đạo đức", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>臤貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "贤", "Unihan_Traditional (Chữ Phồn thể)": "賢", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "hiền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ hoặc làm danh từ chỉ người hiền tài. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('堅', '{"9000": "", "Chữ Trung Quốc": "堅", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thần (137) Hựu (029) Thổ (032)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Thần (số 137 - bề tôi) và chữ Hựu (số 029 - bàn tay) ở trên bộ Thổ (số 032 - đất). Ông quan đốc thúc quân lính tay dùng đất đắp thành lũy. Giải thích sự chuyển ý: Đây là chữ Hội ý. Kiên là chắc chắn, vững chắc, bền bỉ (kiên cố, kiên cường).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>臤土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坚", "Unihan_Traditional (Chữ Phồn thể)": "堅", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄉', '{"9000": "", "Chữ Trung Quốc": "鄉", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 邑 | Số nét | 11 | nét | 𠨍 | biểu nghĩa | hai người ngồi đối diện | 皀 | biểu nghĩa | đồ đựng thức ăn miệng tròn | 鄉 là chữ hội ý: 𠨍 (hai người ngồi đối diện nhau) + 皀 (đồ đựng thức ăn) — hình ảnh bữa tiệc cộng đồng. Nghĩa gốc là yến tiệc (饗), sau do mượn âm hay chuyển nghĩa thành làng, quê hương.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Lệ thư | 鄉 (xiāng) là chữ hội ý: 𠨍 (hai người đối diện) + 皀 (bình đựng thức ăn miệng tròn) — biểu thị cảnh yến tiệc cộng đồng, nghĩa gốc là 饗 (tiệc lớn). Nghĩa \"làng, quê\" do mượn âm hoặc chuyển nghĩa từ đó. Wiktionary xác nhận ls=ic và ghi chú sớm không phân biệt được với 卿. Có đầy đủ giáp cốt, kim văn, đại triện, tiểu triện, lệ thư. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Yêu (052) Lương (851)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lang (郎 - gồm chữ Lương 良 và bộ Ấp 阝) bị chèn chữ Yêu (số 052 - nhỏ bé/ 幺) vào giữa. Về quê hương (bộ Ấp) thấy toàn lối đi quanh co nhỏ bé (Yêu). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Lương chỉ âm, Ấp và Yêu chỉ ý. Hương là làng quê, thôn xóm, chốn cũ (hương quan, tha hương).", "Nghĩa Tiếng Việt_Xie": "thị trấn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰乡郎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "郎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "乡", "Unihan_Simplified (Chữ Giản thể)": "乡", "Unihan_Traditional (Chữ Phồn thể)": "鄉", "Pinyin_Xie": "xiāng", "Âm Hán Việt_Xie": "hương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ nơi chốn, quê quán hoặc đơn vị hành chính cấp xã thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('幷', '{"9000": "", "Chữ Trung Quốc": "幷", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Can (051)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm hai nét phẩy (丷) ở trên hai chữ Can (số 051 - can thiệp/ 干). Hai vật đứng cạnh nhau cùng tham gia một việc. Giải thích sự chuyển ý: Đây là chữ Hội ý. Tịnh là đều cùng như nhau, cùng nhau, gộp lại (tôn tịnh, tịnh hành).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "幷", "Unihan_Traditional (Chữ Phồn thể)": "幷", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臺', '{"9000": "", "Chữ Trung Quốc": "臺", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 至 | Số nét | 14 | nét | 喬 | kiều | hội ý | cao vút, nhô lên cao (rút gọn) | 室 | thất | hội ý | phòng, căn phòng, không gian có mái | 臺 là chữ hội ý (Wiktionary xác nhận: {{Han compound|ls=ic|喬|室|abb1=yes}}). Kết hợp 喬 (kiều, cao vút — rút gọn) và 室 (thất, không gian có mái), tạo ý nghĩa: nơi cao, có sàn đứng. Cấu trúc thay đổi theo vùng và thời kỳ nhưng ngữ nghĩa nhất quán.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | 臺 là chữ hội ý gồm phần rút gọn của 喬 (cao vút) và 室 (phòng, không gian có mái). Ý nghĩa tổng hợp: bệ cao, sân khấu, đài quan sát. Wiktionary ghi: cấu trúc thay đổi theo vùng địa lý và thời kỳ lịch sử, nhưng ý nghĩa trung tâm là \"nơi cao có mái hoặc sàn đứng\". Dạng giản thể là 台. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cát (692) Mịch (014) Chí (414)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Cát (số 692 - tốt lành), bộ Mịch (số 014 - khăn trùm) và chữ Chí (số 414 - đến). Hình cái đài cao xây lên để quan sát bốn hướng. Giải thích sự chuyển ý: Đây là chữ Hội ý. Đài là cái nhà cao, cái nền đất được đắp cao (lâu đài, đài quan sát).", "Nghĩa Tiếng Việt_Xie": "Đài Loan", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>士", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "tái", "Âm Hán Việt_Xie": "đài, thai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ công trình xây dựng cao hoặc làm lượng từ cho máy móc, thiết bị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('檯', '{"9000": "", "Chữ Trung Quốc": "檯", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Đài (1280)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây gỗ/chỉ ý) ở bên trái chữ Đài (số 1280 - nhà cao/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đài chỉ âm, bộ Mộc chỉ ý. Đài là cái bàn gỗ, chỗ để làm việc (khán đài). Chữ giản thể dùng chung với chữ 臺.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木臺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('錠', '{"9000": "", "Chữ Trung Quốc": "錠", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 16 | nét | 金 | kim | biểu nghĩa | kim loại | 定 | định | biểu âm | 錠 = 金 (Kim, biểu nghĩa: kim loại) + 定 (Định, biểu âm). Chữ hình thanh: 金 chỉ vật bằng kim loại đúc thành khối; 定 (định: ổn định, cố định) cho âm dìng (Hán-Việt: đĩnh). Vật đúc thành hình cố định — thoi vàng bạc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 錠 (đĩnh) là chữ hình thanh theo Wiktionary: {{Han compound|金|定|ls=psc|c1=s|c2=p|t1=metal}}. Bộ 金 (kim loại) chỉ vật đúc bằng kim loại; 定 cho âm. Nghĩa gốc là vật đúc từ kim loại theo hình cố định (thoi vàng bạc, dụng cụ dệt). Sau mở rộng sang ''viên thuốc'' (錠劑). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (069) Định (517)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 069 - kim loại/chỉ ý) ở bên trái chữ Định (số 517 - cố định/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Định chỉ âm, bộ Kim chỉ ý. Đĩnh là thỏi vàng, thỏi bạc, nén vàng, đúc nguyên khối (kim đĩnh).", "Nghĩa Tiếng Việt_Xie": "thoi vàng, thoi bạc; con thoi dệt vải", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金定", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "定", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "锭", "Unihan_Traditional (Chữ Phồn thể)": "錠", "Pinyin_Xie": "dìng", "Âm Hán Việt_Xie": "đĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm danh từ chỉ thỏi kim loại quý hoặc làm lượng từ cho các vật có hình thỏi, bánh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撥', '{"9000": "", "Chữ Trung Quốc": "撥", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Phát (1189)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - tay/ 扌/chỉ ý) ở bên trái chữ Phát (số 1189 - xuất ra/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Phát chỉ âm, bộ Thủ chỉ ý. Bát là đưa tay gạt ra, đẩy ra (bát loạn). Cũng có nghĩa là trích ra một phần cho người khác, cấp phát.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌發", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "發", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拨", "Unihan_Traditional (Chữ Phồn thể)": "撥", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緩', '{"9000": "", "Chữ Trung Quốc": "緩", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 15 | nét | 糸 | mịch | biểu nghĩa | tơ, sợi | 爰 | vươn | biểu âm | vươn tới | 緩 = 糸 (Mịch, biểu nghĩa: tơ, sợi) + 爰 (Vươn, biểu âm); chữ hình thanh. Bộ 糸 gợi ý liên quan đến vải, sợi mềm mại — như sợi tơ buông lơi, không căng; 爰 cho âm đọc (huǎn).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Theo Wiktionary, 緩 là chữ hình thanh: 糸 (biểu nghĩa: tơ) + 爰 (biểu âm). Hình ảnh sợi tơ buông lơi, không căng, gợi lên nghĩa gốc là lỏng lẻo, thư thái. Từ đó mở rộng sang: chậm chạp, hoãn lại, bình phục. Tiểu triện và Lục thư thông đã ghi lại hình dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Viên (1291)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糹/chỉ ý) ở bên trái chữ Viên (số 1291 - bèn/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Viên chỉ âm, bộ Mịch chỉ ý. Dây chùng gọi là Hoãn. Từ đó chuyển ý thành chầm chậm, thong thả, không vội, lùi lại (đình hoãn, hòa hoãn).", "Nghĩa Tiếng Việt_Xie": "chậm chạp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "缓", "Unihan_Traditional (Chữ Phồn thể)": "緩", "Pinyin_Xie": "huǎn", "Âm Hán Việt_Xie": "hoãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho hành động hoặc làm động từ chỉ việc trì hoãn thời gian. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閣', '{"9000": "", "Chữ Trung Quốc": "閣", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 門 | Số nét | 14 | nét | 門 | môn | biểu nghĩa | cửa, cổng | 各 | các | biểu âm | 閣 = 門 (Môn, biểu nghĩa: cổng/cửa) + 各 (Các, biểu âm); chữ hình thanh. Bộ Môn gợi cấu trúc có cổng/cửa, phần 各 cho âm đọc gé.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | Chữ hình thanh: 門 (cổng, cửa — biểu nghĩa) + 各 (biểu âm). 閣 ban đầu chỉ loại phòng/gian nhỏ ở bên trong cổng lớn; sau mở rộng thành ''lầu gác'', ''các'' (pavilion), và ''nội các'' (cabinet chính phủ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Môn (180) Các (115)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Môn (số 180 - cửa/ 門 /chỉ ý) bao bên ngoài chữ Các (số 115 - cái nào/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Các chỉ âm, bộ Môn chỉ ý. Các là cái gác, lầu các (nội các, lầu các). Cũng dùng để chỉ gác bếp, kho thóc.", "Nghĩa Tiếng Việt_Xie": "gian hàng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "阁", "Unihan_Traditional (Chữ Phồn thể)": "閣", "Pinyin_Xie": "gé", "Âm Hán Việt_Xie": "các", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các danh từ riêng để chỉ các tòa lầu gác hoặc cơ quan chính phủ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('獨', '{"9000": "", "Chữ Trung Quốc": "獨", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khuyển (058) Thục (1178)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khuyển (số 058 - chó/ 犭) ở bên trái chữ Thục (số 1178 - con sâu). Con chó thường sống đơn lẻ một thân một mình giống như con tằm nằm trong cái kén. Giải thích sự chuyển ý: Đây là chữ Hội ý (hoặc Hình thanh). Độc là sự đơn độc, chỉ có một mình, một thân, cô đơn (cô độc, độc thân, độc lập).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭蜀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蜀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "独", "Unihan_Traditional (Chữ Phồn thể)": "獨", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龍', '{"9000": "", "Chữ Trung Quốc": "龍", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 龍 | Số nét | 16 | nét | 龍 | long | tượng hình | con rồng — hình tượng rồng uốn lượn | 龍 là chữ tượng hình — giáp cốt văn và kim văn vẽ hình con rồng uốn lượn với đầu sừng và thân dài. Là bộ thủ của chính nó. Không có thành phần phân tích psc/ic.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Lệ thư | 龍 là chữ tượng hình nổi tiếng: giáp cốt văn khắc hình con rồng với đầu to có sừng, thân uốn cong, đuôi dài. Kim văn làm rõ thêm các chi tiết. Là biểu tượng quyền lực và may mắn tối thượng trong văn hóa Trung Hoa. Wiktionary xác nhận là pictograph. Tiểu triện dần trừu tượng hóa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình ảnh con rồng thời cổ đại đang bay. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Long là con rồng (một trong tứ linh: Long - Lân - Quy - Phụng).", "Nghĩa Tiếng Việt_Xie": "con rồng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𦚏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "龙", "Unihan_Traditional (Chữ Phồn thể)": "龍", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "long", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ loài rồng truyền thuyết hoặc làm tính từ bổ nghĩa cho đồ dùng của vua. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籠', '{"9000": "", "Chữ Trung Quốc": "籠", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 竹 | Số nét | 22 | nét | 𥫗 | biểu nghĩa | tre, vật liệu tre | 龍 | long | biểu âm | rồng | 籠 = 𥫗 (biểu nghĩa: tre, bộ trúc rút gọn) + 龍 (Long, biểu âm); chữ hình thanh (psc). Vật làm từ tre (𥫗) với âm long (龍) — cái lồng làm từ tre hay vật bao bọc như lồng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 籠 (lóng/lǒng): chữ hình thanh, gồm 𥫗 (bộ trúc — tre, biểu nghĩa) và 龍 (Long, biểu âm). Chỉ vật dụng đan bằng tre: lồng, giỏ; cũng có nghĩa bao trùm, bao phủ. Tiểu triện ghi nhận dạng chữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (108) Long (1298)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 108 - tre trúc/chỉ ý) ở trên chữ Long (số 1298 - con rồng/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Long chỉ âm, bộ Trúc chỉ ý. Lung là cái lồng tre để nhốt chim thú, hoặc dùng đậy cất đồ vật (cái lồng).", "Nghĩa Tiếng Việt_Xie": "cái lồng; lồng nhau", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>⺮龍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笼", "Unihan_Traditional (Chữ Phồn thể)": "籠", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ vật dụng để nhốt hoặc làm động từ chỉ hành động bao trùm, che phủ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嬰', '{"9000": "", "Chữ Trung Quốc": "嬰", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Anh (123)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Anh (số 123 - vòng cổ 賏 /chỉ âm) ở trên bộ Nữ (số 038 - phụ nữ/ 女 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Anh là đứa trẻ sơ sinh (hài anh, anh nhi). Ngoài ra cũng mang nghĩa là vướng mắc (như bị vòng trang sức quấn vào).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>賏女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "婴", "Unihan_Traditional (Chữ Phồn thể)": "嬰", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸚', '{"9000": "", "Chữ Trung Quốc": "鸚", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Điểu (196) Anh (1301)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Anh (số 1301 - em bé/chỉ âm) ở bên trái bộ Điểu (số 196 - con chim/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Anh chỉ âm, bộ Điểu chỉ ý. Anh là tên một loài chim: chim anh vũ (con vẹt).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰嬰鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "嬰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鹦", "Unihan_Traditional (Chữ Phồn thể)": "鸚", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鵡', '{"9000": "", "Chữ Trung Quốc": "鵡", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Điểu (196) Vũ (1303)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Vũ (số 1303 - sức mạnh/chỉ âm) ở bên trái bộ Điểu (số 196 - con chim/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Vũ chỉ âm, bộ Điểu chỉ ý. Vũ là tên một loài chim: chim anh vũ (con vẹt).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰武鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "武", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鹉", "Unihan_Traditional (Chữ Phồn thể)": "鵡", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綢', '{"9000": "", "Chữ Trung Quốc": "綢", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Chu (1305)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糹/chỉ ý) ở bên trái chữ Chu (số 1305 - chu toàn/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Chu chỉ âm, bộ Mịch chỉ ý. Trù là tên một loại vải lụa dệt bằng tơ (tơ trù).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹周", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "绸", "Unihan_Traditional (Chữ Phồn thể)": "綢", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('尋', '{"9000": "", "Chữ Trung Quốc": "尋", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kệ (052) Công (048) Khẩu (030) Thốn (041)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm bộ Kệ (số 052 - đầu nhím/viết giống chữ Hựu 彐), chữ Công (số 048 - thợ/ 工), chữ Khẩu (số 030 - miệng/ 口) và chữ Thốn (số 041 - gang tay/ 寸). Giải thích sự chuyển ý: Đây là chữ Hội ý. Tầm vốn là đơn vị đo chiều dài (khoảng cách từ tay trái sang tay phải khi dang rộng). Sau mở rộng nghĩa thành tìm kiếm, dò xét (tìm tầm, sưu tầm).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>寸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "寻", "Unihan_Traditional (Chữ Phồn thể)": "尋", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('復', '{"9000": "", "Chữ Trung Quốc": "復", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xích (060) Nhân (009) Nhật (072) Truy (034)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xích (số 060 - bước đi/ 彳) và bên phải gồm chữ Nhân ( 亻), chữ Nhật ( 日) và chữ Truy ( 夂). Giải thích sự chuyển ý: Đây là chữ Hội ý. Phục là quay lại, trở lại như cũ, lặp lại (phục hồi, khôi phục).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳复", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "复", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彳", "Unihan_Simplified (Chữ Giản thể)": "复", "Unihan_Traditional (Chữ Phồn thể)": "復", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋪', '{"9000": "", "Chữ Trung Quốc": "鋪", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 15 | nét | 金 | kim | biểu nghĩa | vàng, kim loại | 甫 | phủ | biểu âm | 鋪 = 金 (Kim, biểu nghĩa: kim loại, vật chất) + 甫 (Phủ, biểu âm); chữ hình thanh. Bộ 金 gợi vật liệu trải phủ; 甫 cho âm đọc gần với pù/pū.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 鋪 là chữ hình thanh: 金 (vàng/kim loại) biểu nghĩa, 甫 biểu âm. Nghĩa gốc là trải phẳng, lát phủ (như lát vàng, trải kim loại). Từ đó mở rộng sang nghĩa bày biện, phô trương, và danh từ chỉ cửa hiệu (cửa phố). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (069) Phủ (204)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 069 - kim loại/chỉ ý) ở bên trái chữ Phủ (số 204 - to lớn/chỉ âm). Vàng bạc là đồ trang sức nên phải bày ra cho mọi người nhìn thấy. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Phủ chỉ âm, bộ Kim chỉ ý. Phô là trải ra, bày ra (phô trương). Còn có nghĩa là cửa tiệm (tiệm phô).", "Nghĩa Tiếng Việt_Xie": "phô, bày; lát phẳng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "pù", "Âm Hán Việt_Xie": "phố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ loại hình kinh doanh như tiệm, cửa hiệu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羅', '{"9000": "", "Chữ Trung Quốc": "羅", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 网 | Số nét | 19 | nét | 网 | võng | biểu nghĩa | cái lưới | 維 | duy | biểu nghĩa | chim bị buộc dây | 羅 = 网 (Võng: lưới) + 維 (Duy: chim bị buộc); chữ hội ý. Hình ảnh chiếc lưới bắt chim — nghĩa gốc là bẫy, lưới. Sau mở rộng sang vải lụa mỏng và hành động bày biện, liệt kê. Chữ gốc là 𦌴. Giản thể là 罗.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Lục thư thông | Wiktionary xác nhận chữ hội ý: 网 (lưới) + 維 (chim bị buộc dây) — chiếc lưới bắt chim. Chữ gốc là 𦌴. Nghĩa gốc: lưới (dùng bắt chim); mở rộng sang vải lụa mỏng (vải ra lưới nhẹ), bày biện/liệt kê (giăng bày như lưới). Giản thể là 罗. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Võng (122) Mịch (120) Duy (248)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Võng (số 122 - cái lưới/ 罒) ở trên bộ Mịch (số 120 - sợi tơ/ 糸) và chữ Duy (số 248 - chim đuôi ngắn/ 隹). Dùng sợi tơ bện lưới để bắt chim. Giải thích sự chuyển ý: Đây là chữ Hội ý. La là cái lưới để bẫy chim. Mở rộng ra nghĩa là giăng lưới, bủa vây (võng la, thiên la địa võng).", "Nghĩa Tiếng Việt_Xie": "vải lụa; cái lưới; bày biện", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>罒維", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "維", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罗", "Unihan_Traditional (Chữ Phồn thể)": "羅", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "la", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ lưới bắt chim hoặc làm động từ với nghĩa vây bọc, bày biện. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑼', '{"9000": "", "Chữ Trung Quốc": "鑼", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (069) La (1319)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 069 - kim loại/chỉ ý) ở bên trái chữ La (số 1319 - cái lưới/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ La chỉ âm, bộ Kim chỉ ý. La là nhạc cụ gõ bằng đồng (thanh la, cồng chiêng).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金羅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "锣", "Unihan_Traditional (Chữ Phồn thể)": "鑼", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觀', '{"9000": "", "Chữ Trung Quốc": "觀", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 見 | Số nét | 24 | nét | 雚 | hoan | biểu âm | biểu âm | 見 | kiến | biểu nghĩa | nhìn, thấy | 觀 = 雚 (Hoan, biểu âm) + 見 (Kiến, biểu nghĩa: nhìn/thấy); chữ hình thanh. Bộ 見 xác định nghĩa liên quan đến quan sát; phần 雚 cung cấp âm đọc guān.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 觀 là chữ hình thanh: 雚 là phần biểu âm, 見 (nhìn/thấy) là phần biểu nghĩa. Nghĩa gốc là quan sát kỹ lưỡng; mở rộng sang quan điểm, cảnh vật, đài quan sát. Dạng tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kiến (147) Quán (718)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Quán (số 718 - con chim/chỉ âm) ở bên trái bộ Kiến (số 147 - nhìn thấy/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quán chỉ âm, bộ Kiến chỉ ý. Quan là xem xét, nhìn kỹ, ngắm tỉ mỉ (quan sát, tham quan). Nghĩa khác là tòa đạo quán.", "Nghĩa Tiếng Việt_Xie": "xem, quan sát", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰雚見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "見", "Unihan_Simplified (Chữ Giản thể)": "观", "Unihan_Traditional (Chữ Phồn thể)": "觀", "Pinyin_Xie": "guān", "Âm Hán Việt_Xie": "quán, quan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước tân ngữ hoặc làm danh từ chỉ quan điểm, chùa chiền. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('壯', '{"9000": "", "Chữ Trung Quốc": "壯", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tường (090) Sĩ (033)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tường (số 090 - tấm gỗ/ 爿) ở bên trái chữ Sĩ (số 033 - kẻ sĩ/ 士). Người tráng sĩ vác tấm ván gỗ trông rất mạnh mẽ. Giải thích sự chuyển ý: Đây là chữ Hội ý. Tráng là sự mạnh mẽ, cường tráng, to lớn, mạnh khỏe (tráng sĩ, tráng kiện).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰爿士", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "士", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "爿", "Unihan_Simplified (Chữ Giản thể)": "壮", "Unihan_Traditional (Chữ Phồn thể)": "壯", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狀', '{"9000": "", "Chữ Trung Quốc": "狀", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tường (090) Khuyển (058)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tường (số 090 - cái giường/cái cửa/ 爿) đứng cạnh bộ Khuyển (số 058 - con chó/ 犬). Hình dáng con chó nằm cạnh cái cửa gỗ để trông nhà. Giải thích sự chuyển ý: Đây là chữ Tượng hình kiêm Hội ý. Trạng là hình dạng, dáng vẻ bên ngoài (hình trạng, trạng thái). Cũng có nghĩa là tờ trình (cáo trạng).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰爿犬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "爿", "Unihan_Simplified (Chữ Giản thể)": "状", "Unihan_Traditional (Chữ Phồn thể)": "狀", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('曉', '{"9000": "", "Chữ Trung Quốc": "曉", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhật (072) Nghiêu (941)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhật (số 072 - mặt trời/chỉ ý) ở bên trái chữ Nghiêu (số 941 - cao/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nghiêu chỉ âm, bộ Nhật chỉ ý. Hiểu là lúc trời vừa sáng rõ. Mở rộng ra có nghĩa là biết rõ, hiểu biết tỏ tường (thông hiểu, hiểu rõ).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日堯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晓", "Unihan_Traditional (Chữ Phồn thể)": "曉", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('視', '{"9000": "", "Chữ Trung Quốc": "視", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 見 | Số nét | 11 | nét | 示 | thị | biểu âm | tế lễ, chỉ thị | 見 | kiến | biểu nghĩa | nhìn thấy, gặp gỡ | 視 là chữ hình thanh: 見 (Kiến, biểu nghĩa: nhìn) + 示 (Thị, biểu âm). Theo Wiktionary, dạng Sở không có phần 示, gần giống 見 — sau đó 示 được thêm vào để phân biệt và cung cấp âm.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 視 (Hán-Việt: thị) là chữ hình thanh theo Wiktionary: 示 (Thị, biểu âm) + 見 (Kiến, biểu nghĩa: nhìn). Dạng Sở giống 見 không có 示. Nghĩa là nhìn, xem xét — hành động dùng mắt quan sát. Liên quan đến 見 (gặp/thấy). Thường gặp trong 电视 (truyền hình), 视力 (thị lực), 视野 (tầm nhìn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thị (113) Kiến (147)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thị (số 113 - chỉ bảo/ 示 /chỉ âm) ở bên trái bộ Kiến (số 147 - nhìn thấy/ 見 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Thị (示) chỉ âm, bộ Kiến (見) chỉ ý. Thị là nhìn, ngắm, xem xét (thị lực, thị giác, giám thị).", "Nghĩa Tiếng Việt_Xie": "xem", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "見", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động quan sát, nhìn nhận hoặc làm danh từ trong các từ ghép chỉ thị lực. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('競', '{"9000": "", "Chữ Trung Quốc": "競", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 立 | Số nét | 20 | nét | 誩 | biểu nghĩa | tranh luận, cãi vã | 儿 | nhân | biểu nghĩa | người | 儿 | nhân | biểu nghĩa | người | 競 theo Thuyết Văn: hội ý — 誩 (tranh luận) + 儿儿 (hai người); hình ảnh hai người tranh luận hăng hái. Cũng có thể là hình thanh với 誩 cho âm, 儿儿 cho nghĩa. Lục thư: cả hội ý (ic) lẫn hình thanh (psc) đều được Wiktionary ghi nhận.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Wiktionary trích Thuyết Văn: hội ý (ic) — 誩 (tranh luận) + 儿 + 儿 (hai người), tượng hình hai người tranh luận kịch liệt. Cũng có khả năng là hình thanh với 誩 là biểu âm. So sánh với chữ 友. Nghĩa là tranh đua, ganh đua, cạnh tranh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lập (112) Huynh (059)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm 2 chữ (Lập 立 trên Huynh 兄) đứng ghép lại với nhau. Hình ảnh hai người (huynh đệ) đang đứng đối diện để đua tranh với nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Cạnh là sự tranh đua, đấu tranh giành phần thắng (cạnh tranh, tranh cạnh).", "Nghĩa Tiếng Việt_Xie": "mạnh, khỏe; ganh đua", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴竞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "竞", "Unihan_Traditional (Chữ Phồn thể)": "競", "Pinyin_Xie": "jìng", "Âm Hán Việt_Xie": "cạnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ trong các từ ghép chỉ sự cạnh tranh, thi đấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揮', '{"9000": "", "Chữ Trung Quốc": "揮", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Quân (1125)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Quân (số 1125 - quân đội/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quân chỉ âm, bộ Thủ chỉ ý. Huy là lấy tay chỉ trỏ ra lệnh, chỉ huy quân đội (chỉ huy, phát huy). Cũng có nghĩa là vẫy tay (huy vũ).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌軍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "軍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "挥", "Unihan_Traditional (Chữ Phồn thể)": "揮", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('乑', '{"9000": "", "Chữ Trung Quốc": "乑", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (009)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm 3 chữ Nhân (người) viết ghép lại với nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Chữ này là một biến thể ngụ ý có rất nhiều người.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: msp", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "𧰨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "乑", "Unihan_Traditional (Chữ Phồn thể)": "乑", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眾', '{"9000": "", "Chữ Trung Quốc": "眾", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 目 | Số nét | 11 | nét | 眾 | chúng | tượng hình | nhiều người dưới ánh mặt trời/ánh mắt | 眾 là tượng hình cổ (pictograph): mặt trời (日) chiếu xuống ba người (㐺). Trong giáp cốt văn là ''mặt trời + ba người đứng''. Ở kim văn, đỉnh biến thành mắt nằm ngang (目) — tái diễn giải là ''đám đông dưới ánh mắt ai đó''. Đây là chữ hội ý biến thể theo thời gian.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Theo Wiktionary, 眾 là tượng hình/hội ý: ban đầu là mặt trời (日) và ba con người (㐺), nghĩa ''người tập họp dưới ánh nắng''. Trong kim văn, phần đỉnh biến thành mắt nằm ngang (mắt 目), tái diễn giải là ''đám đông dưới ánh nhìn''. Phần dưới vẫn là ba hình người ghép lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mục (091) Ngâm (1334)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mục (số 091 - con mắt/viết nằm ngang 罒) ở trên chữ Ngâm (số 1334 - nhiều người/ 乑). Mắt nhìn thấy nhiều người đang tụ tập bên dưới. Giải thích sự chuyển ý: Đây là chữ Hội ý. Chúng là đông đảo, nhiều người, đám đông (quần chúng, đại chúng).", "Nghĩa Tiếng Việt_Xie": "công cộng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>罒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "众", "Unihan_Traditional (Chữ Phồn thể)": "眾", "Pinyin_Xie": "zhòng", "Âm Hán Việt_Xie": "chúng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm định ngữ đứng trước danh từ để chỉ số lượng đông đảo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('側', '{"9000": "", "Chữ Trung Quốc": "側", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (009) Tắc (615)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhân (số 009 - người/ 亻/chỉ ý) ở bên trái chữ Tắc (số 615 - phép tắc/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tắc chỉ âm, bộ Nhân chỉ ý. Trắc là đứng bên cạnh, vị trí phụ (không phải chính yếu). Cũng mang nghĩa là nghiêng lệch về một bên (trắc diện).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻則", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "則", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侧", "Unihan_Traditional (Chữ Phồn thể)": "側", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畾', '{"9000": "", "Chữ Trung Quốc": "畾", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Điền (097)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm 3 bộ Điền (số 097 - thửa ruộng/ 田) viết chồng lên nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Lũy là các dải đất ở bên trong ruộng chia cắt các thửa ruộng với nhau.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴田", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "畾", "Unihan_Traditional (Chữ Phồn thể)": "畾", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疊', '{"9000": "", "Chữ Trung Quốc": "疊", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lũy (1341) Nghi (919)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lũy (số 1341 - các thửa ruộng/ 畾) ở trên chữ Nghi (số 919 - thích hợp/ 宜). Những mảnh ruộng được sắp xếp một cách tầng lớp thích hợp. Giải thích sự chuyển ý: Đây là chữ Hội ý. Điệp là sự chồng chất lên nhau, nhiều tầng nhiều lớp (trùng trùng điệp điệp).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>畾冝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "畾", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('䍃', '{"9000": "", "Chữ Trung Quốc": "䍃", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhục (130) Phữu (114)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhục (số 130 - thịt/viết biến thể giống bộ Trảo 爫) ở trên bộ Phữu (số 114 - đồ gốm/ 缶). Giải thích sự chuyển ý: Đây là chữ Hội ý. Diêu là cái nồi đất nung dùng để đựng thịt.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>爪缶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "缶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "爪", "Unihan_Simplified (Chữ Giản thể)": "䍃", "Unihan_Traditional (Chữ Phồn thể)": "䍃", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遙', '{"9000": "", "Chữ Trung Quốc": "遙", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 13 | nét | 遙 | diêu | tượng hình | xa xôi, tận cùng | 遙 thuộc bộ 辵 (xước — đi bộ), chỉ sự di chuyển đến nơi xa. Dữ liệu CHISE không cung cấp cây thành phần chi tiết. Seal script và liushutong có trong dữ liệu.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Triện thư | Lục thư thông | 遙 nghĩa là xa xôi, tận cùng (distant, far away). Thuộc bộ 辵 (đi bộ). Thơ từ 1908 của Trương Chi Động dùng chữ này. Seal script và liushutong có trong dữ liệu. Wiktionary có âm đầy đủ nhưng không có phân tích cấu tạo chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Diêu (1344)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi/chỉ ý) bao bên ngoài chữ Diêu (số 1344 - nồi đất/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Diêu chỉ âm, bộ Xước chỉ ý. Diêu là xa xôi, xa xăm, vời vợi, xa dài (tiêu diêu, diêu viễn).", "Nghĩa Tiếng Việt_Xie": "xa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "遥", "Unihan_Traditional (Chữ Phồn thể)": "遙", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "diêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm tính từ bổ nghĩa cho danh từ chỉ khoảng cách hoặc làm phó từ đứng trước động từ chỉ hành động từ xa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('銳', '{"9000": "", "Chữ Trung Quốc": "銳", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 15 | nét | 釒 | kim | biểu nghĩa | kim loại | 兌 | đoái | biểu âm | 銳 = 釒 (Kim, biểu nghĩa: kim loại) + 兌 (Đoái, biểu âm); chữ hình thanh. Bộ 釒(金) xác nhận nghĩa liên quan đến vật kim loại sắc nhọn; 兌 cho âm đọc gần ruì.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | 銳 (ruì) là chữ hình thanh: bộ 釒/金 (kim loại) cho nghĩa — mũi nhọn bằng kim loại, sắc bén; 兌 (đoái) cho âm. Wiktionary xác nhận cấu trúc Han compound ls=psc với c1=s (semantic: gold/metal), c2=p (phonetic). Có tiểu triện và Lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (069) Đoài (458)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 069 - kim loại/chỉ ý) ở bên trái chữ Đoài (số 458 - quẻ Đoài/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đoài chỉ âm, bộ Kim chỉ ý. Nhuệ là vũ khí làm bằng kim loại được mài rất sắc bén, nhọn. Mở rộng ra chỉ quân lính giỏi, dũng mãnh (tinh nhuệ, duệ khí).", "Nghĩa Tiếng Việt_Xie": "sắc, nhọn; mũi nhọn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金兌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "锐", "Unihan_Traditional (Chữ Phồn thể)": "銳", "Pinyin_Xie": "ruì", "Âm Hán Việt_Xie": "nhuệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ đứng trước danh từ để tu sức hoặc làm vị ngữ trong câu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('㓞', '{"9000": "", "Chữ Trung Quốc": "㓞", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phong (005) Đao (016)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Phong (số 005 - sum suê/ 丰) ở bên trái bộ Đao (số 016 - con dao/ 刀). Giải thích sự chuyển ý: Đây là chữ Hội ý. Khất là dùng con dao để khắc, chạm, vạch lên một vật gì đó.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰丰刀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刀", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晝', '{"9000": "", "Chữ Trung Quốc": "晝", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Duật (595) Đán (135)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Duật (số 595 - cây bút/ 聿) ở trên chữ Đán (số 135 - rạng đông/ 旦). Giải thích sự chuyển ý: Đây là chữ Hội ý (hoặc Tượng hình). Trú là khoảng thời gian ban ngày từ khi mặt trời mọc đến khi mặt trời lặn (bạch trú, trú dạ).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>聿旦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "聿", "Unihan_Simplified (Chữ Giản thể)": "昼", "Unihan_Traditional (Chữ Phồn thể)": "晝", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('旡', '{"9000": "", "Chữ Trung Quốc": "旡", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vô (1350)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Có nét phẩy (丿) ở bên trái chữ Vô (số 1350 - không có/ 无). Giải thích sự chuyển ý: Đây là chữ Hội ý (hoặc Tượng hình). Ký vốn vẽ hình một người đang hả miệng há hơi ra, ngụ ý là sự ăn uống không tiêu, bị nấc nghẹn, ăn không được nữa.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𡕒乚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𡕒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "乚", "Unihan_Simplified (Chữ Giản thể)": "旡", "Unihan_Traditional (Chữ Phồn thể)": "旡", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('養', '{"9000": "", "Chữ Trung Quốc": "養", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 食 | Số nét | 14 | nét | 羊 | dương | biểu âm | con cừu | 食 | thực | biểu nghĩa | cho ăn, nuôi dưỡng | 養 = 羊 (Dương, biểu âm: cừu) + 食 (Thực, biểu nghĩa: cho ăn); chữ hội ý kiêm hình thanh. Wiktionary ghi ls=ic nhưng c1=p, c2=s: 羊 vừa đóng vai âm vừa gợi ý hình ảnh nuôi vật, 食 là phần nghĩa nuôi dưỡng/cho ăn. Nuôi con cừu — ý nghĩa nuôi dưỡng, chăm sóc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 養 có hai cách đọc cấu trúc: theo hội ý, hình ảnh nuôi con cừu (羊) bằng cách cho ăn (食) gợi ý nuôi dưỡng; theo hình thanh, 羊 cho âm dưỡng. Wiktionary xếp ls=ic nhưng ghi c1=p (phonetic). Nghĩa gốc: nuôi dưỡng, chăm sóc. Dạng tiểu triện ghi nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Dương (195) Thực (184)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Dương (số 195 - con dê/chỉ âm) ở trên bộ Thực (số 184 - thức ăn/chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Dương chỉ âm, bộ Thực chỉ ý. Dưỡng là lấy thức ăn cung cấp cho người khác, nuôi nấng, chăm sóc (nuôi dưỡng, phụng dưỡng, bảo dưỡng).", "Nghĩa Tiếng Việt_Xie": "nuôi dưỡng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>良", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "养", "Unihan_Traditional (Chữ Phồn thể)": "養", "Pinyin_Xie": "yǎng", "Âm Hán Việt_Xie": "dưỡng, dạng, dượng, dường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ đứng trước danh từ chỉ đối tượng được nuôi dưỡng hoặc chăm sóc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餅', '{"9000": "", "Chữ Trung Quốc": "餅", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 食 | Số nét | 14 | nét | 飠 | thực | biểu nghĩa | thức ăn | 并 | tinh | biểu âm | thành phần biểu âm cho âm bǐng | 餅 = 飠 (Thực, biểu nghĩa: thức ăn) + 并 (Tinh, biểu âm); chữ hình thanh. Bộ 飠 cho biết đây là loại thức ăn, phần 并 cho âm đọc. Đây là dạng truyền thống, dùng trong thời Minh-Thanh, dạng giản thể là 饼.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Wiktionary phân tích: hình thanh tự (psc) — 食/飠 (thực, thức ăn) là biểu nghĩa, 并 là biểu âm. Dạng truyền thống thời Minh-Thanh dùng 幷 thay 并 (theo ảnh hưởng Thuyết Văn). Nghĩa là bánh làm từ bột, một loại thức ăn phổ biến. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thực (184) Tịnh (1276)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thực (số 184 - thức ăn/ 飠 /chỉ ý) ở bên trái chữ Tịnh (số 1276 - cùng nhau/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tịnh chỉ âm, bộ Thực chỉ ý. Bính là thứ thức ăn bột nhào lại làm thành bánh hình tròn và dẹt (bánh bính).", "Nghĩa Tiếng Việt_Xie": "bánh làm bằng bột", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠并", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "并", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "饼", "Unihan_Traditional (Chữ Phồn thể)": "餅", "Pinyin_Xie": "bǐng", "Âm Hán Việt_Xie": "bánh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ các loại bánh làm từ bột mì hoặc bột gạo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筍', '{"9000": "", "Chữ Trung Quốc": "筍", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 竹 | Số nét | 12 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 旬 | tuần | biểu âm | 筍 = 竹 (Trúc, biểu nghĩa: tre/trúc) + 旬 (Tuần, biểu âm); chữ hình thanh — bộ 竹 chỉ họ tre, 旬 cho âm sǔn/tuần. Là dạng phồn thể/cổ của 笋.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Chữ hình thanh: 竹 (trúc) biểu nghĩa chỉ họ tre; 旬 (tuần) biểu âm cho âm sǔn. Wiktionary ghi: {{Han compound|竹|旬|ls=psc|c1=s|c2=p|t1=bamboo}}. Nghĩa gốc là măng tre — chồi non của cây tre/trúc, thực phẩm truyền thống Trung Hoa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (108) Tuần (283)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 108 - tre trúc/ 竹 /chỉ ý) ở trên chữ Tuần (số 283 - 10 ngày/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tuần chỉ âm, bộ Trúc chỉ ý. Duẩn là măng tre trúc mọc lên. (Chữ giản thể hay dùng 笋).", "Nghĩa Tiếng Việt_Xie": "măng tre", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>⺮旬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笋", "Unihan_Traditional (Chữ Phồn thể)": "筍", "Pinyin_Xie": "sǔn", "Âm Hán Việt_Xie": "tuần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ măng tre, thường kết hợp với các danh từ khác chỉ món ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擇', '{"9000": "", "Chữ Trung Quốc": "擇", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Dịch (1362)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Dịch (số 1362 - xem thấu/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Dịch chỉ âm, bộ Thủ chỉ ý. Trạch là nhìn rồi dùng tay nhặt ra, chọn lấy, phân biệt (tuyển trạch, lựa chọn).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌睪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "择", "Unihan_Traditional (Chữ Phồn thể)": "擇", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籜', '{"9000": "", "Chữ Trung Quốc": "籜", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 竹 | Số nét | 22 | nét | 竹 | trúc | biểu nghĩa | tre — vật liệu | 擇 | trạch | biểu âm | lựa chọn — cho âm đọc tuò/trạch | 籜 = 竹 (Trúc, biểu nghĩa: tre) + 擇 (Trạch, biểu âm); chữ hình thanh. Chỉ lớp vỏ bọc ngoài của măng tre, rụng xuống khi tre lớn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Lục thư thông | Theo Wiktionary, 籜 là chữ hình thanh: 竹 (tre) biểu nghĩa, 擇 biểu âm. Nghĩa là lớp bẹ bao bọc ngoài cùng của măng tre (bamboo sheath) — lớp vỏ tự rụng khi cây tre trưởng thành. Chỉ có hình Lục thư thông (tạo muộn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (108) Trạch (1363)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 108 - tre trúc/ 竹 /chỉ ý) ở trên chữ Trạch (số 1363 - lựa chọn/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Trạch chỉ âm, bộ Trúc chỉ ý. Thác là phần vỏ cứng mọc bên ngoài cây măng, bẹ măng, cật tre măng tre.", "Nghĩa Tiếng Việt_Xie": "箨", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>⺮擇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "擇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箨", "Unihan_Traditional (Chữ Phồn thể)": "籜", "Pinyin_Xie": "tuò", "Âm Hán Việt_Xie": "thác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ phần vỏ bao bọc bên ngoài măng hoặc thân tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞦', '{"9000": "", "Chữ Trung Quốc": "鞦", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 革 | Số nét | 18 | nét | 革 | cách | biểu nghĩa | da thuộc | 秋 | thu | biểu âm | mùa thu (biểu âm) | 鞦 = 革 (Cách, biểu nghĩa: da thuộc) + 秋 (Thu, biểu âm). Chữ hình thanh: bộ 革 cho biết liên quan đến đồ da; 秋 cho âm đọc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 鞦 là chữ hình thanh (psc): 革 (da thuộc) làm biểu nghĩa, 秋 làm biểu âm. Chỉ dây da buộc đuôi ngựa hoặc xích đu (鞦韆). Không tìm thấy dạng giáp cốt. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cách (1316) Thu (201)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Cách (số 1316 - da thú/ 革 /chỉ ý) ở bên trái chữ Thu (số 201 - mùa thu/ 秋 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thu chỉ âm, bộ Cách chỉ ý. Thu vốn là sợi dây da buộc vào ngựa để kéo xe. Về sau dùng chỉ trò chơi đánh đu (thu thiên). Chữ giản thể dùng 秋.", "Nghĩa Tiếng Việt_Xie": "dây thắng đái", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革秋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "qiū", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong các từ ghép chỉ dây thắng ngựa hoặc trò chơi đánh đu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('䙴', '{"9000": "", "Chữ Trung Quốc": "䙴", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Á (670) Đại (035) Tiết (290)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm bộ Á (số 670 - che đậy/ 襾), chữ Đại (số 035 - to lớn/ 大) và bộ Tiết (số 290 - tiết tháo/ 㔾). Một người có tài năng đức hạnh lớn (Đại) và giữ được tiết tháo (Tiết) thì ân huệ sẽ che trùm khắp nơi (Á). Giải thích sự chuyển ý: Đây là chữ Hội ý. Thiên là lên cao, thăng tiến, chuyển dời lên trên. (Đây là chữ cổ).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>䙲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遷', '{"9000": "", "Chữ Trung Quốc": "遷", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 15 | nét | 遷 | thiên | tượng hình | dời chuyển, di chuyển | 遷 không có dữ liệu phân tích thành phần từ CHISE. Từ hình dáng, chữ có bộ 辶/辵 (đi, bước đi) gợi liên quan đến sự di chuyển. Tiểu triện còn lưu trong hanziyuan.net. Cấu trúc chi tiết chưa được phân tích học thuật.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 遷 (cổ văn) chỉ hành động dời chuyển — di dân, chuyển đô, thăng chức hoặc giáng chức. Bộ 辶 (đi) gợi sự di chuyển từ nơi này sang nơi khác. Tiểu triện còn lưu. Chưa có nguồn học thuật xác định cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Thiên (1366)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi/ 辶 /chỉ ý) ở bên ngoài chữ Thiên (số 1366 - lên cao/ 䙴 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thiên chỉ âm, bộ Xước chỉ ý. Thiên là dời đổi chỗ ở, di chuyển từ nơi này sang nơi khác (thiên đô, biến thiên, thăng thiên).", "Nghĩa Tiếng Việt_Xie": "thay đổi; di dời", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "迁", "Unihan_Traditional (Chữ Phồn thể)": "遷", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "thiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ nơi chốn hoặc kết hợp thành từ ghép như di thiên, biến thiên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韆', '{"9000": "", "Chữ Trung Quốc": "韆", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 革 | Số nét | 24 | nét | 韆 | thiên | tượng hình | xích đu — chỉ dùng trong 鞦韆 | 韆 không có phân tích lsCodes. Bộ 革 (cách, da thuộc) gợi ý liên quan đến dây da. Chữ chỉ xuất hiện trong từ ghép 鞦韆 (thu thiên, xích đu). Chưa có nguồn phân tích linh kiện chính thức.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 韆 (qiān) là chữ chỉ dùng trong 鞦韆 (xích đu). Tên 鞦韆 theo truyền thuyết có nguồn gốc từ trò chơi của các bộ tộc du mục phương Bắc, du nhập vào Trung Hoa thời cổ đại. Bộ 革 (da) trong 鞦韆 gợi ý dây xích đu ban đầu làm bằng da thuộc. Chưa có nguồn học thuật Wiktionary phân tích cấu trúc 韆. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cách (1316) Thiên (1367)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Cách (số 1316 - da thú/ 革 /chỉ ý) ở bên trái chữ Thiên (số 1367 - di dời/ 遷 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thiên chỉ âm, bộ Cách chỉ ý. Thiên là cái đu được làm bằng dây da cột vào cây để chơi đu (đánh thu thiên).", "Nghĩa Tiếng Việt_Xie": "(xem: thu thiên 鞦韆,秋千)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革遷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "thiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ thu tạo thành từ ghép chỉ trò chơi đánh đu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('湯', '{"9000": "", "Chữ Trung Quốc": "湯", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Dương (489)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước/ 氵/chỉ ý) ở bên trái chữ Dương (số 489 - bay lên/chỉ âm). Nước đun sôi thì bốc hơi nước bay lên. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Thang là nước nóng, nước đun sôi. Nó cũng mang nghĩa là món canh, nước canh ăn cơm hoặc thuốc sắc đun (thang thuốc, súp).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵昜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汤", "Unihan_Traditional (Chữ Phồn thể)": "湯", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盪', '{"9000": "", "Chữ Trung Quốc": "盪", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 皿 | Số nét | 17 | nét | 盪 | đãng | tượng hình | đung đưa, tráng rửa (dị thể của 蕩) | 盪 là dị thể của 蕩 (đãng), có bộ 皿 (mãnh, chén/bát) hoặc cấu trúc liên quan đến nước và chứa đựng. Không có dữ liệu cấu tạo chi tiết. Chưa có nguồn học thuật xác định ls riêng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 盪 là dị thể của 蕩 (đãng, đung đưa/tráng rửa). Wiktionary ghi nhận nhiều âm đọc (Quan thoại: dàng, Quảng Đông: dong6) và nghĩa: đung đưa, rung lắc, tráng rửa (nước). Chưa có phân tích cấu tạo chi tiết cho dạng 盪 trong dữ liệu. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thang (1371) Mãnh (107)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thang (số 1371 - nước nóng/ 湯 /chỉ âm) ở trên bộ Mãnh (số 107 - cái chậu/cái bát/ 皿 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thang chỉ âm, bộ Mãnh chỉ ý. Đãng là dùng nước trong chậu để rửa, giặt tẩy cho sạch (tẩy đãng). Do sự rung chuyển của nước khi rửa nên cũng có nghĩa là rung động, lắc qua lắc lại (chấn đãng).", "Nghĩa Tiếng Việt_Xie": "đu đưa, đánh đu; chèo thuyền; rửa, súc; làm hết sạch", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>湯皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "湯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "荡", "Unihan_Traditional (Chữ Phồn thể)": "盪", "Pinyin_Xie": "dàng", "Âm Hán Việt_Xie": "đãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ đứng trước tân ngữ để chỉ hành động rửa sạch hoặc lay động, chao đảo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屬', '{"9000": "", "Chữ Trung Quốc": "屬", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thi (044) Thục (1114)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thi (số 044 - cơ thể/cái đuôi/ 尸 /chỉ ý) ở bên trên bao bọc chữ Thục (số 1114 - con tằm/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. (Chữ 尸 ở đây là gốc từ bộ Vĩ 尾 - cái đuôi). Thuộc mang ý nghĩa là đi theo sau, chịu sự sai khiến, phụ thuộc vào (phụ thuộc, lệ thuộc).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴蜀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "属", "Unihan_Traditional (Chữ Phồn thể)": "屬", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戠', '{"9000": "", "Chữ Trung Quốc": "戠", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Âm (180) Qua (062)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Âm (số 180 - âm thanh/ 音) ở bên trái chữ Qua (số 062 - cái mác/ 戈). Giải thích sự chuyển ý: Đây là chữ Hội ý. Chức (hoặc Thức) là âm thanh của binh khí (cái mác) va chạm vào nhau. Chữ này chủ yếu dùng làm thành phần cấu tạo chữ khác.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰音戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "音", "Unihan_Simplified (Chữ Giản thể)": "戠", "Unihan_Traditional (Chữ Phồn thể)": "戠", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('識', '{"9000": "", "Chữ Trung Quốc": "識", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 19 | nét | 言 | ngôn | biểu nghĩa | lời nói | 戠 | biểu âm | phần biểu âm | 識 = 言 (Ngôn, biểu nghĩa: lời nói, ngôn ngữ) + 戠 (biểu âm, không dùng độc lập). Đây là chữ hình thanh (psc): bộ 言 cho biết nghĩa liên quan đến ngôn ngữ/nhận thức, 戠 cho âm đọc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 識 là chữ hình thanh: 言 (lời nói) biểu nghĩa + 戠 biểu âm. Hình kim văn và bigseal đã được ghi nhận. Nghĩa gốc là ''nhận biết, biết rõ'' — từ việc dùng lời nói để phân biệt và nhận thức sự vật. Phái sinh thêm nghĩa ''kiến thức, học thức''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Chức (1383)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Chức (số 1383 - âm thanh binh khí/ 戠 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Chức chỉ âm, bộ Ngôn chỉ ý. Thức là sự hiểu biết, nhìn thấy mà biết được (nhận thức, tri thức, kiến thức).", "Nghĩa Tiếng Việt_Xie": "kiến thức", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "识", "Unihan_Traditional (Chữ Phồn thể)": "識", "Pinyin_Xie": "shí", "Âm Hán Việt_Xie": "thức, chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ sự nhận biết hoặc làm danh từ trong các từ ghép chỉ tri thức. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('終', '{"9000": "", "Chữ Trung Quốc": "終", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 11 | nét | 糹 | mịch | biểu nghĩa | sợi dây, tơ | 冬 | đông | biểu âm | mùa đông (âm gần zhōng) | 終 = 糹 (Mịch, biểu nghĩa: sợi dây/tơ) + 冬 (Đông, biểu âm); chữ hình thanh, được cải tạo từ chữ tượng hình gốc. Nguyên gốc là chữ tượng hình (liushu p) miêu tả nút buộc cuối dây. Sau được viết lại thành hình thanh: 糹 (dây) + 冬 (âm).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Chữ 終 ban đầu là chữ tượng hình (liushu p) — hình nút buộc ở đầu cuối sợi dây (夂 trong nghĩa 2). Sau đó được cải tạo thành chữ hình thanh: 糹 (mịch, dây/tơ) là phần biểu nghĩa, 冬 là phần biểu âm. Wiktionary ghi: \"Originally a liushu p, 夂 – the knot at the end of a cord. Later reformulated as {{Han compound|糸|alt1=糹|冬|ls=psc}}.\" Nghĩa gốc: nút cuối dây, hết; sau mở rộng: kết thúc, cuối cùng. Có hình giáp cốt văn, kim văn, bạch thư, đại triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Đông (238)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái chữ Đông (số 238 - mùa đông/ 冬 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đông chỉ âm, bộ Mịch chỉ ý. Chung là cuộn tơ đã kết thúc. Mở rộng ra là kết thúc, điểm cuối cùng (chung kết, cuối chung).", "Nghĩa Tiếng Việt_Xie": "hết; cuối, kết thúc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹冬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "终", "Unihan_Traditional (Chữ Phồn thể)": "終", "Pinyin_Xie": "zhōng", "Âm Hán Việt_Xie": "chung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ sự kết thúc hoặc làm phó từ bổ nghĩa cho động từ để chỉ hành động kéo dài suốt một khoảng thời gian. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舊', '{"9000": "", "Chữ Trung Quốc": "舊", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 臼 | Số nét | 17 | nét | 雈 | biểu nghĩa | loài cú, chim cú | 臼 | cối | biểu âm | cái cối giã | 舊 = 雈 (biểu nghĩa: loài cú) + 臼 (Cối, biểu âm); chữ hình thanh (psc). Ban đầu chỉ một loại chim cú; sau được mượn âm để ghi từ đồng âm có nghĩa \"cũ, xưa cũ\".", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | 舊 (jiù): chữ hình thanh, gồm 雈 (biểu nghĩa: loài cú) và 臼 (Cối, biểu âm). Nghĩa gốc là một loại chim cú; phần trên thường xuất hiện dưới dạng 萑 (một loại cỏ lau). Chữ được mượn âm để chỉ từ đồng âm mang nghĩa \"cũ, lâu\". Kim văn và giáp cốt đã có hình chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (140) Cữu (134) Truy (034)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm bộ Thảo (số 140 - cỏ/ 艹), chữ Cữu (số 134 - cối giã/ 臼 /chỉ âm) và bộ Truy (số 034 - con chim/ 隹 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cữu chỉ âm, bộ Truy chỉ ý (một loài chim cú). Về sau được mượn làm từ chỉ sự đã qua, cũ, xưa lâu (cũ rích, cựu trào, hoài cựu). Chữ giản thể dùng 旧.", "Nghĩa Tiếng Việt_Xie": "cũ; lâu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "旧", "Unihan_Traditional (Chữ Phồn thể)": "舊", "Pinyin_Xie": "jiù", "Âm Hán Việt_Xie": "cựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để tu sức hoặc làm định ngữ trong câu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('銜', '{"9000": "", "Chữ Trung Quốc": "銜", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 14 | nét | 行 | hàng | biểu nghĩa | đi, hành lộ | 金 | kim | biểu âm | 銜 = 行 (Hàng, biểu nghĩa: đi, con đường) + 金 (Kim, biểu âm). Chữ hình thanh: 行 cho nghĩa liên kết/nối (như hàm thiếc ngựa nối người lái với ngựa); 金 cho âm xián (Hán-Việt: hàm).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 銜 (hàm) là chữ hình thanh theo Wiktionary: {{Han compound|行|金|c1=s|c2=p|ls=psc}}. Bộ 行 (hành: đi) cho nghĩa kết nối, nối tiếp — hàm thiếc ngựa là thứ nối người cưỡi với con ngựa. Kim cho âm. Từ nghĩa ''hàm ngựa'' mở rộng sang ''cấp bậc, chức danh'' (quan hàm). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hành (144) Kim (069)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 069 - kim loại/ 金 /chỉ ý) nằm lọt vào chính giữa bộ Hành (số 144 - ngã tư đường/bước đi/ 行 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Hành chỉ âm, bộ Kim chỉ ý. Hàm vốn là cái hàm thiếc ngậm trong miệng ngựa để điều khiển. Nghĩa mở rộng là ngậm, ngậm ngùi ôm giữ trong lòng (hàm oan).", "Nghĩa Tiếng Việt_Xie": "cái hàm thiết ngựa; quan hàm, quân hàm, phẩm hàm; nuốt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴行金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "金", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "行", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động ngậm trong miệng hoặc danh từ chỉ quân hàm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馮', '{"9000": "", "Chữ Trung Quốc": "馮", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 馬 | Số nét | 12 | nét | 冫 | băng | biểu âm | băng (biến thể 仌) | 馬 | mã | biểu nghĩa | ngựa | 馮 = 冫/仌 (Băng, biểu âm) + 馬 (Mã, biểu nghĩa: ngựa). Chữ hình thanh: bộ 馬 chỉ liên quan đến ngựa, 冫 cho âm đọc. Nghĩa cổ là phi ngựa; nay chủ yếu dùng làm họ người (họ Phùng/Féng).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | Theo Wiktionary, 馮 là chữ hình thanh (psc): bộ 馬 biểu nghĩa ''ngựa'', thành phần 仌/冫 biểu âm. Nghĩa gốc là phi ngựa, phóng ngựa. Có hai âm đọc: féng (họ người) và píng (phi ngựa, vượt sông bộ). Thành ngữ 暴虎馮河 (liều lĩnh đánh hổ tay không, vượt sông không thuyền) dùng âm píng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Băng (015) Mã (187)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Băng (số 015 - nước đá/ 冫/chỉ âm) ở bên trái bộ Mã (số 187 - con ngựa/ 馬 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Băng chỉ âm, bộ Mã chỉ ý. Bằng là con ngựa chạy nhanh. Nó cũng là một họ của người (họ Phùng).", "Nghĩa Tiếng Việt_Xie": "Phong", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冫馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "馬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冫", "Unihan_Simplified (Chữ Giản thể)": "冯", "Unihan_Traditional (Chữ Phồn thể)": "馮", "Pinyin_Xie": "féng", "Âm Hán Việt_Xie": "phùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ riêng chỉ họ người hoặc làm động từ trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('連', '{"9000": "", "Chữ Trung Quốc": "連", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 10 | nét | 辶 | xước | biểu nghĩa | đi lại, di chuyển | 車 | xa | biểu nghĩa | xe | 連 = 辶 (Xước, biểu nghĩa: đi lại) + 車 (Xa, biểu nghĩa: xe). Chữ hội ý: người kéo xe di chuyển — hình ảnh nối liền, kết nối. Duan Yucai cho rằng 聯 (thời Chu) và 連 (thời Hán) là cùng một từ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | 連 là chữ hội ý: 辵/辶 (đi lại) + 車 (xe) — hình ảnh xe được kéo đi, nối liền. Wiktionary xác nhận cấu trúc ic (ideogrammic compound). Theo Duan Yucai: 聯 dùng thời Chu, 連 dùng thời Hán — cùng một từ. Nghĩa: nối liền, liên kết, ngay cả. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Xa (159)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi/ 辶 /chỉ ý) bao bên ngoài bộ Xa (số 159 - xe cộ/ 車 /chỉ âm). Để xe đi được trơn tru thì mặt đường phải liên tục, không đứt đoạn. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Xa chỉ âm, bộ Xước chỉ ý. Liên là liền nhau, tiếp nối không đứt gãy (liên tục, liên kết).", "Nghĩa Tiếng Việt_Xie": "liền nối", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶車", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "車", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "连", "Unihan_Traditional (Chữ Phồn thể)": "連", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "liên, liễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Giới từ | 介词 | Liên từ | 连词 | Chữ này làm động từ chỉ sự liên kết hoặc làm giới từ trong cấu trúc nhấn mạnh ngay cả cái gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('橫', '{"9000": "", "Chữ Trung Quốc": "橫", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Hoàng (201)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây cối/ 木 /chỉ ý) ở bên trái bộ Hoàng (số 201 - màu vàng/ 黃 /chỉ âm). Cây có những cành mọc ngang ra. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Hoàng chỉ âm, bộ Mộc chỉ ý. Hoành là nằm ngang, dắt ngang (nét hoành, tung hoành, hoành phi).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木黃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "横", "Unihan_Traditional (Chữ Phồn thể)": "橫", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('尃', '{"9000": "", "Chữ Trung Quốc": "尃", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phủ (204) Thốn (041)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Phủ (số 204 - rộng lớn/ 甫 /chỉ âm) ở trên bộ Thốn (số 041 - tấc tay/ 寸 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Phủ chỉ âm, bộ Thốn chỉ ý. Phu là dùng tay trải ra, bày biện ra, phân tán ra. (Chữ này dễ nhầm với chữ Chuyên 專).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>甫寸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "寸", "Unihan_Simplified (Chữ Giản thể)": "尃", "Unihan_Traditional (Chữ Phồn thể)": "尃", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躍', '{"9000": "", "Chữ Trung Quốc": "躍", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 足 | Số nét | 21 | nét | 足 | túc | biểu nghĩa | chân | 翟 | biểu âm | 躍 = 足 (Túc, biểu nghĩa: chân) + 翟 (biểu âm, không có Hán-Việt thông dụng); chữ hình thanh. Phần 足 cho biết đây là hành động của chân, phần 翟 cho âm đọc gốc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | 躍 là chữ hình thanh: 足 (túc, biểu nghĩa chân) + 翟 (biểu âm). Chỉ hành động nhảy vọt, bước đại. Dạng đại triện lưu lại. Wiktionary xác nhận cấu trúc psc rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Túc (157) Địch (1396)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Túc (số 157 - cái chân/ 足 /chỉ ý) ở bên trái chữ Địch (số 1396 - chim trĩ/ 翟 /chỉ âm). Khi con chim nhảy vọt lên thì nhìn thấy rõ chân và đuôi lông chim. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Dược là nhảy lên, tung mình vọt lên (nhảy vọt, tước dược).", "Nghĩa Tiếng Việt_Xie": "nhảy", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊翟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跃", "Unihan_Traditional (Chữ Phồn thể)": "躍", "Pinyin_Xie": "yuè", "Âm Hán Việt_Xie": "thích, dược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ hoặc kết hợp để chỉ sự phát triển vượt bậc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謀', '{"9000": "", "Chữ Trung Quốc": "謀", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 16 | nét | 言 | ngôn | biểu nghĩa | lời nói, mưu tính | 某 | mỗ | biểu âm | một ai đó (cho âm) | 謀 = 言 (Ngôn, biểu nghĩa: lời nói/bàn luận) + 某 (Mỗ, biểu âm); chữ hình thanh. Phần 言 chỉ hành động bàn mưu tính kế, phần 某 cung cấp âm móu.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 謀 là chữ hình thanh: 言 (biểu nghĩa: lời nói/bàn luận) + 某 (biểu âm). Nghĩa cốt lõi: mưu tính, bàn mưu, kế sách. Dùng rộng rãi trong cả văn ngôn lẫn hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Mỗ (1398)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Mỗ (số 1398 - phiếm chỉ/ 某 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Mỗ chỉ âm, bộ Ngôn chỉ ý. Mưu là tính toán trước, dùng lời nói bàn định sắp đặt mọi việc rồi cứ thế mà làm (âm mưu, mưu trí, mưu đồ).", "Nghĩa Tiếng Việt_Xie": "lo liệu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言某", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "某", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "谋", "Unihan_Traditional (Chữ Phồn thể)": "謀", "Pinyin_Xie": "móu", "Âm Hán Việt_Xie": "mưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc lên kế hoạch, lo liệu hoặc làm danh từ chỉ mưu kế. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雖', '{"9000": "", "Chữ Trung Quốc": "雖", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 隹 | Số nét | 17 | nét | 虫 | trùng | biểu nghĩa | bò sát/côn trùng | 唯 | duy | biểu âm | 雖 = 虫 (Trùng, biểu nghĩa: bò sát) + 唯 (Duy, biểu âm); chữ hình thanh. Nghĩa gốc là một loài bò sát dạng thằn lằn; sau được mượn âm để biểu thị nghĩa liên từ \"mặc dù, tuy\". Biến thể đúng hơn về mặt tạo tự là 𧐌.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | 雖 (Hán-Việt: tuy) là chữ hình thanh: 虫 (trùng) biểu nghĩa chỉ loài bò sát dạng thằn lằn, 唯 (duy) cho âm đọc. Nghĩa gốc là một loài bò sát; chữ sau đó được mượn âm (giả tá) để ghi liên từ ''mặc dù, tuy nhiên''. Trong kim văn và tiểu triện đều ghi nhận hình dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030) Truy (034) Trùng (143)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 030/ 口) ở trên bộ Trùng (số 143/ 虫) và bên phải là bộ Truy (số 034/ 隹). Giải thích sự chuyển ý: Đây là chữ Hình thanh. (Bộ Trùng chỉ ý, chữ Thôi 唯 chỉ âm). Tuy vốn là tên một loài bò sát (như thằn lằn). Sau này chữ được mượn làm Hư từ mang ý nghĩa nhượng bộ: tuy rằng, mặc dù.", "Nghĩa Tiếng Việt_Xie": "Mặc dù", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虽隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "虽", "Unihan_Traditional (Chữ Phồn thể)": "雖", "Pinyin_Xie": "suī", "Âm Hán Việt_Xie": "tuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Liên từ | 连词 | Dùng làm liên từ đứng đầu vế câu để biểu thị quan hệ nhượng bộ. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倝', '{"9000": "", "Chữ Trung Quốc": "倝", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Triêu (181) Nhân (009)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Trác (số 821 - xuất chúng/viết là 龺 /chỉ âm) ở bên trái chữ Nhân (số 009 - người/viết là 𠆢 và 乚/chỉ ý). Người có trí tuệ thông minh xuất chúng thì nét mặt sẽ sáng sủa. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Cán là rực rỡ, sáng sủa, mặt trời vừa mọc sương mù tan hết.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰龺人", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "人", "Unihan_Simplified (Chữ Giản thể)": "倝", "Unihan_Traditional (Chữ Phồn thể)": "倝", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('幹', '{"9000": "", "Chữ Trung Quốc": "幹", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cán (1406) Can (051)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Cán (số 1406 - sáng sủa/ 倝 /chỉ âm) lồng vào với chữ Can (số 051 - lá chắn/ 干 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cán (倝) chỉ âm, chữ Can (干) chỉ ý. Cán ban đầu nghĩa là cái gốc cây, thân cây. Về sau chỉ thành phần chủ yếu, then chốt của sự vật (cốt cán). Đồng thời mang nghĩa là gánh vác làm việc (cán bộ).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰龺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('採', '{"9000": "", "Chữ Trung Quốc": "採", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Thái (1120)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌 /chỉ ý) ở bên trái chữ Thái (số 1120 - hái lượm/ 采 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Thái là dùng tay ngắt, hái lượm (thái trúc, hái quả). Mở rộng ra là chọn, nhặt (tuyển thái).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌采", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "采", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "采", "Unihan_Traditional (Chữ Phồn thể)": "採", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畝', '{"9000": "", "Chữ Trung Quốc": "畝", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mẫu (255) Cửu (439)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mẫu (số 255 - biến thể gồm chữ Đầu 亠 và chữ Điền 田/ 亩 /chỉ âm) ở bên trái chữ Cửu (số 439 - lâu dài/ 久 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Mẫu (hay sào) là một đơn vị để tính diện tích ruộng đất thời xưa (quyển mẫu).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亩久", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "久", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亩", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飼', '{"9000": "", "Chữ Trung Quốc": "飼", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 食 | Số nét | 13 | nét | 食 | thực | biểu nghĩa | thức ăn | 司 | ti | biểu âm | quản lý | 飼 = 食 (Thực, biểu nghĩa: thức ăn) + 司 (Ti, biểu âm); chữ hình thanh. Phần 食 chỉ nghĩa liên quan đến ăn uống; phần 司 cho âm sì/tự.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Chữ hình thanh: 食 (thực) biểu nghĩa ''thức ăn'', 司 (ti) biểu âm. Nghĩa gốc là cho ăn, nuôi dưỡng gia súc. Chưa có nguồn học thuật Wiktionary chi tiết về lịch sử tự dạng. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thực (184) Từ (249)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thực (số 184 - thức ăn/ 飠 /chỉ ý) ở bên trái chữ Từ (số 249 - làm quan/ 司 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Từ chỉ âm, bộ Thực chỉ ý. Tự là cho thú vật ăn, chăn nuôi gia súc, chim cá (chăn tự, tự dưỡng).", "Nghĩa Tiếng Việt_Xie": "cho ăn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠司", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "司", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "tự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động cho động vật ăn hoặc làm danh từ chỉ thức ăn chăn nuôi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('朁', '{"9000": "", "Chữ Trung Quốc": "朁", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ký (1351) Viết (073)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm 2 chữ Ký (số 1351 - nấc nghẹn/ 旡) đứng cạnh nhau ở trên chữ Viết (số 073 - nói ra/ 曰). Hình ảnh 2 người đang rưng rưng nấc nghẹn kể lể lại cho nhau nghe những cay đắng mà họ đã kinh qua. Giải thích sự chuyển ý: Đây là chữ Hội ý. Thảm (hay Thiêm) mang ý nghĩa là đã từng, từng trải qua. Nó cũng thường được dùng làm thành phần tạo chữ.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>兓日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "朁", "Unihan_Traditional (Chữ Phồn thể)": "朁", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('䖵', '{"9000": "", "Chữ Trung Quốc": "䖵", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trùng (143)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm 2 bộ Trùng (số 143 - con sâu bọ/ 虫) đứng cạnh nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Côn chỉ chung cho các loài sâu bọ, côn trùng sống tụ tập với số lượng nhiều (côn trùng). (Chữ này là chữ cổ, nay được thay thế bằng chữ Côn 昆).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠶', '{"9000": "", "Chữ Trung Quốc": "蠶", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 虫 | Số nét | 24 | nét | 蠶 | tằm | tượng hình | con tằm (silkworm) | 蠶 là chữ phồn thể chỉ con tằm (Bombyx mori). Wiktionary không cung cấp phân tích thành tố chi tiết. Đại triện và tiểu triện được ghi nhận. Giản thể hiện đại là 蚕.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | 蠶 là chữ phồn thể chỉ con tằm, dạng tiểu triện và đại triện được ghi nhận. Con tằm gắn liền với ngành dệt lụa — phát minh nổi tiếng nhất của văn minh Trung Hoa. Chưa có phân tích thành tố chi tiết từ Wiktionary cho chữ này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảm (1424) Côn (1425)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thảm (số 1424 - đã từng trải qua/ 朁 /chỉ âm) ở trên chữ Côn (số 1425 - sâu bọ/ 䖵 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thảm chỉ âm, chữ Côn chỉ ý. Tằm là loài sâu nhả tơ (con tằm). Chữ giản thể dùng 蚕.", "Nghĩa Tiếng Việt_Xie": "Tằm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>兓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蚕", "Unihan_Traditional (Chữ Phồn thể)": "蠶", "Pinyin_Xie": "cán", "Âm Hán Việt_Xie": "tằm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con tằm, thường làm chủ ngữ hoặc tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汙', '{"9000": "", "Chữ Trung Quốc": "汙", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Vu (223)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước/ 氵/chỉ ý) ở bên trái chữ Vu (số 223 - bộ khí/ 于 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Vu chỉ âm, bộ Thủy chỉ ý. Ô là vũng nước đọng đục bẩn, không trong sạch (ô uế, ô nhiễm). (Chữ giản thể hay dùng 污).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵于", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "于", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汙", "Unihan_Traditional (Chữ Phồn thể)": "汙", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穢', '{"9000": "", "Chữ Trung Quốc": "穢", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 禾 | Số nét | 18 | nét | 禾 | biểu nghĩa | lúa, cỏ ruộng | 歲 | biểu âm | 穢 = 禾 (biểu nghĩa: lúa/cỏ trong ruộng) + 歲 (biểu âm); chữ hình thanh. Bộ Hòa (禾) gợi cỏ dại mọc trong ruộng, phần Tuế (歲) cho âm đọc. Chữ mang nghĩa bẩn thỉu, dơ bẩn, ô uế.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 穢 là chữ hình thanh: 禾 (hòa, lúa/cỏ) làm bộ biểu nghĩa (c1=s), 歲 làm phần biểu âm (c2=p). Nghĩa gốc là cỏ dại mọc trong ruộng, từ đó mở rộng thành bẩn thỉu, ô uế, tục tĩu. Tiếng Quảng Đông đọc wai3, tiếng Hokkien đọc è/ò. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hòa (115) Tuế (404)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hòa (số 115 - cây lúa/ 禾 /chỉ ý) ở bên trái chữ Tuế (số 404 - năm/ 歲 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tuế chỉ âm, bộ Hòa chỉ ý. Uế vốn chỉ thứ cỏ hoang, cỏ dại mọc làm hại lúa. Về sau mang ý nghĩa là dơ bẩn, nhơ nhuốc, hành vi xấu xa (ô uế, uế tạp).", "Nghĩa Tiếng Việt_Xie": "bẩn thỉu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾歲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "歲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秽", "Unihan_Traditional (Chữ Phồn thể)": "穢", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "uế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ đứng trước danh từ để miêu tả sự bẩn thỉu hoặc đồi bại. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('責', '{"9000": "", "Chữ Trung Quốc": "責", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 11 | nét | 朿 | thứ | biểu âm | cái gai nhọn | 貝 | buổi | biểu nghĩa | vỏ ốc, tiền | 責 = 朿 (Thứ, biểu âm, gai nhọn) + 貝 (Buổi, biểu nghĩa: tiền của, vỏ ốc); chữ hình thanh. Bộ 貝 chỉ đây liên quan đến tiền của, nghĩa vụ tài chính (thuế, nợ); 朿 cho âm đọc. Phần trên hiện tương tự 生 nhưng đó là biến thể sau.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 責 là chữ hình thanh: 貝 (buổi, tiền/vỏ ốc) biểu nghĩa, 朿 (gai nhọn) biểu âm — nghĩa gốc là thuế, nợ. Theo Wiktionary, phần trên hiện nay trông giống 生 (không có nét chéo) là biến thể, tương tự như ở 青, 素. Từ nghĩa gốc tài chính/nghĩa vụ, mở rộng sang trách nhiệm, trách mắng. Tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sinh (100) Bối (154)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Sinh (số 100 - sinh ra/lớn lên/viết giảm nét thành 𠫓) ở trên bộ Bối (số 154 - vỏ sò/tiền bạc/ 貝). Để có tiền sinh sống thì con người phải làm tròn phận sự, nhiệm vụ được giao phó. Giải thích sự chuyển ý: Đây là chữ Hội ý. Trách là bổn phận, phận sự phải làm cho xong (trách nhiệm, phụ trách). Nó cũng mang nghĩa là chê trách, trách móc kẻ có lỗi.", "Nghĩa Tiếng Việt_Xie": "cầu xin; trách mắng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>龶貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "责", "Unihan_Traditional (Chữ Phồn thể)": "責", "Pinyin_Xie": "zé", "Âm Hán Việt_Xie": "trái, trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ bổn phận hoặc làm động từ mang nghĩa phê bình, yêu cầu thực hiện. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('積', '{"9000": "", "Chữ Trung Quốc": "積", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 禾 | Số nét | 16 | nét | 禾 | hoà | biểu nghĩa | lúa, hoa màu | 責 | trách | biểu âm | 積 = 禾 (Hoà, biểu nghĩa: lúa, hoa màu) + 責 (Trách, biểu âm). Chữ hình thanh: 禾 cho biết liên quan đến lúa/hoa màu tích trữ, 責 cho âm đọc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | 積 là chữ hình thanh: 禾 (lúa) biểu nghĩa, 責 biểu âm. Nghĩa gốc là ''chứa chất lúa gạo'' rồi mở rộng sang ''tích lũy, dồn chứa''. Trong toán học, 積 là kết quả phép nhân (tích số). Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hòa (115) Trách (1434)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hòa (số 115 - cây lúa/ 禾 /chỉ ý) ở bên trái chữ Trách (số 1434 - phận sự/ 責 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Trách chỉ âm, bộ Hòa chỉ ý. Tích là chứa lúa dồn thành đống. Mở rộng ra là chứa, gom góp lại, tích trữ, góp nhặt từ ít thành nhiều (tích lũy, tích trữ, diện tích).", "Nghĩa Tiếng Việt_Xie": "chứa chất, tích, dồn lại; tích (kết quả phép nhân)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾責", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "責", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "积", "Unihan_Traditional (Chữ Phồn thể)": "積", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ sự tích lũy hoặc làm danh từ chỉ kết quả phép nhân trong toán học. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('灑', '{"9000": "", "Chữ Trung Quốc": "灑", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Lệ (1032)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước/ 氵/chỉ ý) ở bên trái chữ Lệ (số 1032 - tươi đẹp/ 麗 /chỉ âm). Để cho cây cỏ luôn tươi tốt, đẹp đẽ thì phải tưới nước thường xuyên. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Sái là rưới, rắc, tưới nước (sái nước). (Chữ giản thể dùng 洒).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵麗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "麗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洒", "Unihan_Traditional (Chữ Phồn thể)": "灑", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒼', '{"9000": "", "Chữ Trung Quốc": "蒼", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 艸 | Số nét | 13 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 倉 | thương | biểu âm | (biểu âm) | 蒼 = 艸 (Tháu, biểu nghĩa: cỏ, thực vật) + 倉 (Thương, biểu âm); chữ hình thanh. Bộ 艸 cho biết liên quan đến màu xanh của cỏ cây; 倉 (thương) cung cấp âm đọc và gần nghĩa xanh lam.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Bạch thư | Tiểu triện | Theo Wiktionary, 蒼 là chữ hình thanh: bộ 艸 (tháu — cỏ) biểu nghĩa, 倉 (thương) biểu âm. Nghĩa là màu xanh lam đậm (màu trời, màu biển), màu xanh của thảo mộc. Dùng trong 蒼天 (trời xanh), 蒼老 (già nua, tóc bạc), 蒼白 (nhợt nhạt). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (140) Thương (631)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 140 - cỏ/ 艹 /chỉ ý) ở trên chữ Thương (số 631 - cái kho/ 倉 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thương chỉ âm, bộ Thảo chỉ ý. Thương vốn chỉ màu xanh của cây cỏ. Về sau chỉ màu xanh thẫm, xanh đen, xám (thương thiên - bầu trời xanh).", "Nghĩa Tiếng Việt_Xie": "xanh, nhợt nhạt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹倉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "倉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苍", "Unihan_Traditional (Chữ Phồn thể)": "蒼", "Pinyin_Xie": "cāng", "Âm Hán Việt_Xie": "thương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ đứng trước danh từ để chỉ màu sắc hoặc trạng thái. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠅', '{"9000": "", "Chữ Trung Quốc": "蠅", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 虫 | Số nét | 19 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sâu bọ | 黽 | mãnh | biểu âm | 蠅 = 虫 (Trùng, biểu nghĩa: côn trùng) + 黽 (Mãnh, biểu âm); chữ hình thanh. Phần 虫 cho biết đây là loài côn trùng, phần 黽 cung cấp âm đọc yíng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Wiktionary xác nhận: 蠅 là chữ hình thanh, gồm 虫 (biểu nghĩa: côn trùng) + 黽 (biểu âm). Chỉ loài ruồi. Có hình tiểu triện và lục thư thông từ nguồn hanziyuan. Ruồi (蠅) gắn với các tục ngữ về vật nhỏ làm phiền như \"蠅頭小利\" (lợi nhỏ như đầu ruồi). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trùng (143) Mãnh (656)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trùng (số 143 - côn trùng/ 虫 /chỉ ý) ở bên trái bộ Mãnh (số 656 - con ếch/ 黽 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Mãnh chỉ âm, bộ Trùng chỉ ý. Nhặng (hoặc Dăng) là con ruồi, con nhặng (thương dăng - con ruồi xanh).", "Nghĩa Tiếng Việt_Xie": "bay", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫黽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝇", "Unihan_Traditional (Chữ Phồn thể)": "蠅", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "nhặng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loài côn trùng có cánh thường thấy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('區', '{"9000": "", "Chữ Trung Quốc": "區", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hệ (023) Phẩm (106)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hệ (số 023 - che đậy/ 匸 /chỉ ý) bao bên ngoài chữ Phẩm (số 106 - vật phẩm/ 品 /chỉ âm). Các vật phẩm cất bên trong có thể được phân thành từng chỗ riêng biệt. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Khu là chia ra, phân biệt (khu biệt). Từ đó chỉ từng cõi, miền, vùng địa lý trong một quốc gia (khu vực, địa khu).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿷ (Bao quanh phía trái)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴匚品", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "品", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "匚", "Unihan_Simplified (Chữ Giản thể)": "区", "Unihan_Traditional (Chữ Phồn thể)": "區", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驅', '{"9000": "", "Chữ Trung Quốc": "驅", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 馬 | Số nét | 21 | nét | 馬 | mã | biểu nghĩa | ngựa | 區 | khu | biểu âm | 驅 = 馬 (Mã, biểu nghĩa: ngựa) + 區 (Khu, biểu âm); chữ hình thanh. Bộ 馬 xác nhận nghĩa liên quan đến việc lái, thúc ngựa; 區 cho âm đọc gần qū.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 驅 (qū) là chữ hình thanh: bộ 馬 (ngựa) cho nghĩa — thúc ngựa chạy, xua đuổi; 區 (khu) cho âm. Wiktionary xác nhận cấu trúc Han compound ls=psc. Có tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mã (187) Khu (1440)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mã (số 187 - con ngựa/ 馬 /chỉ ý) ở bên trái chữ Khu (số 1440 - phân biệt/ 區 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Khu chỉ âm, bộ Mã chỉ ý. Khu là quất roi đuổi ngựa chạy nhanh lên, xua đuổi, lùa súc vật đi (khu trục).", "Nghĩa Tiếng Việt_Xie": "lái xe", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬區", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "區", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "khu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động xua đuổi hoặc điều khiển xe cộ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厭', '{"9000": "", "Chữ Trung Quốc": "厭", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hán (115) Nhật (072) Nguyệt (074) Khuyển (058)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bao gồm bộ Hán (số 115 - sườn núi/ 厂), chữ Nhật (số 072 - mặt trời/ 日), bộ Nguyệt (số 074 - mặt trăng/thịt/ 月) và bộ Khuyển (số 058 - chó/ 犬). Con chó bị che lấp dưới sườn núi tối tăm không thấy mặt trăng mặt trời nên rất chán ghét. Giải thích sự chuyển ý: Đây là chữ Hội ý. Yếm là sự chán ghét, chán ngán, ruồng bỏ (chán yếm, yếm thế).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂猒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "猒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "厌", "Unihan_Traditional (Chữ Phồn thể)": "厭", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腦', '{"9000": "", "Chữ Trung Quốc": "腦", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 肉 | Số nét | 13 | nét | 匕 | tỷ | thìa, muỗng — thay thế sau cho bộ 肉 | 巛 | tóc | 囟 | đầu, thóp đầu trẻ sơ sinh | 腦 là chữ hội ý (ic): nguyên thủy là 匘, gồm 匕 + 巛 (tóc) + 囟 (thóp đầu/đỉnh đầu). Về sau 匕 được thay bằng bộ 肉 (thịt). Hình ảnh: tóc trên đầu, thóp đầu — chỉ não bộ bên trong hộp sọ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 腦 vốn là chữ 匘, hội ý gồm 匕 + 巛 (tóc) + 囟 (thóp đầu). Về sau 匕 được thay bằng 肉 (thịt) để nhấn mạnh não là tổ chức thịt. Chữ chỉ não, óc — cơ quan trong hộp sọ điều khiển toàn thân. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhục (130) Xuyên (047) Tín (1004)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhục (số 130 - thịt/viết dạng 月), chữ Xuyên (số 047 - sông/ 巛 /viết biến đi) và chữ Tín (số 1004 - thóp đầu/ 囟). Giải thích sự chuyển ý: Não là khối óc trong đầu người, là bộ phận trung tâm điều khiển suy nghĩ của cơ thể (bộ não, đầu não).", "Nghĩa Tiếng Việt_Xie": "não, óc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "脑", "Unihan_Traditional (Chữ Phồn thể)": "腦", "Pinyin_Xie": "nǎo", "Âm Hán Việt_Xie": "não", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cơ quan thần kinh trung ương hoặc phần đầu của động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緞', '{"9000": "", "Chữ Trung Quốc": "緞", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 15 | nét | 緞 | đoạn | tượng hình | vải lụa bóng (satin); thuộc bộ tơ sợi (糸) | 緞 thuộc bộ 糸 (mịch, tơ sợi), phiên âm duàn. Wiktionary ghi {{Han etym}} chưa triển khai cấu trúc thành phần. Nghĩa: vải sa tanh (satin) — loại lụa bóng mịn. Có ảnh Tiểu triện từ hanziyuan.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 緞 (duàn) thuộc bộ 糸 (mịch, tơ sợi). Nghĩa: sa tanh, lụa bóng mịn. Wiktionary chưa triển khai gốc chữ chi tiết. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Đoạn (1450)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái chữ Đoạn (số 1450 - chia đoạn/ 段 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đoạn chỉ âm, bộ Mịch chỉ ý. Đoạn là loại lụa được dệt trơn, bóng (tơ đoạn).", "Nghĩa Tiếng Việt_Xie": "vải đoạn, vải lụa trơn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹段", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "段", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "缎", "Unihan_Traditional (Chữ Phồn thể)": "緞", "Pinyin_Xie": "duàn", "Âm Hán Việt_Xie": "đoạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp thành từ ghép chỉ các loại tơ lụa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莊', '{"9000": "", "Chữ Trung Quốc": "莊", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 艸 | Số nét | 10 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 壯 | tráng | biểu âm | mạnh mẽ | 莊 = 艸 (Tháu, biểu nghĩa: cỏ/thực vật) + 壯 (Tráng, biểu âm); chữ hình thanh. Bộ 艸 ban đầu gợi nghĩa cỏ mọc um tùm rồi mở rộng sang trang trại, nơi ở giữa cây cối. 壯 cho âm đọc zhuāng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 莊 là chữ hình thanh: 艸 (cỏ) làm thành phần biểu nghĩa, 壯 làm thành phần biểu âm. Nghĩa gốc là cỏ mọc, về sau mở rộng sang trang trại, gia trang, vùng đất, và ý nghĩa trang nghiêm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (140) Tráng (548)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 140 - cỏ/ 艹 /chỉ ý) ở trên chữ Tráng (số 548 - khỏe mạnh/ 壯 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tráng chỉ âm, bộ Thảo chỉ ý. Trang vốn là nhà có ruộng vườn cây cỏ mọc xung quanh (thôn trang, trang trại). Nó cũng mang ý nghĩa là sự kính cẩn, nét mặt nghiêm trang (trang trọng, đoan trang).", "Nghĩa Tiếng Việt_Xie": "trang trại, gia trang; họ Trang", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹壯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "zhuāng", "Âm Hán Việt_Xie": "trang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ chỉ thái độ nghiêm túc hoặc danh từ chỉ khu đất, trang trại. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覺', '{"9000": "", "Chữ Trung Quốc": "覺", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 見 | Số nét | 20 | nét | 𦥯 | học | biểu âm | biểu âm (dạng cổ của 學) | 見 | kiến | biểu nghĩa | nhìn, thấy | 覺 = 𦥯 (dạng cổ của 學, biểu âm) + 見 (Kiến, biểu nghĩa: nhìn/thấy); chữ hình thanh. Phần 見 xác định nghĩa liên quan đến nhận thức bằng thị giác; phần 𦥯 cung cấp âm đọc gần với giác/học.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | Theo Wiktionary, 覺 là chữ hình thanh: 𦥯 (dạng cổ của 學) là phần biểu âm, 見 (nhìn/thấy) là phần biểu nghĩa. Nghĩa gốc là thức giấc, giác ngộ, nhận ra. Dạng đại triện và tiểu triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Học (1140) Kiến (147)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Phần trên của chữ Học (số 1140 - học hành/giảm nét thành 𦥯) ở trên chữ Kiến (số 147 - nhìn thấy/ 見). Nhờ có học hành và quan sát mà thấu suốt được sự lý. Giải thích sự chuyển ý: Đây là chữ Hội ý. Giác là hiểu ra, ngộ ra, cảm thấy, nhận biết (giác ngộ, cảm giác). Nếu đọc là jiào thì mang nghĩa là giấc ngủ (thụy giác).", "Nghĩa Tiếng Việt_Xie": "biết; phát hiện; tỉnh dậy", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>𦥯見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦥯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "見", "Unihan_Simplified (Chữ Giản thể)": "觉", "Unihan_Traditional (Chữ Phồn thể)": "覺", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "giác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ biểu thị sự nhận biết, cảm giác hoặc tỉnh ngộ tâm linh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('諾', '{"9000": "", "Chữ Trung Quốc": "諾", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Nhược (801)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Nhược (số 801 - như/ 若 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nhược chỉ âm, bộ Ngôn chỉ ý. Nặc là tiếng đáp lại lời gọi (vâng, dạ). Từ đó mở rộng nghĩa là nhận lời, hứa hẹn, đồng ý (ưng nặc, tựu nặc).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言若", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "若", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "诺", "Unihan_Traditional (Chữ Phồn thể)": "諾", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謂', '{"9000": "", "Chữ Trung Quốc": "謂", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 16 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn từ | 胃 | vị | biểu âm | dạ dày | 謂 = 言 (Ngôn, biểu nghĩa: lời nói) + 胃 (Vị, biểu âm); chữ hình thanh. Bộ 言 cho nghĩa lời nói/gọi tên, bộ 胃 cho âm wèi.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Chữ hình thanh: 言 (ngôn) biểu nghĩa chỉ lời nói, 胃 (vị) biểu âm wèi. Nghĩa: gọi là, được gọi là, nói rằng. Dùng rất nhiều trong câu 所謂 (sở vị = cái gọi là), 謂語 (vị ngữ = vị từ trong ngữ pháp). Phồn thể 謂 tương ứng giản thể 谓. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Vị (1457)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Vị (số 1457 - dạ dày/ 胃 /chỉ âm). Dùng lời nói từ tận đáy lòng (dạ dày) để nói cho biết. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Vị nghĩa là nói cho biết, bảo cho biết (xưng vị). Nghĩa khác là gọi là, có nghĩa là (sở vị).", "Nghĩa Tiếng Việt_Xie": "vị ngữ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言胃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "谓", "Unihan_Traditional (Chữ Phồn thể)": "謂", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "vị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ để giải thích ý nghĩa hoặc gọi tên một sự vật, hiện tượng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('週', '{"9000": "", "Chữ Trung Quốc": "週", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 11 | nét | 辶 | sước | biểu nghĩa | đi lại | 周 | chu | biểu âm | chu vi, vòng quanh | 週 = 辶 (Sước, biểu nghĩa: đi lại) + 周 (Chu, biểu âm); chữ hình thanh. Đây là chữ tạo muộn (後起字) bổ sung bộ 辶 vào 周 để chỉ rõ ý nghĩa đi một vòng, tuần hoàn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | 週 là chữ tạo muộn (後起字): 辶 (đi lại) + 周 (chu vi). Được tạo ra để phân biệt nghĩa \"tuần, một vòng\" với 周 (nhà Chu, chu đáo). Có dạng đại triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Chu (451)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi/ 辶 /chỉ ý) bao bên ngoài chữ Chu (số 451 - chu toàn/vòng quanh/ 周 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Chu là xoay vòng, vòng quanh. Mở rộng là khoảng thời gian tuần hoàn lặp lại định kỳ (chu kỳ, tuần lễ / chu mạt - cuối tuần).", "Nghĩa Tiếng Việt_Xie": "tuần", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶周", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "zhōu", "Âm Hán Việt_Xie": "chu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ hoặc lượng từ đứng sau số từ để chỉ đơn vị thời gian tuần lễ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('於', '{"9000": "", "Chữ Trung Quốc": "於", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 方 | Số nét | 8 | nét | 方 | phương | biểu nghĩa | phương hướng | 仒 | biểu âm | thành phần gốc từ biến thể của 烏 | 於 là biến thể cổ của 烏 (ô – con quạ), không liên quan đến 方 (phương). Cấu trúc hiện đại ⿰方仒 là kết quả của sự biến dạng chữ viết. Không phân loại hình thanh hay hội ý rõ ràng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Wiktionary ghi 於 bắt nguồn từ biến thể cổ của 烏 (quạ). Không liên quan đến 方 hay 㫃 dù trông giống. Là giới từ/hư từ cổ điển nghĩa là ''ở, tại, về, hơn''. Tiếng Việt đọc là ''ư'' — tiểu từ cổ trong văn ngôn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Yểm (070) Nhị (007)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Yểm (số 070 - lá cờ/ 㫃) bao bọc lấy chữ Nhị (số 007 - số 2/ 二). Lá cờ được cắm ở một nơi nào đó trên mặt đất (nhị). Giải thích sự chuyển ý: Đây là chữ Hội ý. Nghĩa gốc của Ư là ở tại, cắm mốc. Về sau được mượn làm Giới từ (Hư từ) mang ý nghĩa: ở, tại, đối với, bị, được (sinh ư tư, trưởng ư tư).", "Nghĩa Tiếng Việt_Xie": "Tại", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰方仒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "方", "Unihan_Simplified (Chữ Giản thể)": "於", "Unihan_Traditional (Chữ Phồn thể)": "於", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "ư, ô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Giới từ | 介词 | Thường làm giới từ đứng trước danh từ hoặc đại từ để giới thiệu nơi chốn, đối tượng. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吳', '{"9000": "", "Chữ Trung Quốc": "吳", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030) Đại (035)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm bộ Khẩu (số 030 - cái miệng/ 口), chữ Đại (số 035 - to lớn/ 大) và một nét phẩy hướng lên trên (đầu người). Hình ảnh một người đang nghiêng đầu, giơ tay nói thật lớn tiếng. Giải thích sự chuyển ý: Đây là chữ Hội ý. Nghĩa gốc của Ngô là tiếng nói to, ồn ào. Sau này dùng làm một Họ của người (họ Ngô) hoặc tên nước (Đông Ngô).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "吴", "Unihan_Traditional (Chữ Phồn thể)": "吳", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('誤', '{"9000": "", "Chữ Trung Quốc": "誤", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 14 | nét | 言 | ngôn | biểu nghĩa | lời nói | 吳 | ngô | biểu âm | nước Ngô (cho âm) | 誤 là chữ hình thanh: 言 (ngôn — lời nói) biểu nghĩa gợi sai sót trong ngôn ngữ, 吳 (ngô) biểu âm. Wiktionary ghi ''nói sai'' là nghĩa gốc. Giản thể là 误.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Theo Wiktionary, 誤 = 言 (ngôn — lời nói, biểu nghĩa) + 吳 (ngô, biểu âm) — nghĩa gốc là nói sai. Mở rộng thành: sai lầm, nhầm lẫn, làm lỡ, gây hại. Tiểu triện và lục thư thông đều ghi nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Ngô (1463)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Ngô (số 1463 - họ Ngô/nói to/ 吳 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ngô chỉ âm, bộ Ngôn chỉ ý. Ngộ là lỡ lời, nói lầm, sai lầm, nhầm lẫn (nhầm ngộ, ngộ nhận, ngộ sát).", "Nghĩa Tiếng Việt_Xie": "nhầm; làm mê hoặc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言吴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "误", "Unihan_Traditional (Chữ Phồn thể)": "誤", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "ngộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ sự nhầm lẫn hoặc làm phó từ bổ nghĩa cho hành động sai sót. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('墮', '{"9000": "", "Chữ Trung Quốc": "墮", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tùy (1465) Thổ (032)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tùy/Đọa (số 1465 - nhà Tùy/ 隋 /chỉ âm) ở trên bộ Thổ (số 032 - đất/ 土 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tùy/Đọa chỉ âm, bộ Thổ chỉ ý. Đọa là rơi xuống đất, rớt xuống, sa vào một cảnh giới tồi tệ (sa đọa, đọa đày, đọa lạc).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>隋土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "堕", "Unihan_Traditional (Chữ Phồn thể)": "墮", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驚', '{"9000": "", "Chữ Trung Quốc": "驚", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 馬 | Số nét | 22 | nét | 敬 | kính | biểu âm | phần cho âm jīng | 馬 | mã | biểu nghĩa | ngựa | 驚 = 敬 (Kính, biểu âm) + 馬 (Mã, biểu nghĩa: ngựa); chữ hình thanh (psc). Wiktionary giải thích: ngựa rất dễ bị giật mình sợ hãi (skittish) — bộ 馬 biểu nghĩa \"sợ hãi, giật mình\", 敬 cho âm.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | 驚 là chữ hình thanh: 敬 (biểu âm) + 馬 (ngựa — biểu nghĩa). Wiktionary: ngựa là loài dễ bị hoảng sợ và giật mình (skittish), nên bộ 馬 biểu nghĩa \"kinh hãi\". Xuất hiện trong đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kính (458) Mã (187)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Kính (số 458 - kính trọng/đề phòng/ 敬 /chỉ âm) ở trên bộ Mã (số 187 - con ngựa/ 馬 /chỉ ý). Hình ảnh con ngựa đang cảnh giác và kinh hãi lồng lên vì nguy hiểm. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Kính chỉ âm, bộ Mã chỉ ý. Kinh là sợ hãi tột độ, sửng sốt, giật mình (kinh hãi, hoảng kinh, kinh khủng).", "Nghĩa Tiếng Việt_Xie": "kinh động; kinh sợ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>敬馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "惊", "Unihan_Traditional (Chữ Phồn thể)": "驚", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "kinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ trạng thái giật mình, hoảng sợ hoặc làm tính từ miêu tả sự kinh ngạc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溫', '{"9000": "", "Chữ Trung Quốc": "溫", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước/ 氵/chỉ ý) ở bên trái chữ Ôn (𥁕 - hình ảnh người tù được cho ăn trong chậu/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ôn (𥁕) chỉ âm, bộ Thủy chỉ ý. Ôn là nước nóng ấm, không quá lạnh (hòa ôn, ôn tuyền). Mở rộng ra là ấm áp, hòa nhã (ôn hòa, ôn tồn). Nghĩa khác là học lại, làm cho nhuần nhuyễn (ôn tập).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵𥁕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𥁕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "温", "Unihan_Traditional (Chữ Phồn thể)": "溫", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輩', '{"9000": "", "Chữ Trung Quốc": "輩", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 車 | Số nét | 15 | nét | 車 | xa | biểu nghĩa | xe | 非 | phi | biểu âm | không phải, sai | 輩 = 車 (Xa, biểu nghĩa) + 非 (Phi, biểu âm); chữ hình thanh. Ban đầu 車 (xe) biểu nghĩa gợi ý về hàng xe xếp thành dãy, từ đó mở rộng sang nghĩa ''thế hệ, lớp người, hàng lớp''.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Chữ hình thanh: bộ 車 biểu nghĩa, 非 biểu âm. Nghĩa gốc là ''dãy xe xếp hàng'', mở rộng sang ''thế hệ, lớp người, hạng''. 輩 hiện dùng phổ biến trong 輩分 (thứ bậc thế hệ), 晚輩 (thế hệ sau), 前輩 (tiền bối). Có tiểu triện và Lục thư thông trong dữ liệu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phi (175) Xa (159)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Phi (số 175 - trái phải/sai trái/ 非 /chỉ âm) ở trên bộ Xa (số 159 - xe cộ/ 車 /chỉ ý). Hình ảnh những chiếc xe xếp thành từng hàng, từng lối. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Bộ Phi chỉ âm, bộ Xa chỉ ý. Bối là xe cộ nối đuôi nhau thành hàng. Nghĩa mở rộng là một lớp người, thế hệ người cùng tuổi, thứ bậc (tiền bối, hậu bối).", "Nghĩa Tiếng Việt_Xie": "lũ, bọn, chúng; hàng xe, dãy xe; ví, so sánh; thế hệ, lớp người; hạng, lớp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>非車", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "車", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "非", "Unihan_Simplified (Chữ Giản thể)": "辈", "Unihan_Traditional (Chữ Phồn thể)": "輩", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ thế hệ hoặc hậu tố chỉ nhóm người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巖', '{"9000": "", "Chữ Trung Quốc": "巖", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sơn (046) Nghiêm (1482)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Sơn (số 046 - ngọn núi/ 山 /chỉ ý) ở trên chữ Nghiêm (số 1482 - nghiêm khắc/ 嚴 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nghiêm chỉ âm, bộ Sơn chỉ ý. Nham là chỗ núi đá hiểm trở, hang đá (nham thạch). (Chữ này chữ giản thể dùng 岩/Nham - núi đá).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>山嚴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "嚴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嚴', '{"9000": "", "Chữ Trung Quốc": "嚴", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030) Hán (115) Cảm (1480)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm hai bộ Khẩu (số 030/ 吅), bộ Hán (số 115/ 厂) và chữ Cảm (số 1480/ 敢). (Chữ này cũng hay dùng làm 1 họ: họ Nghiêm). Giải thích sự chuyển ý: Nghiêm là sự dặn dò (Khẩu) khắt khe, giáo dục người dưới (như dưới núi/Hán) trở nên can đảm (Cảm). Mang nghĩa là khắt khe, nghiêm túc (nghiêm khắc, nghiêm trọng). (Chữ giản thể là 严).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>吅𠪚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠪚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "吅", "Unihan_Simplified (Chữ Giản thể)": "严", "Unihan_Traditional (Chữ Phồn thể)": "嚴", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禦', '{"9000": "", "Chữ Trung Quốc": "禦", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 示 | Số nét | 17 | nét | 御 | ngự | biểu âm | 示 | thị | biểu nghĩa | thần linh, lễ nghi | 禦 = 御 (Ngự, biểu âm) + 示 (Thị, biểu nghĩa); chữ hình thanh. Bộ Thị mang ý nghĩa thiêng liêng/bảo vệ, phần 御 cho âm đọc yù.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Đại triện | Tiểu triện | Chữ hình thanh: 御 (biểu âm) + 示 (thần linh/lễ nghi, biểu nghĩa). 禦 nghĩa là ''phòng thủ, kháng cự, chống lại''. Bộ Thị gợi ý sự bảo vệ có tính thiêng liêng, thần linh bảo hộ. Trong giáp cốt văn đã có dạng sơ khai của chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kỳ (135) Ngự (1484)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Ngự (số 1484 - đánh xe/ 御 /chỉ âm) ở trên bộ Kỳ (số 135 - thần đất/thần kỳ/ 示 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ngự (御) chỉ âm, bộ Kỳ (示) chỉ ý. Ngự vốn chỉ việc làm lễ tế thần để tạ ơn. Về sau mang ý nghĩa là ngăn chặn lại, chống lại hiểm họa từ bên ngoài (phòng ngự, kháng ngự). Chữ giản thể dùng 御.", "Nghĩa Tiếng Việt_Xie": "Hoàng gia", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>御示", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "御", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "示", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "ngữ, ngự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ để chỉ việc phòng ngự hoặc chống lại kẻ thù. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟻', '{"9000": "", "Chữ Trung Quốc": "蟻", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 虫 | Số nét | 19 | nét | 虫 | trùng | biểu nghĩa | côn trùng | 義 | nghĩa | biểu âm | 蟻 = 虫 (Trùng, biểu nghĩa: côn trùng) + 義 (Nghĩa, biểu âm); chữ hình thanh. Phần 虫 cho biết đây là côn trùng, phần 義 cho âm đọc gốc (yǐ).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 蟻 là chữ hình thanh: 虫 (trùng, biểu nghĩa côn trùng) + 義 (nghĩa, biểu âm). Chỉ con kiến — loài côn trùng sống bầy đàn. Wiktionary xác nhận cấu trúc psc rõ ràng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trùng (143) Nghĩa (728)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trùng (số 143 - sâu bọ/ 虫 /chỉ ý) ở bên trái chữ Nghĩa (số 728 - tình nghĩa/ 義 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nghĩa chỉ âm, bộ Trùng chỉ ý. Nghị là tên loài kiến sống tụ tập thành bầy đàn đông đúc (con kiến).", "Nghĩa Tiếng Việt_Xie": "con kiến", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫義", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "義", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚁", "Unihan_Traditional (Chữ Phồn thể)": "蟻", "Pinyin_Xie": "yǐ", "Âm Hán Việt_Xie": "nghĩa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con kiến hoặc dùng để tự xưng một cách khiêm tốn thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陣', '{"9000": "", "Chữ Trung Quốc": "陣", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 阜 | Số nét | 9 | nét | 東 | đông | biểu nghĩa | bao tải? (thành phần cổ, nghĩa gốc chưa rõ) | 攴 | phốc | biểu nghĩa | hành động đánh, gõ | 陣 bắt nguồn từ 敶, cấu trúc hội ý: 東 (x2) + 攴 (Phốc — hành động đánh). Sau đó một 東 bị rút gọn và thêm 阜 (bộ đất/đồi) bên trái. Wiktionary xác nhận ls=ic (hội ý) cho dạng gốc. Nghĩa: đội hình chiến trận.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Lục thư thông | 陣 bắt nguồn từ 敶 — hội ý: hai 東 (nghi là hình bao tải hoặc vật gì đó) + 攴 (tay cầm vũ khí đánh). Sau đó một 東 bị rút gọn, thêm 阜 (đất nổi cao — gợi địa hình quân sự) bên trái thành 陣. Nghĩa: trận địa, đội hình; cũng dùng làm lượng từ (một trận mưa, một cơn gió). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phụ (170) Xa (159)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Phụ (số 170 - đống đất/ 阝 /chỉ ý) ở bên trái bộ Xa (số 159 - xe cộ/ 車 /chỉ âm). Xe và quân lính được bố trí ở những nơi địa hình hiểm yếu đồi núi để tạo thành thế trận. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Trận là đội ngũ, hàng lối quân lính đóng ở chiến trường (trận chiến, trận đồ, lâm trận).", "Nghĩa Tiếng Việt_Xie": "trận đánh; trận, cơn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝車", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "車", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "阵", "Unihan_Traditional (Chữ Phồn thể)": "陣", "Pinyin_Xie": "zhèn", "Âm Hán Việt_Xie": "trận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường dùng làm lượng từ cho các hiện tượng tự nhiên diễn ra trong thời gian ngắn hoặc các cuộc tranh đấu. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豦', '{"9000": "", "Chữ Trung Quốc": "豦", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hô (136) Thỉ (216)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hô (số 136 - vằn vện/hổ/ 虍) ở trên bộ Thỉ (số 216 - con lợn/ 豕). Hình ảnh con hổ và con lợn rừng đang cắn xé vồ đánh nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Cứ vốn là con lợn rừng. Nó cũng mang nghĩa là tranh chấp, cắn xé đánh nhau. Hiện nay chữ này chủ yếu dùng làm thành phần tạo chữ.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虍豕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虍", "Unihan_Simplified (Chữ Giản thể)": "豦", "Unihan_Traditional (Chữ Phồn thể)": "豦", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('據', '{"9000": "", "Chữ Trung Quốc": "據", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Cứ (1490)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Cứ (số 1490 - tranh chấp/ 豦 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cứ (豦) chỉ âm, bộ Thủ chỉ ý. Cứ là dùng tay bám lấy, chiếm giữ làm chỗ nương tựa (chiếm cứ). Từ đó mở rộng thành chứng cớ, dựa vào, căn cứ (căn cứ, bằng cứ, cứ liệu).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌豦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觸', '{"9000": "", "Chữ Trung Quốc": "觸", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 角 | Số nét | 20 | nét | 角 | giác | biểu nghĩa | sừng | 蜀 | thục | biểu âm | nước Thục, con tằm | 觸 = 角 (Giác, biểu nghĩa: sừng) + 蜀 (Thục, biểu âm); chữ hình thanh. Bộ 角 chỉ đây liên quan đến húc, đâm bằng sừng; 蜀 cho âm đọc chù.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Đại triện | Tiểu triện | 觸 là chữ hình thanh: 角 (giác, sừng) biểu nghĩa, 蜀 (thục) biểu âm. Theo Wiktionary, nghĩa gốc là húc (dùng sừng đâm), sau mở rộng sang chạm vào, sờ vào, xúc phạm. Kim văn, đại triện và tiểu triện xác nhận dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Giác (265) Thục (1114)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Giác (số 265 - cái sừng/ 角 /chỉ ý) ở bên trái chữ Thục (số 1114 - con sâu/con tằm/ 蜀 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Xúc là dùng sừng để húc, đâm vào nhau (xúc giác). Mở rộng là đụng chạm, tiếp xúc, cảm nhận được (tiếp xúc, xúc động, xúc phạm).", "Nghĩa Tiếng Việt_Xie": "húc, đâm; chạm vào, sờ vào; cảm động; xúc phạm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角蜀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蜀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "触", "Unihan_Traditional (Chữ Phồn thể)": "觸", "Pinyin_Xie": "chù", "Âm Hán Việt_Xie": "xúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành vi tiếp xúc vật lý hoặc tác động làm thay đổi trạng thái tâm lý. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐮', '{"9000": "", "Chữ Trung Quốc": "鐮", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 21 | nét | 金 | kim | biểu nghĩa | kim loại | 廉 | liêm | biểu âm | liêm khiết (cho âm lián) | 鐮 = 金 (Kim, biểu nghĩa: kim loại) + 廉 (Liêm, biểu âm); chữ hình thanh. Kim loại 金 chỉ vật bằng sắt; 廉 cho âm lián gần liàn/lián.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 鐮 là chữ hình thanh: 金 (kim loại) biểu nghĩa, 廉 biểu âm. Nghĩa là liềm — dụng cụ gặt hái hình lưỡi cong bằng kim loại. Wiktionary xác nhận cấu trúc psc rõ ràng. Dạng giản thể là 镰. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (069) Liêm (601)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 069 - kim loại/ 金 /chỉ ý) ở bên trái chữ Liêm (số 601 - liêm khiết/ 廉 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Liêm (廉) chỉ âm, bộ Kim chỉ ý. Liêm là nông cụ làm bằng kim loại sắt thép để cắt lúa, cắt cỏ (cái liềm).", "Nghĩa Tiếng Việt_Xie": "liềm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金廉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "liềm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ công cụ lao động dùng để gặt lúa hoặc cắt cỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('曬', '{"9000": "", "Chữ Trung Quốc": "曬", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhật (072) Lệ (1032)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhật (số 072 - mặt trời/ 日 /chỉ ý) ở bên trái chữ Lệ (số 1032 - tươi đẹp/ 麗 /chỉ âm). Dưới ánh nắng rực rỡ mặt trời. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Lệ chỉ âm, bộ Nhật chỉ ý. Sái là sự chiếu sáng bộc lộ ra ngoài của nắng mặt trời, phơi nắng (sái kiền - phơi khô). (Chữ giản thể là 晒).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日麗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "麗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紛', '{"9000": "", "Chữ Trung Quốc": "紛", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 10 | nét | 糸 | mịch | biểu nghĩa | tơ, sợi chỉ | 分 | phân | biểu âm | chia ra, phân tách | 紛 = 糸 (Mịch, biểu nghĩa: tơ sợi) + 分 (Phân, biểu âm). Chữ hình thanh (ls=psc): 糸 gợi hình ảnh sợi tơ rối rắm, 分 cho âm. Nghĩa: hỗn loạn, rối ren, đông đảo.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Triện thư | 紛 là chữ hình thanh: 糸 (mịch — tơ sợi) biểu nghĩa, 分 (phân) biểu âm. Hình ảnh sợi tơ phân tán rối rắm → nghĩa \"hỗn loạn, rối ren\". Cũng nghĩa đông đảo, nhiều. Wiktionary xác nhận cấu tạo psc. Bigseal và seal script có trong dữ liệu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Phân (268)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái chữ Phân (số 268 - chia cắt/ 分 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Phân chỉ âm, bộ Mịch chỉ ý. Phân là cuộn tơ bị chia cắt đứt gãy lộn xộn. Từ đó mang ý nghĩa là rắc rối, rối loạn, tơi bời (phân vân,紛 tranh, nhao phân).", "Nghĩa Tiếng Việt_Xie": "cuộc náo loạn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "纷", "Unihan_Traditional (Chữ Phồn thể)": "紛", "Pinyin_Xie": "fēn", "Âm Hán Việt_Xie": "phân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm tính từ miêu tả trạng thái hỗn loạn hoặc làm phó từ đứng trước động từ để chỉ sự việc xảy ra dồn dập. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覓', '{"9000": "", "Chữ Trung Quốc": "覓", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 見 | Số nét | 11 | nét | 爪 | trảo | biểu nghĩa | tay, bàn tay tìm kiếm | 見 | kiến | biểu nghĩa | nhìn, thấy | 覓 = 爪 (Trảo, tay/móng vuốt tìm kiếm) + 見 (Kiến, biểu nghĩa: nhìn, thấy); chữ hội ý. Tay đưa ra tìm kiếm + mắt nhìn = tìm kiếm, mò mẫm.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | 覓 là chữ hội ý, ghép 爪 (trảo, tay/móng vuốt tìm kiếm) với 見 (kiến, nhìn, thấy). Ý nghĩa: dùng tay mò mẫm trong khi mắt dõi tìm — nghĩa là tìm kiếm, mò. Theo Wiktionary. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trảo (148) Kiến (147)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trảo (số 148 - móng vuốt/bàn tay/ 爫) ở trên chữ Kiến (số 147 - nhìn/ 見). Vừa dùng tay moi móc, vừa dùng mắt nhìn ngó tìm kiếm vật. Giải thích sự chuyển ý: Đây là chữ Hội ý. Mịch là tìm tòi, tìm kiếm, vạch ra để tìm (tìm mịch, tầm mịch).", "Nghĩa Tiếng Việt_Xie": "tìm kiếm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>爫見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "見", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "爫", "Unihan_Simplified (Chữ Giản thể)": "觅", "Unihan_Traditional (Chữ Phồn thể)": "覓", "Pinyin_Xie": "mì", "Âm Hán Việt_Xie": "mịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động tìm kiếm, thường làm vị ngữ trong câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘗', '{"9000": "", "Chữ Trung Quốc": "嘗", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thượng (1453) Chỉ (146)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thượng (số 1453/ 尚 /chỉ âm) ở trên chữ Chỉ (số 146 - ý ngon/ 旨 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Thường là nếm thử mùi vị thức ăn (nếm thường). Nghĩa khác là đã từng, từng trải qua một việc gì đó.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>龸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "尝", "Unihan_Traditional (Chữ Phồn thể)": "嘗", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('奐', '{"9000": "", "Chữ Trung Quốc": "奐", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (009) Đại (035)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Nhân (𠂊 - hình người), chữ Tứ (罒 - 4 phương trời) và chữ Đại (số 035 - to lớn/ 大). Người có hiểu biết bao quát cả 4 phương thì thực là to lớn. Giải thích sự chuyển ý: Đây là chữ Hội ý. Hoán là sự thịnh vượng, lớn lao, đẹp đẽ rực rỡ văn vẻ (mỹ hoán, luân hoán).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>大", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "奂", "Unihan_Traditional (Chữ Phồn thể)": "奐", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喚', '{"9000": "", "Chữ Trung Quốc": "喚", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030) Hoán (1505)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 030 - cái miệng/ 口 /chỉ ý) ở bên trái chữ Hoán (số 1505/ 奐 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hoán (奐) chỉ âm, bộ Khẩu chỉ ý. Hoán là mở to miệng kêu lên, gọi (hô hoán, hoán gọi).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口奐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唤", "Unihan_Traditional (Chữ Phồn thể)": "喚", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('㶳', '{"9000": "", "Chữ Trung Quốc": "㶳", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Duật (278) Hỏa (085)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Duật (số 278 - cây bút/ 聿) ở trên bộ Hỏa (số 085 - ngọn lửa/ 火). Gỗ bị đốt dưới ngọn lửa. Giải thích sự chuyển ý: Tẫn vốn là phần gỗ còn dư lại sau khi bị cháy sém, củi tàn, than củi.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>聿火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "火", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "聿", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盡', '{"9000": "", "Chữ Trung Quốc": "盡", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 皿 | Số nét | 14 | nét | 聿 | duật | biểu nghĩa | tay cầm bút | 灬 | biểu nghĩa | lông bàn chải | 皿 | mãnh | biểu nghĩa | cái đĩa, bát | 盡 là chữ hội ý: 聿 (tay cầm bàn chải) + 灬 (lông bàn chải) + 皿 (cái bát) — hình ảnh dùng bàn chải lau sạch cái bát, ý nghĩa cạn kiệt, hết sạch.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | 盡 là chữ hội ý gồm 聿 (tay cầm bàn chải) + 灬 (lông bàn chải) + 皿 (bát đĩa) — mô tả hành động lau sạch bát, từ đó có nghĩa rỗng hết, cạn kiệt. Có đủ dạng từ giáp cốt, kim văn, đại triện đến tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tẫn (1507) Mãnh (107)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tẫn (số 1507 - tro tàn/ 㶳 /chỉ âm) ở trên bộ Mãnh (số 107 - cái chậu/ 皿 /chỉ ý). Mọi thứ trong chậu đã bị đốt thành tro. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Tận là trống rỗng không còn gì, cạn kiệt, hết sạch (tận cùng, tận lực, tiêu tận).", "Nghĩa Tiếng Việt_Xie": "khí thải", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "jǐn", "Âm Hán Việt_Xie": "tan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Phó từ | 副词 | Chữ này làm phó từ đứng trước động từ để chỉ mức độ cao nhất hoặc làm động từ chỉ sự kết thúc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疒', '{"9000": "", "Chữ Trung Quốc": "疒", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tường (204) Nhân (009)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tường (số 204 - cái giường/ 爿) kết hợp với chữ Nhân (số 009 - con người/ 亻). Hình ảnh người đang nằm vật ra giường. Giải thích sự chuyển ý: Đây là chữ Hội ý. Nạch là con người bị ốm đau, bệnh tật nên phải nằm liệt giường. Đây là bộ thủ thứ 104 trong Khang Hy (bộ Nạch 疒).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亠广", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "广", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亠", "Unihan_Simplified (Chữ Giản thể)": "疒", "Unihan_Traditional (Chữ Phồn thể)": "疒", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貪', '{"9000": "", "Chữ Trung Quốc": "貪", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 11 | nét | 今 | kim | biểu âm | miệng há, âm hiện tại | 貝 | bối | biểu nghĩa | tiền, của cải | 貪 = 今 (Kim, biểu âm; gợi miệng há) + 貝 (Bối, biểu nghĩa: tiền/của cải); chữ hình thanh, cũng có thể đọc là hội ý: miệng há (今) chực vơ tiền (貝).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 貪 là chữ hình thanh: 貝 (bối, tiền/của cải) biểu nghĩa, 今 (kim) biểu âm; đồng thời có thể hiểu là hội ý: miệng há chực lấy tiền. Nghĩa là tham lam, ham muốn của cải. Lưu ý: Wiktionary ghi cả ls=psc và ls2=ic. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (556) Bối (154)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Kim (số 556 - ngày nay/ 今) ở trên bộ Bối (số 154 - tiền bạc/ 貝). Ngày nay tiền bạc là thứ mà ai cũng ham muốn có được. Giải thích sự chuyển ý: Đây là chữ Hội ý. Tham là ham muốn quá mức, khao khát có được, không biết chán (tham lam, tham vọng).", "Nghĩa Tiếng Việt_Xie": "Tham", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>今貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "今", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "贪", "Unihan_Traditional (Chữ Phồn thể)": "貪", "Pinyin_Xie": "tān", "Âm Hán Việt_Xie": "tham", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ đứng trước danh từ chỉ đối tượng bị ham muốn hoặc làm tính từ bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('櫻', '{"9000": "", "Chữ Trung Quốc": "櫻", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Anh (1222)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây cối/ 木 /chỉ ý) ở bên trái chữ Anh (số 1222 - trẻ sơ sinh/ 嬰 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Anh (嬰) chỉ âm, bộ Mộc chỉ ý. Anh là tên cây hoa đào Nhật (hoa anh đào).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木嬰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "嬰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "樱", "Unihan_Traditional (Chữ Phồn thể)": "櫻", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漿', '{"9000": "", "Chữ Trung Quốc": "漿", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tương (1273) Thủy (082)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tương (số 1273 - sắp sửa/將 /chỉ âm) ở trên bộ Thủy (số 082 - nước/ 水 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tương chỉ âm, bộ Thủy chỉ ý. Tương là các loại chất lỏng hơi sền sệt được vắt ra từ quả cây, hồ bột (hồ tương, tương quả).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>將水", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "將", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "水", "Unihan_Simplified (Chữ Giản thể)": "浆", "Unihan_Traditional (Chữ Phồn thể)": "漿", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('極', '{"9000": "", "Chữ Trung Quốc": "極", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Cức (1519)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây cối/gỗ/ 木 /chỉ ý) ở bên trái chữ Cức (số 1519 - vội vàng/ 亟 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cức chỉ âm, bộ Mộc chỉ ý. Cực vốn chỉ cái cột làm bằng gỗ, cái nóc nhà. Về sau mang ý nghĩa là chỗ cao nhất, điểm xa nhất, chỗ tận cùng (đỉnh cực, thái cực, vô cực).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木亟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "极", "Unihan_Traditional (Chữ Phồn thể)": "極", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('墜', '{"9000": "", "Chữ Trung Quốc": "墜", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Đội (986) Thổ (032)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Đội (số 986 - hàng lối/ 隊 /chỉ âm) ở trên bộ Thổ (số 032 - đất/ 土 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đội chỉ âm, bộ Thổ chỉ ý. Trụy là rơi rụng, ngã rớt xuống đất (sa trụy, suy trụy).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>隊土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坠", "Unihan_Traditional (Chữ Phồn thể)": "墜", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詳', '{"9000": "", "Chữ Trung Quốc": "詳", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 13 | nét | 言 | ngôn | biểu nghĩa | lời nói | 羊 | dương | biểu âm | con cừu | 詳 = 言 (Ngôn, biểu nghĩa: lời nói) + 羊 (Dương, biểu âm); chữ hình thanh. Bộ 言 chỉ đây liên quan đến lời nói, diễn đạt; 羊 cho âm đọc xiáng. Chữ mang nghĩa giải thích tường tận, chi tiết.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | 詳 là chữ hình thanh: 言 (ngôn, lời nói) biểu nghĩa, 羊 (dương, cừu) biểu âm. Theo Wiktionary, nghĩa là chi tiết, đầy đủ, tường tận; cũng có nghĩa bình tĩnh, thư thái (an詳). Tiểu triện và Lục thư thông xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Dương (123)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Dương (số 123 - con dê/ 羊 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Dương chỉ âm, bộ Ngôn chỉ ý. Tường là lấy lời nói để bàn luận, xem xét kỹ càng từng chi tiết nhỏ (tường tận, rõ tường, chi tiết).", "Nghĩa Tiếng Việt_Xie": "rõ ràng, tường tận", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言羊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "详", "Unihan_Traditional (Chữ Phồn thể)": "詳", "Pinyin_Xie": "xiáng", "Âm Hán Việt_Xie": "tường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ hoặc làm động từ với nghĩa giải thích cặn kẽ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釋', '{"9000": "", "Chữ Trung Quốc": "釋", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 釆 | Số nét | 20 | nét | 釆 | biện | biểu nghĩa | phân biệt, nhận ra | 睪 | dịch | biểu âm | phóng thích, nhìn thấy | 釋 là chữ hội ý kết hợp hình thanh: Wiktionary ghi ls=ic (hội ý) với ls2=psc (hình thanh). Bộ 釆 (biện, phân biệt) biểu nghĩa và 睪 (dịch, phóng thích/nhìn thấy) cả biểu nghĩa lẫn biểu âm. Trong kim văn thường viết tắt là 睪. Tiểu triện và lục thư thông còn lưu.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | 釋 (thích/shì) là chữ hội ý kiêm hình thanh: 釆 (phân biệt) + 睪 (phóng thích; nhìn thấy). Nghĩa gốc: nhận biết và giải phóng — từ đó suy ra hai nghĩa chính: (1) giải thích, làm rõ; (2) phóng thích, tha. Trong kim văn thường viết là 睪. Tiểu triện và lục thư thông đều còn lưu dạng chữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Biện (165) Dịch (1367)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Biện (số 165 - phân biệt/ 釆 /chỉ ý) ở bên trái chữ Dịch (số 1367 - nhìn ngó/ 睪 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Chữ Dịch chỉ âm, bộ Biện chỉ ý. Thích là lấy lời lẽ giảng giải phân biệt rạch ròi cho người ta hiểu (giải thích, chú thích). Từ đó mang nghĩa là cởi bỏ, tha ra (thích phóng).", "Nghĩa Tiếng Việt_Xie": "giải thích", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰釆睪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "釆", "Unihan_Simplified (Chữ Giản thể)": "释", "Unihan_Traditional (Chữ Phồn thể)": "釋", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thích, dịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động giải thích, phóng thích hoặc danh từ chỉ họ Thích của Phật giáo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禿', '{"9000": "", "Chữ Trung Quốc": "禿", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 禾 | Số nét | 7 | nét | 毛 | mao | biểu nghĩa | tóc, lông | 儿 | nhân | biểu nghĩa | người | 禿 = 毛 (Mao: tóc/lông) + 儿 (Nhân: người); chữ hội ý. Người (儿) không có tóc (毛) — hình ảnh đầu trọc. Lưu ý: 毛 về sau biến dạng thành 禾 trong dạng hiện đại, nhưng nguyên gốc là người + tóc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Theo Wiktionary, 禿 là chữ hội ý: 毛 (tóc) + 儿 (người). Người mà không có tóc. Phần 毛 sau bị biến dạng thành 禾 trong quá trình phát triển chữ viết, nhưng ý nghĩa gốc là \"người trọc đầu\". Nghĩa mở rộng: cùn, cụt (bút lông hết lông = cùn như đầu trọc). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hòa (115) Nhân (010)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hòa (số 115 - cây lúa/ 禾) ở trên bộ Nhân đi (số 010 - con người/ 儿). Hình ảnh người nông dân đội bó lúa mới gặt đi về nhà, cánh đồng sẽ trở nên trống trải, trọc lốc. Giải thích sự chuyển ý: Đây là chữ Hội ý. Thốc (ngốc) là không có tóc, trụi lông, hói đầu (thốc đầu).", "Nghĩa Tiếng Việt_Xie": "trọc, trụi, hói; cùn, cụt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>禾儿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "儿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秃", "Unihan_Traditional (Chữ Phồn thể)": "禿", "Pinyin_Xie": "tū", "Âm Hán Việt_Xie": "thốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để miêu tả trạng thái không có tóc, lá hoặc bị mòn cùn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輕', '{"9000": "", "Chữ Trung Quốc": "輕", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 車 | Số nét | 14 | nét | 車 | xa | biểu nghĩa | xe ngựa, xe kéo | 巠 | biểu âm | 輕 = 車 (Xa, biểu nghĩa: xe kéo nhẹ) + 巠 (biểu âm, cho âm qīng/khinh); chữ hình thanh. Nghĩa gốc là xe ngựa nhỏ, nhẹ (xe trận bỏ bớt đồ nặng); từ đó mở rộng sang nghĩa ''nhẹ, không nặng''.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 輕 (Hán-Việt: khinh, đọc qīng) gốc là chữ hình thanh: 車 (xa, xe ngựa) biểu nghĩa, 巠 cho âm. Nghĩa ban đầu là xe kéo nhẹ — loại xe chiến đấu bỏ bớt trang bị để di chuyển nhanh; từ đó phát triển nghĩa ''nhẹ, dễ dàng, không đáng kể''. Tiểu triện ghi nhận dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xa (159) Kinh (996)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xa (số 159 - xe cộ/ 車 /chỉ ý) ở bên trái chữ Kinh (số 996 - đường chỉ thẳng/ 巠 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Kinh chỉ âm, bộ Xa chỉ ý. Khinh vốn là cái xe chạy nhẹ và nhanh chóng. Từ đó mở rộng nghĩa là nhẹ, khối lượng nhỏ gọn (khinh khí). Nghĩa khác là coi thường, không coi trọng (khinh bỉ, khinh thường).", "Nghĩa Tiếng Việt_Xie": "ánh sáng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車巠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "轻", "Unihan_Traditional (Chữ Phồn thể)": "輕", "Pinyin_Xie": "qīng", "Âm Hán Việt_Xie": "khánh, khinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Phó từ | 副词 | Thường làm tính từ đứng trước danh từ hoặc làm phó từ đứng trước động từ để chỉ mức độ nhẹ nhàng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趙', '{"9000": "", "Chữ Trung Quốc": "趙", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 走 | Số nét | 14 | nét | 走 | tẩu | biểu nghĩa | chạy, đi nhanh | 肖 | tiêu | biểu âm | (cho âm zhào) | 趙 = 走 (Tẩu, biểu nghĩa: chạy/đi nhanh) + 肖 (Tiêu, biểu âm); chữ hình thanh. Phần 走 gợi ý nghĩa di chuyển/vùng đất; phần 肖 cho âm zhào. Chữ truyền thống (giản thể là 赵), chủ yếu dùng là quốc danh (nước Triệu) và họ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Wiktionary phân tích: 趙 là chữ hình thanh (psc) gồm 走 (tẩu, biểu nghĩa: chạy) + 肖 (tiêu, biểu âm). Nghĩa gốc: tên nước Triệu (một trong Thất Hùng thời Chiến Quốc). Sau dùng làm họ Triệu (Zhao). Cũng có nghĩa \"trả lại\". Chữ truyền thống, giản thể là 赵. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tẩu (156) Tiếu (634)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tẩu (số 156 - chạy/ 走 /chỉ ý) bao bên ngoài chữ Tiếu (số 634 - giống nhau/ 肖 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tiếu chỉ âm, bộ Tẩu chỉ ý. Triệu là sự chạy mau, chạy nhanh (triệu bộ). Cũng là một họ của người (họ Triệu) hoặc tên nước thời Chiến Quốc (nước Triệu).", "Nghĩa Tiếng Việt_Xie": "họ Triệu; nước Triệu; trả lại", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "赵", "Unihan_Traditional (Chữ Phồn thể)": "趙", "Pinyin_Xie": "zhào", "Âm Hán Việt_Xie": "triệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này chủ yếu dùng làm danh từ riêng chỉ họ người hoặc tên nước thời Chiến Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('達', '{"9000": "", "Chữ Trung Quốc": "達", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 12 | nét | 辶 | xước | biểu nghĩa | di chuyển, đi đường | 羍 | đạt | biểu âm | (âm) | 達 = 辶 (Xước, biểu nghĩa: di chuyển, đi đường) + 羍 (biểu âm); chữ hình thanh. Wiktionary lưu ý: thành phần bên trong không phải 幸 (hạnh) — có thêm một nét ngang, không liên quan. Bộ Xước chỉ sự di chuyển tới đích.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Lục thư thông | 達 là chữ hình thanh: 辶 (xước: đi đường) biểu nghĩa, 羍 biểu âm. Wiktionary ghi chú quan trọng: phần bên trong là 羍 (không phải 幸) — có ba nét ngang ở dưới, không hai. Nghĩa gốc là ''đi thông suốt, đạt tới đích''. Dạng kim văn và lục thư thông còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Thổ (032) Dương (123)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi/ 辶 /chỉ ý) bao quanh chữ Đạt (羍 - con dê non / gồm Thổ 土 ở trên Dương 羊 /chỉ âm). Bước đi một cách nhẹ nhàng như con dê con. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đạt (羍) chỉ âm, bộ Xước chỉ ý. Đạt là làm cho xong, hoàn thành viên mãn mục tiêu (thành đạt, đạt tới, thông đạt).", "Nghĩa Tiếng Việt_Xie": "với tới", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶垟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "达", "Unihan_Traditional (Chữ Phồn thể)": "達", "Pinyin_Xie": "dá", "Âm Hán Việt_Xie": "đạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ biểu thị việc đi đến nơi hoặc đạt được mục đích, tiêu chuẩn nào đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('織', '{"9000": "", "Chữ Trung Quốc": "織", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 18 | nét | 糸 | mịch | biểu nghĩa | tơ, sợi | 戠 | biểu âm | 織 = 糸 (Mịch, biểu nghĩa: tơ, sợi) + 戠 (biểu âm). Chữ hình thanh: 糸 liên quan đến sợi tơ/dệt, 戠 cho âm đọc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Đại triện | Tiểu triện | 織 là chữ hình thanh: 糸 (tơ) biểu nghĩa, 戠 biểu âm. Nghĩa gốc là dệt vải từ sợi tơ. Mở rộng: tổ chức (組織), dệt nên. Wiktionary xác nhận cấu trúc psc. Thấy trong giáp cốt văn, đại triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Thức (1369)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái chữ Thức (số 1369 - dấu hiệu/ 戠 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thức (戠) chỉ âm, bộ Mịch chỉ ý. Chức là công việc dệt vải, dệt lụa, dùng các sợi tơ kết đan lại với nhau (chức nữ, tổ chức).", "Nghĩa Tiếng Việt_Xie": "dệt vải", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "织", "Unihan_Traditional (Chữ Phồn thể)": "織", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ, thường đứng trước danh từ làm tân ngữ như dệt vải, dệt áo hoặc dệt nên ước mơ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夃', '{"9000": "", "Chữ Trung Quốc": "夃", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nãi (1524) Hựu (029)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hựu (số 029 - cái tay/ 又) được bao bọc trong chữ Nãi (số 1524 - nối tiếp/ 乃). Giải thích sự chuyển ý: Đây là chữ Hội ý. Hình ảnh bàn tay vơ lấy vật nối tiếp nhau, vơ lấy nhiều đồ vật mang về. Cô là mua bán nhiều đồ ở ngoài chợ, bán buôn để kiếm lời.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴乃又", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "又", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紋', '{"9000": "", "Chữ Trung Quốc": "紋", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 10 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, chỉ | 文 | văn | biểu âm | văn chương, hoa văn | 紋 = 糸 (Mịch, biểu nghĩa: sợi tơ/chỉ) + 文 (Văn, biểu âm: cho âm wén); chữ hình thanh. Ban đầu là chuyên biệt hoá từ 文, chỉ đường kẻ của sợi chỉ, sau mở rộng thành mẫu hoa văn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Chữ hình thanh, tách ra từ 文 (văn): 糸 (mịch) biểu nghĩa chỉ sợi tơ, 文 biểu âm. Wiktionary xác nhận: 紋 là chữ chuyên hoá từ 文, ban đầu chỉ đường vân của sợi tơ, sau chỉ mọi loại hoa văn, đường vân, mẫu. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Văn (189)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái bộ Văn (số 189 - nét hoa văn/ 文 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Văn chỉ âm, bộ Mịch chỉ ý. Văn là các đường vân nếp nhăn trên lụa tơ. Từ đó dùng để chỉ các nét hoa văn trang trí, nếp nhăn, vằn vện (hoa văn, vân tay).", "Nghĩa Tiếng Việt_Xie": "mẫu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "文", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "纹", "Unihan_Traditional (Chữ Phồn thể)": "紋", "Pinyin_Xie": "wén", "Âm Hán Việt_Xie": "văn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ chất liệu để chỉ đường nét trên bề mặt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳳', '{"9000": "", "Chữ Trung Quốc": "鳳", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 鳥 | Số nét | 14 | nét | 凡 | phàm | biểu âm | cung cấp âm fèng/phụng | 鳥 | điểu | biểu nghĩa | chim | 鳳 = 凡 (Phàm, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim); chữ hình thanh. Trong giáp cốt và kim văn, 鳳 ban đầu được mượn âm để viết 風 (gió); sau đó 風 tự tách ra thành chữ riêng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | 鳳 là chữ hình thanh, ghép 凡 (phàm, biểu âm) với 鳥 (điểu, chim, biểu nghĩa). Trong giáp cốt văn, tự dạng 鳳 thường được mượn để viết 風 (gió); về sau 風 phát triển độc lập từ phần kim văn của 鳳. Nghĩa chính: phượng hoàng đực trong thần thoại Trung Hoa, biểu tượng của niềm vui và điềm lành. Theo Wiktionary. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phàm (066) Điểu (196)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Phàm (số 066 - cái buồm/bình thường/ 凡 /chỉ âm) bao bọc lấy bộ Điểu (số 196 - con chim/ 鳥 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Phàm chỉ âm, bộ Điểu chỉ ý. Phượng là tên một loài chim thần thoại biểu tượng cho cái đẹp và người phụ nữ cao quý (chim phượng hoàng).", "Nghĩa Tiếng Việt_Xie": "Phượng hoàng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴几𩾏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𩾏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "几", "Unihan_Simplified (Chữ Giản thể)": "凤", "Unihan_Traditional (Chữ Phồn thể)": "鳳", "Pinyin_Xie": "fèng", "Âm Hán Việt_Xie": "phượng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loài chim phượng hoàng, biểu tượng của sự cao quý và tốt lành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驟', '{"9000": "", "Chữ Trung Quốc": "驟", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 馬 | Số nét | 24 | nét | 馬 | mã | biểu nghĩa | ngựa | 聚 | tụ | biểu âm | 驟 = 馬 (Mã, biểu nghĩa: ngựa) + 聚 (Tụ, biểu âm); chữ hình thanh. Bộ Mã gợi tốc độ và sức mạnh ngựa phi nước đại, phần 聚 cho âm đọc zhòu.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Chữ hình thanh: 馬 (ngựa, biểu nghĩa) + 聚 (biểu âm). 驟 nghĩa gốc là ''phi nước đại, chạy nhanh''; từ đó mở rộng thành ''đột ngột, bất ngờ''. Bộ Mã phản ánh tốc độ vũ bão — ngựa phi nhanh như cơn mưa rào ập đến. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mã (187) Tụ (1543)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mã (số 187 - con ngựa/ 馬 /chỉ ý) ở bên trái chữ Tụ (số 1543 - hợp lại/ 聚 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tụ chỉ âm, bộ Mã chỉ ý. Sậu là hành động ngựa phi nước đại, chạy rất nhanh. Từ đó diễn tả sự việc xảy đến bất ngờ, vùn vụt, hốt nhiên (sậu vũ - mưa rào bất chợt).", "Nghĩa Tiếng Việt_Xie": "bước chân", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬聚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "聚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "骤", "Unihan_Traditional (Chữ Phồn thể)": "驟", "Pinyin_Xie": "zhòu", "Âm Hán Việt_Xie": "sậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Thường làm phó từ đứng trước động từ để chỉ hành động xảy ra một cách đột ngột. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('濁', '{"9000": "", "Chữ Trung Quốc": "濁", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Thục (1114)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước/ 氵/chỉ ý) ở bên trái chữ Thục (số 1114 - con sâu/ 蜀 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thục chỉ âm, bộ Thủy chỉ ý. Trọc là dòng nước có lẫn nhiều tạp chất không trong sạch (vẩn đục, trong trọc). Mở rộng ra là sự không rõ ràng thanh sạch (trọc khí).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵蜀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蜀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浊", "Unihan_Traditional (Chữ Phồn thể)": "濁", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('燒', '{"9000": "", "Chữ Trung Quốc": "燒", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hỏa (085) Nghiêu (973)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hỏa (số 085 - ngọn lửa/ 火 /chỉ ý) ở bên trái chữ Nghiêu (số 973 - đế Nghiêu/cao/ 堯 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nghiêu chỉ âm, bộ Hỏa chỉ ý. Thiêu là dùng ngọn lửa lớn để đốt cháy (thiêu rụi, thiêu hủy, hỏa thiêu).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火堯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烧", "Unihan_Traditional (Chữ Phồn thể)": "燒", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('慮', '{"9000": "", "Chữ Trung Quốc": "慮", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hổ (136) Tư (350)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hổ (số 136 - con hổ/ 虍) ở trên chữ Tư (số 350 - suy tư/ 思). Giải thích sự chuyển ý: Lự là sự nghĩ ngợi kỹ càng, lo lắng sâu xa trong lòng, e ngại (tư lự, lo lự, suy lự).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虍思", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "思", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虍", "Unihan_Simplified (Chữ Giản thể)": "虑", "Unihan_Traditional (Chữ Phồn thể)": "慮", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盧', '{"9000": "", "Chữ Trung Quốc": "盧", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hổ (136) Điền (097) Mãnh (107)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hổ (số 136/ 虍) ở trên chữ Điền (số 097/ 田) và bộ Mãnh (số 107 - cái chậu/ bát/ 皿). Giải thích sự chuyển ý: Lư vốn là cái bát lớn, đồ dùng để đựng cơm. Ngày nay chữ Lư hay được dùng làm Tên họ (họ Lư).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𧆨皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𧆨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "卢", "Unihan_Traditional (Chữ Phồn thể)": "盧", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('爐', '{"9000": "", "Chữ Trung Quốc": "爐", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hỏa (085) Lư (1559)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hỏa (số 085 - ngọn lửa/ 火 /chỉ ý) ở bên trái chữ Lư (số 1559 - bát cơm/ 盧 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Lư (盧) chỉ âm, bộ Hỏa chỉ ý. Lư là cái lò bằng đất đá để đun nấu, lò sưởi, hỏa lò (lò bát quái, hương lư - bát hương).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火盧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炉", "Unihan_Traditional (Chữ Phồn thể)": "爐", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耤', '{"9000": "", "Chữ Trung Quốc": "耤", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lỗi (1271) Tích (1561)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Lỗi (số 1271 - cái cày/ 耒 /chỉ ý) ở bên trái chữ Tích (số 1561 - ngày xưa/ 昔 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Tịch là hành động dùng cày để cày ruộng. Thời phong kiến, nhà vua đích thân cày ruộng tế thần Nông để làm gương khuyến khích dân chúng gọi là tịch điền.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒昔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耤", "Unihan_Traditional (Chữ Phồn thể)": "耤", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藉', '{"9000": "", "Chữ Trung Quốc": "藉", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 艸 | Số nét | 17 | nét | 艹 | thảo | biểu nghĩa | cỏ, cây | 耤 | tịch | biểu âm | cày ruộng tịch điền | 藉 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 耤 (Tịch, biểu âm); chữ hình thanh suy luận từ cấu trúc (nguồn Wiktionary không có phân tích chi tiết). Bộ thảo 艹 gợi ý nghĩa chiếu rơm, thảm cỏ; 耤 cho âm đọc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích cấu trúc chi tiết cho 藉. Từ cấu trúc: 艹 (thảo) + 耤 (tịch), có thể là chữ hình thanh với 艹 biểu nghĩa (chiếu cỏ, thảm lót) và 耤 biểu âm. Nghĩa gốc là chiếu, thảm lót bằng cỏ; mở rộng sang nhờ vào, mượn cớ. Chữ tạo muộn so với giáp cốt/kim văn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (140) Tịch (1562)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 140 - cỏ/ 艹 /chỉ ý) ở trên chữ Tịch (số 1562 - cày ruộng/ 耤 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tịch chỉ âm, bộ Thảo chỉ ý. Tịch/Tạ vốn là cái chiếu đan bằng cỏ để dựa vào, đệm cẩn thận. Mở rộng mang nghĩa là mượn nhờ, dựa dẫm vào cái cớ gì đó (bằng tạ, ủy tạ). (Chữ giản thể mượn chữ 借).", "Nghĩa Tiếng Việt_Xie": "nhờ vào, trông cậy vào; vin cớ, mượn cớ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹耤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藉", "Unihan_Traditional (Chữ Phồn thể)": "藉", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "tịch, tạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Giới từ | 介词 | Thường làm động từ chỉ sự nương tựa, mượn cớ hoặc làm giới từ biểu thị phương thức dựa vào đâu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膚', '{"9000": "", "Chữ Trung Quốc": "膚", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 肉 | Số nét | 15 | nét | 肉 | nhục | biểu nghĩa | thịt, cơ thể | 盧 | lư | biểu âm | 膚 = 肉 (Nhục, biểu nghĩa: thịt, cơ thể) + 盧 viết tắt (Lư, biểu âm). Chữ hình thanh: bộ 肉 chỉ lớp bên ngoài cơ thể; 盧 cho âm. Nghĩa gốc: da — lớp phủ bên ngoài thịt.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Theo Wiktionary: 膚 là chữ hình thanh gồm 肉 (biểu nghĩa: thịt) và viết tắt của 盧 (biểu âm). Nghĩa gốc là da — lớp phủ bên ngoài cơ thể. Mở rộng sang nghĩa nông cạn, bề mặt (膚淺). Xuất hiện trong kim văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hổ (136) Vị (1457)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hổ (số 136 - con hổ/vằn vện/ 虍 /chỉ âm) ở trên chữ Vị (số 1457 - dạ dày/thịt/ 胃 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Bộ Hổ (虍) chỉ âm, chữ Vị (胃) chỉ ý. Phu là lớp da thịt bao phủ ở bề ngoài của cơ thể (bì phu). Mở rộng ra là chỉ những thứ ở bề ngoài, nông cạn không sâu sắc (thiển phu).", "Nghĩa Tiếng Việt_Xie": "da", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虍胃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虍", "Unihan_Simplified (Chữ Giản thể)": "肤", "Unihan_Traditional (Chữ Phồn thể)": "膚", "Pinyin_Xie": "fū", "Âm Hán Việt_Xie": "phu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ da của người và động vật, hoặc làm tính từ chỉ sự hời hợt, nông cạn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('誑', '{"9000": "", "Chữ Trung Quốc": "誑", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Cuồng (1467)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Cuồng (số 1467 - điên rồ/ 狂 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cuồng chỉ âm, bộ Ngôn chỉ ý. Cuống là lời nói dối lừa bịp, nói phét, nói xạo, lời nói phóng đại điên rồ không thật (cuống gạt).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言狂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "狂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "诳", "Unihan_Traditional (Chữ Phồn thể)": "誑", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷹', '{"9000": "", "Chữ Trung Quốc": "鷹", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 鳥 | Số nét | 24 | nét | 䧹 | ưng | biểu âm | phần biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鷹 là chữ hình thanh: 䧹 (biểu âm) + 鳥 (Điểu, biểu nghĩa: chim). Chỉ chim ưng/đại bàng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Hình thanh tự: bộ 鳥 biểu nghĩa (chim), 䧹 biểu âm (đọc ưng). Chỉ loài chim ưng — biểu tượng dũng mãnh trong văn hóa Á Đông. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nghiễm (053) Nhân (009) Truy (034) Điểu (196)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bao gồm chữ 䧹 (chim ưng cổ/ Nghiễm 广 + Nhân 亻+ Truy 隹 /chỉ âm) nằm trên bộ Điểu (số 196 - con chim/ 鳥 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Phần 䧹 chỉ âm, bộ Điểu chỉ ý. Ưng là chim ưng, một loài chim săn mồi dũng mãnh thường được huấn luyện để đi săn.", "Nghĩa Tiếng Việt_Xie": "chim cú mèo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴䧹鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䧹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鹰", "Unihan_Traditional (Chữ Phồn thể)": "鷹", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "ưng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng độc lập hoặc làm thành phần trong từ ghép chỉ các loài chim săn mồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('應', '{"9000": "", "Chữ Trung Quốc": "應", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (061)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Ưng giảm nét (số 1571 - giảm thành 䧹 /chỉ âm) nằm trên bộ Tâm (số 061 - trái tim/ 心 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Ưng (䧹) chỉ âm, bộ Tâm chỉ ý. Đọc là Ứng mang nghĩa là phản ứng lại, đáp lại, hiệu nghiệm, thuận theo (phản ứng, ứng nghiệm, đáp ứng). Đọc là Ưng mang nghĩa tỏ sự đồng ý, nên thế, bằng lòng (ưng thuận, ưng ý).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴䧹心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䧹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "应", "Unihan_Traditional (Chữ Phồn thể)": "應", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溼', '{"9000": "", "Chữ Trung Quốc": "溼", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Nhất (001) Yêu (052) Thổ (032)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước/ 氵/chỉ ý) ở bên trái chữ Hiển (㬎 - gồm Nhất 一, hai bộ Yêu 幺 và Thổ 土 /chỉ âm). Mạch nước chảy li ti (幺) dưới lòng mặt đất (一, 土). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Thấp là mặt đất có mạch nước chứa sũng nước, rất ẩm ướt (thấp át, ẩm thấp). (Chữ giản thể là 湿).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵𡌥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𡌥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "湿", "Unihan_Traditional (Chữ Phồn thể)": "溼", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緣', '{"9000": "", "Chữ Trung Quốc": "緣", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 15 | nét | 糹 | mịch | biểu nghĩa | sợi chỉ, dây | 彖 | đoán | biểu âm | 緣 = 糹 (Mịch, biểu nghĩa: sợi chỉ) + 彖 (Đoán, biểu âm); chữ hình thanh. Sợi dây (糹) gợi sự kết nối liên hệ; 彖 cho âm yuán. Nghĩa gốc là mép viền, về sau chỉ nhân duyên, mối liên hệ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 緣 là chữ hình thanh: 糹 (sợi chỉ/dây) biểu nghĩa, 彖 biểu âm. Nghĩa gốc: mép viền của vải (hem/border). Từ hình ảnh dây chỉ bện vào nhau, nghĩa mở rộng sang: nhân duyên, mối liên kết tiền định. Chữ truyền thống, dạng giản thể là 缘. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Thoán (1574)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái chữ Thoán (số 1574 - lời bình/ 彖 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thoán chỉ âm, bộ Mịch chỉ ý. Duyên vốn là đường viền mép quần áo bằng lụa chỉ tơ. Mở rộng mang nghĩa là nguyên cớ, nguyên do, phần kết nối, theo như (nhân duyên, duyên cớ, hữu duyên).", "Nghĩa Tiếng Việt_Xie": "định mệnh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹彖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "缘", "Unihan_Traditional (Chữ Phồn thể)": "緣", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "duyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Giới từ | 介词 | Thường làm danh từ chỉ duyên số hoặc làm giới từ trong văn ngôn mang nghĩa vì, dựa vào. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趨', '{"9000": "", "Chữ Trung Quốc": "趨", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 走 | Số nét | 17 | nét | 走 | tẩu | biểu nghĩa | đi, chạy | 芻 | sô | biểu âm | âm đọc gần qū | 趨 = 走 (Tẩu, biểu nghĩa: đi/chạy) + 芻 (Sô, biểu âm); chữ hình thanh. Bộ 走 cho biết nghĩa liên quan di chuyển, 芻 cung cấp âm đọc qū.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Chữ hình thanh: 走 (đi) biểu nghĩa, 芻 biểu âm. 趨 nghĩa gốc là bước nhanh, dần mở rộng sang xu hướng (大勢所趨) và nịnh hót quyền thế (趨炎附勢). Dạng phồn thể của giản thể 趋. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tẩu (156) Sô (155)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tẩu (số 156 - chạy/ 走 /chỉ ý) bao bên trái chữ Sô (số 155 - cỏ non/ 芻 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Sô chỉ âm, bộ Tẩu chỉ ý. Xu là chạy những bước ngắn mà nhanh, rảo bước vội vã. Nghĩa khác là hướng về, đi theo một chiều nào đó (xu hướng, xu thế).", "Nghĩa Tiếng Việt_Xie": "xu hướng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走芻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "芻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趋", "Unihan_Traditional (Chữ Phồn thể)": "趨", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "xu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ sự hướng tới hoặc danh từ trong từ ghép chỉ xu hướng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撲', '{"9000": "", "Chữ Trung Quốc": "撲", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Bộc (1275)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Bộc (số 1275 - đầy tớ/ 菐 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Bộc chỉ âm, bộ Thủ chỉ ý. Phác là hành động dùng tay đánh, đập, vỗ (vỗ phác). Cũng mang nghĩa bôi, xoa, phủi bụi.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌菐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "菐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "扑", "Unihan_Traditional (Chữ Phồn thể)": "撲", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('傷', '{"9000": "", "Chữ Trung Quốc": "傷", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (009) Dương (360)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhân đứng (số 009/ 亻/chỉ ý), chữ Nhân (𠂉/ 人 /chỉ ý) ở trên bên phải, và chữ Dương (số 360 - mặt trời/ 昜 /chỉ âm). Chữ Nhân này làm đau chữ Nhân kia. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Chữ Dương chỉ âm. Thương là chỗ đau, vết thương tổn hại trên cơ thể (thương tích, bị thương). Nghĩa bóng là đau buồn (bi thương, xót thương).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "伤", "Unihan_Traditional (Chữ Phồn thể)": "傷", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('適', '{"9000": "", "Chữ Trung Quốc": "適", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 14 | nét | 辶 | xước | biểu nghĩa | đi, di chuyển | 啻 | sắc | biểu âm | chỉ, chẳng qua là | 適 = 辶(Xước, biểu nghĩa: đi lại) + 啻 (Sắc, biểu âm; sau được viết thành 啇). Chữ hình thanh — bộ Xước xác định liên quan đến sự di chuyển; phần Sắc biểu âm shì.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 適 là chữ hình thanh: bộ 辵/辶(Xước — đi đường) biểu ý sự di chuyển đến nơi phù hợp; 啻 (Sắc) biểu âm. Nguyên hình là 𨗁, sau nội bộ được viết thành 啇 rồi 啻. Nghĩa gốc: đi đến (nơi phù hợp); phát triển sang \"phù hợp, thích hợp, vừa vặn\". Đây là dạng phồn thể của 适 (giản thể). Chữ phổ biến trong cả văn ngôn lẫn hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Đích (264)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi/ 辶 /chỉ ý) bao quanh chữ Đích (số 264 - gốc gác/ 啇 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đích chỉ âm, bộ Xước chỉ ý. Thích là đi đến vừa đúng lúc, gặp đúng lúc (thích phùng). Nghĩa khác là hòa hợp, vừa vặn, hợp lý (thích hợp, thích nghi).", "Nghĩa Tiếng Việt_Xie": "đang lúc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶啇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "啇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "đích, trích, địch, thích, quát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Phó từ | 副词 | Chữ này làm động từ chỉ sự đi đến hoặc tính từ chỉ sự phù hợp với hoàn cảnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('經', '{"9000": "", "Chữ Trung Quốc": "經", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 13 | nét | 糹 | mịch | biểu nghĩa | sợi tơ, chỉ | 巠 | kinh | biểu âm | 經 = 糹 (Mịch, biểu nghĩa: sợi tơ, chỉ dệt) + 巠 (biểu âm); chữ hình thanh. Phần mịch cho biết nghĩa gốc liên quan đến sợi vải dọc (kinh tuyến trên khung dệt); phần 巠 gợi âm.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Chữ hình thanh: 糹 (sợi tơ) biểu nghĩa, 巠 biểu âm. Nghĩa gốc: sợi chỉ dọc trên khung dệt (kinh tuyến). Từ đó phái sinh: đường thẳng, nguyên tắc cơ bản, kinh điển (kinh sách — văn bản được coi là ''sợi dọc'' định hướng), kinh mạch (đường dọc trong cơ thể), trải qua (đi theo đường). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Kinh (996)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái chữ Kinh (số 996 - đường chỉ thẳng/ 巠 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Kinh (巠) chỉ âm, bộ Mịch chỉ ý. Kinh vốn là những sợi tơ chăng dọc trên khung cửi (sợi kinh, sợi vĩ). Từ đó chỉ sách vở của thánh hiền chép lại đạo lý (kinh sách, Phật kinh). Cũng có nghĩa là đi qua, trải qua (kinh qua, kinh nghiệm).", "Nghĩa Tiếng Việt_Xie": "dây vải; kinh sách; trải qua, chịu đựng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹巠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "经", "Unihan_Traditional (Chữ Phồn thể)": "經", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "kinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Giới từ | 介词 | Thường làm danh từ chỉ kinh sách hoặc làm động từ đứng trước tân ngữ với nghĩa trải qua. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('傘', '{"9000": "", "Chữ Trung Quốc": "傘", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (009)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tượng hình. Vẽ hình dáng một cái lọng, cái ô che nắng mưa. Gồm chữ Thập (十 - cán ô) và các chữ Nhân (人 - nan ô) tỏa ra tứ phía. Giải thích sự chuyển ý: Tản là cái ô, cái dù, cái lọng dùng để che nắng che mưa (che tản).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>人", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "伞", "Unihan_Traditional (Chữ Phồn thể)": "傘", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禮', '{"9000": "", "Chữ Trung Quốc": "禮", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 示 | Số nét | 17 | nét | 礻 | thị | biểu nghĩa | bàn thờ, nghi lễ | 豊 | phong | biểu âm | lễ nghi, phong phú | 禮 = 礻 (Thị, biểu nghĩa: bàn thờ, thần linh) + 豊 (Phong, biểu âm và biểu nghĩa: lễ nghi); vừa hình thanh vừa hội ý. Thực hiện nghi lễ trước bàn thờ — 豊 nguyên gốc là chữ 禮, viết giản lược.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Nguyên gốc viết là 豊, sau thêm bộ 礻 (thị – bàn thờ) để chỉ rõ ngữ nghĩa: thực hiện nghi lễ tế tự trước thần linh. Wiktionary ghi nhận cả hai tầng: hình thanh (豊 biểu âm) và hội ý (礻 biểu nghĩa: thờ cúng + 豊 biểu nghĩa: lễ nghi). Lễ vốn là hành vi thờ phụng, sau mở rộng sang phép tắc xã giao. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kỳ (113) Lễ (637)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thị (còn gọi là Kỳ, số 113 - thần đất/bàn thờ/ 示 /chỉ ý) ở bên trái chữ Lễ (số 637 - đồ tế khí/ 豊 /chỉ âm). Đem lễ vật bày lên bàn thờ để tế lễ thần linh. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Lễ là phép tắc thờ cúng thần Phật, tổ tiên (tế lễ, lễ vật). Từ đó suy rộng ra quy tắc cư xử kính trọng giữa người với người (lễ nghi, lễ phép, lễ độ).", "Nghĩa Tiếng Việt_Xie": "lễ nghi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻豊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "礼", "Unihan_Traditional (Chữ Phồn thể)": "禮", "Pinyin_Xie": "lǐ", "Âm Hán Việt_Xie": "lễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ các quy tắc ứng xử hoặc tính từ thể hiện sự lịch thiệp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('爯', '{"9000": "", "Chữ Trung Quốc": "爯", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trảo (087) Nhiễm (1599)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trảo (số 087 - móng vuốt/bàn tay/ 爫 /chỉ ý) ở trên chữ Nhiễm (số 1599/ 冉 /chỉ âm). Dùng tay nhấc hai vật lên. Giải thích sự chuyển ý: Chữ Xưng (爯) mang nghĩa là nhấc lên, giơ lên (cử dã). Đây là chữ tạo âm cho chữ 稱 (Xưng - xưng hô, cái cân). Chú ý: Trong video bài 64, hình ảnh chữ cuối cùng bị hiển thị nhầm thành chữ Tái (再 - lặp lại/ Gồm chữ Nhất 一, Quynh 冂 và Thổ 土). Nhưng phần âm thanh và giảng giải chiết tự lại dành cho chữ Xưng (爯).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>爫冉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "爫", "Unihan_Simplified (Chữ Giản thể)": "爯", "Unihan_Traditional (Chữ Phồn thể)": "爯", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稱', '{"9000": "", "Chữ Trung Quốc": "稱", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 禾 | Số nét | 14 | nét | 禾 | biểu nghĩa | cây lúa, đo lường ngũ cốc | 爯 | biểu âm | cầm lên, nhấc lên | 稱 = 禾 (biểu nghĩa: lúa/đo lường) + 爯 (biểu âm); chữ hình thanh. Nghĩa gốc: đo lường lúa gạo. Wiktionary xác nhận cấu trúc và nghĩa gốc \"measure rice\".", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Chữ hình thanh: 禾 (lúa) biểu nghĩa, 爯 biểu âm. Nghĩa gốc: cân đo lúa gạo — từ đó mở rộng sang gọi tên, xưng danh, ca ngợi. Wiktionary xác nhận {{Han compound|禾|t1=rice|爯|ls=psc|c1=s|c2=p}} – measure rice. Tiểu triện có dạng 稱. Đây là dạng truyền thống, dạng giản là 称. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hòa (115) Xưng (1600)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hòa (số 115 - cây lúa/ 禾 /chỉ ý) ở bên trái chữ Xưng (số 1600 - nhấc lên/ 爯 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Chữ Xưng (爯) chỉ âm, bộ Hòa chỉ ý. Xứng là từ từ nhấc bao lúa lên bằng đòn cân để xem nặng nhẹ bao nhiêu (cái cân đòn, xưng trọng). Do hai bên đòn cân thăng bằng nên mang ý nghĩa thích hợp, vừa vặn (xứng đáng, cân xứng). Nghĩa khác là gọi tên (danh xưng, xưng hô).", "Nghĩa Tiếng Việt_Xie": "gọi bằng, gọi là, xưng là", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾爯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "称", "Unihan_Traditional (Chữ Phồn thể)": "稱", "Pinyin_Xie": "chēng", "Âm Hán Việt_Xie": "xưng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ đứng trước tân ngữ để biểu thị việc xưng hô, gọi tên hoặc cân đo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謝', '{"9000": "", "Chữ Trung Quốc": "謝", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 17 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn ngữ | 射 | xạ | biểu âm | 謝 = 言 (Ngôn, biểu nghĩa: lời nói) + 射 (Xạ, biểu âm). Chữ hình thanh — bộ ngôn ngữ kết hợp âm xạ cho nghĩa cảm ơn/từ chối.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Lục thư thông | Wiktionary: 謝 là chữ hình thanh gồm 言 (s, biểu nghĩa lời nói/ngôn ngữ) và 射 (p, biểu âm). Nghĩa gốc: xin lỗi, biện hộ; mở rộng sang từ chối, cảm ơn, héo tàn. Có dạng giáp cốt văn và kim văn cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Xạ (1602)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Xạ (số 1602 - phát ra/ 射 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Xạ chỉ âm, bộ Ngôn chỉ ý. Tạ là dùng lời lẽ để từ biệt, bày tỏ lòng biết ơn (cảm tạ, tạ ơn). Nghĩa khác là dùng lời nói để nhận lỗi (tạ lỗi).", "Nghĩa Tiếng Việt_Xie": "Cảm ơn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言射", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "射", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "谢", "Unihan_Traditional (Chữ Phồn thể)": "謝", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước đối tượng được cảm ơn hoặc dùng độc lập để biểu thị sự biết ơn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叕', '{"9000": "", "Chữ Trung Quốc": "叕", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hựu (029)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm 4 chữ Hựu (số 029 - cái tay/ 又) nối liền lại với nhau tạo thành một khối liên kết. Giải thích sự chuyển ý: Chuế là sự nối liền, liên kết không ngừng, chắp nối nhau.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴又", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "叕", "Unihan_Traditional (Chữ Phồn thể)": "叕", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輟', '{"9000": "", "Chữ Trung Quốc": "輟", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xa (159) Chuế (1604)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xa (số 159 - xe cộ/ 車 /chỉ ý) ở bên trái chữ Chuế (số 1604 - nối liền/ 叕 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Chữ Chuế chỉ âm, bộ Xa chỉ ý. Xuyết là các cỗ xe tập hợp nối liền nhau thành vòng tròn lại một chỗ để nghỉ. Từ đó mang ý nghĩa là dừng lại, ngừng nghỉ (trung xuyết - ngừng nửa chừng).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車叕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "辍", "Unihan_Traditional (Chữ Phồn thể)": "輟", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('試', '{"9000": "", "Chữ Trung Quốc": "試", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 13 | nét | 言 | ngôn | biểu nghĩa | lời nói | 式 | thức | biểu âm | 試 = 言 (Ngôn, biểu nghĩa: lời nói, kiểm tra qua lời) + 式 (Thức, biểu âm); chữ hình thanh.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Theo Wiktionary, 試 là chữ hình thanh: 言 (ngôn) biểu nghĩa hành động thử thách qua ngôn ngữ hoặc kiểm tra, còn 式 (thức) biểu âm. Nghĩa gốc là ''thử'', ''kiểm tra'', mở rộng sang ''thi cử''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Thức (458)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Thức (số 458 - phép tắc/ 式 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Chữ Thức chỉ âm, bộ Ngôn chỉ ý. Thí là dùng lời nói để kiểm tra xem có nắm được các phép tắc, khuôn phép hay không (thử thách, thi thí). Mở rộng là thử làm, so sánh tài nghệ (thí nghiệm, thí điểm).", "Nghĩa Tiếng Việt_Xie": "thử, thử nghiệm; thi tài", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言式", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "式", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "试", "Unihan_Traditional (Chữ Phồn thể)": "試", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ biểu thị hành động thử nghiệm hoặc làm danh từ trong các kỳ thi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('獎', '{"9000": "", "Chữ Trung Quốc": "獎", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tương (1273) Khuyển (058)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tương (số 1273 - sắp sửa, mong cầu/ 將 /chỉ âm) nằm trên bộ Khuyển (số 058 - con chó/ 犬 /chỉ ý). Cho chó ăn để tưởng thưởng, dỗ dành nó. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tương chỉ âm, bộ Khuyển chỉ ý. Tưởng là ban phần thưởng, khen ngợi, khích lệ công lao (tưởng thưởng, khen tưởng, giải tưởng).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>將犬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "將", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犬", "Unihan_Simplified (Chữ Giản thể)": "奖", "Unihan_Traditional (Chữ Phồn thể)": "獎", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賈', '{"9000": "", "Chữ Trung Quốc": "賈", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 13 | nét | 襾 | á | biểu âm | 貝 | bối | biểu nghĩa | tiền, vỏ sò | 賈 = 貝 (Bối, biểu nghĩa: tiền/hàng hóa) + 襾 (Á, biểu âm); chữ hình thanh. Bộ 貝 chỉ nghĩa liên quan đến buôn bán; 襾 cho âm jiǎ/gǔ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Theo Wiktionary, 賈 là chữ hình thanh: 貝 (tiền/hàng hóa) biểu nghĩa, 襾 biểu âm. Hai âm đọc: jiǎ (họ người) và gǔ (nhà buôn). Nghĩa gốc: người buôn bán cố định (khác với 商 là thương nhân lưu động). Chữ truyền thống, có hình tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Á (146) Bối (154)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Á (số 146 - che đậy/ 襾) nằm trên bộ Bối (số 154 - tiền bạc/ 貝). Giải thích sự chuyển ý: Cổ (thương cổ) là hành động mua bán, trao đổi hàng hóa để lấy tiền bạc. Nghĩa khác là Tên họ (họ Giả).", "Nghĩa Tiếng Việt_Xie": "cửa hàng buôn bán", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>西貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "西", "Unihan_Simplified (Chữ Giản thể)": "贾", "Unihan_Traditional (Chữ Phồn thể)": "賈", "Pinyin_Xie": "jiǎ", "Âm Hán Việt_Xie": "cổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ người buôn bán hoặc động từ chỉ hoạt động mua bán trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喪', '{"9000": "", "Chữ Trung Quốc": "喪", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thổ (032) Khẩu (030) Y (145)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm hai bộ Khẩu (số 030/ 口) nằm trong chữ Thổ (số 032 - đất/ 土), dưới cùng là bộ Y (số 145 - quần áo/ 衣) được viết giảm nét (thành 𧘇). Giải thích sự chuyển ý: Hình ảnh những người thân mặc áo tang đang gào khóc bên ngôi mộ bằng đất. Tang là lễ tang, việc mai táng (tang lễ, chịu tang). Từ đó mang nghĩa là mất mát đồ đạc, người thân (tang thi, tang mệnh).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>𡋑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "丧", "Unihan_Traditional (Chữ Phồn thể)": "喪", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紡', '{"9000": "", "Chữ Trung Quốc": "紡", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Phương (070)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái bộ Phương (số 070 - vuông vức/ 方 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Phương chỉ âm, bộ Mịch chỉ ý. Phưởng (phỏng) là làm ra vải lụa mỏng và mịn màng, dệt tơ (phưởng chỉ - se chỉ, dệt phưởng).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹方", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "方", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "纺", "Unihan_Traditional (Chữ Phồn thể)": "紡", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('錢', '{"9000": "", "Chữ Trung Quốc": "錢", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 16 | nét | 金 | kim | biểu nghĩa | kim loại, vàng, tiền | 戔 | tiên | biểu âm | nhỏ, ít | 錢 = 金 (Kim, biểu nghĩa: kim loại/tiền) + 戔 (Tiên, biểu âm); chữ hình thanh. Bộ Kim chỉ chất liệu đúc tiền, 戔 cho âm đọc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Chữ hình thanh: 金 (kim loại, vàng) là thành phần biểu nghĩa, 戔 là thành phần biểu âm. Tiền xưa được đúc bằng đồng hoặc vàng — bộ Kim phản ánh chất liệu đó. Dạng tiểu triện đã thấy cấu trúc này rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (556) Tiển (480)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 556 - kim loại/ 金 /chỉ ý) ở bên trái chữ Tiển (số 480 - nhỏ giọt/tàn dư/ 戔 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tiển chỉ âm, bộ Kim chỉ ý. Tiền là một loại nông cụ thu hoạch mùa màng làm bằng kim loại thời cổ. Sau này do nông cụ đó có thể mang đi đổi lấy vật dụng khác nên Tiền mới mang ý nghĩa là tiền tệ, tiền bạc (tiền tài).", "Nghĩa Tiếng Việt_Xie": "tiền nong", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金戔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "钱", "Unihan_Traditional (Chữ Phồn thể)": "錢", "Pinyin_Xie": "qián", "Âm Hán Việt_Xie": "tiền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tiền tệ hoặc vật có giá trị dùng trong giao dịch hàng ngày. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('費', '{"9000": "", "Chữ Trung Quốc": "費", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 12 | nét | 弗 | phất | biểu âm | âm phù | 貝 | buối | biểu nghĩa | vỏ sò, tiền | 費 là chữ hình thanh (psc): 弗 (phất, biểu âm) + 貝 (buối — tiền/vỏ sò, biểu nghĩa). Tiêu tiền (貝) theo cách phất tay bỏ đi — hình ảnh chi tiêu, phí tổn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Lục thư thông | Wiktionary: 費 = 弗 (biểu âm) + 貝 (vỏ sò/tiền, biểu nghĩa), chữ hình thanh. 貝 là ký hiệu tiền tệ cổ (vỏ sò dùng làm tiền). 弗 cho âm fèi/phí. Kim văn, tiểu triện và lục thư thông đều có dạng chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phất (042) Bối (154)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Phất (số 042 - không/ 弗 /chỉ âm) nằm trên bộ Bối (số 154 - tiền bạc/ 貝 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Phất chỉ âm, bộ Bối chỉ ý. Phí là việc sử dụng tiền tài vật chất quá độ, làm hao tổn (hao phí, lãng phí). Cũng mang nghĩa là khoản tiền chi ra cho một việc gì (chi phí, học phí).", "Nghĩa Tiếng Việt_Xie": "phí", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>弗貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "费", "Unihan_Traditional (Chữ Phồn thể)": "費", "Pinyin_Xie": "fèi", "Âm Hán Việt_Xie": "bí, bỉ, phí, phỉ, phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc tiêu tốn thời gian, tiền bạc hoặc làm danh từ chỉ các khoản chi phí. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孫', '{"9000": "", "Chữ Trung Quốc": "孫", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tử (039) Hệ (120)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tử (số 039 - con cái/ 子) ở bên trái chữ Hệ (số 120 - dòng dõi nối tiếp/ 系). Người nối tiếp ngay sau con mình chính là cháu mình. Giải thích sự chuyển ý: Đây là chữ Hội ý. Tôn là thế hệ cháu chắt nối tiếp nhau (con tôn, tử tôn).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰子系", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "系", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "子", "Unihan_Simplified (Chữ Giản thể)": "孙", "Unihan_Traditional (Chữ Phồn thể)": "孫", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('爾', '{"9000": "", "Chữ Trung Quốc": "爾", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (014)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 014 - che trùm/ 冂) đan chéo với các nét khác. Giải thích sự chuyển ý: Nhĩ là một đại từ nhân xưng ngôi thứ hai dùng thời cổ đại, tương đương với từ \"ngươi, mày, anh, chị, bạn\" (nhĩ đẳng).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>𤓯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躡', '{"9000": "", "Chữ Trung Quốc": "躡", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Túc (157) Nhiếp (150)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Túc (số 157 - cái chân/ 足 /chỉ ý) ở bên trái chữ Nhiếp (số 150 - thì thầm/nhỏ nhẹ/ 聶 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nhiếp chỉ âm, bộ Túc chỉ ý. Niếp là dùng chân giẫm lên, đạp lên nhưng một cách cẩn thận, nhẹ nhàng, kín đáo không gây tiếng động (niếp cước).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊聶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "聶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹑", "Unihan_Traditional (Chữ Phồn thể)": "躡", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('懼', '{"9000": "", "Chữ Trung Quốc": "懼", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (061) Cù (1576)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tâm (số 061 - trái tim/ 忄/chỉ ý) ở bên trái chữ Cù (số 1576 - nhìn nhớn nhác/ 瞿 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cù chỉ âm, bộ Tâm chỉ ý. Cụ là sự sợ hãi, lo lắng, sợ sệt trong lòng (sợ cụ, cụ phạ, úy cụ).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄瞿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瞿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "惧", "Unihan_Traditional (Chữ Phồn thể)": "懼", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豈', '{"9000": "", "Chữ Trung Quốc": "豈", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 豆 | Số nét | 10 | nét | 豈 | khải | tượng hình | há, lẽ nào, dùng để hỏi tu từ | 豈 không có dữ liệu phân tích thành phần từ CHISE. Theo Wiktionary, đây có thể là biến thể của 壴 (dụng cụ âm nhạc) với phần trên được thay đổi, hoặc dạng gốc của 凱 (khúc nhạc khải hoàn). Tiểu triện và lục thư thông còn lưu.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | 豈 có thể là biến thể của 壴 (biểu tượng nhạc cụ) với phần trên thay đổi, hoặc là dạng gốc của 凱 (khúc nhạc khải hoàn thắng trận). Sau chuyển sang dùng làm phó từ tu từ \"há, lẽ nào\". Tiểu triện và lục thư thông còn lưu dạng cổ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sơn (046) Đậu (151)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Sơn (số 046 - ngọn núi/ 山) nằm ở trên bộ Đậu (số 151 - bát cúng/ 豆). Giải thích sự chuyển ý: Khởi là một phó từ (hoặc liên từ) được dùng ở đầu câu dùng để hỏi ngược lại, mang ý nghĩa: lẽ nào, há lại, dễ thường (khởi cảm - há dám).", "Nghĩa Tiếng Việt_Xie": "Tề", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>山豆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岂", "Unihan_Traditional (Chữ Phồn thể)": "豈", "Pinyin_Xie": "qǐ", "Âm Hán Việt_Xie": "khải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Thường dùng làm phó từ đứng trước động từ để cấu tạo câu hỏi tu từ. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('譚', '{"9000": "", "Chữ Trung Quốc": "譚", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Đàm (1631)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Đàm (số 1631/ 覃 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đàm chỉ âm, bộ Ngôn chỉ ý. Đàm là dùng lời nói bàn bạc tranh luận để hiểu sâu xa vấn đề (đàm luận, đàm thoại).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "谭", "Unihan_Traditional (Chữ Phồn thể)": "譚", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萬', '{"9000": "", "Chữ Trung Quốc": "萬", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 艸 | Số nét | 12 | nét | 萬 | vạn | tượng hình | hình con bọ cạp; sau mượn âm để chỉ số mười nghìn | 萬 là chữ tượng hình (象形字): hình vẽ con bọ cạp trong giáp cốt văn. Sau này chữ được mượn âm (giả tá) để chỉ số mười nghìn. Chữ phái sinh 蠆 mới chỉ nghĩa gốc là bọ cạp. Không phân tích được thành hình thanh hay hội ý.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Bạch thư | Đại triện | Tiểu triện | 萬 vốn là tượng hình, vẽ hình con bọ cạp (xem bạch thư, đại triện, tiểu triện). Chữ phái sinh 蠆 về sau đảm nhiệm nghĩa gốc \"bọ cạp\". Còn 萬 được mượn âm (giả tá) để chỉ số mười nghìn — một trong những phép giả tá phổ biến nhất trong chữ Hán. Dạng bạch thư, đại triện và tiểu triện đều còn lưu giữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (140) Ngu (1460)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm bộ Thảo (số 140 - cây cỏ/ 艹) nằm ở trên chữ Ngu (số 1460 - con khỉ/ 禺). Vốn là chữ Tượng hình của con bọ cạp (với hai càng 艹 ở trên). Giải thích sự chuyển ý: Vì con bọ cạp có thể đẻ rất nhiều con cái, nên chữ Vạn được giả tá mượn làm đại từ chỉ số nhiều. Vạn là số 10.000 (một vạn, vạn vật, hàng vạn).", "Nghĩa Tiếng Việt_Xie": "vạn, mười nghìn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹禺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "wàn", "Âm Hán Việt_Xie": "vạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Tính từ | 形容词 | Phó từ | 副词 | Chữ này làm số từ chỉ mười nghìn hoặc làm phó từ biểu thị mức độ cực kỳ. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厲', '{"9000": "", "Chữ Trung Quốc": "厲", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hán (115) Vạn (1639)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hán (số 115 - sườn núi/ 厂 /chỉ âm) ở trên chữ Vạn (số 1639 - con bọ cạp/ 萬 /chỉ ý). Con bọ cạp trú dưới sườn núi vô cùng nguy hiểm và dữ tợn. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Lệ là sự dữ dội, mạnh mẽ, tàn khốc, không nương tay (khắc lệ, lợi hại). Cũng có ý nghĩa là nghiêm khắc, nghiêm nghị (nghiêm lệ).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂萬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "萬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "厉", "Unihan_Traditional (Chữ Phồn thể)": "厲", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螞', '{"9000": "", "Chữ Trung Quốc": "螞", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 虫 | Số nét | 16 | nét | 虫 | trùng | biểu nghĩa | côn trùng | 馬 | mã | biểu âm | 螞 là chữ hình thanh (psc): 虫 (trùng, biểu nghĩa: côn trùng) + 馬 (Mã, biểu âm). Bộ 虫 xác định đây là côn trùng; 馬 cung cấp âm đọc (mǎ).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 螞 (hình thanh): 虫 (côn trùng, biểu nghĩa) + 馬 (biểu âm). Chỉ con kiến (螞蟻) — côn trùng nhỏ sống thành đàn. Cũng có thể chỉ châu chấu trong một số phương ngữ. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trùng (142) Mã (187)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trùng (số 142 - côn trùng/ 虫 /chỉ ý) ở bên trái bộ Mã (số 187 - con ngựa/ 馬 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Mã chỉ âm, bộ Trùng chỉ ý. Mã là từ dùng để chỉ loại côn trùng nhó bé (như con mã nghị - kiến).", "Nghĩa Tiếng Việt_Xie": "(xem: mã hoàng 螞蟥); (xem: mã nghĩ 螞蟻); con nhặng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "馬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚂", "Unihan_Traditional (Chữ Phồn thể)": "螞", "Pinyin_Xie": "mǎ", "Âm Hán Việt_Xie": "mã", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép chỉ các loài côn trùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('幾', '{"9000": "", "Chữ Trung Quốc": "幾", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Yêu (052) Nhân (009) Qua (062)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm hai bộ Yêu (số 052 - nhỏ bé/ 幺), chữ Nhân (số 009 - con người/ 人) và chữ Qua (số 062 - cái giáo mác/ 戈). Những dấu hiệu rất nhỏ li ti báo trước sự việc (chữ Yêu) chỉ có bậc quân tử cầm giáo (nhân, qua) tinh tế mới thấy được. Giải thích sự chuyển ý: Đọc là Cơ mang ý nghĩa là dấu hiệu báo trước, thời cơ, cơ hội (cơ may, cơ hội). Đọc là Kỷ để chỉ số đếm ít, một vài, chừng bao nhiêu (kỷ người).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𢆶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('塊', '{"9000": "", "Chữ Trung Quốc": "塊", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thổ (032) Quỷ (1643)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thổ (số 032 - đất/ 土 /chỉ ý) ở bên trái chữ Quỷ (số 1643 - ma quỷ/ 鬼 /chỉ âm). Con quỷ ngồi dựa bên đống đất. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quỷ chỉ âm, bộ Thổ chỉ ý. Khối vốn là hòn đất sét, cục đất lớn. Sau này được dùng chỉ tảng đá, hòn, viên, những vật liền thành một tảng to (khối đá, khối lượng).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土鬼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "块", "Unihan_Traditional (Chữ Phồn thể)": "塊", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淨', '{"9000": "", "Chữ Trung Quốc": "淨", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Tranh (1014)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - dòng nước/ 氵/chỉ ý) ở bên trái chữ Tranh (số 1014 - tranh giành/ 爭 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tranh chỉ âm, bộ Thủy chỉ ý. Tịnh là sạch sẽ, gột rửa dơ bẩn, thanh khiết không vướng tạp niệm (thanh tịnh, tịnh hóa).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵爭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('欶', '{"9000": "", "Chữ Trung Quốc": "欶", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thúc (075) Khiếm (076)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thúc (số 075 - bó lại/ 束) ở bên trái bộ Khiếm (số 076 - thiếu/há miệng/ 欠). Giải thích sự chuyển ý: Đây là chữ Hội ý. Sóc là động tác mút, hút nước, ngậm.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰束欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "束", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "欠", "Unihan_Simplified (Chữ Giản thể)": "欶", "Unihan_Traditional (Chữ Phồn thể)": "欶", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('囷', '{"9000": "", "Chữ Trung Quốc": "囷", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vi (031) Hòa (115)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Vi (số 031 - bao quanh/ 囗) bao bên ngoài chữ Hòa (số 115 - cây lúa/ 禾). Khoanh vùng vây kín lúa lại để bảo quản. Giải thích sự chuyển ý: Đây là chữ Hội ý. Khuân là cái lẫm, cái vựa dùng để đựng thóc gạo thời xưa.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰囗禾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "囷", "Unihan_Traditional (Chữ Phồn thể)": "囷", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('㐱', '{"9000": "", "Chữ Trung Quốc": "㐱", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (009) Sam (059)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhân (số 009 - con người/ 人) ở trên bộ Sam (số 059 - lông râu/ 彡). Giải thích sự chuyển ý: Đây là chữ Hội ý. Chẩn là mái tóc tơ dài mượt mà của con người.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>人彡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "人", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('丟', '{"9000": "", "Chữ Trung Quốc": "丟", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (001) Khứ (028)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhất (số 001/ 一) nằm trên chữ Khứ (số 028 - đi/ 去). Sự vật một khi đã ra đi là không bao giờ quay lại nữa. (Có một cách viết khác là nét Phẩy 丿 nằm trên chữ Khứ: 丢). Giải thích sự chuyển ý: Đâu (đưu) là ném đi, vứt bỏ đi. Cũng mang nghĩa là mất đi, đánh mất vật gì đó biến mất hẳn (đâu kiểm - mất mặt).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>王厶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "丢", "Unihan_Traditional (Chữ Phồn thể)": "丟", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('幫', '{"9000": "", "Chữ Trung Quốc": "幫", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bang (163) Bạch (050)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bang (số 163 - quốc gia/ 邦 /chỉ âm) nằm trên chữ Bạch (số 050 - tấm lụa/ 帛 /chỉ ý). Giải thích sự chuyển ý: Bang là mang đồ vật tới để giúp đỡ, trợ giúp người khác (bang trợ, giúp bang). (Ghi chú: Trong video bài giảng thầy có nhầm lẫn phân tích thành chữ Phong 封 ở trên chữ Bạch. Thực tế phần trên là chữ Bang 邦).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>封帛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "封", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謊', '{"9000": "", "Chữ Trung Quốc": "謊", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Hoang (1680)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Hoang (số 1680 - bỏ hoang/ 荒 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hoang chỉ âm, bộ Ngôn chỉ ý. Hoang là những lời nói không có căn cứ, không có thật, lời nói lừa dối (nói hoang, hoang báo, hoang đường).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言荒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "荒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "谎", "Unihan_Traditional (Chữ Phồn thể)": "謊", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嚇', '{"9000": "", "Chữ Trung Quốc": "嚇", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030) Hách (1683)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 030 - cái miệng/ 口 /chỉ ý) ở bên trái chữ Hách (số 1683 - rực rỡ/khí thế/ 赫 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hách chỉ âm, bộ Khẩu chỉ ý. Hách là dùng miệng la to tỏ khí thế để làm người khác sợ hãi, dọa nạt (hống hách, dọa hách).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口赫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吓", "Unihan_Traditional (Chữ Phồn thể)": "嚇", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搖', '{"9000": "", "Chữ Trung Quốc": "搖", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Diêu (1231)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Diêu (số 1231 - vò đồ gốm/ 䍃 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Diêu chỉ âm, bộ Thủ chỉ ý. Dao là hành động dùng tay làm cho rung chuyển, lay động, lắc, vẫy (rung dao, dao động).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "摇", "Unihan_Traditional (Chữ Phồn thể)": "搖", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罷', '{"9000": "", "Chữ Trung Quốc": "罷", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 网 | Số nét | 15 | nét | 网 | võng | biểu nghĩa | lưới | 能 | năng | biểu nghĩa | con gấu; tài năng | 罷 là chữ hội ý (ic): 网 (lưới, võng) + 能 (con gấu hoặc tài năng). Theo Thuyết Văn Giải Tự, nghĩa gốc là \"bắt tội nhân\"; theo Zhang Shunhui nghĩa là \"mệt mỏi\" — hình ảnh dùng lưới bắt gấu gợi lên sự vất vả kiệt sức.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 罷 (hội ý): 网 (lưới) + 能 (con gấu). Theo Thuyết Văn Giải Tự, nghĩa gốc là bắt tội phạm bằng lưới; theo học giả Zhang Shunhui nghĩa là mệt mỏi. Từ đó phát triển nghĩa thôi việc, bãi miễn, giải tán. Hình tượng: dùng lưới để bắt gấu — công việc nặng nhọc, mệt mỏi. Tiểu triện còn lưu dạng gốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Võng (122) Năng (650)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Võng (số 122 - cái lưới/ 罒 /chỉ ý) ở trên chữ Năng (số 650 - con gấu/ 能). Con gấu lớn đã bị sa vào lưới, cuộc đi săn đã xong. Giải thích sự chuyển ý: Bãi vốn là con gấu mệt mỏi. Sau đó mang nghĩa là dừng lại, kết thúc, bỏ đi, nghỉ việc (bãi công, bãi thị, bãi miễn).", "Nghĩa Tiếng Việt_Xie": "ngừng, thôi, nghỉ; bãi, bỏ; xong", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>罒能", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "能", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罢", "Unihan_Traditional (Chữ Phồn thể)": "罷", "Pinyin_Xie": "bà", "Âm Hán Việt_Xie": "bãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Trợ từ | 助词 | Thường làm động từ chỉ sự ngưng nghỉ, bãi chức hoặc làm trợ từ ngữ khí ở cuối câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擺', '{"9000": "", "Chữ Trung Quốc": "擺", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Bãi (1687)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Bãi (số 1687 - xong việc/ 罷 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Bãi chỉ âm, bộ Thủ chỉ ý. Bài là dùng tay sắp xếp đồ đạc, đặt để mọi thứ vào đúng vị trí sau khi xong việc (bài bố, bài biện). (Nghĩa khác là lắc lư, vẫy: bài thủ).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌罷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "摆", "Unihan_Traditional (Chữ Phồn thể)": "擺", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悤', '{"9000": "", "Chữ Trung Quốc": "悤", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thông (291) Tâm (061)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thông (số 291 - ống khói/ 囪 /chỉ âm) ở trên bộ Tâm (số 061 - trái tim/ 心 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thông chỉ âm, bộ Tâm chỉ ý. Thông là sự vội vàng, hấp tấp trong tâm (thông thông). Chữ này (悤) là gốc của chữ Tổng 總. (Khác chữ thông minh 聰).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>囱心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "囱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('總', '{"9000": "", "Chữ Trung Quốc": "總", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 17 | nét | 糸 | biểu nghĩa | tơ lụa, sợi dây | 悤 | biểu âm | lo lắng, hối hả | 總 = 糸 (biểu nghĩa: dây/tơ) + 悤 (biểu âm zǒng); chữ hình thanh. Bộ 糸 cho nghĩa buộc lại/tổng hợp (như buộc dây), bộ 悤 cho âm zǒng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary: {{Han compound|糸|悤|c1=s|c2=p|t1=rope|ls=psc}} — ý \"buộc gom lại bằng dây\", từ đó tất cả/tổng cộng. Nghĩa gốc: buộc gom; mở rộng sang: tổng cộng, tất cả, luôn luôn. Phồn thể 總 tương ứng giản thể 总. Có dạng tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Thông (1690)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái chữ Thông (số 1690 - ống khói/vội vàng/ 悤 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thông chỉ âm, bộ Mịch chỉ ý. Tổng là túm lại, buộc sợi lại với nhau. Nghĩa mở rộng là gộp lại, hợp lại, bao quát toàn bộ (tổng kết, tổng số, tổng thống).", "Nghĩa Tiếng Việt_Xie": "tổng cộng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹悤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "悤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "总", "Unihan_Traditional (Chữ Phồn thể)": "總", "Pinyin_Xie": "zǒng", "Âm Hán Việt_Xie": "tổng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm phó từ đứng trước động từ để biểu thị ý nghĩa luôn luôn hoặc tổng cộng. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盜', '{"9000": "", "Chữ Trung Quốc": "盜", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 皿 | Số nét | 12 | nét | 㳄 | biểu âm | thành phần biểu âm (gốc: nước chảy tràn) | 皿 | mãnh | biểu nghĩa | chậu, bát (nghĩa hiện tại sau biến thể); gốc là 舟 (chu, thuyền) | 盜 có lịch sử phức tạp: giáp cốt văn là hình thanh — 㳄 (biểu âm) + 舟 (biểu nghĩa: thuyền), nghĩa gốc là dòng nước tràn bờ. Nghĩa ''ăn cắp'' là hội ý — 㳄 (thèm muốn, nước dãi) + 皿 (vật dụng của người khác). 舟 biến thành 皿 trong chữ Sở.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Wiktionary (李学勤《字源》) giải thích: giáp cốt văn là hình thanh — 㳄 (biểu âm) + 舟 (thuyền), nghĩa gốc là dòng nước tràn bờ, tương thông với 衍, 羨, 延 trong kim văn. Chữ 舟 biến thành 皿 trong văn Sở. Nghĩa ''ăn cắp'' là hội ý riêng: 㳄 (nước dãi/thèm muốn) + 皿 (vật dụng) — thèm muốn tài vật của người khác mà lấy trộm. Hai nghĩa có lịch sử tách biệt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Diên (1695) Mãnh (107)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Diên (số 1695 - thèm rỏ rãi/ 涎 /viết đổi thành 㳄) nằm trên bộ Mãnh (số 107 - bát dĩa/ 皿). Kẻ trộm nhìn thấy những đồ vật (bát đĩa thời xưa rất có giá trị) mà thèm nhỏ dãi, muốn lén lút lấy trộm. Giải thích sự chuyển ý: Đây là chữ Hội ý. Đạo là hành động lén lút ăn cắp đồ của người khác, kẻ trộm, phường cướp bóc (đạo tặc, ăn đạo, cường đạo).", "Nghĩa Tiếng Việt_Xie": "ăn cắp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>㳄皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㳄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盗", "Unihan_Traditional (Chữ Phồn thể)": "盜", "Pinyin_Xie": "dào", "Âm Hán Việt_Xie": "đạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ kẻ trộm hoặc làm động từ chỉ hành vi lấy cắp tài sản của người khác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搶', '{"9000": "", "Chữ Trung Quốc": "搶", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Thương (266)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Thương (số 266 - kho lúa/ 倉 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thương chỉ âm, bộ Thủ chỉ ý. Thưởng (Thương) là hành động dùng tay giành giật lấy, cướp đoạt bằng sức mạnh (thưởng kiếp, cướp thưởng). (Khác với Đạo 盜 là trộm lén lút không dùng sức lực).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌倉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "倉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "抢", "Unihan_Traditional (Chữ Phồn thể)": "搶", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('該', '{"9000": "", "Chữ Trung Quốc": "該", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 13 | nét | 言 | ngôn | biểu nghĩa | lời nói | 亥 | hợi | biểu âm | 該 = 言 (Ngôn, biểu nghĩa: lời nói) + 亥 (Hợi, biểu âm). Chữ hình thanh. Bộ 言 gợi ý liên quan đến lời nói, truyền đạt; 亥 cung cấp âm đọc gāi. Có ảnh tiểu triện.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary: 該 là chữ hình thanh gồm 言 (biểu nghĩa: lời nói) và 亥 (biểu âm). Nghĩa hiện đại: nên, cần phải. Có ảnh tiểu triện từ hanziyuan. Trong tiếng Trung giản thể viết là 该. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Hợi (101)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Hợi (số 101 - chi Hợi/ 亥 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hợi chỉ âm, bộ Ngôn chỉ ý. Cai vốn là tên chức quan võ phụ trách trông nom, quản lý một toán quân thời xưa (cai đội). Mở rộng mang nghĩa là nên làm, phải làm (ưng cai). Cũng có nghĩa là bao quát, gồm đủ (cai quát).", "Nghĩa Tiếng Việt_Xie": "cái", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言亥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "该", "Unihan_Traditional (Chữ Phồn thể)": "該", "Pinyin_Xie": "gāi", "Âm Hán Việt_Xie": "cái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ động từ | 能愿动词 | Đại từ | 代词 | Động từ | 动词 | Thường làm trợ động từ đứng trước động từ để biểu thị nghĩa nên hoặc đáng làm gì. | Trợ động từ | 能愿动词 | Đứng trước động từ chính để nêu khả năng, ý muốn hoặc sự cho phép: 会, 能, 可以, 想, 要. Phủ định đặt 不 trước chính nó — 不能去. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('慶', '{"9000": "", "Chữ Trung Quốc": "慶", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lộc (362) Tâm (061) Truy (034)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lộc viết giảm nét (số 362 - hươu nai/ 鹿), dưới là bộ Tâm (số 061/ 心) và bộ Truy (số 034 - bước theo/ 夂). Mang miếng da nai (lộc) với tấm lòng vui vẻ, mang đến để mừng cho người khác. Giải thích sự chuyển ý: Khánh là việc chúc mừng lễ vui, tiệc mừng, lễ nghi mừng rỡ (quốc khánh, lễ khánh, khánh hạ).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴夂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "庆", "Unihan_Traditional (Chữ Phồn thể)": "慶", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紀', '{"9000": "", "Chữ Trung Quốc": "紀", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 9 | nét | 糸 | mịch | biểu nghĩa | tơ lụa, sợi chỉ | 己 | kỷ | biểu âm | bản thân, can chi Kỷ | 紀 = 糸 (Mịch/Ty, biểu nghĩa: tơ lụa, sợi chỉ) + 己 (Kỷ, biểu âm); chữ hình thanh. Phần 糸 gợi ý nghĩa liên quan đến sự sắp xếp có trật tự như cuộn chỉ, phần 己 cho biết âm đọc jì/jǐ — gần với Hán-Việt kỷ/kỉ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 紀 là chữ hình thanh: 糸 (biểu nghĩa, tơ lụa) kết hợp với 己 (biểu âm). Nghĩa gốc là cuộn, gom tơ — từ đó phát sinh nghĩa kỷ luật, trật tự, ghi chép, thế kỷ. Có hình kim văn và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Kỷ (049)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái chữ Kỷ (số 049 - bản thân/ 己 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Kỷ chỉ âm, bộ Mịch chỉ ý. Kỷ vốn chỉ đầu mối của một cuộn tơ sợi. Từ đó mở rộng ra ý nghĩa là lề lối, phép tắc, lề luật có tính hệ thống (kỷ luật, kỷ cương, thế kỷ).", "Nghĩa Tiếng Việt_Xie": "Kỷ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹己", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "己", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "纪", "Unihan_Traditional (Chữ Phồn thể)": "紀", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kỉ, kỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ quy tắc hoặc động từ ghi chép sự kiện lịch sử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('敵', '{"9000": "", "Chữ Trung Quốc": "敵", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Đích (264) Phộc (066)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Đích (số 264 - gốc gác/ 啇 /chỉ âm) ở bên trái bộ Phộc (số 066 - đánh khẽ/ 攵 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đích chỉ âm, bộ Phộc chỉ ý. Địch là kẻ thù, người đánh chọi chống đối lại mình (kẻ địch, quân địch, vô địch).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "敌", "Unihan_Traditional (Chữ Phồn thể)": "敵", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('敗', '{"9000": "", "Chữ Trung Quốc": "敗", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bối (154) Phộc (066)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Bối (số 154 - tiền bạc/ 貝) ở bên trái bộ Phộc (số 066 - đánh khẽ/ 攵). Bị đánh thua cởi giáp quy hàng phải mang tiền bạc đến để xin bồi thường giảng hòa. Giải thích sự chuyển ý: Đây là chữ Hội ý. Bại là thua trận, bị đánh bại (thất bại, bại trận). Mở rộng là hỏng hóc, tàn tạ (hủ bại, suy bại).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貝⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "⺙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "败", "Unihan_Traditional (Chữ Phồn thể)": "敗", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殺', '{"9000": "", "Chữ Trung Quốc": "殺", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thù (079) Hựu (029) Mộc (075)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bên trái là chữ Hựu (số 029 - cái tay/ 又) ở dưới chữ Mộc có nét phẩy (木 + 丿). Bên phải là bộ Thù (số 079 - vũ khí/ 殳). Một bàn tay cầm cái gậy gỗ đánh nhau với một bàn tay cầm vũ khí. Giải thích sự chuyển ý: Đây là chữ Hội ý. Sát là hành động làm tổn hại đến tính mạng, giết hại, chém giết (tàn sát, sát hại). Mở rộng là làm hao mòn đi (tiêu sát).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰杀殳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "杀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "殳", "Unihan_Simplified (Chữ Giản thể)": "杀", "Unihan_Traditional (Chữ Phồn thể)": "殺", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夠', '{"9000": "", "Chữ Trung Quốc": "夠", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cú (431) Đa (233)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Cú (số 431 - câu văn/ 句 /chỉ âm) ở bên trái chữ Đa (số 233 - nhiều/ 多 /chỉ ý). (Dạng phổ biến hơn là chữ Cú nằm bên phải chữ Đa: 够). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cú chỉ âm, bộ Đa chỉ ý. Cú mang ý nghĩa là số lượng nhiều, đầy đủ, đạt đến một mức độ nào đó (đầy cú, dư cú).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰多句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "多", "Unihan_Simplified (Chữ Giản thể)": "够", "Unihan_Traditional (Chữ Phồn thể)": "夠", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漢', '{"9000": "", "Chữ Trung Quốc": "漢", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (085) Cách (177) Đại (037)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bên phải là chữ Cách (số 177 - da thú/ 革 /viết giảm nét) ở trên chữ Đại (số 037 - to lớn/ 大 /viết giảm nét), bên trái là bộ Thủy (số 085 - dòng nước/ 氵). Giải thích sự chuyển ý: Hán vốn là tên của con sông Hán Thủy. Nhà Hán (Lưu Bang lập ra) làm nên sự rực rỡ của văn minh Hoa Hạ nên chữ Hán được dùng để chỉ người Trung Quốc, văn tự của Trung Quốc (người Hán, Hán tự, Hán nôm).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "汉", "Unihan_Traditional (Chữ Phồn thể)": "漢", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('難', '{"9000": "", "Chữ Trung Quốc": "難", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 隹 | Số nét | 19 | nét | 暵 | biểu âm | phần biểu âm rút gọn | 隹 | truỳ | biểu nghĩa | chim đuôi ngắn | 難 = 暵 rút gọn (biểu âm) + 隹 (Truỳ, biểu nghĩa: chim đuôi ngắn); chữ hình thanh. Bộ 隹 gốc chỉ loài chim; 暵 rút gọn cho âm đọc nán. Nghĩa gốc là tên chim, sau mượn âm cho nghĩa khó.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Lục thư thông | Chữ hình thanh: 暵 rút gọn (biểu âm) + 隹 (truỳ, chim đuôi ngắn) biểu nghĩa. Kim văn và tiểu triện ghi nhận. Nghĩa gốc: tên loài chim. Phiên âm mượn (giả tá) sang nghĩa khó, gian nan. Lục thư thông ghi nhận dạng chuyển tiếp. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hán (1724) Truy (034)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hán (số 1724/ 漢) viết giảm đi bộ Thủy (氵) nằm ở bên trái, bên phải là bộ Truy (số 034 - con chim đuôi ngắn/ 隹). Rất khó để bắt được một con chim bay qua sông lớn. Giải thích sự chuyển ý: Đây là chữ Hội ý. Đọc là Nan với nghĩa là sự khó khăn, vất vả, gian nan (gian nan, khốn nan, nan giải). Đọc là Nạn với nghĩa là chịu đựng tai họa thảm khốc, hoạn nạn (tai nạn, tị nạn).", "Nghĩa Tiếng Việt_Xie": "khó", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "难", "Unihan_Traditional (Chữ Phồn thể)": "難", "Pinyin_Xie": "nán", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm tính từ đứng trước động từ để chỉ việc gì đó khó thực hiện. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏡', '{"9000": "", "Chữ Trung Quốc": "鏡", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 19 | nét | 金 | kim | biểu nghĩa | kim loại | 竟 | cánh | biểu âm | rốt cuộc, hết | 鏡 = 金 (Kim, biểu nghĩa: kim loại) + 竟 (Cánh, biểu âm); chữ hình thanh. Gương cổ đại làm từ đồng đánh bóng — bộ 金 chỉ chất liệu kim loại, 竟 cho âm jìng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | Wiktionary xác nhận: hình thanh gồm 金 (kim loại, biểu nghĩa) và 竟 (biểu âm). Gương cổ Trung Quốc làm bằng đồng đánh bóng (bronze mirror), sau này mới có gương thủy tinh. Đại triện và tiểu triện đều ghi nhận cấu trúc 金+竟 này. 鏡 là phồn thể, giản thể là 镜. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (167) Cánh (1726)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 167 - kim loại/ 金 /chỉ ý) ở bên trái chữ Cánh (số 1726 - xong, hoàn thành/ 竟 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cánh chỉ âm, bộ Kim chỉ ý. Thời xưa gương soi được làm bằng kim loại (đồng thau) mài nhẵn, nên Kính chính là cái gương soi (minh kính). Ngày nay dùng để chỉ các loại kính, thấu kính (kính hiển vi, nhãn kính).", "Nghĩa Tiếng Việt_Xie": "gương, kính", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金竟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "竟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "镜", "Unihan_Traditional (Chữ Phồn thể)": "鏡", "Pinyin_Xie": "jìng", "Âm Hán Việt_Xie": "kẻng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng độc lập hoặc làm hậu tố cấu tạo từ chỉ các loại kính mắt, kính viễn vọng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴉', '{"9000": "", "Chữ Trung Quốc": "鴉", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 鳥 | Số nét | 15 | nét | 牙 | nha | biểu âm | răng, ngà | 鳥 | điểu | biểu nghĩa | chim | 鴉 = 牙 (Nha, biểu âm: cho âm đọc) + 鳥 (Điểu, biểu nghĩa: chim); chữ hình thanh. Bộ Điểu chỉ đây là loài chim; phần Nha cho âm yā.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Chữ hình thanh: 鳥 (điểu) biểu nghĩa chỉ loài chim, 牙 (nha) biểu âm cho âm đọc yā. Quạ đen tuyền, tiếng kêu ồn ào — người xưa ghép 牙 vào 鳥 để tạo chữ riêng cho loài chim đặc biệt này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nha (092) Điểu (196)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nha (số 092 - cái răng/ 牙 /chỉ âm) ở bên trái bộ Điểu (số 196 - con chim/ 鳥 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nha chỉ âm, bộ Điểu chỉ ý. Nha là tên gọi con quạ khoang (ô nha).", "Nghĩa Tiếng Việt_Xie": "con quạ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牙鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鳥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牙", "Unihan_Simplified (Chữ Giản thể)": "鸦", "Unihan_Traditional (Chữ Phồn thể)": "鴉", "Pinyin_Xie": "yā", "Âm Hán Việt_Xie": "a", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim quạ, thường kết hợp thành từ ghép như ô nha. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聰', '{"9000": "", "Chữ Trung Quốc": "聰", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 耳 | Số nét | 17 | nét | 囪 | thông | biểu âm | lỗ thông hơi (biểu âm và gốc hình ảnh) | 心 | tâm | biểu nghĩa | tâm trí, trái tim | 聰 có bộ 耳 (nhĩ, tai) là thành phần nhận diện chính; cấu trúc cũng liên quan đến 囪 (lỗ thông hơi) và 心 (tâm). Theo học giả Qiu Xigui và Shen Pei, nguyên hình là 悤 — tâm mở (心) với dấu chấm lớn chỉ lỗ thông. Sau thêm bộ 耳. Chữ hội ý phức tạp.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Lục thư thông | Wiktionary ghi nhận chữ phái sinh từ 悤 — nguyên hình là tâm/trí (心) mở như cái lỗ thông hơi (囪) — chỉ tâm mở, trí rộng. Theo Qiu Xigui và Shen Pei, nghĩa gốc là tâm trí thông suốt, sau thêm 耳 (tai nghe nhạy). Nghĩa hiện tại: thông minh, tai thính. Chữ truyền thống, giản thể là 聪. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhĩ (128) Thông (1690)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhĩ (số 128 - cái tai/ 耳 /chỉ ý) ở bên trái chữ Thông (số 1690 - vội vàng/ống khói/ 悤 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thông (悤) chỉ âm, bộ Nhĩ chỉ ý. Thông là thính tai, nghe rõ và hiểu nhanh vấn đề (thông minh).", "Nghĩa Tiếng Việt_Xie": "Công", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳悤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "悤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聪", "Unihan_Traditional (Chữ Phồn thể)": "聰", "Pinyin_Xie": "cōng", "Âm Hán Việt_Xie": "thông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để chỉ sự thông minh, sáng suốt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夢', '{"9000": "", "Chữ Trung Quốc": "夢", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (140) Mục (109) Mịch (014) Tịch (036)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm bộ Thảo (số 140 - cây cỏ/ 艹), chữ Mục viết ngang (số 109 - con mắt/ 罒), bộ Mịch (số 014 - trùm che/ 冖) và bộ Tịch (số 036 - đêm tối/ 夕). Khi màn đêm (tịch) bao phủ (mịch), mắt (mục) nhắm lại mơ màng thấy những cánh đồng cỏ (thảo) tươi tốt. Giải thích sự chuyển ý: Mộng là giấc mơ, chiêm bao (nằm mộng, mộng mị, ác mộng). Mở rộng chỉ những điều ảo tưởng, hư ảo không có thực (mộng tưởng, mộng ảo).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "梦", "Unihan_Traditional (Chữ Phồn thể)": "夢", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緊', '{"9000": "", "Chữ Trung Quốc": "緊", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 14 | nét | 臤 | kiên | biểu âm | cứng rắn (cho âm) | 糸 | mịch | biểu nghĩa | sợi tơ, dây | 緊 = 臤 (Kiên, biểu âm) + 糸 (Mịch, biểu nghĩa: sợi tơ, dây); chữ hình thanh. Sợi tơ 糸 bị kéo căng — hình ảnh chặt, căng. Wiktionary xác nhận cấu trúc psc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | 緊 là chữ hình thanh: 糸 (sợi tơ) biểu nghĩa, 臤 biểu âm. Nghĩa gốc là sợi dây căng chặt, từ đó nghĩa chặt, gấp, căng thẳng. Wiktionary xác nhận cấu trúc psc rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kiên (469) Mịch (120)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Kiên viết giảm nét thành chữ Khan (số 469 - bền chắc/ 臤 /chỉ âm) ở trên bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Khan chỉ âm, bộ Mịch chỉ ý. Khẩn là dùng dây tơ buộc căng, buộc cho thật chắc chắn (khẩn bế - đóng chặt). Mở rộng mang nghĩa là cấp bách, gấp gáp, quan trọng (khẩn cấp, khẩn trương, trọng khẩn).", "Nghĩa Tiếng Việt_Xie": "chặt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>臤糸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糸", "Unihan_Simplified (Chữ Giản thể)": "紧", "Unihan_Traditional (Chữ Phồn thể)": "緊", "Pinyin_Xie": "jǐn", "Âm Hán Việt_Xie": "khẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp với bổ ngữ trạng thái để chỉ mức độ chặt chẽ, gấp rút. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窮', '{"9000": "", "Chữ Trung Quốc": "窮", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 穴 | Số nét | 15 | nét | 穴 | huyệt | biểu nghĩa | hang, hố sâu | 躬 | cung | biểu âm | thân mình, cúi mình (biểu âm) | 窮 = 穴 (Huyệt, biểu nghĩa: hang, hốc) + 躬 (Cung, biểu âm); chữ hình thanh. Bộ 穴 gợi ý bị giới hạn trong không gian hẹp — nghèo khổ như bị nhốt trong hang tối.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Lục thư thông | Wiktionary xác nhận cấu trúc hình thanh: 穴 (hang, sự giam cầm) biểu nghĩa, 躬 biểu âm. Nghĩa gốc: nghèo khổ, cùng cực, không còn lối thoát. Hình ảnh người bị nhốt trong hang tối không ra được — đó là cảnh \"cùng\" (窮) đến tận cùng. Chữ truyền thống, giản thể là 穷. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Huyệt (116) Cung (1259)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Huyệt (số 116 - cái hang/ 穴 /chỉ ý) ở trên chữ Cung (số 1259 - cái thân mình/ 躬 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cung chỉ âm, bộ Huyệt chỉ ý. Cùng là điểm tận cùng, cuối cùng (cùng tận, vô cùng). Đi đến ngõ cụt thì không còn lối thoát, mở rộng mang nghĩa là nghèo đói, túng bấn, khốn khó (bần cùng, khốn cùng).", "Nghĩa Tiếng Việt_Xie": "nghèo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>穴躬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "躬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "穷", "Unihan_Traditional (Chữ Phồn thể)": "窮", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "cùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Động từ | 动词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để chỉ sự nghèo túng, cùng cực. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('𢇇', '{"9000": "", "Chữ Trung Quốc": "𢇇", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Yêu (052) Củng (055)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm hai chữ Yêu (số 052 - nhỏ bé/ 幺) ở trên chữ Củng (số 055 - chắp tay/ 廾). Hai bàn tay đang cầm những sợi tơ nhỏ quấn vào con thoi. Giải thích sự chuyển ý: Quan là hành động cầm sợi tơ quấn vào con thoi để dệt vải. Chữ này là phần bên trong làm âm đọc cho chữ Quan (關 - cái cổng).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>𢆶丱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "𢆶", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('關', '{"9000": "", "Chữ Trung Quốc": "關", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 門 | Số nét | 19 | nét | 門 | môn | biểu nghĩa | cánh cửa | 關 = 門 (Môn, biểu nghĩa: cửa) + 𢇅 (biểu âm: hình hai vòng dây 幺幺 biểu tượng cơ chế khoá cửa); chữ hình thanh, gốc là hội ý. Kim văn mô tả cửa + hai thanh gỗ khoá ngang (卝) — thể hiện hành động đóng khoá cửa thực tế.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Lục thư thông | 關 có hình kim văn là 門 (cửa) + 卝 (hai thanh gỗ khoá ngang cửa). Sau đó phát triển thành cấu trúc 門 + 𢇅 với hai vòng dây giống 幺幺 — biểu trưng cơ chế khoá. Đây là chữ ban đầu có tính hội ý, sau mang thêm yếu tố biểu âm. Có nhiều hình kim văn và lục thư thông phong phú. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Môn (169) Quan (1739)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Môn (số 169 - cái cửa/ 門 /chỉ ý) bao bên ngoài chữ Quan (số 1739 - con thoi/ 𢇇 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quan (𢇇) chỉ âm, bộ Môn chỉ ý. Quan vốn là cái thanh gỗ để gài cửa lại cho chắc. Sau mang nghĩa là cái cổng, cửa ải nối với bên ngoài (hải quan, ải quan). Mở rộng mang nghĩa là mối liên hệ, gắn kết (quan hệ, liên quan).", "Nghĩa Tiếng Việt_Xie": "đóng lại", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門𢇇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𢇇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "关", "Unihan_Traditional (Chữ Phồn thể)": "關", "Pinyin_Xie": "guān", "Âm Hán Việt_Xie": "quan, loan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ cửa ải hoặc động từ mang tân ngữ chỉ hành động đóng, khép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罵', '{"9000": "", "Chữ Trung Quốc": "罵", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 网 | Số nét | 15 | nét | 网 | võng | biểu nghĩa | lưới (nghĩa gốc mơ hồ, vai trò biểu nghĩa chưa rõ) | 馬 | mã | biểu âm | ngựa (cho âm mà) | 罵 = 网 (Võng, biểu nghĩa: lưới) + 馬 (Mã, biểu âm: ngựa); chữ hình thanh. Wiktionary ghi dạng gốc là 𦋻. Phần 馬 cho âm mà; phần 网 (lưới) vai trò biểu nghĩa không hoàn toàn rõ ràng trong ngữ cảnh \"mắng chửi\". Chữ truyền thống, giản thể là 骂.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Wiktionary phân tích: 罵 hình thanh (psc) gồm 网 (lưới, biểu nghĩa) + 馬 (ngựa, biểu âm). Dạng nguyên bản là 𦋻. Nghĩa: la mắng, chửi rủa. Chữ truyền thống, giản thể là 骂. Xem thêm 詈 (lị, một chữ cổ cùng nghĩa mắng chửi). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Võng (122) Mã (187)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Võng (số 122 - cái lưới/ 罒 /chỉ ý) ở trên chữ Mã (số 187 - con ngựa/ 馬 /chỉ âm). Lời mắng chửi tuôn ra dồn dập như một cái lưới vô hình bủa vây lên đầu người khác. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Mã chỉ âm, bộ Võng chỉ ý. Mạ là dùng lời lẽ thô tục để mắng chửi người khác trước mặt (lăng mạ, chửi mạ).", "Nghĩa Tiếng Việt_Xie": "la mắng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>罒馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "馬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "骂", "Unihan_Traditional (Chữ Phồn thể)": "罵", "Pinyin_Xie": "mà", "Âm Hán Việt_Xie": "mạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ mang tân ngữ chỉ đối tượng bị mắng chửi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擋', '{"9000": "", "Chữ Trung Quốc": "擋", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Đang (1463)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Đang (số 1463 - làm/ 當 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đang chỉ âm, bộ Thủ chỉ ý. Đáng là dùng tay ngăn cản, chặn lại, che lấp đi (đáng lộ - cản đường).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌當", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "當", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "挡", "Unihan_Traditional (Chữ Phồn thể)": "擋", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('銀', '{"9000": "", "Chữ Trung Quốc": "銀", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 14 | nét | 金 | kim | biểu nghĩa | kim loại | 艮 | cấn | biểu âm | cứng chắc (âm yín) | 銀 = 金 (Kim, biểu nghĩa: kim loại) + 艮 (Cấn, biểu âm); chữ hình thanh. Bộ 金 cho biết đây là kim loại quý; 艮 (gèn/gěn) gần âm với yín của 銀 qua biến âm lịch sử.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Chữ 銀 là chữ hình thanh: 金 (kim, kim loại) là phần biểu nghĩa, 艮 là phần biểu âm. Wiktionary xác nhận: {{Han compound|金|艮|c1=s|c2=p|t1=metal|ls=psc}}. Nghĩa gốc: bạc (silver). Sau mở rộng: tiền bạc, của cải. Có hình tiểu triện. Chữ truyền thống, giản thể là 银. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (167) Cấn (138)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 167 - kim loại/ 金 /chỉ ý) ở bên trái chữ Cấn (số 138 - dừng lại/ 艮 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cấn chỉ âm, bộ Kim chỉ ý. Ngân là kim loại bạc (vàng bạc, kim ngân). Bạc được dùng làm tiền đúc nên Ngân cũng dùng để chỉ tiền tệ, ngân lượng (ngân hàng).", "Nghĩa Tiếng Việt_Xie": "bạc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金艮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "银", "Unihan_Traditional (Chữ Phồn thể)": "銀", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "ngân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ kim loại bạc hoặc tiền bạc, cũng có thể làm định ngữ chỉ màu sắc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顆', '{"9000": "", "Chữ Trung Quốc": "顆", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 頁 | Số nét | 17 | nét | 果 | quả | biểu âm | 頁 | hiệt | biểu nghĩa | đầu, hình tròn | 顆 là chữ hình thanh (psc): 果 (Quả, biểu âm) + 頁 (Hiệt, biểu nghĩa: đầu/hình tròn như đầu). Bộ 頁 gợi hình dạng tròn nhỏ; 果 cung cấp âm đọc (kē). Tiểu triện còn lưu.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 顆 (hình thanh): 果 (biểu âm) + 頁 (hình tròn/đầu, biểu nghĩa). Dùng làm lượng từ chỉ các vật nhỏ hình tròn: hạt, viên thuốc, ngôi sao, giọt nước mắt. Tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Quả (1001) Hiệt (181)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Quả (số 1001 - kết quả/ 果 /chỉ âm) ở bên trái bộ Hiệt (số 181 - cái đầu/ 頁 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quả chỉ âm, bộ Hiệt chỉ ý. Khỏa vốn chỉ cái đầu nhỏ. Mở rộng được dùng làm lượng từ đếm các vật nhỏ, hình tròn tròn như hột, viên, hạt (nhất khỏa - một viên).", "Nghĩa Tiếng Việt_Xie": "ngũ cốc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰果頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "颗", "Unihan_Traditional (Chữ Phồn thể)": "顆", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "khỏa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường làm lượng từ đứng trước danh từ chỉ các vật nhỏ hình tròn. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彈', '{"9000": "", "Chữ Trung Quốc": "彈", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cung (057) Đơn (1271)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Cung (số 057 - cây cung/ 弓 /chỉ ý) ở bên trái chữ Đơn (số 1271 - chiếc, một mình/ 單 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đơn chỉ âm, bộ Cung chỉ ý. Đọc là Đạn mang ý nghĩa là viên đạn, mũi tên bắn ra từ cung (viên đạn, đạn dược). Đọc là Đàn mang ý nghĩa là gảy, đánh, gõ, bật (đàn cầm, đàn tấu).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰弓單", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "單", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弓", "Unihan_Simplified (Chữ Giản thể)": "弹", "Unihan_Traditional (Chữ Phồn thể)": "彈", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楊', '{"9000": "", "Chữ Trung Quốc": "楊", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Dương (1134)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây cối/ 木 /chỉ ý) ở bên trái chữ Dương (số 1134 - rực rỡ/ 昜 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Dương chỉ âm, bộ Mộc chỉ ý. Dương là cây dương, cây dương liễu (bạch dương). Dương cũng là một họ phổ biến.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木昜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杨", "Unihan_Traditional (Chữ Phồn thể)": "楊", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顧', '{"9000": "", "Chữ Trung Quốc": "顧", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 頁 | Số nét | 21 | nét | 雇 | cố | biểu âm | thuê mướn (cho âm) | 頁 | hiệt | biểu nghĩa | đầu, trang (gợi hành động quay đầu nhìn lại) | 顧 là chữ hình thanh: 雇 (cố) biểu âm, 頁 (hiệt — đầu) biểu nghĩa gợi hành động quay đầu nhìn lại. Chữ hình thanh điển hình của nhóm bộ 頁.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Theo Wiktionary, 顧 = 雇 (cố, biểu âm) + 頁 (hiệt — đầu, biểu nghĩa). Nghĩa gốc là ngoảnh đầu nhìn lại; mở rộng thành: chăm sóc, quan tâm, đến thăm, coi trọng. Kim văn và tiểu triện đã ghi nhận dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cố (1762) Hiệt (181)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Cố (số 1762 - thuê mướn/chim cố/ 雇 /chỉ âm) ở bên trái bộ Hiệt (số 181 - cái đầu/ 頁 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cố chỉ âm, bộ Hiệt chỉ ý. Cố là quay đầu lại nhìn, đoái nhìn (nhìn cố, chiếu cố, cố thức).", "Nghĩa Tiếng Việt_Xie": "ngoảnh, ngoái nhìn, đoái", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰雇頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "顾", "Unihan_Traditional (Chữ Phồn thể)": "顧", "Pinyin_Xie": "gù", "Âm Hán Việt_Xie": "cố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước tân ngữ để chỉ hành động nhìn lại hoặc quan tâm chăm sóc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搥', '{"9000": "", "Chữ Trung Quốc": "搥", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Truy (1767)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Truy (số 1767 - đuổi theo/ 追 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Truy chỉ âm, bộ Thủ chỉ ý. Trùy là dùng tay để đánh, đập, nện, đấm (trùy đả, trùy hung - đấm ngực). (Giản thể thường dùng chữ Chùy 捶).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌追", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "追", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帶', '{"9000": "", "Chữ Trung Quốc": "帶", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cân (050) Mịch (014)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ hội ý tạo thành hình cái đai áo được làm bằng vải để thắt quanh bụng: Vải là bộ Cân (số 050/ 巾), thắt buộc trùm qua lưng là bộ Mịch (số 014/ 冖), và phía trên (卅) là hình cái đai. Giải thích sự chuyển ý: Đái là cái đai áo, dây dải thắt lưng (đai đái, ngọc đái). Mở rộng mang nghĩa là vùng đất (địa đái, nhiệt đới), hoặc mang theo bên mình (đái tẩu - mang đi).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "带", "Unihan_Traditional (Chữ Phồn thể)": "帶", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碼', '{"9000": "", "Chữ Trung Quốc": "碼", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 石 | Số nét | 15 | nét | 石 | thạch | biểu nghĩa | đá | 馬 | mã | biểu âm | 碼 = 石 (Thạch, biểu nghĩa: đá) + 馬 (Mã, biểu âm); chữ hình thanh. Bộ Thạch gốc chỉ quả cân đá dùng đo lường, phần 馬 cho âm đọc mǎ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Chữ hình thanh: 石 (đá, biểu nghĩa) + 馬 (biểu âm). 碼 ban đầu chỉ quả cân bằng đá trong hệ thống đo lường. Về sau nghĩa mở rộng thành ''số, mã số, ký hiệu'', và trong tiếng Anh-Hán là ''yard'' (đơn vị đo chiều dài). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thạch (112) Mã (187)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thạch (số 112 - hòn đá/ 石 /chỉ ý) ở bên trái chữ Mã (số 187 - con ngựa/ 馬 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Mã chỉ âm, bộ Thạch chỉ ý. Mã vốn là tên một loại đá quý báu (mã não). Ngày nay Mã thường dùng để chỉ con số, ký hiệu số, mã số (mật mã, mã số, xích mã - kích cỡ thước tấc).", "Nghĩa Tiếng Việt_Xie": "mã số", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "馬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "码", "Unihan_Traditional (Chữ Phồn thể)": "碼", "Pinyin_Xie": "mǎ", "Âm Hán Việt_Xie": "mã", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ các loại mã số hoặc làm lượng từ đo chiều dài trong tiếng Anh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鵝', '{"9000": "", "Chữ Trung Quốc": "鵝", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 鳥 | Số nét | 18 | nét | 我 | ngã | biểu âm | tôi, ta | 鳥 | điểu | biểu nghĩa | chim | 鵝 = 我 (Ngã, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim). Chữ hình thanh: 鳥 cho nghĩa ''chim'', 我 cho âm ''é''. Đây là chữ hình thanh chuẩn chỉ con ngỗng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | 鵝 là chữ hình thanh (psc): 我 biểu âm, 鳥 biểu nghĩa chim. Wiktionary ghi: Han compound 我+鳥, ls=psc, c1=p, c2=s. Nghĩa: ngỗng. Hán-Việt ''nga'' từ Trung cổ âm *ŋɑ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngã (062) Điểu (196)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Ngã (số 062 - tôi, ta/ 我 /chỉ âm) ở bên trái bộ Điểu (số 196 - con chim/ 鳥 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ngã chỉ âm, bộ Điểu chỉ ý. Nga là từ để chỉ những con chim nước cổ dài như ngan, ngỗng (thiên nga).", "Nghĩa Tiếng Việt_Xie": "ngỗng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰我鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "我", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "é", "Âm Hán Việt_Xie": "nga", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là danh từ chỉ con ngỗng, thường đứng độc lập hoặc làm định ngữ trong cụm danh từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髒', '{"9000": "", "Chữ Trung Quốc": "髒", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 骨 | Số nét | 21 | nét | 骨 | cốt | biểu nghĩa | xương, cốt tủy | 葬 | táng | biểu âm | chôn cất — cho âm đọc | 髒 là chữ hình thanh: 骨 (Cốt, biểu nghĩa — xương) + 葬 (Táng, biểu âm). Wiktionary xác nhận: {{Han compound|骨|t1=bone|葬|ls=psc|c1=s|c2=p}}. Nghĩa: bẩn, dơ bẩn; cũng có nghĩa cứng và mập (cổ văn). Chữ truyền thống.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 髒 là chữ hình thanh gồm 骨 (xương — biểu nghĩa) và 葬 (biểu âm, âm zāng). Nghĩa phái sinh: bẩn bởi vì xương sau khi chôn cất sẽ bẩn, ô uế. Nghĩa hiện đại thông dụng: bẩn thỉu, dơ. Dạng giản thể là 脏 (đồng âm và đồng nghĩa với 臟 — nội tạng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cốt (188) Táng (1776)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Cốt (số 188 - xương xẩu/ 骨 /chỉ ý) ở bên trái chữ Táng (số 1776 - chôn cất/ 葬 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Táng chỉ âm, bộ Cốt chỉ ý. Đọc là Tảng mang ý nghĩa là dơ bẩn, dơ dáy ô uế (tảng hắc - nhơ bẩn đen tối). Đọc là Tạng (nghĩa cổ) để chỉ lục phủ ngũ tạng (nội tạng).", "Nghĩa Tiếng Việt_Xie": "bẩn thỉu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "zāng", "Âm Hán Việt_Xie": "tạng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường đứng trước danh từ làm định ngữ hoặc đứng sau phó từ chỉ mức độ để miêu tả trạng thái không sạch sẽ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('討', '{"9000": "", "Chữ Trung Quốc": "討", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 10 | nét | 肘 | chẩu | biểu âm | khuỷu tay | 言 | ngôn | biểu nghĩa | lời nói | 討 = 肘 (Chẩu, biểu âm) + 言 (Ngôn, biểu nghĩa: lời nói); chủ yếu là chữ hình thanh. Shuowen có phân tích hội ý: 言 (lời) + 寸 (tay) — chỉnh lý bằng lời nói, nhưng phân tích hình thanh từ bộ 肘+言 được coi chuẩn hơn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | 討 chủ yếu là chữ hình thanh: 肘 (khuỷu tay, biểu âm) + 言 (lời nói, biểu nghĩa). Shuowen Jiezi giải thích theo hội ý: 言 (lời) + 寸 (tay) — ý nghĩa chỉnh trị bằng ngôn từ. Nghĩa gốc là phái quân đi trấn áp, mở rộng sang lên án, thảo luận, cầu xin. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Thốn (041)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái bộ Thốn (số 041 - tấc/pháp độ/ 寸 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hội ý. Thảo là dùng ngôn luận kết hợp với pháp độ để phán quyết trừng trị kẻ có tội (thảo phạt). Từ đó mang ý nghĩa đòi hỏi (thảo nợ), hay bàn bạc xem xét sự việc cho rõ ràng (thảo luận, bàn thảo).", "Nghĩa Tiếng Việt_Xie": "đánh, trừng phạt người có tội; dò xét; đòi lại của cải; bỏ đi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言寸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "讨", "Unihan_Traditional (Chữ Phồn thể)": "討", "Pinyin_Xie": "tǎo", "Âm Hán Việt_Xie": "thao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đi kèm tân ngữ để biểu thị việc đòi hỏi, xin xỏ hoặc chinh phạt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('級', '{"9000": "", "Chữ Trung Quốc": "級", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 9 | nét | 糹 | mịch | biểu nghĩa | sợi tơ, lụa | 及 | cập | biểu âm | kịp đến, đạt tới | 級 = 糹 (Mịch, biểu nghĩa: sợi tơ) + 及 (Cập, biểu âm); chữ hình thanh — bộ 糹 chỉ liên quan tơ lụa (thứ bậc xếp theo thứ tự như các sợi tơ), 及 cho âm jí.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | Theo Wiktionary, 級 là chữ hình thanh: 糸/糹 (sợi tơ) biểu nghĩa, 及 biểu âm. Shuowen Jiezi ghi nguyên nghĩa là \"thứ tự của tơ lụa\" (絲的次第) — ý nói thứ bậc, cấp bậc sắp xếp theo trình tự như các sợi tơ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Cập (029)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái chữ Cập (số 029 - theo kịp/ 及 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cập chỉ âm, bộ Mịch chỉ ý. Sợi tơ kéo ra thì luôn phải có thứ lớp gọn gàng nếu không sẽ bị rối. Cấp là thứ bậc trên dưới, cấp bậc, cấp độ (giai cấp, đẳng cấp).", "Nghĩa Tiếng Việt_Xie": "cấp bậc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹及", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "及", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "级", "Unihan_Traditional (Chữ Phồn thể)": "級", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "cấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm danh từ chỉ thứ bậc hoặc làm lượng từ cho các bậc thang, cấp độ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('違', '{"9000": "", "Chữ Trung Quốc": "違", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辵 | Số nét | 12 | nét | 辶 | sước | biểu nghĩa | đi lại, chuyển dịch | 韋 | vi | biểu âm | 違 = 辶 (Sước, biểu nghĩa: đi lại) + 韋 (Vi, biểu âm); chữ hình thanh. Bộ 辶 gợi nghĩa rời xa, đi ngược lại; 韋 cho âm đọc gần wéi.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 違 (wéi) là chữ hình thanh: bộ 辶/辵 (đi lại) cho nghĩa — đi ngược, rời xa, vi phạm; 韋 (vi) cho âm. Wiktionary xác nhận cấu trúc Han compound ls=psc. Nghĩa gốc là đi ngược chiều, sau mở rộng sang vi phạm, bất tuân. Có tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Vi (1152)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi/ 辶 /chỉ ý) bao bên ngoài chữ Vi (số 1152 - da thú bọc lại/ 韋 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Vi (韋) chỉ âm, bộ Xước chỉ ý. (Chữ Vi 韋 vốn là hình hai bàn chân dẫm lên quảng trường ngự trụ, bước chân rời rạc ra xa). Vi (違) mang nghĩa là làm trái ngược lại, lìa xa, vi phạm (vi phạm, vi cảnh).", "Nghĩa Tiếng Việt_Xie": "Vi phạm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶韋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "违", "Unihan_Traditional (Chữ Phồn thể)": "違", "Pinyin_Xie": "wéi", "Âm Hán Việt_Xie": "vi, vy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ làm tân ngữ như vi pháp, vi quy để chỉ hành vi phạm luật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衛', '{"9000": "", "Chữ Trung Quốc": "衛", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 行 | Số nét | 15 | nét | 行 | hàng | biểu nghĩa | đường đi, tuần tra | 韋 | vi | biểu âm | (âm) | 衛 = 行 (Hàng, biểu nghĩa: đường đi, ý tuần tra bảo vệ) + 韋 (biểu âm); chữ hình thanh. Bộ 行 gợi hành động đi tuần, bảo vệ; 韋 cho âm wèi.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | 衛 là chữ hình thanh: 行 biểu nghĩa chỉ tuần tra/đi đường, 韋 biểu âm. Nghĩa gốc là ''bảo vệ, canh gác, phòng thủ''. Dạng giáp cốt văn cho thấy hình ảnh người đi xung quanh để bảo vệ. Cũng là tên nước Vệ thời Đông Chu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hành (144) Vi (1152)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hành (số 144 - ngã tư đường/ 行 /chỉ ý) được tách ra ôm lấy chữ Vi (số 1152 - trái ngược/ 韋 /chỉ âm). Cử binh lính đi bảo vệ nơi ngã tư đường phố. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Vi chỉ âm, bộ Hành chỉ ý. Vệ vốn là đi lại tuần tra cảnh giới. Nghĩa mở rộng là giữ gìn cho được an toàn, che chở, bảo vệ (bảo vệ, vệ quốc, phòng vệ).", "Nghĩa Tiếng Việt_Xie": "canh gác", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴行韋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "行", "Unihan_Simplified (Chữ Giản thể)": "卫", "Unihan_Traditional (Chữ Phồn thể)": "衛", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "vệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động bảo vệ hoặc làm danh từ chỉ lực lượng phòng vệ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('記', '{"9000": "", "Chữ Trung Quốc": "記", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 10 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn ngữ | 己 | kỷ | biểu âm | bản thân, mình | 記 = 言 (Ngôn, biểu nghĩa: lời nói) + 己 (Kỷ, biểu âm); chữ hình thanh — bộ 言 chỉ ngôn ngữ, chữ viết, 己 cho âm jì.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 記 là chữ hình thanh: 言 (lời nói, ghi chép) biểu nghĩa, 己 biểu âm. Nguyên nghĩa là ghi lại bằng lời/chữ để nhớ — ghi chép, lưu giữ thông tin. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Kỷ (049)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Kỷ (số 049 - bản thân/ 己 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Kỷ chỉ âm, bộ Ngôn chỉ ý. Ký là đem lời nói ghi chép vào sổ sách (ghi ký, nhật ký). Mở rộng là khắc ghi vào trong lòng (nhớ ký, ký ức).", "Nghĩa Tiếng Việt_Xie": "nhớ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "记", "Unihan_Traditional (Chữ Phồn thể)": "記", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kí, ký", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ biểu thị hành động ghi nhớ hoặc làm danh từ chỉ dấu vết, bài ký. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('勞', '{"9000": "", "Chữ Trung Quốc": "勞", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hỏa (086) Mịch (014) Lực (019)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hai bộ Hỏa (số 086 - lửa/ 火) nằm trên bộ Mịch (số 014 - trùm che/ 冖) và dưới cùng là bộ Lực (số 019 - sức mạnh/ 力). Đem hết sức lực (lực) ra làm việc vã mồ hôi nhễ nhại dưới tiết trời cheo leo nắng nóng như thiêu (hai ngọn lửa dưới một cái mái hiên). Giải thích sự chuyển ý: Đây là chữ Hội ý. Lao là xuất sức làm việc một cách cực nhọc vất vả (lao động, lao lực, cần lao).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "劳", "Unihan_Traditional (Chữ Phồn thể)": "勞", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('機', '{"9000": "", "Chữ Trung Quốc": "機", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Cơ (1649)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây cối/ 木 /chỉ ý) ở bên trái chữ Cơ (số 1649 - mầm mống/ 幾 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cơ (幾) chỉ âm, bộ Mộc chỉ ý. Cơ vốn là cái lẫy bằng gỗ dùng để bắn nỏ. Từ đó mở rộng để chỉ máy móc nói chung (cơ khí, phi cơ). Cũng chỉ những điểm the chốt, mầm mống, dịp may mắn (cơ hội, thời cơ).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木幾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "机", "Unihan_Traditional (Chữ Phồn thể)": "機", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('壓', '{"9000": "", "Chữ Trung Quốc": "壓", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Yếm (027) Thổ (032)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Yếm (số 027 - ghét/chán/ 厭 /chỉ âm) nằm trên bộ Thổ (số 032 - đất/ 土 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Yếm chỉ âm, bộ Thổ chỉ ý. Áp là dùng sức từ trên cao đè mạnh xuống mặt đất, đè nén, ép buộc (áp lực, áp bức, trấn áp).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>厭土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "压", "Unihan_Traditional (Chữ Phồn thể)": "壓", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艦', '{"9000": "", "Chữ Trung Quốc": "艦", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 舟 | Số nét | 20 | nét | 舟 | chu | biểu nghĩa | thuyền, tàu | 監 | giám | biểu âm | giám sát — cho âm | 艦 = 舟 (Chu, biểu nghĩa: thuyền/tàu) + 監 (Giám, biểu âm). Chữ hình thanh: 舟 chỉ loại phương tiện đường thuỷ, 監 cho âm.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Wiktionary xác nhận 艦 là chữ hình thanh (psc): 舟 (chu — thuyền) cho nghĩa, 監 (giám) cho âm. Nghĩa gốc và hiện tại: chiến hạm, tàu chiến. Đây là chữ truyền thống, giản thể viết giống (艦 không có dạng giản thể phổ biến). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chu (137) Giám (108)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Chu (số 137 - chiếc thuyền/ 舟 /chỉ ý) ở bên trái chữ Giám (số 108 - xem xét/gương/ 監 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Giám chỉ âm, bộ Chu chỉ ý. Hạm là tàu chiến lớn có lầu cao, có trang bị vũ khí dùng trong chiến tranh trên biển (chiến hạm, hạm đội).", "Nghĩa Tiếng Việt_Xie": "tàu thủy", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟監", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "監", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舰", "Unihan_Traditional (Chữ Phồn thể)": "艦", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "hạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ quân sự để tạo thành danh từ ghép như chiến hạm, quân hạm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('兟', '{"9000": "", "Chữ Trung Quốc": "兟", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tiên (010)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hai chữ Tiên (số 010 - trước/hiên ngang/ 先) viết cạnh nhau. Hai người đang tranh nhau tiến lên phía trước. Giải thích sự chuyển ý: Đây là chữ Hội ý. Sân (Tân) là đi về phía trước, tiến lên phía trước (sân sân). Chữ này là phần bên trên làm âm đọc và làm gốc nghĩa cho chữ Tán (贊).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴先", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "兟", "Unihan_Traditional (Chữ Phồn thể)": "兟", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贊', '{"9000": "", "Chữ Trung Quốc": "贊", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 19 | nét | 㚘 | biểu nghĩa | hai người (hội ý cũ) | 貝 | bối | biểu nghĩa/biểu âm | tiền của (ý); 兟 làm biểu âm trong dạng hiện đại | 贊 có hai lớp cấu tạo. Dạng gốc 賛: 㚘 (hai người) + 貝 (tiền) = hội ý — giúp đỡ bằng tiền. Dạng hiện đại: 兟 (biểu âm) + 貝 (biểu nghĩa: tiền của); chuyển sang hình thanh.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | Theo Wiktionary, 贊 vốn là 賛, gồm 㚘 (hai người) + 貝 (tiền của) theo hội ý — ý nghĩa \"giúp đỡ bằng tài chính\". Dạng hiện đại tái cấu trúc thành 兟 (biểu âm) + 貝 (biểu nghĩa: tiền của), trở thành hình thanh. Nghĩa mở rộng: giúp đỡ (to assist), khen ngợi (to praise), giới thiệu (to introduce/announce). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tân (1792) Bối (154)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Sân/Tân (số 1792 - tiến lên/ 兟 /chỉ âm) nằm trên bộ Bối (số 154 - tiền bạc/ 貝 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Sân/Tân chỉ âm, bộ Bối chỉ ý. Tán vốn là mang lễ vật tiến dâng lên bề trên để xin yết kiến. Từ việc yết kiến dâng lễ vật mang ý nghĩa là giúp đỡ lẫn nhau (tán trợ). Cũng mang nghĩa là đồng ý, khen ngợi (tán thành, tán dương, ca tán).", "Nghĩa Tiếng Việt_Xie": "Giống", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>兟貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "zàn", "Âm Hán Việt_Xie": "tán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ biểu thị sự đồng ý, ủng hộ hoặc ca ngợi một điều gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侖', '{"9000": "", "Chữ Trung Quốc": "侖", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tập (009) Sách (013)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tập/Nhập (số 009 - tụ tập, gộp lại/ 亼) ở trên bộ Sách (số 013 - cuốn sách thẻ tre/ 冊). Học trò tụ tập lại dưới một mái nhà nghe thầy giảng giải kinh sách. Giải thích sự chuyển ý: Đây là chữ Hội ý. Luân vốn mang nghĩa là suy nghĩ, nghiền ngẫm kinh sách, hiểu thấu lý lẽ mọi việc. Chữ Luân (侖) đóng vai trò là một chữ gốc để tạo nên hàng loạt chữ khác.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>亼𠕁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠕁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亼", "Unihan_Simplified (Chữ Giản thể)": "仑", "Unihan_Traditional (Chữ Phồn thể)": "侖", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輪', '{"9000": "", "Chữ Trung Quốc": "輪", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 車 | Số nét | 15 | nét | 車 | xa | biểu nghĩa | xe ngựa | 侖 | lỏn | biểu âm | 輪 = 車 (Xa, biểu nghĩa: xe ngựa) + 侖 (Lỏn, biểu âm); chữ hình thanh. Phần 車 cho biết liên quan tới xe cộ, phần 侖 cho âm đọc. Nghĩa gốc là bánh xe tròn xoay.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | 輪 là chữ hình thanh: 車 (xa, biểu nghĩa xe ngựa) + 侖 (lỏn, biểu âm). Nghĩa gốc là bánh xe; mở rộng thành bất kỳ vật hình tròn xoay, và động từ luân phiên, xoay vòng. Dạng tiểu triện và Lục thư thông lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xa (159) Luân (1794)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xa (số 159 - xe cộ/ 車 /chỉ ý) ở bên trái chữ Luân (số 1794 - lý lẽ/ 侖 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Luân (侖) chỉ âm, bộ Xa chỉ ý. Luân là cái bánh xe (xa luân). Cái bánh xe luôn xoay tròn nên Luân mang nghĩa là luân phiên thay đổi nhau (luân hồi, luân phiên, luân chuyển).", "Nghĩa Tiếng Việt_Xie": "bánh xe", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車侖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "侖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "轮", "Unihan_Traditional (Chữ Phồn thể)": "輪", "Pinyin_Xie": "lún", "Âm Hán Việt_Xie": "luân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Lượng từ | 量词 | Thường làm danh từ chỉ bánh xe hoặc lượng từ cho các vật hình tròn như mặt trời, mặt trăng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('壘', '{"9000": "", "Chữ Trung Quốc": "壘", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tư (028) Thổ (032)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm ba chữ Tư (số 028 - riêng tư/người/ 厶) viết chồng lên nhau tạo thành chữ Toái (畾 - chữ cổ), nằm trên bộ Thổ (số 032 - đất/ 土). Đây là hình tượng những khối đất được đắp chất chồng lên nhau. Giải thích sự chuyển ý: Lũy là đắp đất làm tường vách vững chắc phòng thủ trong quân sự (chiến lũy, đồn lũy). Mở rộng là chồng chất lên nhau (lũy tích - tích lũy).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>畾土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垒", "Unihan_Traditional (Chữ Phồn thể)": "壘", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('參', '{"9000": "", "Chữ Trung Quốc": "參", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chẩn (1659) Lũy (1796)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Chẩn/Tam (số 1659 - mái tóc dài/mặt trời tỏa sáng/ 㐱) nằm trên chữ Lũy viết giảm nét (số 1796 - đắp thành cục/ 畾 -> 𠫓). Giải thích sự chuyển ý: Đọc là Sâm là chỉ củ nhân sâm, rễ sâm kết thành các cục mấu tròn, có các tua rễ dài mọc tua tủa như bộ tóc. Đọc là Tham với ý nghĩa là xem xét, đóng góp ý kiến dự phần vào một việc (tham gia, tham chiếu, tham luận).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>厽㐱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厽", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('興', '{"9000": "", "Chữ Trung Quốc": "興", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 臼 | Số nét | 16 | nét | 舁 | dư | biểu nghĩa | nhiều tay cùng nâng | 型 | hình | biểu âm | 興 = 舁 (Dư, biểu nghĩa: nhiều tay cùng nâng) + 型 (Hình, biểu âm). Chữ hình thanh. Giáp cốt văn vẽ hình nhiều bàn tay cùng nâng vật nặng — gợi nghĩa phát khởi, hưng thịnh. Có đầy đủ giáp cốt văn, kim văn, đại triện, tiểu triện.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary: 興 là chữ hình thanh gồm 舁 (biểu nghĩa: nhiều tay cùng nâng) và 型 (biểu âm). Nghĩa gốc trong giáp cốt văn: nhiều người cùng nâng vật — từ đó mở rộng sang phát khởi, hưng thịnh, phấn chấn. Có đủ các giai đoạn từ giáp cốt đến tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Đồng (241) Dữ (895)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Đồng (số 241 - cùng nhau/ 同) nằm ở bên trong chữ Dữ (số 895 - tham dự/ 與 - ở đây lấy phần bao ngoài là 舁 và 冂). Cùng nhau (đồng) góp sức, tương trợ lẫn nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Cùng nhau tương trợ, hỗ trợ thì mọi việc sẽ phát triển mạnh mẽ. Đọc là Hưng mang nghĩa dấy lên, phát động làm cho thịnh vượng (hưng thịnh, hưng phấn). Đọc là Hứng chỉ sự thích thú, cảm hứng (hứng thú).", "Nghĩa Tiếng Việt_Xie": "Xing", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "兴", "Unihan_Traditional (Chữ Phồn thể)": "興", "Pinyin_Xie": "xìng", "Âm Hán Việt_Xie": "hưng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ hứng thú hoặc tính từ chỉ sự phấn khởi trong các từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('願', '{"9000": "", "Chữ Trung Quốc": "願", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 頁 | Số nét | 19 | nét | 原 | nguyên | biểu âm | nguồn gốc, nguyên thủy | 頁 | hiệt | biểu nghĩa | đầu, trang — chỉ tâm tư, lòng người | 願 = 原 (Nguyên, biểu âm) + 頁 (Hiệt, biểu nghĩa: đầu, lòng người). Chữ hình thanh: 頁 biểu nghĩa ý nguyện trong đầu, 原 cho âm đọc. Chữ truyền thống, giản thể viết 愿.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lệ thư | Theo Wiktionary, 願 là chữ hình thanh (psc): bộ 頁 biểu nghĩa (đầu, tâm tư), thành phần 原 biểu âm. Nghĩa gốc là mong muốn, nguyện vọng, ý chí. Từ tiếng Việt Hán-Việt ''nguyện'' (như trong ''nguyện vọng'', ''ước nguyện'') có nguồn trực tiếp từ chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nguyên (096) Hiệt (181)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nguyên (số 096 - cánh đồng/nguồn gốc/ 原 /chỉ âm) ở bên trái bộ Hiệt (số 181 - cái đầu/ 頁 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nguyên chỉ âm, bộ Hiệt chỉ ý. Nguyện là lòng mong cầu, sự mong muốn, hy vọng được đáp ứng (tâm nguyện, nguyện vọng, tình nguyện).", "Nghĩa Tiếng Việt_Xie": "ước", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰原頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "原", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "yuàn", "Âm Hán Việt_Xie": "nguyện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ động từ | 能愿动词 | Động từ | 动词 | Danh từ | 名词 | Thường làm trợ động từ đứng trước động từ khác để biểu thị ý muốn hoặc nguyện vọng. | Trợ động từ | 能愿动词 | Đứng trước động từ chính để nêu khả năng, ý muốn hoặc sự cho phép: 会, 能, 可以, 想, 要. Phủ định đặt 不 trước chính nó — 不能去. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('斷', '{"9000": "", "Chữ Trung Quốc": "斷", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kế (1066) Cân (069)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Kế (số 1066 - nối tiếp/ 㡭) ở bên trái bộ Cân (số 069 - cái búa, cái rìu/ 斤). Dùng cái rìu (cân) chặt đứt sự liên tục, nối tiếp (kế). Giải thích sự chuyển ý: Đây là chữ Hội ý. Đoạn là đứt gãy, làm cho đứt đoạn (đứt đoạn, đoạn tuyệt). Mở rộng mang nghĩa là dứt khoát, định đoạt rõ ràng (phán đoạn, quả đoạn).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰㡭斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㡭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "斤", "Unihan_Simplified (Chữ Giản thể)": "断", "Unihan_Traditional (Chữ Phồn thể)": "斷", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貫', '{"9000": "", "Chữ Trung Quốc": "貫", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 11 | nét | 毌 | biểu âm | 貝 | bối | biểu nghĩa | vỏ sò, tiền cổ | 貫 = 毌 (biểu âm, cho âm guàn) + 貝 (Bối, biểu nghĩa: tiền/vỏ sò). Chữ hình thanh. Chú thích Wiktionary: 毌 có thể đồng thời biểu thị hình ảnh dây xâu đồng tiền.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Theo Wiktionary, 貫 là chữ hình thanh: 毌 biểu âm (guàn), 貝 biểu nghĩa (vỏ sò/tiền). Ngoài ra 毌 có thể gợi hình dây xâu xuyên qua đồng tiền — nghĩa gốc là một xâu 1000 đồng tiền. Tiểu triện đã ghi nhận hình thể này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Quán (771) Bối (154)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Quán (số 771 - xâu suốt/ 毌) ở trên bộ Bối (số 154 - tiền bạc/ 貝). Hình ảnh dùng dây xâu các đồng tiền lại với nhau. Giải thích sự chuyển ý: Đây là chữ Hội ý. Quán là dây xâu tiền, xâu chuỗi liên tiếp (tiền quán). Từ hình ảnh xâu chuỗi, Quán mang ý nghĩa là xuyên qua, nối liền (quán xuyến, quán thông, nhất quán).", "Nghĩa Tiếng Việt_Xie": "bởi vì", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>毌貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "贯", "Unihan_Traditional (Chữ Phồn thể)": "貫", "Pinyin_Xie": "guàn", "Âm Hán Việt_Xie": "quan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động xuyên qua hoặc làm danh từ chỉ quan tiền thời cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('慣', '{"9000": "", "Chữ Trung Quốc": "慣", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (061) Quán (1814)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tâm (số 061 - trái tim/ 忄/chỉ ý) ở bên trái chữ Quán (số 1814 - xuyên suốt/ 貫 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quán chỉ âm, bộ Tâm chỉ ý. Những suy nghĩ (tâm) hoặc việc làm lặp đi lặp lại xuyên suốt sẽ tạo thành thói quen. Quán là thói quen, tập quán (tập quán, thói quen).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄貫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "惯", "Unihan_Traditional (Chữ Phồn thể)": "慣", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飽', '{"9000": "", "Chữ Trung Quốc": "飽", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 食 | Số nét | 13 | nét | 食 | thực | biểu nghĩa | thức ăn, ăn | 包 | bao | biểu âm | bao bọc | 飽 = 食 (Thực, biểu nghĩa: thức ăn/ăn) + 包 (Bao, biểu âm); chữ hình thanh. Bộ 食 chỉ nghĩa liên quan đến ăn uống; 包 cho âm bǎo. Bụng chứa đầy thức ăn = no.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 飽 là chữ hình thanh: 食 (thức ăn, ăn) biểu nghĩa, 包 biểu âm. Wiktionary ghi chú: bộ 食 xác định nghĩa ăn uống, và 包 (bao bọc) gợi ý bao gói trong ngữ cảnh thực phẩm. Nghĩa: no bụng. Mở rộng: đầy đủ, thoả mãn. Chữ truyền thống, dạng giản thể cũng là 饱. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thực (184) Bao (211)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thực (số 184 - thức ăn/ 食/飠/chỉ ý) ở bên trái chữ Bao (số 211 - bao bọc/ 包 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Bao chỉ âm, bộ Thực chỉ ý. Bão là ăn uống đầy đủ no nê, no bụng không đói (ôn bão - ấm no).", "Nghĩa Tiếng Việt_Xie": "no bụng; hạt gạo mẩy; đủ, nhiều, từng trải; thoả thích", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "饱", "Unihan_Traditional (Chữ Phồn thể)": "飽", "Pinyin_Xie": "bǎo", "Âm Hán Việt_Xie": "bão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ đứng sau động từ làm bổ ngữ kết quả hoặc đứng trước danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紗', '{"9000": "", "Chữ Trung Quốc": "紗", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 10 | nét | 紗 | sa | tượng hình | sợi tơ mỏng, vải mỏng | 紗 thuộc bộ 糸 (mịch — tơ sợi), chỉ loại vải mỏng như sợi. Dữ liệu CHISE không cung cấp cây thành phần chi tiết. Nhiều âm đọc theo phương ngữ. Chưa xác định hình thanh hay hội ý từ anchor.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 紗 nghĩa là sợi (yarn), vải thưa mỏng (gauze), the/lụa mỏng. Thuộc bộ 糸 (tơ). Wiktionary ghi đầy đủ Quan Thoại và các phương ngữ. Từ Hán-Việt \"sa\" dùng trong \"vải sa\", \"màn sa\". Cùng bộ với nhiều chữ vải vóc. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Thiểu (042)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái chữ Thiểu (số 042 - ít, nhỏ/ 少 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thiểu chỉ âm, bộ Mịch chỉ ý. Thiểu là nhỏ ít, Mịch là sợi tơ. Sa là một thứ lụa, vải được dệt mỏng và mịn màng (vải sa, sa sương).", "Nghĩa Tiếng Việt_Xie": "sợi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹少", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "少", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "纱", "Unihan_Traditional (Chữ Phồn thể)": "紗", "Pinyin_Xie": "shā", "Âm Hán Việt_Xie": "sa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp thành từ ghép như sa lưới, thiết sa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('細', '{"9000": "", "Chữ Trung Quốc": "細", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 11 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, chỉ | 囟 | tín | biểu âm | (thóp đầu trẻ em — chỉ đóng vai biểu âm) | 細 = 糸 (Mịch, biểu nghĩa: sợi tơ mảnh) + 囟 (Tín, biểu âm); chữ hình thanh. Lưu ý: phần bên phải bị biến dạng thành hình tương tự 田 sau nhà Hán, nhưng không có quan hệ nghĩa với 田 (ruộng).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Chữ hình thanh: 糸 (sợi tơ) là thành phần biểu nghĩa — sợi tơ mảnh gợi ý nghĩa ''nhỏ, mịn, tinh tế''. 囟 là thành phần biểu âm. Sau thời Hán, phần biểu âm bị biến dạng thành hình dạng giống 田, nhưng đây là biến dạng chữ viết, không phải thay đổi ngữ nghĩa — 田 (ruộng) hoàn toàn vô quan hệ với 細. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Điền (097)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái bộ Điền (số 097 - thửa ruộng/ 田 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Điền chỉ âm, bộ Mịch chỉ ý. Tế là nhỏ nhặt, nhỏ bé, mịn màng (nhỏ tế, mảnh tế, tế nhị). Phàm những việc có quy mô nhỏ bé đều gọi là Tế (tiểu tế).", "Nghĩa Tiếng Việt_Xie": "nhỏ bé; tinh xảo; mịn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹田", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "田", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "细", "Unihan_Traditional (Chữ Phồn thể)": "細", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "tới", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ bổ nghĩa cho danh từ để chỉ tính chất nhỏ, mịn hoặc kỹ lưỡng của sự vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('凍', '{"9000": "", "Chữ Trung Quốc": "凍", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Băng (015) Đông (335)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Băng (số 015 - nước đá/ 冫 /chỉ ý) ở bên trái chữ Đông (số 335 - phương đông/ 東 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đông chỉ âm, bộ Băng chỉ ý. Đống là nước đóng băng lại (đống kết, đông đống). Cũng mang nghĩa là lạnh giá (giá đống).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冫東", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "東", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冫", "Unihan_Simplified (Chữ Giản thể)": "冻", "Unihan_Traditional (Chữ Phồn thể)": "凍", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涼', '{"9000": "", "Chữ Trung Quốc": "涼", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (085) Kinh (008)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 085 - dòng nước/ 氵/chỉ ý) ở bên trái chữ Kinh (số 008 - kinh đô/ 京 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Kinh chỉ âm, bộ Thủy chỉ ý. Lương là cảm giác mát mẻ, mát lạnh thoang thoảng hơi nước (thanh lương, lương phong - gió mát). Tương tự chữ Lương có bộ Băng (凉) thường được dùng thay thế trong Giản thể.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵京", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "京", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "凉", "Unihan_Traditional (Chữ Phồn thể)": "涼", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑽', '{"9000": "", "Chữ Trung Quốc": "鑽", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 27 | nét | 釒 | kim | biểu nghĩa | kim loại (bộ thủ bên trái của 金) | 贊 | tán | biểu âm | âm zuān/zuàn/tán | 鑽 = 釒 (Kim, biểu nghĩa: kim loại) + 贊 (Tán, biểu âm); chữ hình thanh. Bộ 釒 là dạng viết bên trái của 金, chỉ dụng cụ kim loại; 贊 cung cấp âm; cả chữ chỉ khoan, mũi khoan.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 鑽 là chữ hình thanh, ghép 釒 (kim, kim loại, biểu nghĩa) với 贊 (tán, biểu âm). Nghĩa là khoan, đục (zuān); cũng là mũi khoan, mũi dùi (zuàn). Theo Wiktionary. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (167) Tán (1793)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 167 - kim loại/ 金 /chỉ ý) ở bên trái chữ Tán (số 1793 - khen ngợi/ 贊 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tán chỉ âm, bộ Kim chỉ ý. Toản là cái dùi, cái khoan làm bằng kim loại (toản đầu - mũi khoan). Đọc là Toàn là động từ xuyên, dùi, khoan lỗ (toàn mộc - khoan gỗ). Đi sâu vào nghiên cứu môn gì đó cũng gọi là Toàn (toàn nghiên).", "Nghĩa Tiếng Việt_Xie": "Máy khoan", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金贊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "zuān", "Âm Hán Việt_Xie": "toản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động khoan đục hoặc danh từ chỉ dụng cụ khoan. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('勸', '{"9000": "", "Chữ Trung Quốc": "勸", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Quán (1357) Lực (019)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Quán (số 1357 - con cò/ 雚 /chỉ âm) ở bên trái bộ Lực (số 019 - sức lực/ 力 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quán chỉ âm, bộ Lực chỉ ý. Khuyến là khích lệ, động viên ra sức làm việc (khuyến khích, khuyến học). Mở rộng là khuyên bảo nhau làm việc thiện (khuyên can, khuyến thiện).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰雚力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "力", "Unihan_Simplified (Chữ Giản thể)": "劝", "Unihan_Traditional (Chữ Phồn thể)": "勸", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('處', '{"9000": "", "Chữ Trung Quốc": "處", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 虍 | Số nét | 11 | nét | 虍 | hô | biểu âm | da hổ, hổ | 夂 | truy | biểu nghĩa | chân, bước chân | 几 | cơ | biểu nghĩa | bàn, ghế | 處 = 虍 (Hô, biểu âm) + 夂 (Truy, biểu nghĩa: bước chân) + 几 (Cơ, biểu nghĩa: bàn/ghế nhỏ). Chữ hình thanh: 虍 cho âm; 夂 + 几 gợi hình ảnh người dừng chân, ngồi xuống bàn — nơi chốn, chỗ ở lại. Có hình kim văn, chữ xưa có nghĩa gốc là dừng lại, cư trú.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Theo Wiktionary, 處 là chữ hình thanh: 虍 biểu âm; 夂 và 几 biểu nghĩa (dừng chân bên bàn ghế). Nghĩa gốc: ở lại, cư trú; dẫn sang các nghĩa nơi chốn (chỗ, địa điểm), xử lý (處理), ở một mình (獨處). Chữ có hình kim văn (đồng khắc), là chữ khá cổ. Tiếng Hán hiện đại dùng dạng giản 处 nhưng phồn thể 處 vẫn thấy ở Đài Loan, Hồng Kông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hổ (141) Xử (035)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hổ (số 141 - con hổ/ 虍) ôm lấy chữ Xử (số 035 - nương thân/ 処 - được tạo bởi chữ 夂 và 几). Giải thích sự chuyển ý: Đây là chữ Hội ý. Đọc là Xứ với ý nghĩa là một nơi chốn, địa điểm, chỗ ở (trụ xứ, nơi xứ). Đọc là Xử mang ý nghĩa là giải quyết, ứng xử, ở lại (cư xử, xử lý).", "Nghĩa Tiếng Việt_Xie": "Tại", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虍処", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "処", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虍", "Unihan_Simplified (Chữ Giản thể)": "处", "Unihan_Traditional (Chữ Phồn thể)": "處", "Pinyin_Xie": "chù", "Âm Hán Việt_Xie": "xử, xứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ địa điểm hoặc đơn vị, bộ phận hành chính. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘿', '{"9000": "", "Chữ Trung Quốc": "蘿", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 艸 | Số nét | 22 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật dây leo | 羅 | la | biểu âm | lưới, la liệt | 蘿 = 艸 (Thảo, biểu nghĩa: thực vật) + 羅 (La, biểu âm); chữ hình thanh. Bộ thảo chỉ đây là loài cây dây leo, phần 羅 (la) cung cấp âm đọc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Chữ hình thanh: bộ 艸 (cỏ/thực vật) biểu nghĩa, 羅 biểu âm. 蘿 chỉ các loài thực vật leo bò (trailing plants), điển hình là 蘿蔔 (củ cải). Tiểu triện và Lục thư thông xác nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (140) La (1559)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 140 - cây cỏ/ 艹 /chỉ ý) ở trên chữ La (số 1559 - cái lưới/ 羅 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ La chỉ âm, bộ Thảo chỉ ý. La là tên một loài cỏ cây dây leo, thân mọc bò quấn quýt chằng chịt như cái lưới (đằng la).", "Nghĩa Tiếng Việt_Xie": "một loài nấm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹羅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萝", "Unihan_Traditional (Chữ Phồn thể)": "蘿", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "lá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ các loài cây dây leo bám vào cây khác hoặc dùng trong tên gọi củ cải. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔔', '{"9000": "", "Chữ Trung Quốc": "蔔", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 艸 | Số nét | 14 | nét | 艸 | tháu | biểu nghĩa | cây cỏ | 匐 | bặc | biểu âm | bò sát đất | 蔔 = 艸/艹 (Tháu, biểu nghĩa: cây cỏ) + 匐 (Bặc, biểu âm); chữ hình thanh (psc). Bộ cỏ gợi thực vật, 匐 cho âm. Chủ yếu dùng trong 蘿蔔 (củ cải).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 蔔 (bó/bo): chữ hình thanh, gồm 艸 (cây cỏ, biểu nghĩa) và 匐 (Bặc, biểu âm). Chủ yếu xuất hiện trong 蘿蔔 (củ cải, luo bo) và 薝蔔 (gardenia). Âm vernacular là bo (nhẹ) trong từ ghép. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (140) Bặc (1840)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 140 - cây cỏ/ 艹 /chỉ ý) nằm trên chữ Bặc/Phục (số 1840 - bò trườn/ 匐 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Bặc (Phục) chỉ âm, bộ Thảo chỉ ý. Bặc là tên gọi của một loại rau củ. Ghép với chữ La tạo thành La Bặc (蘿蔔) nghĩa là củ cải trắng.", "Nghĩa Tiếng Việt_Xie": "(xem: đảm bặc 薝蔔)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹匐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác để tạo thành danh từ chỉ các loại củ cải như la bặc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藝', '{"9000": "", "Chữ Trung Quốc": "藝", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 艸 | Số nét | 18 | nét | 藝 | nghệ | tượng hình | nghệ thuật, kỹ năng trồng trọt | 藝 ban đầu được viết là 埶 (người quỳ trồng cây). Bộ 艸 (cỏ/thực vật) và 云 được thêm vào muộn hơn. Dữ liệu IDS hiện tại không phân rã thành các thành phần riêng biệt; đây là chữ phức hợp lịch sử phát triển qua nhiều giai đoạn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Lục thư thông | Nguyên gốc là chữ 埶: người quỳ gối (𠂉) cầm cây con (木/艸) trồng xuống đất (土), mang nghĩa ''trồng trọt, gieo trỉa''. Bộ 艸 (cỏ) và phần 云 được bổ sung muộn. Từ nghĩa gốc ''trồng cây'' mở rộng sang ''kỹ năng, nghề nghiệp'', rồi ''nghệ thuật''. Chỉ có hình Lục thư thông (thời Minh) trong dữ liệu, chưa thấy giáp cốt hay kim văn rõ ràng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (140) Thế (831)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 140 - cây cỏ/ 艹 /chỉ ý) ở trên cùng, phía dưới là chữ Thế (số 831 - trồng cây/ 埶) và bộ Vân (云) đóng vai trò làm âm đọc. Giải thích sự chuyển ý: Nghệ vốn mang nghĩa là trồng cây, tài bồi (viên nghệ). Mở rộng mang ý nghĩa là một nghề nghiệp, kỹ năng, tài năng, kỹ thuật (nghệ thuật, thủ nghệ, học nghệ).", "Nghĩa Tiếng Việt_Xie": "nghệ thuật", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "艺", "Unihan_Traditional (Chữ Phồn thể)": "藝", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "nghệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ tài năng, nghệ thuật hoặc động từ chỉ việc trồng trọt cây cối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('團', '{"9000": "", "Chữ Trung Quốc": "團", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vi (031) Chuyên (1055)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Vi (số 031 - vây quanh/ 囗 /chỉ ý) bao bên ngoài chữ Chuyên (số 1055 - chuyên chú/ 專 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Chuyên chỉ âm, bộ Vi chỉ ý. Đoàn vốn chỉ một vật có hình tròn, vo tròn lại (đoàn tử, đoàn vân). Mở rộng chỉ một tập thể quy tụ, tổ chức gồm nhiều người quây quần lại với nhau (đoàn thể, đoàn kết).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗專", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "專", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "团", "Unihan_Traditional (Chữ Phồn thể)": "團", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訓', '{"9000": "", "Chữ Trung Quốc": "訓", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 10 | nét | 言 | ngôn | biểu nghĩa | lời nói | 川 | xuyên | biểu âm | 訓 = 言 (Ngôn, biểu nghĩa: lời nói/diễn đạt) + 川 (Xuyên, biểu âm); chữ hình thanh. Phần 言 gợi dạy dỗ bằng lời; 川 cho âm xùn. Ý nghĩa: truyền đạt bài học như dòng nước chảy.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Theo Wiktionary, 訓 là chữ hình thanh: 言 (ngôn, biểu nghĩa: lời nói) kết hợp với 川 (xuyên, biểu âm). Mang nghĩa truyền đạt bài giảng — \"giảng dạy một điều gì đó\". | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Xuyên (047)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Xuyên (số 047 - sông ngòi/ 川 - ở đây Xuyên là cách viết giảm nét của chữ Thuận 順 làm âm đọc). Giải thích sự chuyển ý: Huấn là dùng lời nói (ngôn) để dạy bảo, khuyên răn sao cho người ta được xuôi thuận (thuận) theo điều đúng đắn (giáo huấn, huấn luyện, huấn từ).", "Nghĩa Tiếng Việt_Xie": "đào tạo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言川", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "川", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "训", "Unihan_Traditional (Chữ Phồn thể)": "訓", "Pinyin_Xie": "xùn", "Âm Hán Việt_Xie": "huấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc giáo dục, răn dạy hoặc làm danh từ chỉ lời giáo huấn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淚', '{"9000": "", "Chữ Trung Quốc": "淚", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (085) Lệ (1847)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 085 - dòng nước/ 氵/chỉ ý) ở bên trái chữ Lệ (số 1847 - tội lỗi/ 戾 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Lệ chỉ âm, bộ Thủy chỉ ý. Lệ là nước mắt tuôn rơi (huyết lệ, rơi lệ, bi lệ). (Giản thể thường dùng chữ Lệ 泪 - mắt 目 rơi nước 氵).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵戾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泪", "Unihan_Traditional (Chữ Phồn thể)": "淚", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('題', '{"9000": "", "Chữ Trung Quốc": "題", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 頁 | Số nét | 18 | nét | 是 | thị | biểu âm | thành phần biểu âm | 頁 | hiệt | biểu nghĩa | đầu, trang | 題 = 是 (Thị, biểu âm) + 頁 (biểu nghĩa: đầu/trang); chữ hình thanh. Nghĩa gốc là trán (phần trên của 頁 – đầu), sau mở rộng sang đề tài, tiêu đề.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 題 là chữ hình thanh: 頁 (đầu) biểu nghĩa + 是 biểu âm. Nghĩa gốc là \"trán\" (phần trên mặt người), rồi chuyển nghĩa sang \"tiêu đề\" (phần đứng đầu văn bản) và \"đề bài\" (chủ đề, câu hỏi). Wiktionary ghi: \"forehead\" là nghĩa ban đầu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thị (268) Hiệt (181)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thị (số 268 - đúng/là/ 是 /chỉ âm) ở bên trái bộ Hiệt (số 181 - cái đầu/ 頁 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thị chỉ âm, bộ Hiệt chỉ ý. Đề vốn là cái trán (phần nhô ra phía trước trên đầu). Mở rộng chỉ phần nêu lên trên, phần đặt ở trước tiên của bài văn, bài thơ (đề bài, chủ đề, tiêu đề).", "Nghĩa Tiếng Việt_Xie": "câu hỏi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴是頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "是", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "题", "Unihan_Traditional (Chữ Phồn thể)": "題", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ tiêu đề, câu hỏi hoặc làm động từ với nghĩa viết, ghi chữ lên bề mặt nào đó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋸', '{"9000": "", "Chữ Trung Quốc": "鋸", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 16 | nét | 金 | kim | biểu nghĩa | kim loại | 居 | cư | biểu âm | âm cư/cưa | 鋸 = 金 (Kim, biểu nghĩa: kim loại) + 居 (Cư, biểu âm); chữ hình thanh. 金 gợi công cụ kim loại, 居 cho âm jù.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Theo Wiktionary: 鋸 là chữ hình thanh gồm 金 (kim loại — biểu nghĩa) và 居 (biểu âm). Nghĩa: cái cưa; hành động cưa. Kim văn có ảnh. Âm Hán cổ: jù. Từ ghép: 鋸子 (cưa tay), 電鋸 (cưa điện), 切割 (cắt cưa). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (167) Cư (336)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 167 - kim loại/ 金 /chỉ ý) ở bên trái chữ Cư (số 336 - cư trú/ 居 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cư chỉ âm, bộ Kim chỉ ý. Cứ là cái cưa làm bằng kim loại có răng sắc nhọn dùng để xẻ gỗ (cưa cứ, cương cứ - cưa thép). Cứ cũng là động từ cưa, cắt.", "Nghĩa Tiếng Việt_Xie": "cưa; cái cưa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金居", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "居", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "锯", "Unihan_Traditional (Chữ Phồn thể)": "鋸", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cưa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ dụng cụ cắt hoặc làm động từ chỉ hành động cưa xẻ gỗ đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('錯', '{"9000": "", "Chữ Trung Quốc": "錯", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 16 | nét | 金 | kim | biểu nghĩa | kim loại, vàng | 昔 | tích | biểu âm | ngày xưa, quá khứ | 錯 = 金 (Kim, biểu nghĩa: kim loại) + 昔 (Tích, biểu âm); chữ hình thanh — bộ 金 chỉ kim loại (đá mài bằng kim loại), 昔 cho âm cuò.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 錯 là chữ hình thanh: 金 (kim loại) biểu nghĩa, 昔 biểu âm. Nguyên nghĩa là hòn đá mài kim loại; từ ý mài dũa, chà xát mà sinh nghĩa lẫn lộn, xen kẽ; rồi mở rộng sang sai lầm, nhầm lẫn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (167) Tích (072)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 167 - kim loại/ 金 /chỉ ý) ở bên trái chữ Tích (số 072 - ngày xưa/ 昔 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tích chỉ âm, bộ Kim chỉ ý. Thác vốn là hòn đá mài kim loại. Sau này chữ Thác được mượn dùng với nghĩa là sai lầm, lầm lẫn, không đúng (sai thác, thác ngộ).", "Nghĩa Tiếng Việt_Xie": "hòn đá mài; lẫn lộn, nhầm lẫn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金昔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "错", "Unihan_Traditional (Chữ Phồn thể)": "錯", "Pinyin_Xie": "cuò", "Âm Hán Việt_Xie": "thố, thác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc đứng sau động từ làm bổ ngữ kết quả chỉ sự sai sót. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('變', '{"9000": "", "Chữ Trung Quốc": "變", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 23 | nét | 䜌 | loan | biểu âm | rối ren, phức tạp | 攴 | phác | biểu nghĩa | hành động tác động | 變 = 䜌 (Loan, biểu âm) + 攴 (Phác, biểu nghĩa: hành động tác động, gõ). Chữ hình thanh — 攴 gợi hành động làm biến đổi, 䜌 cho âm.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Theo Wiktionary, 變 là chữ hình thanh: 䜌 biểu âm, 攴 (hành động tác động) biểu nghĩa. Kim văn và tiểu triện đã có dạng này. Nghĩa gốc là làm cho thay đổi, biến đổi bằng tác động bên ngoài. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Luyến (149) Phộc (066)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Phía trên là chữ Luyến (số 149 - 䜌 - gồm chữ Ngôn 言 ở giữa hai bộ Mịch 糸), phía dưới là chữ Phộc (số 066 - đánh khẽ/ 攵). Gặp hoàn cảnh rắc rối ràng buộc như những sợi tơ tằm, phải dùng lời lẽ (ngôn) và bắt tay hành động (phộc) để làm thay đổi nó đi. Giải thích sự chuyển ý: Đây là chữ Hội ý. Biến là làm thay đổi hình thức, tính chất trạng thái của sự việc (biến đổi, biến hóa, cải biến).", "Nghĩa Tiếng Việt_Xie": "thay đổi, biến đổi; trờ thành, biến thành; bán lấy tiền; biến cố, rối loạn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>䜌⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䜌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺙", "Unihan_Simplified (Chữ Giản thể)": "变", "Unihan_Traditional (Chữ Phồn thể)": "變", "Pinyin_Xie": "biàn", "Âm Hán Việt_Xie": "biến, biện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ sự thay đổi trạng thái hoặc danh từ chỉ biến cố lịch sử. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辦', '{"9000": "", "Chữ Trung Quốc": "辦", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 辛 | Số nét | 16 | nét | 辡 | biểu âm | 力 | lực | biểu nghĩa | sức mạnh, cố gắng | 辦 = 辡 (biểu âm) + 力 (Lực, biểu nghĩa: sức, cố gắng); chữ hình thanh. Ý nghĩa: dùng sức lực để xử lý, giải quyết công việc. Đây là dạng phồn thể của 办.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Theo Wiktionary, 辦 là chữ hình thanh: 力 (sức mạnh, biểu nghĩa) + 辡 (biểu âm). Nghĩa gốc là làm việc, xử lý — dùng sức để hoàn thành công việc. Dạng giản thể là 办. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tân (160) Lực (019)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Lực (số 019 - sức lực/ 力) nằm ở giữa hai chữ Tân (số 160 - cay đắng/ 辛). Dốc hết sức lực ra làm việc để mong thoát khỏi những sự khó khăn cay đắng. Giải thích sự chuyển ý: Đây là chữ Hội ý. Biện là trù liệu, lo tính công việc đã chuẩn bị sẵn (biện pháp, trù biện). Mở rộng là làm việc, xử lý công việc (biện sự, biện công thất - văn phòng).", "Nghĩa Tiếng Việt_Xie": "LÀM", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辡力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "力", "Unihan_Simplified (Chữ Giản thể)": "办", "Unihan_Traditional (Chữ Phồn thể)": "辦", "Pinyin_Xie": "bàn", "Âm Hán Việt_Xie": "biện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ chính trong câu và có thể mang theo tân ngữ phía sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('廚', '{"9000": "", "Chữ Trung Quốc": "廚", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nghiễm (053) Thụ (033)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nghiễm (số 053 - mái nhà/ 广 /chỉ ý) bao lấy chữ Thụ (số 033 - dựng đứng/ 尌 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thụ chỉ âm, bộ Nghiễm chỉ ý. Trù là cái bếp, nhà bếp để đun nấu thức ăn (trù phòng). Đầu bếp được gọi là Trù sư.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广尌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釘', '{"9000": "", "Chữ Trung Quốc": "釘", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 金 | Số nét | 10 | nét | 金 | kim | biểu nghĩa | kim loại, vàng | 丁 | đinh | biểu âm | đinh, đàn ông tráng kiện — cho âm đọc | 釘 là chữ hình thanh: 金 (Kim, biểu nghĩa — kim loại) + 丁 (Đinh, biểu âm). Wiktionary xác nhận: {{Han compound|金|丁|c1=s|c2=p|t1=metal|ls=psc}}. Nghĩa: cái đinh, thanh kim loại nhọn. Thú vị: 丁 vừa là thành phần biểu âm vừa có thể là hình ảnh cái đinh nhọn trong chữ tượng hình cổ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | 釘 là chữ hình thanh gồm 金 (kim loại — biểu nghĩa) và 丁 (biểu âm). Wiktionary ghi thêm: một số nhà nghiên cứu cho rằng 丁 vốn là hình ảnh cái đinh nhọn trong giáp cốt văn — do đó 釘 còn có thể phân tích là hội ý giữa \"kim loại\" và \"hình đinh\". Nghĩa gốc: cái đinh kim loại. Dạng truyền thống; giản thể là 钉. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kim (167) Đinh (001)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Kim (số 167 - kim loại/ 金 /chỉ ý) ở bên trái chữ Đinh (số 001 - đinh tráng/ 丁 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đinh chỉ âm, bộ Kim chỉ ý. Đinh là cái đinh làm bằng kim loại để đóng đồ vật (đinh ốc). Nếu đọc là Đính (dìng) thì mang nghĩa là đóng đinh (đính mộc bả).", "Nghĩa Tiếng Việt_Xie": "Móng tay", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金丁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "钉", "Unihan_Traditional (Chữ Phồn thể)": "釘", "Pinyin_Xie": "dīng", "Âm Hán Việt_Xie": "đinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ vật nhọn bằng kim loại hoặc làm động từ khi kết hợp với tân ngữ chỉ hành động đóng đinh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹵', '{"9000": "", "Chữ Trung Quốc": "鹵", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tây (146) Bốn dấu chấm", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Đây là một chữ Tượng hình. Vỏ ngoài vẽ hình dáng một dụng cụ để đựng muối. Bốn dấu chấm ở bên trong tượng trưng cho những hạt muối. Giải thích sự chuyển ý: Lỗ là muối tự nhiên sinh ra chưa qua chế biến tinh lọc, còn gọi là muối mỏ (bể muối) khai thác từ lòng đất (lỗ mạc - đất hoang vu nhiều muối).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>⺊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹹', '{"9000": "", "Chữ Trung Quốc": "鹹", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 鹵 | Số nét | 20 | nét | 鹵 | biểu nghĩa | muối, bùn mặn | 咸 | hàm | biểu âm | 鹹 = 鹵 (biểu nghĩa: muối/bùn mặn) + 咸 (Hàm, biểu âm); chữ hình thanh. Bộ muối (鹵) gợi nghĩa vị mặn; âm phần 咸 cho phát âm xián.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Lục thư thông | Theo Wiktionary, 鹹 là chữ hình thanh (psc): 鹵 (muối/bùn mặn, biểu nghĩa) + 咸 (biểu âm). Chữ chỉ vị mặn, nước mặn. 咸 (hàm) vừa là thành phần âm vừa có nghĩa ''tất cả/mọi thứ'' — ở đây chỉ đóng vai trò biểu âm. Chữ tạo muộn theo lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lỗ (197) Hàm (030)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Lỗ (số 197 - muối mỏ/ 鹵 /chỉ ý) ở bên trái chữ Hàm (số 030 - đều, cùng/ 咸 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hàm chỉ âm, bộ Lỗ chỉ ý. Hàm là vị mặn của muối (hàm thủy - nước mặn, hàm ngư - cá muối mặn).", "Nghĩa Tiếng Việt_Xie": "mặn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鹵咸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹵", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc sau động từ để chỉ vị mặn của thức ăn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱔', '{"9000": "", "Chữ Trung Quốc": "鱔", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngư (195) Thiện (030)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngư (số 195 - con cá/ 魚 /chỉ ý) ở bên trái chữ Thiện (số 030 - tốt lành/ 善 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thiện chỉ âm, bộ Ngư chỉ ý. Thiện là tên gọi của con lươn, loài động vật giống cá nhưng sống chui rúc dưới bùn lầy (thiện ngư).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚善", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "善", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訴', '{"9000": "", "Chữ Trung Quốc": "訴", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 12 | nét | 言 | ngôn | biểu nghĩa | lời nói, ngôn ngữ | 斥 | xích | biểu âm | trách mắng, buộc tội | 訴 = 言 (Ngôn, biểu nghĩa: lời nói) + 斥 (Xích, biểu âm); chữ hình thanh (psc). Kết hợp \"nói\" và \"buộc tội\" gợi hành động tố cáo bằng lời, kêu oan.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 訴 (sù): chữ hình thanh, gồm 言 (biểu nghĩa: lời nói, phát biểu) và 斥 (Xích, biểu âm: trách mắng, buộc tội). Ý gốc là tố cáo bằng lời nói. Từ đó mở rộng nghĩa: kể lể, giãi bày, khởi kiện. Tiểu triện ghi nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Xích (069)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Xích (số 069 - ruồng bỏ/ 斥 /chỉ âm). Dùng lời nói chê bai nói xấu lẫn nhau do sự thù ghét ruồng bỏ trong lòng. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Xích chỉ âm, bộ Ngôn chỉ ý. Tố là gièm pha, chê bai, báo cáo sự xấu xa (tố cáo, khiếu tố, tố khổ). Cũng là sự kêu oan kiện cáo (tố tụng).", "Nghĩa Tiếng Việt_Xie": "kể, thuật; tố giác, mách", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言斥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "tố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đi kèm tân ngữ chỉ nội dung hoặc đối tượng bị khiếu nại, tố cáo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('談', '{"9000": "", "Chữ Trung Quốc": "談", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 言 | Số nét | 15 | nét | 言 | ngôn | biểu nghĩa | lời nói | 炎 | viêm | biểu âm | âm phù | 談 là chữ hình thanh (psc): 言 (ngôn — lời nói, biểu nghĩa) + 炎 (viêm, biểu âm). Lời nói 言 sôi nổi như lửa 炎 — hình ảnh cuộc trò chuyện nóng bỏng, nhiệt tình.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | Wiktionary: 談 = 言 (lời nói, biểu nghĩa) + 炎 (biểu âm), chữ hình thanh. 言 cho nghĩa, 炎 cho âm tán/đàm. Tiểu triện và lục thư thông đã có dạng chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngôn (149) Viêm (086)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Ngôn (số 149 - lời nói/ 言 /chỉ ý) ở bên trái chữ Viêm (số 086 - lửa cháy rực/ 炎 /chỉ âm). Những lời bàn luận tranh luận sôi nổi rực lửa. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Viêm chỉ âm, bộ Ngôn chỉ ý. Đàm là nói chuyện, bàn bạc, thảo luận qua lại với nhau (đàm luận, hội đàm, đàm thoại).", "Nghĩa Tiếng Việt_Xie": "nói chuyện", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言炎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "炎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "谈", "Unihan_Traditional (Chữ Phồn thể)": "談", "Pinyin_Xie": "tán", "Âm Hán Việt_Xie": "đàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ đứng trước tân ngữ để chỉ hoạt động trò chuyện, thảo luận. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('響', '{"9000": "", "Chữ Trung Quốc": "響", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 音 | Số nét | 20 | nét | 鄉 | hương | biểu âm | làng quê | 音 | âm | biểu nghĩa | âm thanh | 響 = 鄉 (Hương, biểu âm) + 音 (Âm, biểu nghĩa: âm thanh); chữ hình thanh. Bộ Âm chỉ đây là chữ liên quan đến âm thanh; 鄉 cho âm xiǎng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | 響 là chữ hình thanh: 音 (âm thanh) biểu nghĩa, 鄉 biểu âm. Nghĩa là tiếng vang, âm thanh vọng lại, tiếng響. Dạng đại triện còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hương (785) Âm (065)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Âm (số 065 - âm thanh/ 音 /chỉ ý) ở bên dưới chữ Hương (số 785 - làng quê/ 鄉 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hương chỉ âm, bộ Âm chỉ ý. Hưởng là âm thanh vang dội, vọng lại (âm hưởng, tiếng vang). Mở rộng chỉ sự tác động gây ra phản ứng dây chuyền (ảnh hưởng).", "Nghĩa Tiếng Việt_Xie": "nhẫn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>鄉音", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鄉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "音", "Unihan_Simplified (Chữ Giản thể)": "响", "Unihan_Traditional (Chữ Phồn thể)": "響", "Pinyin_Xie": "xiǎng", "Âm Hán Việt_Xie": "hưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả âm thanh to rõ hoặc làm động từ chỉ sự phát ra tiếng động. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棗', '{"9000": "", "Chữ Trung Quốc": "棗", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thích (838)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hai chữ Thích (số 838 - cái gai/ 朿) viết chồng lên nhau. Chữ để chỉ ý rằng đây là một loại cây có rất nhiều gai nhọn. Giải thích sự chuyển ý: Đây là chữ Hội ý. Táo (Tảo) là cây táo, quả táo (táo thụ - cây táo, táo tử - quả táo). Cổ nhân quan sát thấy cây táo có rất nhiều gai nên dùng hai chữ Thích chồng lên nhau để mô tả.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴朿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "枣", "Unihan_Traditional (Chữ Phồn thể)": "棗", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陸', '{"9000": "", "Chữ Trung Quốc": "陸", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 阜 | Số nét | 10 | nét | 阝 | phụ | biểu nghĩa | gò đất, đê, mô đất | 坴 | lục | biểu âm | mô đất cao | 陸 = 阝 (bộ 阜, biểu nghĩa: gò đất) + 坴 (Lục, biểu âm); chữ hình thanh. Nghĩa gốc là đất cao so với mặt nước — đất liền.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Bạch thư | Tiểu triện | 陸 là chữ hình thanh: 阝(阜) (gò đất) cho nghĩa, 坴 cho âm. Nghĩa gốc là vùng đất cao, đất liền (phân biệt với nước). Có đủ dạng từ giáp cốt, kim văn, bạch thư đến tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phụ (158) Lục (430)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Phụ (số 158 - cồn đất/ 阝/chỉ ý) ở bên trái chữ Lục (số 430 - khối đất/ 坴 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Lục chỉ âm, bộ Phụ chỉ ý. Lục là vùng đất liền, đất ở trên cao mà bằng phẳng không có nước (lục địa, đại lục).", "Nghĩa Tiếng Việt_Xie": "đất liền; đường bộ; sao Lục; sáu, 6 (dùng trong văn tự, như: 六)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝坴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陆", "Unihan_Traditional (Chữ Phồn thể)": "陸", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Số từ | 数词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ đất liền hoặc làm số từ viết hoa của số sáu trong tài chính. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('績', '{"9000": "", "Chữ Trung Quốc": "績", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 糸 | Số nét | 17 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, chỉ | 責 | trách | biểu âm | âm trách/tích | 績 = 糸 (Mịch, biểu nghĩa: sợi chỉ/tơ) + 責 (Trách, biểu âm); chữ hình thanh. Nghĩa gốc: xe sợi, đánh chỉ — mở rộng thành thành tích tích luỹ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary: 績 là chữ hình thanh gồm 糸 (sợi chỉ — biểu nghĩa) và 責 (biểu âm). Nghĩa gốc: xe sợi tơ, kéo chỉ. Từ hình ảnh sợi chỉ được xe dài thêm từng chút, nghĩa mở rộng thành thành tích tích luỹ qua thời gian. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch (120) Trách (136)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (số 120 - sợi tơ/ 糸 /chỉ ý) ở bên trái chữ Trách (số 136 - đòi nợ/ 責 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Trách chỉ âm, bộ Mịch chỉ ý. Tích vốn là động từ đánh sợi, xe các sợi tơ nhỏ lại thành sợi to (phưởng tích). Do quá trình xe sợi cần sự gom góp, góp nhặt từ nhỏ đến lớn nên Tích mở rộng thành ý nghĩa tích lũy lại, công lao thu được (thành tích, công tích).", "Nghĩa Tiếng Việt_Xie": "đánh sợi, xe chỉ; tích luỹ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹責", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "責", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "绩", "Unihan_Traditional (Chữ Phồn thể)": "績", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ trong các từ ghép chỉ thành tích hoặc động từ chỉ việc xe tơ dệt sợi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
